window.DATA_B2_G=[{"id":"G1","q":"Le pusieron una multa ____ conducir la moto sin casco.","o":["por","porque","puesto que","ya que"],"a":0,"k":"원인의 por + 동사원형","t":"그는 헬멧 없이 오토바이를 몰아서 벌금을 받았다.","e":"빈칸 뒤에 동사원형 conducir가 바로 옵니다. 원인·이유를 나타낼 때 'por + 동사원형' 구조를 쓰며 '~해서, ~한 탓에'라는 뜻입니다. 반면 porque, puesto que, ya que는 접속사라서 뒤에 주어와 활용된 동사(condujo 등)가 와야 합니다. 예: Lo castigaron por mentir. (거짓말을 해서 벌을 받았다.)","x":["por: 전치사로 동사원형 앞에서 원인(~해서)을 나타냄 → 정답 ✓","porque: '왜냐하면'이라는 접속사로 뒤에 활용된 동사가 필요해 동사원형과 쓸 수 없음 ✗","puesto que: '~이므로'라는 접속사로 역시 활용된 동사가 와야 함 ✗","ya que: '~이니까'라는 접속사로 동사원형 앞에는 쓰지 않음 ✗"]},{"id":"G2","q":"¿Alguna vez ____ este plato local?","o":["probases","estabas probando","has probado","estuviste probando"],"a":2,"k":"현재완료(경험)","t":"이 지역 요리를 먹어 본 적 있니?","e":"'Alguna vez(한 번이라도, 언젠가)'로 지금까지의 경험을 물을 때는 현재완료(haber 현재형 + 과거분사)를 씁니다. 그래서 has probado(먹어 봤다)가 정답입니다. 참고로 중남미에서는 ¿Alguna vez probaste...?처럼 단순과거를 쓰는 경우도 많습니다.","x":["probases: 접속법 과거(가정·바람에 쓰는 형태)로 의문문의 평서 질문에 맞지 않음 ✗","estabas probando: 과거진행형(먹고 있었다)이라 경험을 묻는 뜻이 안 됨 ✗","has probado: 현재완료로 지금까지의 경험을 나타냄 → 정답 ✓","estuviste probando: 단순과거 진행형으로 일정 기간 하던 동작을 말해 경험 질문에 어색함 ✗"]},{"id":"G3","q":"Los niños se han ido ____ dar un paseo con su abuelo.","o":["hacia","desde","a","hasta"],"a":2,"k":"목적의 a + 동사원형","t":"아이들은 할아버지와 산책하러 나갔다.","e":"ir(se)처럼 이동을 나타내는 동사 뒤에서 '~하러'라는 목적을 말할 때는 'a + 동사원형'을 씁니다. 그래서 se han ido a dar un paseo(산책하러 갔다)가 됩니다. dar un paseo는 '산책하다'라는 자주 쓰는 표현입니다.","x":["hacia: '~쪽으로'라는 방향을 나타내며 동사원형 앞에서 목적을 뜻하지 않음 ✗","desde: '~부터'라는 출발점을 나타내 의미가 맞지 않음 ✗","a: 이동 동사 + a + 동사원형으로 '~하러'를 나타냄 → 정답 ✓","hasta: '~까지'라는 한계를 나타내 목적 표현이 아님 ✗"]},{"id":"G4","q":"____ salimos empezó a diluviar. ¡Qué mala suerte!","o":["Por poco","Casi","Apenas","Todavía"],"a":2,"k":"apenas(~하자마자)","t":"우리가 나가자마자 비가 억수같이 쏟아지기 시작했다. 운도 없지!","e":"apenas는 문장 맨 앞에서 활용된 동사와 함께 쓰이면 '~하자마자'라는 뜻이 됩니다. 나간 직후 곧바로 비가 내리기 시작했다는 상황이므로 Apenas salimos가 자연스럽습니다. diluviar는 '폭우가 쏟아지다'라는 뜻입니다.","x":["Por poco: '하마터면 ~할 뻔했다'라는 뜻이라 실제로 나간 상황과 맞지 않음 ✗","Casi: '거의'라는 뜻으로 '거의 나갔다'가 되어 뒷문장과 연결이 어색함 ✗","Apenas: 문장 앞에서 '~하자마자'라는 뜻 → 정답 ✓","Todavía: '아직'이라는 뜻으로 시간의 연결을 나타내지 못함 ✗"]},{"id":"G5","q":"No está confirmado que Francisco ____ a presentarse como candidato.","o":["irá","iría","vaya","va"],"a":2,"k":"불확실 + 접속법","t":"프란시스코가 후보로 출마할지는 확정되지 않았다.","e":"'No está confirmado que(~인지 확정되지 않았다)'처럼 확실하지 않음을 나타내는 표현 뒤에는 접속법(바람·의심·불확실을 나타내는 동사 형태)을 씁니다. 그래서 ir의 접속법 현재 vaya가 정답입니다. 긍정문 Está confirmado que va...라면 직설법을 씁니다.","x":["irá: 직설법 미래로 확실한 사실을 말할 때 쓰여 불확실 표현 뒤에 맞지 않음 ✗","iría: 가능법(~할 텐데)으로 이 구조에 쓰지 않음 ✗","vaya: 접속법 현재로 불확실성을 나타냄 → 정답 ✓","va: 직설법 현재로 사실을 단정해 버려 맞지 않음 ✗"]},{"id":"G6","q":"¿Te ____ bien que comamos a las 3?","o":["está pareciendo","parezca","parece","pareces"],"a":2,"k":"parecer 구문","t":"3시에 점심 먹는 거 괜찮아?","e":"'¿Te parece bien que...?(~하는 것이 괜찮니?)'에서 parecer의 주어는 뒤의 que절 전체이고, 의견을 가진 사람은 간접목적격 대명사 te(너에게)로 나타냅니다. 주어가 절이므로 3인칭 단수 parece를 씁니다. 상대에게 제안할 때 아주 자주 쓰는 표현입니다.","x":["está pareciendo: 진행형으로 parecer의 의견 표현에 쓰지 않음 ✗","parezca: 접속법인데 이 의문문에는 접속법을 쓸 이유가 없음 ✗","parece: que절을 주어로 한 3인칭 단수 직설법 → 정답 ✓","pareces: 2인칭 단수로 '네가 ~처럼 보인다'는 뜻이 되어 구조가 맞지 않음 ✗"]},{"id":"G7","q":"Cuando ____ estudiantes, salíamos cada noche y nos lo pasábamos genial.","o":["éramos","estuvimos","estábamos","fuimos"],"a":0,"k":"ser 불완료과거","t":"우리가 학생이었을 때는 매일 밤 놀러 나가서 정말 즐겁게 보냈다.","e":"'학생이다'처럼 신분·정체성을 나타낼 때는 estar가 아니라 ser를 씁니다. 또 과거의 어떤 시기를 배경으로 묘사할 때는 불완료과거(과거에 계속되던 상태·습관을 나타내는 시제)를 쓰므로 éramos가 정답입니다. 뒤의 salíamos, nos lo pasábamos도 같은 시제입니다.","x":["éramos: ser의 불완료과거로 과거의 신분·배경을 나타냄 → 정답 ✓","estuvimos: estar의 단순과거로 신분을 나타내지 못함 ✗","estábamos: estar는 일시적 상태에 쓰므로 '학생이다'에는 맞지 않음 ✗","fuimos: ser의 단순과거로 끝난 사건처럼 말해 배경 묘사에 어색함 ✗"]},{"id":"G8","q":"____ hotel que tanto nos gustaba ya no existe.","o":["Una","El","La","Un"],"a":1,"k":"정관사","t":"우리가 그토록 좋아했던 그 호텔은 이제 없다.","e":"hotel은 남성 명사이고, 뒤의 관계절(que tanto nos gustaba)이 '우리가 좋아했던 바로 그' 호텔로 특정하고 있으므로 정관사 el을 씁니다. 부정관사(un)는 처음 언급하거나 정해지지 않은 대상에 씁니다.","x":["Una: 여성 부정관사로 남성 명사 hotel과 맞지 않음 ✗","El: 남성 정관사로 특정한 호텔을 가리킴 → 정답 ✓","La: 여성 정관사라 성이 맞지 않음 ✗","Un: 부정관사로 '어떤 호텔'이 되어 특정한 대상에 어색함 ✗"]},{"id":"G9","q":"Es muy molesto que los vecinos ____ tanto ruido cada noche.","o":["están haciendo","hagan","hacen","harían"],"a":1,"k":"감정·평가 + 접속법","t":"이웃들이 매일 밤 그렇게 시끄럽게 하는 건 정말 짜증 난다.","e":"'Es molesto que(~하는 것은 짜증 난다)'처럼 감정이나 가치 판단을 나타내는 표현 뒤의 que절에는 접속법을 씁니다. 그래서 hacer의 접속법 현재 hagan이 정답입니다. hacer ruido는 '소음을 내다'라는 뜻입니다.","x":["están haciendo: 직설법 진행형이라 감정 표현 뒤에 맞지 않음 ✗","hagan: 접속법 현재로 감정·평가 표현 뒤에 옴 → 정답 ✓","hacen: 직설법 현재라 이 구조에서는 쓰지 않음 ✗","harían: 가능법으로 이 문장 구조와 맞지 않음 ✗"]},{"id":"G10","q":"Eugenia se expresa muy bien tanto en inglés ____ en francés.","o":["como","a que","como que","que"],"a":0,"k":"tanto ... como","t":"에우헤니아는 영어로도 프랑스어로도 아주 잘 표현한다.","e":"'tanto A como B'는 'A도 B도, A와 B 모두'라는 뜻의 짝 표현입니다. 앞에 tanto가 나왔으므로 짝이 되는 como를 씁니다. 예: Tanto Ana como Luis vienen. (아나도 루이스도 온다.)","x":["como: tanto와 짝을 이루어 'A도 B도'를 만듦 → 정답 ✓","a que: 이런 짝 표현은 없음 ✗","como que: '~인 것처럼'이라는 다른 표현이라 맞지 않음 ✗","que: más/menos ... que 비교에 쓰며 tanto와는 짝이 아님 ✗"]},{"id":"G11","q":"¿Puedes explicarme ____ se hace este ejercicio?","o":["qué","cómo","que","como"],"a":1,"k":"간접의문문 cómo","t":"이 문제를 어떻게 푸는지 설명해 줄래?","e":"'어떻게 하는지'를 묻는 간접의문문(문장 안에 들어간 의문문)에서는 의문사 cómo를 강세 부호와 함께 씁니다. 강세 없는 como는 '~처럼, ~이므로'라는 뜻이 됩니다. explicar cómo는 '어떻게 ~하는지 설명하다'입니다.","x":["qué: '무엇을'이라는 뜻이라 방법을 묻는 문장에 맞지 않음 ✗","cómo: '어떻게'라는 의문사로 방법을 물음 → 정답 ✓","que: 강세 없는 접속사/관계사로 의문의 뜻이 없음 ✗","como: 강세가 없으면 '~처럼'이라는 뜻이라 의문사로 쓸 수 없음 ✗"]},{"id":"G12","q":"Al parecer, ____ mayoría votó en contra de la propuesta.","o":["la","el","ø","lo"],"a":0,"k":"la mayoría","t":"듣자 하니 대다수가 그 제안에 반대표를 던졌다고 한다.","e":"mayoría(대다수)는 여성 명사이며 보통 정관사 la와 함께 la mayoría라고 씁니다. 그래서 la가 정답입니다. al parecer는 '듣자 하니, 보아하니'라는 뜻의 자주 쓰는 표현입니다.","x":["la: 여성 명사 mayoría 앞의 정관사 → 정답 ✓","el: 남성 정관사라 mayoría와 성이 맞지 않음 ✗","ø: 주어 자리에서 관사 없이 mayoría만 쓰면 어색함 ✗","lo: 중성 관사로 명사 앞에 쓰지 않음 ✗"]},{"id":"G13","q":"Te llamo para ____ una buena noticia.","o":["te dar","darte","que te dé","dar a ti"],"a":1,"k":"동사원형 + 대명사","t":"좋은 소식을 전해 주려고 전화했어.","e":"전치사 para 뒤에는 동사원형이 오고, 목적격 대명사는 동사원형 뒤에 붙여 씁니다: dar + te = darte. 주어가 같을 때(내가 전화하고 내가 전함)는 para que가 아니라 'para + 동사원형'을 씁니다.","x":["te dar: 대명사를 동사원형 앞에 둘 수 없음 ✗","darte: 동사원형 뒤에 대명사를 붙인 올바른 형태 → 정답 ✓","que te dé: para que는 주어가 다를 때 쓰는데 여기선 주어가 같아 부적절 ✗","dar a ti: 간접목적격 대명사 te 없이 a ti만 쓰는 것은 부자연스러움 ✗"]},{"id":"G14","q":"No podré ir a la excursión con vosotros. ____ día tengo turno de mañana.","o":["Ese","El","Este","Aquel"],"a":0,"k":"지시사 ese","t":"너희와 함께 소풍에 못 갈 것 같아. 그날은 오전 근무가 있어.","e":"앞에서 이미 말한 날(소풍 가는 날)을 다시 가리킬 때는 지시사 ese를 씁니다. este는 '지금·여기 가까운 것', aquel은 '아주 먼 과거나 거리가 먼 것'에 주로 씁니다. tener turno de mañana는 '오전 근무가 있다'는 뜻입니다.","x":["Ese: 앞에서 말한 그날을 가리킴 → 정답 ✓","El: 관사만으로는 '그날'이라는 지시의 뜻이 약해 어색함 ✗","Este: 지금과 가까운 '이번'을 뜻해 언급된 날을 받기 어색함 ✗","Aquel: 먼 과거·먼 대상을 가리켜 이 상황에 맞지 않음 ✗"]},{"id":"G15","q":"¿____ cuánto tiempo lleváis esperando?","o":["Desde","ø","De","En"],"a":1,"k":"llevar + 시간 + 현재분사","t":"너희 얼마나 오래 기다리고 있었니?","e":"'llevar + 시간 + 현재분사(-ando/-iendo)'는 '~동안 계속 ~하고 있다'는 뜻으로, 시간 앞에 전치사를 붙이지 않습니다. 그래서 ¿Cuánto tiempo lleváis esperando?가 맞습니다. 전치사 desde를 쓰려면 ¿Desde cuándo esperáis?처럼 말합니다.","x":["Desde: desde cuánto tiempo라는 표현은 쓰지 않음 ✗","ø: llevar 구문에서는 시간 앞에 전치사가 없음 → 정답 ✓","De: '~의/~부터'라는 뜻으로 이 구조에 맞지 않음 ✗","En: '~ 안에'라는 뜻이라 지속 기간을 묻는 문장에 맞지 않음 ✗"]},{"id":"G16","q":"Últimamente, Miguel hace las cosas ____ mala gana. ¿Qué le pasará?","o":["a","con","en","de"],"a":3,"k":"de mala gana","t":"요즘 미겔은 일을 마지못해 한다. 무슨 일이 있는 걸까?","e":"'de mala gana'는 '마지못해, 내키지 않게'라는 뜻의 관용 표현이고, 반대는 'de buena gana(기꺼이)'입니다. 이처럼 방식을 나타내는 관용구에는 전치사 de가 쓰입니다. ¿Qué le pasará?는 미래형으로 현재에 대한 추측(무슨 일일까?)을 나타냅니다.","x":["a: a mala gana라는 표현은 없음 ✗","con: con ganas(의욕적으로)는 있지만 con mala gana는 쓰지 않음 ✗","en: 이 관용구에 쓰지 않는 전치사 ✗","de: de mala gana(마지못해)라는 고정 표현 → 정답 ✓"]},{"id":"G17","q":"En los 80 ____ el pelo con mucho volumen.","o":["se llevó","se ha llevado","se llevaba","se estaba llevando"],"a":2,"k":"llevarse(유행하다)","t":"80년대에는 볼륨이 큰 머리 스타일이 유행했다.","e":"llevarse는 '유행하다(estar de moda)'라는 뜻으로 쓰입니다. 80년대라는 과거의 한 시기 동안 계속된 상황·경향을 묘사하므로 불완료과거(과거의 배경·습관을 나타내는 시제) se llevaba가 정답입니다.","x":["se llevó: 단순과거로 한 번 일어나고 끝난 사건처럼 말해 시대 묘사에 어색함 ✗","se ha llevado: 현재완료라 지금과 연결되어 80년대 과거와 맞지 않음 ✗","se llevaba: 불완료과거로 과거 시대의 유행을 묘사 → 정답 ✓","se estaba llevando: 진행형이라 '유행하고 있는 중이었다'로 어색함 ✗"]},{"id":"G18","q":"Me gustaría que mi marido ____ más atento conmigo.","o":["sería","fuese","sea","haya sido"],"a":1,"k":"me gustaría que + 접속법 과거","t":"남편이 나에게 좀 더 다정했으면 좋겠다.","e":"'Me gustaría que(~했으면 좋겠다)'처럼 가능법(조건법) 동사로 바람을 말하면 que절에는 접속법 과거를 씁니다. 그래서 ser의 접속법 과거 fuese(=fuera)가 정답입니다. 시제 일치 규칙: 주절이 가능법이면 종속절은 접속법 과거입니다.","x":["sería: 가능법이라 que절 안에 쓸 수 없음 ✗","fuese: 접속법 과거로 가능법 주절과 시제가 맞음 → 정답 ✓","sea: 접속법 현재로 me gusta que 뒤에 쓰며 me gustaría와는 시제가 맞지 않음 ✗","haya sido: 접속법 현재완료로 과거에 끝난 일에 써 의미가 맞지 않음 ✗"]},{"id":"G19","q":"No es inteligente ____ listo.","o":["aunque","pero","no obstante","sino"],"a":3,"k":"no A sino B","t":"그는 지적인 게 아니라 영리한 것이다.","e":"앞에서 부정한 내용을 고쳐 '~가 아니라 ~이다'라고 말할 때는 sino를 씁니다. 'No es inteligente sino listo'는 '똑똑한 게 아니라 약삭빠르다/영리하다'라는 대조입니다. pero는 '하지만'이라는 단순 대립이라 앞의 내용을 대체하지 못합니다.","x":["aunque: '비록 ~지만'이라는 양보라 뜻이 맞지 않음 ✗","pero: '하지만'으로 앞의 부정을 바로잡는 뜻이 없음 ✗","no obstante: '그럼에도 불구하고'라는 뜻이라 맞지 않음 ✗","sino: 부정 뒤에서 '~가 아니라 ~'를 만듦 → 정답 ✓"]},{"id":"G20","q":"____ dos años que estudio español.","o":["De hace","Desde","Desde hace","Hace"],"a":3,"k":"hace + 시간 + que","t":"스페인어를 공부한 지 2년이 됐다.","e":"'Hace + 시간 + que + 현재형'은 '~한 지 (시간)이 되었다'라는 뜻입니다. 같은 뜻을 'Estudio español desde hace dos años'로도 말할 수 있지만, 문장이 que로 이어지는 이 구조에서는 Hace만 씁니다.","x":["De hace: 이런 표현은 없음 ✗","Desde: desde는 시점(desde 2020) 앞에 쓰며 이 구조에 맞지 않음 ✗","Desde hace: 문장 끝에 오는 표현으로 que 구조와 함께 쓰지 않음 ✗","Hace: hace + 시간 + que로 경과 기간을 나타냄 → 정답 ✓"]},{"id":"G21","q":"Seguro que todo ____ bien, no te preocupes tanto.","o":["va a salir","salga","esté saliendo","vaya a salir"],"a":0,"k":"seguro que + 직설법","t":"분명 다 잘될 거야, 너무 걱정하지 마.","e":"'Seguro que(분명히 ~이다)'는 확신을 나타내므로 뒤에 직설법을 씁니다. 앞으로 일어날 일이므로 'ir a + 동사원형' 미래 표현인 va a salir가 정답입니다. salir bien은 '잘되다'라는 뜻입니다.","x":["va a salir: 직설법 미래 표현으로 확신을 나타냄 → 정답 ✓","salga: 접속법이라 확신 표현 뒤에 쓰지 않음 ✗","esté saliendo: 접속법 진행형이라 맞지 않음 ✗","vaya a salir: 접속법이므로 seguro que 뒤에 부적절 ✗"]},{"id":"G22","q":"Busco un diccionario que ____ actualizado. ¿Me recomiendas alguno?","o":["está","esté","ha estado","haya estado"],"a":1,"k":"미지의 선행사 + 접속법","t":"최신판으로 업데이트된 사전을 찾고 있어. 하나 추천해 줄래?","e":"아직 있는지 없는지 모르는, 찾고 있는 대상(선행사)을 꾸밀 때 관계절에는 접속법을 씁니다. '그런 사전이 있으면 좋겠다'는 뜻이므로 estar의 접속법 현재 esté가 맞습니다. 이미 아는 특정 사전이면 직설법 está를 씁니다.","x":["está: 직설법이라 이미 존재하는 특정 사전을 말하게 됨 ✗","esté: 찾는 대상이 불확실하므로 접속법 현재 → 정답 ✓","ha estado: 직설법 현재완료로 의미·형태 모두 맞지 않음 ✗","haya estado: 접속법 현재완료로 과거에 업데이트됐던 상태를 말해 어색함 ✗"]},{"id":"G23","q":"Mi hermano es un pasota, no le importa ____.","o":["algo","poco","nada","todo"],"a":2,"k":"이중부정 no ... nada","t":"우리 형은 만사에 무관심한 사람이라 아무것도 신경 쓰지 않는다.","e":"스페인어에서는 동사 앞에 no가 있으면 뒤에 nada(아무것도), nadie(아무도) 같은 부정어를 함께 쓰는 이중부정이 정상입니다. 그래서 no le importa nada(아무것도 상관하지 않는다)가 맞습니다. pasota는 스페인 구어로 '만사에 무관심한 사람'입니다.","x":["algo: '무언가'라는 긍정어로 no와 함께 쓰지 않음 ✗","poco: no le importa poco는 뜻이 어색하고 이 문맥에 맞지 않음 ✗","nada: no와 짝을 이루는 부정어 '아무것도' → 정답 ✓","todo: '모든 것'이 되어 '전부 신경 쓰는 건 아니다'라는 다른 뜻이 됨 ✗"]},{"id":"G24","q":"En cuanto ____ a la oficina, me puse a leer los correos que me habían mandado.","o":["estuve llegando","llegaba","estaba llegando","llegué"],"a":3,"k":"en cuanto + 단순과거","t":"사무실에 도착하자마자 나는 사람들이 보낸 메일을 읽기 시작했다.","e":"'En cuanto(~하자마자)'가 과거에 실제로 일어나 완료된 일을 나타낼 때는 단순과거를 씁니다. 도착한 순간 바로 다음 행동이 이어졌으므로 llegué가 정답입니다. 미래 일이면 접속법을 써서 En cuanto llegue...라고 합니다.","x":["estuve llegando: 순간적 동작 llegar를 진행형으로 쓰면 어색함 ✗","llegaba: 불완료과거로 반복·배경을 나타내 '도착하자마자'의 한 사건과 맞지 않음 ✗","estaba llegando: '도착하는 중이었다'라는 뜻이라 완료된 순간이 아님 ✗","llegué: 단순과거로 완료된 한 순간을 나타냄 → 정답 ✓"]},{"id":"G25","q":"____ lo que te pasa.","o":["Me cuenta","Cuénteme","Cuenta me","Cuéntame"],"a":3,"k":"tú 긍정명령 + 대명사","t":"무슨 일 있는지 나한테 얘기해 봐.","e":"뒤에 te pasa(너에게 일어나는)가 있으므로 상대는 tú입니다. tú 긍정명령 cuenta에 대명사 me를 붙이면 강세 위치를 지키기 위해 악센트를 찍어 cuéntame가 됩니다. 긍정명령에서는 대명사를 동사 뒤에 붙여 한 단어로 씁니다.","x":["Me cuenta: 평서문 '그가 나에게 이야기한다'라는 뜻이라 명령이 아님 ✗","Cuénteme: usted에 대한 명령이라 te pasa(tú)와 맞지 않음 ✗","Cuenta me: 대명사를 띄어 쓰면 안 되고 악센트도 필요함 ✗","Cuéntame: tú 긍정명령 + me, 악센트 포함 → 정답 ✓"]},{"id":"G26","q":"¿Ya sabe a ____ candidato va a votar en las elecciones?","o":["qué","quién","que","cual"],"a":0,"k":"qué + 명사","t":"선거에서 어느 후보에게 투표할지 이미 정하셨어요?","e":"명사(candidato) 바로 앞에서 '어느, 무슨'이라고 물을 때는 qué를 씁니다. a qué candidato는 '어느 후보에게'입니다. 참고로 중남미 구어에서는 ¿cuál candidato?도 자주 들리지만, 표준적으로는 명사 앞에 qué를 씁니다.","x":["qué: 명사 앞에서 '어느/무슨'을 뜻하는 의문사 → 정답 ✓","quién: '누구'라는 대명사라 명사 앞에 쓸 수 없음 ✗","que: 강세가 없어 의문사가 아님 ✗","cual: 강세 부호가 없고 표준적으로는 명사 앞에 쓰지 않음 ✗"]},{"id":"G27","q":"Pienso que ____ suficientemente preparada para afrontar esta situación.","o":["estés","seas","estás","eres"],"a":2,"k":"pienso que + 직설법","t":"너는 이 상황에 맞설 준비가 충분히 되어 있다고 생각해.","e":"긍정문 'Pienso que(~라고 생각한다)' 뒤에는 직설법을 씁니다(부정문 No pienso que 뒤에는 접속법). 또 '준비되어 있다'는 상태이므로 estar preparada를 씁니다. 그래서 estás가 정답입니다.","x":["estés: 접속법이라 긍정 의견 표현 뒤에 쓰지 않음 ✗","seas: 접속법이고 ser는 상태 표현 preparada와 맞지 않음 ✗","estás: 직설법 + 상태의 estar → 정답 ✓","eres: ser preparado는 '교양 있는 사람이다'라는 다른 뜻이 되어 문맥과 맞지 않음 ✗"]},{"id":"G28","q":"Les mando esta carta ____ expresar mi malestar.","o":["así que","a efectos de","gracias a","debido a"],"a":1,"k":"목적 a efectos de","t":"제 불만을 표명하기 위해 여러분께 이 편지를 보냅니다.","e":"'a efectos de + 동사원형'은 '~할 목적으로, ~하기 위해'라는 격식체 목적 표현입니다. 편지에서 '불만을 표하기 위해'라는 목적을 말하므로 정답입니다. 일상에서는 para expresar와 같은 뜻입니다.","x":["así que: '그래서'라는 결과 접속사로 동사원형 앞에 쓰지 않음 ✗","a efectos de: '~하기 위해'라는 격식 목적 표현 → 정답 ✓","gracias a: '~덕분에'라는 긍정적 원인이라 뜻이 맞지 않음 ✗","debido a: '~때문에'라는 원인 표현이라 목적이 아님 ✗"]},{"id":"G29","q":"Buscamos empleados que ____ trabajar los fines de semana.","o":["podemos","podéis","pueden","puedan"],"a":3,"k":"미지의 선행사 + 접속법","t":"우리는 주말에 일할 수 있는 직원을 구하고 있습니다.","e":"아직 정해지지 않은, 찾고 있는 사람(empleados)을 꾸미는 관계절에는 접속법을 씁니다. 3인칭 복수 empleados에 맞춰 poder의 접속법 현재 puedan이 정답입니다. 구인 광고에서 아주 흔한 구조입니다.","x":["podemos: 1인칭 복수 직설법이라 주어(empleados)와 맞지 않음 ✗","podéis: 2인칭 복수 직설법이라 주어와 맞지 않음 ✗","pueden: 3인칭 복수지만 직설법이라 불특정 대상에 맞지 않음 ✗","puedan: 3인칭 복수 접속법 현재 → 정답 ✓"]},{"id":"G30","q":"____ nos permite aumentar nuestro vocabulario.","o":["Al leer","Leer","Leyendo","Habiendo leído"],"a":1,"k":"주어로 쓰는 동사원형","t":"독서는 우리의 어휘를 늘려 준다.","e":"스페인어에서 '~하는 것'이라는 뜻으로 동사를 문장의 주어로 쓸 때는 동사원형을 씁니다. Leer(읽는 것)가 nos permite의 주어입니다. 영어처럼 -ing(현재분사 leyendo)를 주어로 쓰지 않는다는 점에 주의하세요.","x":["Al leer: '읽을 때'라는 시간 표현이라 주어가 될 수 없음 ✗","Leer: 동사원형이 명사처럼 주어 역할 → 정답 ✓","Leyendo: 현재분사는 '읽으면서'라는 부사적 뜻으로 주어가 될 수 없음 ✗","Habiendo leído: '읽고 나서'라는 완료 분사구문이라 주어가 아님 ✗"]},{"id":"G31","q":"La mujer ____ me ayudó vive en este barrio.","o":["quien","cual","la que","que"],"a":3,"k":"관계대명사 que","t":"나를 도와준 그 여자는 이 동네에 산다.","e":"쉼표 없이 앞의 명사를 바로 한정하는 관계절(제한적 관계절)에서 주어 역할을 할 때는 que를 씁니다. quien은 전치사 뒤나 쉼표가 있는 설명적 관계절에서 주로 쓰고, la que는 보통 전치사 뒤에 옵니다.","x":["quien: 쉼표 없는 제한적 관계절의 주어로는 쓰지 않음 ✗","cual: 관사 없이 단독으로 관계대명사로 쓸 수 없음 ✗","la que: 전치사 없이 이 위치에 쓰면 어색함 ✗","que: 제한적 관계절의 주어로 가장 기본적인 관계대명사 → 정답 ✓"]},{"id":"G32","q":"El bebé no deja de llorar. ¿____ hambre?","o":["Tendrá","Habría tenido","Tendría","Habrá tenido"],"a":0,"k":"미래형(현재 추측)","t":"아기가 계속 울어. 배가 고픈 걸까?","e":"스페인어 단순미래는 '지금 ~일 것이다/~일까?'라는 현재에 대한 추측에도 쓰입니다. 아기가 지금 배고픈지 추측하므로 Tendrá hambre?가 정답입니다. 예: ¿Qué hora será? (지금 몇 시쯤일까?)","x":["Tendrá: 단순미래로 현재 상황을 추측 → 정답 ✓","Habría tenido: 가능법 완료로 과거 사실과 반대되는 가정에 씀 ✗","Tendría: 가능법으로 과거에 대한 추측(배고팠던 걸까)이 됨 ✗","Habrá tenido: 미래완료로 방금 지난 일에 대한 추측이라 현재 상황과 맞지 않음 ✗"]},{"id":"G33","q":"____ de ellas podría recibir una beca de estudios.","o":["Otro cualquiera","Cualquier","Cualquiera","Uno cualquiera"],"a":2,"k":"cualquiera de","t":"그녀들 중 누구든 장학금을 받을 수 있을 것이다.","e":"'~ 중 누구든/아무나'는 'cualquiera de + 복수'로 씁니다. 명사 앞에서는 cualquier로 줄어들지만(cualquier persona), 여기처럼 de 앞에서는 줄이지 않은 cualquiera를 씁니다.","x":["Otro cualquiera: '아무 다른 사람'이라는 뜻으로 de ellas와 쓰지 않음 ✗","Cualquier: 명사 바로 앞에서만 쓰는 단축형이라 de 앞에 쓸 수 없음 ✗","Cualquiera: de ellas와 함께 '그들 중 누구든' → 정답 ✓","Uno cualquiera: 남성형 uno가 여성 ellas와 맞지 않고 구조도 어색함 ✗"]},{"id":"G34","q":"No vino ni Jose ____ Felipe.","o":["ni","no","tampoco","o"],"a":0,"k":"ni ... ni","t":"호세도 펠리페도 오지 않았다.","e":"'ni A ni B'는 'A도 B도 ~않다'라는 뜻입니다. 동사 앞의 no와 함께 쓰여 No vino ni José ni Felipe라고 합니다. 앞에 ni가 나왔으므로 짝으로 ni를 씁니다.","x":["ni: 앞의 ni와 짝을 이뤄 'A도 B도 아니다' → 정답 ✓","no: 두 사람을 연결하는 접속사 역할을 못 함 ✗","tampoco: '~도 역시 아니다'라는 부사라 ni ... ni 구조에 들어가지 않음 ✗","o: '또는'이라 부정의 짝 표현이 되지 않음 ✗"]},{"id":"G35","q":"¿Te molesta que te ____ tu edad?","o":["preguntarían","pregunten","preguntan","preguntasen"],"a":1,"k":"감정 동사 + 접속법","t":"사람들이 너에게 나이를 묻는 게 싫니?","e":"'¿Te molesta que...?(~하는 것이 싫니/거슬리니?)'처럼 감정을 나타내는 동사 뒤의 que절에는 접속법을 씁니다. 주절이 현재(molesta)이므로 접속법 현재 pregunten이 정답입니다. 주어가 정해지지 않은 3인칭 복수는 '사람들이'라는 뜻입니다.","x":["preguntarían: 가능법이라 que절에 맞지 않음 ✗","pregunten: 접속법 현재로 현재 시제 주절과 일치 → 정답 ✓","preguntan: 직설법이라 감정 동사 뒤에 쓰지 않음 ✗","preguntasen: 접속법 과거로 주절이 molestaría 같은 가능법일 때 씀 ✗"]},{"id":"G36","q":"La gente optimista no se da ____ vencida fácilmente.","o":["por","de","a","para"],"a":0,"k":"darse por vencido","t":"낙관적인 사람들은 쉽게 포기하지 않는다.","e":"'darse por vencido/a'는 '패배를 인정하다, 포기하다'라는 고정 표현으로 전치사 por를 씁니다. 여기서는 gente(사람들, 여성 단수 명사)에 맞추어 vencida가 되었습니다.","x":["por: darse por vencido(포기하다)의 고정 전치사 → 정답 ✓","de: 이 표현에 쓰지 않는 전치사 ✗","a: 이 표현에 쓰지 않는 전치사 ✗","para: 목적의 전치사라 이 관용구에 맞지 않음 ✗"]},{"id":"G37","q":"No es verdad que ____ a favor de tu propuesta.","o":["estemos","estábamos","estaríamos","estamos"],"a":0,"k":"부정 + 접속법","t":"우리가 네 제안에 찬성한다는 건 사실이 아니야.","e":"'No es verdad que(~라는 것은 사실이 아니다)'처럼 사실을 부정하는 표현 뒤에는 접속법을 씁니다. 그래서 estar의 접속법 현재 estemos가 정답입니다. 긍정문 Es verdad que estamos...라면 직설법입니다. estar a favor de는 '~에 찬성하다'입니다.","x":["estemos: 접속법 현재로 사실 부정 표현 뒤에 옴 → 정답 ✓","estábamos: 직설법 불완료과거라 맞지 않음 ✗","estaríamos: 가능법이라 맞지 않음 ✗","estamos: 직설법으로 긍정의 Es verdad que 뒤에 쓰는 형태 ✗"]},{"id":"G38","q":"La chica ____ te hablé ayer es la novia de Pedro.","o":["con quien","a que","de quien","por la que"],"a":2,"k":"전치사 + 관계사","t":"내가 어제 너에게 말했던 그 여자애가 페드로의 여자 친구야.","e":"'~에 대해 이야기하다'는 hablar de이므로, 관계절에서도 전치사 de를 관계사 앞에 둡니다. 사람을 가리키므로 de quien(=de la que)이 맞습니다. 즉 te hablé de la chica → la chica de quien te hablé입니다.","x":["con quien: hablar con은 '~와 이야기하다'인데 문장은 '~에 대해 말했다'는 뜻 ✗","a que: 전치사 a와 que는 hablar의 이 뜻과 맞지 않음 ✗","de quien: hablar de(~에 대해 말하다)의 de + 사람 관계사 → 정답 ✓","por la que: por는 hablar와 쓰는 전치사가 아님 ✗"]},{"id":"G39","q":"El chico ____ comparto piso es alemán.","o":["con el","con el que","con él","con lo que"],"a":1,"k":"con + 관계사 el que","t":"나와 집을 같이 쓰는 그 남자애는 독일 사람이다.","e":"'~와 집을 함께 쓰다'는 compartir piso con이므로 관계절 앞에 전치사 con이 필요합니다. 전치사 뒤의 관계대명사는 'el/la/los/las que'를 쓰며, 남성 단수 chico에 맞춰 con el que가 됩니다.","x":["con el: 관계사 que가 빠져 관계절이 만들어지지 않음 ✗","con el que: 전치사 + 관계대명사의 올바른 형태 → 정답 ✓","con él: '그와 함께'라는 인칭대명사라 관계절을 이끌 수 없음 ✗","con lo que: 중성 lo는 사람(chico)을 가리키지 않음 ✗"]},{"id":"G40","q":"No conozco a la chica ____ la camiseta negra.","o":["en","hacia","de","con"],"a":2,"k":"특징을 나타내는 de","t":"검은 티셔츠를 입은 여자애는 모르겠다.","e":"사람을 옷차림이나 특징으로 구별해 '~을 입은/~한 사람'이라고 할 때 전치사 de를 씁니다. 예: el señor de las gafas (안경 쓴 아저씨). 구어에서 con을 쓰기도 하지만 교재 기준으로는 de가 가장 자연스러운 표현입니다.","x":["en: 장소의 '~에'라는 뜻이라 옷차림 묘사에 맞지 않음 ✗","hacia: '~쪽으로'라는 방향 전치사라 맞지 않음 ✗","de: 옷차림·특징으로 사람을 구별하는 de → 정답 ✓","con: 구어에서 들리기도 하지만 이런 구별 표현에는 de가 표준 ✗"]},{"id":"G41","q":"Este anillo tiene un valor especial para mí, ____ regaló mi abuela.","o":["a mí","me","me lo","me le"],"a":2,"k":"간접+직접목적격 대명사","t":"이 반지는 나에게 특별한 가치가 있다. 할머니가 나에게 선물해 주신 것이다.","e":"'누구에게(me) 무엇을(lo=anillo)' 선물했는지 두 대명사가 모두 필요합니다. 순서는 간접목적격(~에게) + 직접목적격(~을)이므로 me lo regaló가 됩니다. anillo는 남성 단수라 lo를 씁니다.","x":["a mí: 대명사 me 없이 a mí만 쓸 수 없고 직접목적어도 빠짐 ✗","me: '반지를'에 해당하는 직접목적격 lo가 빠짐 ✗","me lo: 간접(me) + 직접(lo) 순서가 올바름 → 정답 ✓","me le: le는 간접목적격이라 '반지를'을 나타낼 수 없음 ✗"]},{"id":"G42","q":"No entiendo ____ te enfadas con tanta facilidad.","o":["por que","porque","porqué","por qué"],"a":3,"k":"por qué / porque","t":"네가 왜 그렇게 쉽게 화를 내는지 이해가 안 돼.","e":"'왜'라는 의문의 뜻은 직접의문문이든 간접의문문이든 띄어 쓰고 악센트가 있는 por qué로 씁니다. 여기서는 'no entiendo(이해 못 한다)' 뒤의 간접의문문입니다. porque는 '왜냐하면', el porqué는 '이유'라는 명사입니다.","x":["por que: 전치사 por + 관계사/접속사 que로 '왜'라는 뜻이 아님 ✗","porque: '왜냐하면'이라는 이유 접속사라 의문의 뜻이 없음 ✗","porqué: '이유'라는 명사로 관사(el porqué)와 함께 씀 ✗","por qué: '왜'라는 의문사로 간접의문문에도 씀 → 정답 ✓"]},{"id":"G43","q":"Mis cuadros ____ en este museo a partir de la próxima semana.","o":["serán expuestas","serán expuestos","serán expuesto","será expuestos"],"a":1,"k":"수동태 ser + 과거분사","t":"내 그림들은 다음 주부터 이 미술관에 전시될 것이다.","e":"'ser + 과거분사' 수동태에서는 ser가 주어의 수에, 과거분사는 주어의 성·수에 일치합니다. cuadros는 남성 복수이므로 serán expuestos가 정답입니다.","x":["serán expuestas: 여성 복수라 cuadros(남성)와 맞지 않음 ✗","serán expuestos: 남성 복수로 주어와 일치 → 정답 ✓","serán expuesto: 과거분사가 단수라 복수 주어와 맞지 않음 ✗","será expuestos: 동사가 단수라 복수 주어와 맞지 않음 ✗"]},{"id":"G44","q":"Últimamente ____ muchos pisos en esta zona.","o":["están vendiendo se","se están vendiendo","se está vendiendo","se vende"],"a":1,"k":"수동의 se(복수)","t":"요즘 이 지역에서 많은 아파트가 팔리고 있다.","e":"'se + 3인칭 동사'는 '~가 ~되다'라는 수동의 se 구문이며, 동사는 뒤의 명사(muchos pisos)에 수를 맞춥니다. 복수이므로 se están vendiendo가 정답이며, se venden muchos pisos도 가능합니다. 진행형일 때 se는 조동사 앞에 두거나 현재분사 뒤에 붙입니다(están vendiéndose).","x":["están vendiendo se: se를 띄어서 뒤에 둘 수 없음 ✗","se están vendiendo: 복수 명사에 맞춘 수동의 se 진행형 → 정답 ✓","se está vendiendo: 단수라 muchos pisos와 수가 맞지 않음 ✗","se vende: 단수라 복수 명사와 맞지 않음 ✗"]},{"id":"G45","q":"¿Quién ____ ha comido mi trozo de tarta?","o":["la","lo","se","ø"],"a":2,"k":"강조의 se(comerse)","t":"누가 내 케이크 조각을 먹어 치웠어?","e":"comer에 se를 붙인 comerse는 '다 먹어 치우다'라는 완전함·강조의 뜻을 더합니다. 특정한 음식을 남김없이 먹었을 때 자주 쓰며 ¿Quién se ha comido...?가 자연스럽습니다. 다른 예: Me bebí todo el café. (커피를 다 마셔 버렸다.)","x":["la: 여성 직접목적격인데 trozo(남성)를 받지 않고 명사와 중복됨 ✗","lo: 직접목적어 mi trozo가 바로 뒤에 있어 중복되므로 쓰지 않음 ✗","se: comerse(다 먹어 치우다)의 강조 se → 정답 ✓","ø: 문법상 가능하지만 '먹어 치웠다'는 뉘앙스에는 se가 자연스러움 ✗"]},{"id":"G46","q":"Te llamo para ____ un favor.","o":["pedirte","pedir te","que te pido","pedírtelo"],"a":0,"k":"동사원형 + 대명사","t":"부탁 하나 하려고 전화했어.","e":"para 뒤에는 동사원형이 오고, 간접목적격 대명사 te(너에게)를 동사원형 뒤에 붙여 pedirte라고 씁니다. 직접목적어 un favor가 명사로 이미 나와 있으므로 lo를 또 붙이지 않습니다.","x":["pedirte: 동사원형 + te를 붙인 올바른 형태 → 정답 ✓","pedir te: 대명사를 띄어 쓰면 안 됨 ✗","que te pido: para que 뒤에는 접속법이 와야 하고 주어도 같아 부적절 ✗","pedírtelo: lo가 un favor와 중복되어 틀림 ✗"]},{"id":"G47","q":"Eloy no tiene ____ suerte como tú.","o":["tan","tanto","tanta","tantas"],"a":2,"k":"동등비교 tanto/a ... como","t":"엘로이는 너만큼 운이 좋지 않다.","e":"명사를 비교할 때 '~만큼 많은'은 'tanto/tanta/tantos/tantas + 명사 + como'를 쓰고, tanto는 명사의 성·수에 맞춥니다. suerte(운)는 여성 단수 명사이므로 tanta가 정답입니다.","x":["tan: 형용사·부사 앞에 쓰며 명사 앞에는 쓰지 않음 ✗","tanto: 남성 단수형이라 여성 명사 suerte와 맞지 않음 ✗","tanta: 여성 단수 명사 suerte에 일치 → 정답 ✓","tantas: 복수형이라 단수 suerte와 맞지 않음 ✗"]},{"id":"G48","q":"Me temo que no ____ ir con vosotras de excursión, tengo muchos quehaceres.","o":["pudiera","habré podido","pueda","podré"],"a":3,"k":"me temo que + 직설법","t":"아무래도 너희와 소풍 못 갈 것 같아, 할 일이 너무 많아.","e":"'Me temo que'는 여기서 '유감이지만 ~인 것 같다'라는 정중한 표현으로, 뒤에 직설법을 씁니다. 앞으로의 일이므로 단순미래 podré가 정답입니다. quehaceres는 '해야 할 일, 집안일'입니다.","x":["pudiera: 접속법 과거라 이 구조에 맞지 않음 ✗","habré podido: 미래완료로 '~할 수 있었을 것이다'라는 다른 뜻 ✗","pueda: 접속법이라 '유감이지만 ~이다'라는 뜻의 me temo que 뒤에 맞지 않음 ✗","podré: 직설법 미래로 앞으로 갈 수 없음을 나타냄 → 정답 ✓"]},{"id":"G49","q":"Esos dos chicos son igual ____ altos.","o":["de","como","ø","que"],"a":0,"k":"igual de + 형용사","t":"그 두 남자애는 키가 똑같이 크다.","e":"'igual de + 형용사/부사'는 '똑같이 ~하다'라는 동등비교 표현입니다. 그래서 son igual de altos(똑같이 키가 크다)가 됩니다. 반면 '~와 같다'고 비교 대상을 말할 때는 igual que를 씁니다(G82 참고).","x":["de: igual de + 형용사로 '똑같이 ~한' → 정답 ✓","como: igual como는 형용사 앞에서 쓰지 않음 ✗","ø: igual altos는 비문 ✗","que: igual que 뒤에는 비교 대상이 오며 형용사가 오지 않음 ✗"]},{"id":"G50","q":"El otro día ____ a Gema en el gimnasio.","o":["estaba viendo","veía","vi","he visto"],"a":2,"k":"단순과거(한 번의 사건)","t":"며칠 전에 헬스장에서 헤마를 봤어.","e":"'El otro día(며칠 전에, 일전에)'라는 과거의 특정 시점에 한 번 일어나고 끝난 일은 단순과거로 씁니다. 그래서 vi가 정답입니다. 불완료과거 veía는 반복되던 습관이나 배경 묘사에 씁니다.","x":["estaba viendo: '보고 있던 중이었다'라는 배경 묘사라 맞지 않음 ✗","veía: 불완료과거로 반복·습관을 나타내 한 번의 사건에 맞지 않음 ✗","vi: 단순과거로 과거에 완료된 한 번의 일 → 정답 ✓","he visto: 현재완료라 el otro día 같은 지난 시점과 쓰지 않음 ✗"]},{"id":"G51","q":"¿Cuándo ____ venir a nuestro nuevo hogar?","o":["puedan","podáis","podréis","puedas"],"a":2,"k":"직설법 미래(의문)","t":"너희 언제 우리 새 집에 올 수 있겠니?","e":"의문사 ¿Cuándo...?로 시작하는 직접의문문에서는 접속법을 쓰지 않고 직설법을 씁니다. 앞으로의 일이므로 vosotros(너희)의 단순미래 podréis가 정답입니다. 접속법은 Cuando podáis, venid.처럼 미래의 시간절에서 씁니다.","x":["puedan: 접속법이라 직접의문문에 맞지 않음 ✗","podáis: 접속법이라 의문사로 시작하는 질문에 쓰지 않음 ✗","podréis: vosotros 직설법 미래 → 정답 ✓","puedas: 접속법 tú형이라 시제·문맥이 맞지 않음 ✗"]},{"id":"G52","q":"Puede que no ____ este domingo, todavía no lo sé.","o":["trabajaría","trabajo","trabajase","trabaje"],"a":3,"k":"puede que + 접속법","t":"이번 일요일엔 일을 안 할 수도 있어, 아직 모르겠어.","e":"'Puede que(~일지도 모른다)'는 가능성을 나타내며 뒤에 항상 접속법을 씁니다. 그래서 trabajar의 접속법 현재 trabaje가 정답입니다. 예: Puede que llueva mañana. (내일 비가 올지도 몰라.)","x":["trabajaría: 가능법이라 puede que 뒤에 쓰지 않음 ✗","trabajo: 직설법이라 puede que 뒤에 쓰지 않음 ✗","trabajase: 접속법 과거로 현재 시제 puede와 시제가 맞지 않음 ✗","trabaje: 접속법 현재로 가능성을 나타냄 → 정답 ✓"]},{"id":"G53","q":"Cuando ____ calor me siento débil.","o":["hace","haría","haga","hará"],"a":0,"k":"cuando + 직설법(습관)","t":"더울 때면 나는 기운이 없다.","e":"cuando가 '~할 때마다'처럼 일반적·습관적인 사실을 말할 때는 직설법 현재를 씁니다. 날씨 '덥다'는 hacer calor이므로 hace가 정답입니다. 미래의 일(Cuando haga calor, iremos a la playa)이면 접속법을 씁니다.","x":["hace: 습관·일반적 사실을 나타내는 직설법 현재 → 정답 ✓","haría: 가능법이라 cuando절에 쓰지 않음 ✗","haga: 접속법은 미래의 일을 말할 때 써서 습관적 사실과 맞지 않음 ✗","hará: cuando절 안에는 미래형을 쓰지 않음 ✗"]},{"id":"G54","q":"____ tenga alguna novedad, me pondré en contacto con usted.","o":["Pese a que","Apenas","Por si","Si"],"a":1,"k":"apenas + 접속법(미래)","t":"새로운 소식이 생기는 대로 바로 연락드리겠습니다.","e":"apenas는 '~하자마자'라는 뜻이며, 미래의 일을 말할 때는 접속법을 씁니다(tenga). 뒤의 주절이 미래 me pondré이므로 시간 관계가 자연스럽습니다. ponerse en contacto con은 '~와 연락하다'라는 격식 표현입니다.","x":["Pese a que: '~에도 불구하고'라는 양보라 뜻이 맞지 않음 ✗","Apenas: '~하자마자' + 접속법(미래) → 정답 ✓","Por si: '~할 경우에 대비해'라는 뜻으로 보통 직설법과 쓰며 의미도 어색함 ✗","Si: 조건절에는 접속법 현재(tenga)를 쓰지 않음 ✗"]},{"id":"G55","q":"Cuando era chico, iba a un colegio que ____ muy cerca de mi casa.","o":["estuvo","había estado","ha estado","estaba"],"a":3,"k":"estar(위치) 불완료과거","t":"어렸을 때 나는 집에서 아주 가까운 학교에 다녔다.","e":"건물·장소의 위치를 말할 때는 estar를 씁니다. 과거의 배경 묘사(학교가 가까이 있었다)이므로 불완료과거 estaba가 정답입니다. chico는 중남미에서 '어린아이'라는 뜻으로 자주 씁니다(Cuando era chico = 어렸을 때).","x":["estuvo: 단순과거로 끝난 사건처럼 말해 배경 묘사에 맞지 않음 ✗","había estado: 과거완료로 '그 이전에 있었다'가 되어 어색함 ✗","ha estado: 현재완료라 과거 어린 시절 묘사에 맞지 않음 ✗","estaba: 불완료과거로 과거의 위치·배경을 묘사 → 정답 ✓"]},{"id":"G56","q":"En la sala ahora mismo hay más ____ doscientas personas.","o":["de","que","a","sobre"],"a":0,"k":"más de + 숫자","t":"지금 이 홀에는 200명이 넘는 사람이 있다.","e":"비교 표현에서 숫자·수량 앞에서는 que 대신 de를 써서 'más de + 숫자(~ 이상, ~ 넘게)'라고 합니다. 예: Tengo más de diez libros. (책이 10권 넘게 있다.)","x":["de: 숫자 앞의 비교 más de → 정답 ✓","que: 숫자 앞에서는 más que를 쓰지 않음(no ... más que는 '오직'이라는 다른 뜻) ✗","a: 이 비교 구조에 쓰지 않음 ✗","sobre: '대략'이라는 뜻으로 más와 함께 쓰지 않음 ✗"]},{"id":"G57","q":"Yo que tú no me lo pensaría, ____ un trabajo así inmediatamente.","o":["estaría aceptando","aceptaría","aceptaré","aceptase"],"a":1,"k":"yo que tú + 가능법","t":"내가 너라면 고민하지 않을 거야, 그런 일자리는 당장 받아들이겠어.","e":"'Yo que tú(내가 너라면)'는 조언할 때 쓰는 표현으로 뒤에 가능법(조건법, ~할 텐데)을 씁니다. 앞의 no me lo pensaría와 같은 시제로 aceptaría가 정답입니다.","x":["estaría aceptando: 가능법 진행형이라 어색함 ✗","aceptaría: 가능법으로 조언·가정의 결과를 나타냄 → 정답 ✓","aceptaré: 직설법 미래라 가정 표현과 맞지 않음 ✗","aceptase: 접속법 과거라 주절 동사로 쓸 수 없음 ✗"]},{"id":"G58","q":"No veo mi cartera, ¿dónde la ____?","o":["estaré dejando","dejaré","voy a dejar","habré dejado"],"a":3,"k":"미래완료(과거 추측)","t":"지갑이 안 보이네, 어디에 뒀을까?","e":"미래완료(habrá + 과거분사)는 '~했을 것이다/~했을까?'처럼 방금 지나간 일에 대한 추측을 나타냅니다. 지갑을 이미 어딘가에 두었고 그 장소를 추측하므로 habré dejado가 정답입니다.","x":["estaré dejando: 미래진행형이라 이미 끝난 행동 추측에 맞지 않음 ✗","dejaré: 단순미래로 '둘 것이다'가 되어 의미가 맞지 않음 ✗","voy a dejar: '두려고 한다'라는 미래 계획이라 맞지 않음 ✗","habré dejado: 미래완료로 지난 행동을 추측 → 정답 ✓"]},{"id":"G59","q":"No creo que Fernando ____ tan listo como cree.","o":["sería","era","es","sea"],"a":3,"k":"no creo que + 접속법","t":"페르난도가 스스로 생각하는 만큼 똑똑하다고는 생각하지 않아.","e":"긍정 Creo que 뒤에는 직설법이지만, 부정 'No creo que(~라고 생각하지 않는다)' 뒤에는 접속법을 씁니다. 그래서 ser의 접속법 현재 sea가 정답입니다. listo는 ser와 쓰면 '똑똑한', estar와 쓰면 '준비된'입니다.","x":["sería: 가능법이라 no creo que 뒤에 맞지 않음 ✗","era: 직설법 과거라 부정 의견 뒤에 맞지 않음 ✗","es: 직설법이라 부정의 no creo que 뒤에 쓰지 않음 ✗","sea: 접속법 현재 → 정답 ✓"]},{"id":"G60","q":"A los vecinos ____ ha tocado la lotería.","o":["ø","les","le","los"],"a":1,"k":"tocar + 간접목적격","t":"이웃들이 복권에 당첨됐다.","e":"'tocarle a alguien la lotería(복권이 ~에게 당첨되다)'는 gustar처럼 '받는 사람'을 간접목적격 대명사로 씁니다. a los vecinos는 3인칭 복수이므로 les가 정답이며, 'a + 사람'이 앞에 나오면 대명사를 반드시 함께 씁니다.","x":["ø: a los vecinos가 앞에 나오면 간접목적격 대명사가 반드시 필요함 ✗","les: 3인칭 복수 간접목적격(그들에게) → 정답 ✓","le: 단수라 vecinos(복수)와 맞지 않음 ✗","los: 직접목적격이라 tocar(당첨되다) 구문에 쓰지 않음 ✗"]},{"id":"G61","q":"No le ____ a Eloy todo lo que te he contado.","o":["dice","dices","di","digas"],"a":3,"k":"tú 부정명령","t":"내가 너한테 말한 거 엘로이한테 전부 말하지 마.","e":"tú에게 하는 부정명령(~하지 마)은 'no + 접속법 현재'로 만듭니다. decir의 접속법 tú형은 digas이므로 No le digas가 정답입니다. 긍정명령(말해)은 dile처럼 di를 씁니다.","x":["dice: 3인칭 직설법 현재라 명령이 아님 ✗","dices: tú 직설법 현재로 평서문이 되어 버림 ✗","di: tú 긍정명령형이라 no와 함께 쓰지 않음 ✗","digas: no + 접속법 현재의 tú 부정명령 → 정답 ✓"]},{"id":"G62","q":"La jefa me ha dicho que ____ ser más organizada.","o":["haya debido","debo","he debido","deba"],"a":1,"k":"간접화법 + 직설법","t":"팀장님이 나에게 좀 더 정리를 잘해야 한다고 말했다.","e":"decir que가 '~라고 말했다'는 정보 전달일 때는 직설법을 씁니다. 상사의 말 'debes ser más organizada'를 그대로 전달하므로 debo가 정답입니다. 참고로 decir que + 접속법은 명령 전달(me ha dicho que sea más organizada)일 때 씁니다.","x":["haya debido: 접속법 현재완료라 맞지 않음 ✗","debo: 직설법 현재로 들은 내용을 전달 → 정답 ✓","he debido: 현재완료로 '~해야 했다'가 되어 의미가 맞지 않음 ✗","deba: 접속법인데 deber 자체가 의무를 나타내 명령 전달 구조로 쓰지 않음 ✗"]},{"id":"G63","q":"____ no había nadie en el aula, pensé que habían cancelado la clase.","o":["Siempre y cuando","De ahí que","Pese a que","Como"],"a":3,"k":"이유의 como(문두)","t":"강의실에 아무도 없어서 수업이 취소된 줄 알았다.","e":"como가 문장 맨 앞에 와서 직설법과 쓰이면 '~이니까, ~해서'라는 이유를 나타냅니다. 이유를 먼저 말하고 결과(pensé que...)를 뒤에 이어 가는 구조입니다. 이유의 como는 porque와 달리 항상 문장 앞에 둡니다.","x":["Siempre y cuando: '~하기만 한다면'이라는 조건으로 접속법과 씀 ✗","De ahí que: '그래서 ~이다'라는 결과 표현으로 문두에서 이유를 이끌지 않음 ✗","Pese a que: '~에도 불구하고'라는 양보라 뜻이 맞지 않음 ✗","Como: 문두에서 '~이니까'라는 이유 → 정답 ✓"]},{"id":"G64","q":"Me gustaría conocer a alguien ____ tuviera las mismas aficiones que yo.","o":["que","cual","cuya","quien"],"a":0,"k":"관계대명사 que","t":"나와 같은 취미를 가진 사람을 만나 보고 싶다.","e":"쉼표 없이 앞의 명사(alguien)를 바로 꾸미는 관계절의 주어로는 que를 씁니다. 존재 여부를 모르는 막연한 사람이고 주절이 가능법(me gustaría)이라 관계절에 접속법 과거 tuviera가 쓰였습니다.","x":["que: 제한적 관계절의 주어 → 정답 ✓","cual: 관사 없이 관계대명사로 쓸 수 없음 ✗","cuya: '~의'라는 소유 관계사로 뒤에 명사가 와야 함 ✗","quien: 쉼표 없는 제한적 관계절의 주어로는 쓰지 않음 ✗"]},{"id":"G65","q":"Los inquilinos llegarán ____ las seis.","o":["ante","hacia","entre","en"],"a":1,"k":"hacia(대략의 시각)","t":"세입자들은 6시쯤 도착할 것이다.","e":"hacia는 '~쪽으로'라는 방향뿐 아니라 시간 앞에서 '~쯤, ~경'이라는 대략의 시점을 나타냅니다. hacia las seis는 '6시쯤'으로 sobre las seis, alrededor de las seis와 비슷합니다. 정확한 시각은 a las seis라고 합니다.","x":["ante: '~앞에서'라는 뜻이라 시간 표현에 쓰지 않음 ✗","hacia: 시간 앞에서 '~쯤'이라는 대략의 시점 → 정답 ✓","entre: '~사이에'라 두 시점(entre las cinco y las seis)이 필요함 ✗","en: 시각 앞에는 en을 쓰지 않음 ✗"]},{"id":"G66","q":"Tienes razón, ____ que haberte avisado antes, lo siento.","o":["he tenido","tuve","había tenido","tenía"],"a":3,"k":"tenía que haber + p.p.","t":"네 말이 맞아, 내가 너에게 더 일찍 알려 줬어야 했는데, 미안해.","e":"'tenía que + haber + 과거분사'는 '~했어야 했는데 (하지 않았다)'라는 과거에 대한 후회를 나타냅니다. tendría que haberte avisado와 같은 뜻입니다. 사과하는 상황에서 자주 씁니다.","x":["he tenido: 현재완료로 '실제로 해야만 했다'는 사실을 말해 후회의 뜻이 안 됨 ✗","tuve: 단순과거로 '실제로 했어야만 했다(그리고 했다)'는 뜻이 됨 ✗","había tenido: 과거완료로 시점이 맞지 않음 ✗","tenía: tenía que haber + p.p.로 '~했어야 했는데' → 정답 ✓"]},{"id":"G67","q":"Sé que todos ____ a favor de nuestra propuesta.","o":["sean","estén","están","son"],"a":2,"k":"saber que + 직설법","t":"모두가 우리 제안에 찬성한다는 걸 알고 있어.","e":"'Sé que(~라는 것을 안다)'는 확실한 사실을 말하므로 뒤에 직설법을 씁니다. 또 '찬성하다'는 estar a favor de이므로 estar의 직설법 están이 정답입니다.","x":["sean: 접속법이고 ser는 a favor 표현과 쓰지 않음 ✗","estén: estar는 맞지만 접속법이라 Sé que 뒤에 맞지 않음 ✗","están: 직설법 + estar a favor → 정답 ✓","son: ser는 estar a favor de 표현에 쓰지 않음 ✗"]},{"id":"G68","q":"____ me moleste, tendré que cenar en Navidad con mis suegros.","o":["Pese a","Como si","Por mucho que","Incluso"],"a":2,"k":"por mucho que + 접속법","t":"아무리 싫어도 크리스마스에 시부모님과 저녁을 먹어야 할 것이다.","e":"'Por mucho que + 접속법'은 '아무리 ~해도'라는 강한 양보 표현입니다. 뒤에 활용된 동사(me moleste)가 오므로 접속사구가 필요합니다. pese a는 명사나 동사원형 앞에, 활용된 동사 앞에는 pese a que를 씁니다.","x":["Pese a: 활용된 동사 앞에는 que가 필요(pese a que) ✗","Como si: '마치 ~인 것처럼'이라 뜻이 맞지 않음 ✗","Por mucho que: '아무리 ~해도' + 접속법 → 정답 ✓","Incluso: '~조차'라는 부사로 절을 이끌 수 없음 ✗"]},{"id":"G69","q":"____ anoche fue desastroso.","o":["La","Lo","El","Lo de"],"a":3,"k":"lo de + 명사/부사","t":"어젯밤 일은 엉망이었다.","e":"'lo de + 명사/부사'는 '~의 일, ~에 관한 것'이라는 뜻으로 이미 서로 아는 사건을 가리킵니다. lo de anoche는 '어젯밤에 있었던 일'입니다. 예: ¿Qué tal lo de tu trabajo? (네 일 관련된 건 어떻게 됐어?)","x":["La: 여성 관사로 뒤에 명사가 없어 쓸 수 없음 ✗","Lo: 중성 lo만으로는 anoche와 연결되지 않음 ✗","El: 남성 관사로 뒤에 명사가 없어 비문 ✗","Lo de: '~의 일'이라는 표현 → 정답 ✓"]},{"id":"G70","q":"No me gustó el documental de anoche; prefiero ____ vimos el domingo.","o":["que","el que","que lo","el cual"],"a":1,"k":"명사 생략 el que","t":"어젯밤 다큐멘터리는 별로였어. 일요일에 본 게 더 좋아.","e":"앞에 나온 명사(documental)를 반복하지 않을 때 '정관사 + que'로 '~한 것'을 나타냅니다. documental은 남성 단수라 el que vimos(우리가 본 것)가 됩니다.","x":["que: 관사 없이 que만으로는 '~한 것'이라는 명사구가 되지 않음 ✗","el que: 앞의 documental을 받는 '~한 것' → 정답 ✓","que lo: 문법 구조가 성립하지 않음 ✗","el cual: 쉼표나 전치사 뒤에 쓰며 이런 명사 생략에는 쓰지 않음 ✗"]},{"id":"G71","q":"No ____ lleves mi plato, todavía no he terminado de comer.","o":["ø","se","te","lo"],"a":2,"k":"llevarse(가져가다)","t":"내 접시 가져가지 마, 아직 다 안 먹었어.","e":"llevarse는 '(어떤 것을) 가져가 버리다, 치워 가다'라는 뜻입니다. tú에게 하는 부정명령이므로 재귀대명사 te를 동사 앞에 두어 No te lleves라고 합니다.","x":["ø: no lleves만 쓰면 '가져가 버리다'라는 뜻이 약하고 부자연스러움 ✗","se: 3인칭(usted)용 재귀대명사로 tú 명령 lleves와 맞지 않음 ✗","te: tú의 재귀대명사로 No te lleves → 정답 ✓","lo: mi plato가 바로 뒤에 있어 중복됨 ✗"]},{"id":"G72","q":"No voy a castigaros esta vez, ____, la próxima vez que lleguéis tarde, os quedaréis en clase media hora más.","o":["o sea","ahora bien","al fin y al cabo","pues"],"a":1,"k":"담화표지 ahora bien","t":"이번에는 벌을 주지 않을게, 하지만 다음에 또 늦으면 수업 끝나고 30분 더 남게 될 거야.","e":"'ahora bien'은 '하지만, 그렇긴 하지만'이라는 뜻으로 앞의 내용에 단서나 조건을 붙일 때 씁니다. 벌을 주지 않겠다고 한 뒤 경고를 덧붙이는 이 문장에 딱 맞습니다.","x":["o sea: '즉, 다시 말해'라는 설명 표현이라 대조가 안 됨 ✗","ahora bien: '하지만'이라는 단서·제한 → 정답 ✓","al fin y al cabo: '결국, 어쨌든'이라는 뜻으로 맞지 않음 ✗","pues: '그러니까, 그러면'이라는 뜻이라 대조를 나타내지 못함 ✗"]},{"id":"G73","q":"¿Te has fijado ____ lo delgada que se ha quedado Cristina?","o":["a","en","desde","sobre"],"a":1,"k":"fijarse en","t":"크리스티나가 얼마나 날씬해졌는지 봤어?","e":"fijarse는 '주목하다, 눈여겨보다'라는 뜻으로 항상 전치사 en과 함께 씁니다(fijarse en algo). 'lo + 형용사 + que'는 '얼마나 ~한지'를 나타내는 강조 구조입니다.","x":["a: fijarse와 쓰지 않는 전치사 ✗","en: fijarse en(~을 눈여겨보다) → 정답 ✓","desde: '~부터'라는 뜻이라 맞지 않음 ✗","sobre: '~에 대해'라는 뜻이라 fijarse와 쓰지 않음 ✗"]},{"id":"G74","q":"No me imaginaba que Adrián ____ tan bien el piano.","o":["haya tocado","tocará","esté tocando","tocase"],"a":3,"k":"과거 부정 상상 + 접속법","t":"아드리안이 그렇게 피아노를 잘 치는 줄은 상상도 못 했다.","e":"부정의 'No me imaginaba que(~라고는 상상하지 못했다)' 뒤에는 접속법을 씁니다. 주절이 과거(불완료과거)이므로 접속법 과거 tocase(=tocara)가 정답입니다.","x":["haya tocado: 접속법 현재완료로 과거 주절과 시제가 맞지 않음 ✗","tocará: 직설법 미래이고 악센트도 있어 tocara와 다른 형태 ✗","esté tocando: 접속법 현재 진행형이라 과거 주절과 맞지 않음 ✗","tocase: 접속법 과거로 과거 부정 표현 뒤에 옴 → 정답 ✓"]},{"id":"G75","q":"No tengo ____ trabajo, llevo varios meses en paro.","o":["un","el","ø","del"],"a":2,"k":"관사 생략","t":"일이 없어, 몇 달째 실업 상태야.","e":"tener, buscar 같은 동사 뒤에서 '일, 직장'을 막연하게 말할 때는 관사 없이 씁니다: No tengo trabajo. estar en paro는 스페인에서 '실업 상태이다'라는 뜻이며, 중남미에서는 estar desempleado/sin trabajo를 더 많이 씁니다.","x":["un: '일 하나'라는 셈을 하게 되어 부자연스러움 ✗","el: 특정한 일을 가리키게 되어 문맥과 맞지 않음 ✗","ø: 막연한 개념으로 관사 없이 씀 → 정답 ✓","del: de + el로 이 구조에 쓰지 않음 ✗"]},{"id":"G76","q":"Ya sabéis que podéis venir cuando ____.","o":["queráis","queríais","queréis","querríais"],"a":0,"k":"cuando + 접속법","t":"원할 때 언제든 와도 된다는 거 알지?","e":"cuando가 미래나 정해지지 않은 때를 나타내면 접속법을 씁니다. '너희가 원할 때(언제든)'라는 뜻이므로 querer의 vosotros 접속법 현재 queráis가 정답입니다.","x":["queráis: 정해지지 않은 미래를 나타내는 접속법 현재 → 정답 ✓","queríais: 직설법 불완료과거라 시제가 맞지 않음 ✗","queréis: 직설법 현재라 막연한 미래 시점에 맞지 않음 ✗","querríais: 가능법이라 cuando절에 쓰지 않음 ✗"]},{"id":"G77","q":"Llevamos ____ tres semanas aguantando el ruido de las obras.","o":["por","de","ø","desde"],"a":2,"k":"llevar + 시간 + 현재분사","t":"우리는 3주째 공사 소음을 견디고 있다.","e":"'llevar + 시간 + 현재분사'는 '~동안 계속 ~하고 있다'는 뜻이고 시간 앞에 전치사를 넣지 않습니다. 그래서 Llevamos tres semanas aguantando가 맞습니다. aguantar는 '참다, 견디다'입니다.","x":["por: llevar 구문의 시간 앞에 쓰지 않음 ✗","de: 시간 앞에 쓰지 않음 ✗","ø: 시간 앞에 전치사가 없음 → 정답 ✓","desde: desde는 desde hace tres semanas 등과 쓰며 llevar 구문에는 쓰지 않음 ✗"]},{"id":"G78","q":"Yo creo que aquí no hay más ____ cien personas.","o":["a","de","por","sobre"],"a":1,"k":"no más de + 숫자","t":"내 생각엔 여기 100명이 넘지 않는 것 같아.","e":"숫자 앞의 비교는 'más de + 숫자'입니다. 'no hay más de cien'은 '100명을 넘지 않는다(100명 이하)'라는 뜻입니다. 참고로 'no hay más que cien'은 '딱 100명뿐이다'라는 다른 뜻이 됩니다.","x":["a: 비교 구조에 쓰지 않음 ✗","de: 숫자 앞의 más de → 정답 ✓","por: '~당/~때문에'라는 뜻으로 비교에 쓰지 않음 ✗","sobre: '대략'이라는 뜻으로 más와 함께 쓰지 않음 ✗"]},{"id":"G79","q":"Nadie quiere que sus hijos ____ los estudios.","o":["dejarán","dejan","dejarían","dejen"],"a":3,"k":"querer que + 접속법","t":"자식이 학업을 그만두길 바라는 사람은 아무도 없다.","e":"'querer que(~하기를 바라다)'처럼 바람을 나타내는 동사 뒤에 주어가 다른 que절이 오면 접속법을 씁니다. 주절이 현재이므로 접속법 현재 dejen이 정답입니다. dejar los estudios는 '학업을 그만두다'입니다.","x":["dejarán: 직설법 미래라 바람 동사 뒤에 맞지 않음 ✗","dejan: 직설법 현재라 querer que 뒤에 쓰지 않음 ✗","dejarían: 가능법이라 맞지 않음 ✗","dejen: 접속법 현재 → 정답 ✓"]},{"id":"G80","q":"Tendremos una segunda reunión ____ resolver sus posibles dudas.","o":["por","para que","a efectos de","a fin de que"],"a":2,"k":"목적 a efectos de","t":"여러분의 궁금한 점을 해결하기 위해 두 번째 회의를 하겠습니다.","e":"빈칸 뒤에 동사원형(resolver)이 오므로 '전치사(구) + 동사원형' 형태의 목적 표현이 필요합니다. a efectos de는 '~하기 위해'라는 격식 표현이라 정답입니다. para que, a fin de que는 뒤에 접속법 활용 동사가 와야 합니다.","x":["por: por + 동사원형은 원인이나 '아직 ~하지 않은'의 뜻이라 목적에 맞지 않음 ✗","para que: 뒤에 접속법 활용 동사가 필요함 ✗","a efectos de: '~하기 위해' + 동사원형 → 정답 ✓","a fin de que: 뒤에 접속법 활용 동사가 필요함(동사원형이면 a fin de) ✗"]},{"id":"G81","q":"Iremos ____ España cuando podamos.","o":["en la","a","en","a la"],"a":1,"k":"ir a + 국가명","t":"우리는 가능할 때 스페인에 갈 거야.","e":"방향·목적지를 나타낼 때 ir 뒤에는 전치사 a를 씁니다. 또 España 같은 대부분의 나라 이름은 관사 없이 씁니다(예외: el Perú, la India 등). 그래서 ir a España가 정답입니다.","x":["en la: en은 장소 안에 '있을' 때 쓰고 관사도 불필요 ✗","a: 목적지를 나타내는 a + 국가명 → 정답 ✓","en: ir와 함께 목적지를 나타내지 않음 ✗","a la: España 앞에는 관사를 쓰지 않음 ✗"]},{"id":"G82","q":"Fernando habla igual ____ su padre.","o":["de","como","de que","que"],"a":3,"k":"igual que","t":"페르난도는 자기 아버지랑 똑같이 말한다.","e":"'igual que + 비교 대상'은 '~와 똑같이'라는 뜻입니다. 동사(habla) 뒤에서 아버지와 같은 방식이라고 할 때 igual que su padre를 씁니다. igual de는 뒤에 형용사가 올 때만 씁니다(igual de alto).","x":["de: igual de 뒤에는 형용사·부사가 와야 함 ✗","como: igual como는 표준적이지 않음 ✗","de que: 이런 비교 구조는 없음 ✗","que: igual que + 비교 대상 → 정답 ✓"]},{"id":"G83","q":"____ a diario y aumentaréis vuestro nivel de español en menos tiempo.","o":["Practiquen","Practique","Practicas","Practicad"],"a":3,"k":"vosotros 긍정명령","t":"매일 연습하면 더 짧은 시간에 스페인어 실력이 늘 거예요.","e":"뒤의 aumentaréis, vuestro로 보아 상대는 vosotros(너희)입니다. vosotros 긍정명령은 동사원형의 -r을 -d로 바꿔 만듭니다: practicar → practicad. 중남미에서는 vosotros 대신 ustedes를 써서 Practiquen ... aumentarán su nivel이라고 합니다.","x":["Practiquen: ustedes에 대한 명령이라 aumentaréis(vosotros)와 맞지 않음 ✗","Practique: usted에 대한 명령이라 맞지 않음 ✗","Practicas: tú 직설법 현재라 명령형이 아님 ✗","Practicad: vosotros 긍정명령 → 정답 ✓"]},{"id":"G84","q":"No ____ todavía, quedaos un poco más.","o":["os vayáis","te vayas","se vaya","se vayan"],"a":0,"k":"vosotros 부정명령","t":"아직 가지 마, 좀 더 있다 가.","e":"뒤의 quedaos(vosotros 명령)로 보아 상대는 vosotros입니다. 부정명령은 'no + 접속법'이므로 irse의 vosotros 접속법 os vayáis를 씁니다. 재귀동사의 부정명령에서는 대명사가 동사 앞에 옵니다.","x":["os vayáis: vosotros 부정명령 → 정답 ✓","te vayas: tú에게 하는 명령이라 quedaos와 맞지 않음 ✗","se vaya: usted에게 하는 명령이라 맞지 않음 ✗","se vayan: ustedes에게 하는 명령이라 맞지 않음(중남미에서는 이 형태를 씀) ✗"]},{"id":"G85","q":"¡____ frío hace hoy!","o":["Cómo","Cuándo","Qué","Cuál"],"a":2,"k":"감탄문 qué + 명사","t":"오늘 정말 춥다!","e":"명사(frío) 앞에서 '정말 ~하다!'라고 감탄할 때는 ¡Qué + 명사/형용사!를 씁니다. 예: ¡Qué calor! (정말 덥다!) cómo는 동사를 강조할 때 씁니다(¡Cómo llueve! 비가 엄청 오네!).","x":["Cómo: 동사를 강조하는 감탄사라 명사 앞에 쓰지 않음 ✗","Cuándo: '언제'라는 뜻이라 감탄문에 맞지 않음 ✗","Qué: 명사 앞의 감탄 ¡Qué + 명사! → 정답 ✓","Cuál: '어느 것'이라는 뜻이라 감탄문에 쓰지 않음 ✗"]},{"id":"G86","q":"Ya ____ he comprado los regalos de Navidad a mis padres.","o":["se les","los","les","se"],"a":2,"k":"간접목적격 중복","t":"부모님께 드릴 크리스마스 선물을 벌써 샀어.","e":"'a mis padres(부모님께)'라는 간접목적어가 있으면 같은 문장에 간접목적격 대명사 les를 함께 쓰는 것이 일반적입니다. 직접목적어 los regalos는 명사로 나와 있으므로 대명사 los를 또 쓰지 않습니다.","x":["se les: se는 le/les가 lo/la 앞에서 바뀐 형태로, 여기서는 쓸 이유가 없음 ✗","los: 직접목적어 los regalos와 중복됨 ✗","les: a mis padres를 받는 간접목적격 → 정답 ✓","se: 간접목적격이 아니므로 맞지 않음 ✗"]},{"id":"G87","q":"Hay muchas posibilidades ____ te den el puesto de trabajo porque tienes un currículum magnífico.","o":["que","a que","de que","de"],"a":2,"k":"posibilidad de que","t":"네 이력서가 아주 훌륭하니 그 자리를 얻을 가능성이 높아.","e":"명사 posibilidad(가능성) 뒤에 절이 이어질 때는 'de que'를 씁니다: hay posibilidades de que + 접속법. 명사가 내용을 받는 구조(el hecho de que, la idea de que)에서 de를 빼먹지 않도록 주의하세요.","x":["que: 명사 뒤에는 de가 필요해 de를 빼면 queísmo라는 오류가 됨 ✗","a que: 이 명사와 쓰지 않는 전치사 ✗","de que: 명사 + de que + 접속법 → 정답 ✓","de: 뒤에 활용된 동사가 오므로 que가 필요함 ✗"]},{"id":"G88","q":"No podéis imaginaros ____ bien que baila mi hija.","o":["lo que","cuánto","cómo","lo"],"a":3,"k":"lo + 부사 + que","t":"우리 딸이 춤을 얼마나 잘 추는지 너희는 상상도 못 할 거야.","e":"'lo + 형용사/부사 + que'는 '얼마나 ~한지'라는 강조 표현입니다. lo bien que baila는 '얼마나 춤을 잘 추는지'입니다. 예: No sabes lo cansada que estoy. (내가 얼마나 피곤한지 넌 몰라.)","x":["lo que: 뒤에 bien이 바로 오는 구조가 아님 ✗","cuánto: cuánto bien que는 비문 ✗","cómo: cómo bien que는 비문(cómo baila de bien은 가능) ✗","lo: lo + bien + que로 정도를 강조 → 정답 ✓"]},{"id":"G89","q":"Ojalá ____ más en esta región.","o":["lloviera","llueve","llovería","llovía"],"a":0,"k":"ojalá + 접속법 과거","t":"이 지역에 비가 좀 더 많이 왔으면 좋을 텐데.","e":"ojalá 뒤에는 항상 접속법을 씁니다. 접속법 과거(lloviera)는 실현 가능성이 낮거나 현재 사실과 반대되는 바람을 나타냅니다. 접속법 현재 llueva를 쓰면 실현 가능한 바람이 됩니다.","x":["lloviera: 접속법 과거로 이루어지기 어려운 바람 → 정답 ✓","llueve: 직설법이라 ojalá 뒤에 쓰지 않음 ✗","llovería: 가능법이라 ojalá 뒤에 쓰지 않음 ✗","llovía: 직설법 불완료과거라 ojalá 뒤에 쓰지 않음 ✗"]},{"id":"G90","q":"____ persona puede hacer bien una tarea tan sencilla.","o":["Cualesquiera","Cualquier","Cualesquier","Cualquiera"],"a":1,"k":"cualquier + 명사","t":"이렇게 간단한 일은 누구라도 잘할 수 있다.","e":"cualquiera는 단수 명사 앞에서 -a가 빠져 cualquier가 됩니다: cualquier persona(어떤 사람이든). 명사 없이 단독으로 쓰거나 명사 뒤에 올 때는 cualquiera(una persona cualquiera)를 씁니다.","x":["Cualesquiera: 복수형이라 단수 persona와 맞지 않음 ✗","Cualquier: 단수 명사 앞의 단축형 → 정답 ✓","Cualesquier: 복수 단축형으로 단수 명사와 맞지 않음 ✗","Cualquiera: 명사 바로 앞에서는 줄여서 cualquier로 씀 ✗"]},{"id":"G91","q":"Está claro que Penélope nació ____ actriz.","o":["para","por","hasta","hacia"],"a":0,"k":"nacer para","t":"페넬로페가 배우가 되려고 태어났다는 건 분명하다.","e":"'nacer para + 명사/동사원형'은 '~하도록 타고나다, ~가 되려고 태어나다'라는 뜻입니다. 목적·운명을 나타내므로 para를 씁니다. 예: Nació para cantar. (그는 노래하려고 태어났다.)","x":["para: '~가 되도록' 타고난 목적·운명 → 정답 ✓","por: 원인·이유를 나타내 이 표현에 쓰지 않음 ✗","hasta: '~까지'라는 뜻이라 맞지 않음 ✗","hacia: '~쪽으로'라는 방향이라 맞지 않음 ✗"]},{"id":"G92","q":"Todavía no ____ ninguna noticia con respecto a ese tema.","o":["recibí","estoy recibiendo","he recibido","recibía"],"a":2,"k":"todavía no + 현재완료","t":"그 일에 관해서는 아직 아무 소식도 받지 못했다.","e":"'todavía no(아직 ~않았다)'는 지금까지 이어지는 상황을 말하므로 스페인에서는 현재완료 he recibido를 씁니다. 중남미에서는 Todavía no recibí처럼 단순과거를 쓰는 경우가 흔하지만, 교재 기준은 현재완료입니다. con respecto a는 '~에 관해'입니다.","x":["recibí: 단순과거로 중남미에서는 쓰지만 표준 스페인 용법에서는 현재완료를 씀 ✗","estoy recibiendo: 현재진행형이라 '아직 받지 못했다'는 뜻과 맞지 않음 ✗","he recibido: 현재까지 이어지는 상황의 현재완료 → 정답 ✓","recibía: 불완료과거라 현재와 연결되지 않음 ✗"]},{"id":"G93","q":"El teléfono no ____ sonar en toda la tarde. ¡Qué estrés!","o":["vino a","se puso a","volvió","dejó de"],"a":3,"k":"dejar de + 동사원형","t":"전화가 오후 내내 울리기를 멈추지 않았다. 스트레스 받아!","e":"'dejar de + 동사원형'은 '~하기를 그만두다, 멈추다'라는 뜻입니다. no dejó de sonar는 '계속 울렸다'는 의미입니다. 반대로 'ponerse a + 동사원형'은 '~하기 시작하다'입니다.","x":["vino a: venir a + 동사원형은 '결국 ~하게 되다'라는 뜻이라 맞지 않음 ✗","se puso a: '~하기 시작했다'라 no와 함께 쓰면 '울리기 시작하지 않았다'가 됨 ✗","volvió: volver a 없이 sonar와 바로 연결되지 않음 ✗","dejó de: '멈추다'로 no dejó de sonar(계속 울렸다) → 정답 ✓"]},{"id":"G94","q":"Si tuviera la oportunidad, ____ un país cada mes.","o":["visitaré","visitaría","visitara","visito"],"a":1,"k":"si + 접속법 과거, 가능법","t":"기회가 있다면 매달 한 나라씩 방문할 텐데.","e":"현재 사실과 다르거나 가능성이 낮은 가정은 'Si + 접속법 과거, 가능법'으로 말합니다. Si tuviera...에 맞춰 주절은 가능법 visitaría(방문할 텐데)가 정답입니다.","x":["visitaré: 직설법 미래는 si + 현재형 조건과 짝을 이룸 ✗","visitaría: 가능법으로 가정의 결과 → 정답 ✓","visitara: 접속법 과거라 주절에 쓰지 않음(si절에 씀) ✗","visito: 직설법 현재라 가정문의 결과로 맞지 않음 ✗"]},{"id":"G95","q":"Los lápices de colores ____ tiene Ernesto. Pídeselos a él.","o":["les","los","ø","las"],"a":1,"k":"목적어 앞세우기 + 대명사","t":"색연필은 에르네스토가 가지고 있어. 그에게 달라고 해.","e":"직접목적어(los lápices)를 강조하려고 문장 앞에 두면, 동사 앞에 같은 것을 가리키는 직접목적격 대명사를 반드시 다시 씁니다. lápiz는 남성 명사이므로 복수 los를 씁니다: Los lápices los tiene Ernesto.","x":["les: 간접목적격(~에게)이라 '~을'을 나타낼 수 없음 ✗","los: 남성 복수 직접목적격으로 앞의 lápices를 받음 → 정답 ✓","ø: 목적어를 앞에 두면 대명사로 다시 받아야 함 ✗","las: 여성형이라 남성 명사 lápices와 맞지 않음 ✗"]},{"id":"G96","q":"Perdonen, ¿les ____ dejarme pasar primero? Es que tengo prisa...","o":["importe","importará","importara","importaría"],"a":3,"k":"정중한 가능법","t":"실례합니다, 제가 먼저 지나가도 될까요? 급해서요...","e":"'¿Le/Les importaría + 동사원형?'은 '~해 주실 수 있을까요?'라는 아주 정중한 부탁 표현입니다. 가능법(조건법)이 공손함을 더해 줍니다. 상대가 여러 명(perdonen)이라 les가 쓰였습니다.","x":["importe: 접속법 현재라 독립된 의문문에 쓰지 않음 ✗","importará: 미래형은 공손한 부탁보다는 추측의 느낌이 강해 부자연스러움 ✗","importara: 접속법 과거라 주절 동사로 쓸 수 없음 ✗","importaría: 정중한 부탁의 가능법 → 정답 ✓"]},{"id":"G97","q":"No sé ____ de ellos desde hace años.","o":["alguna","algo","nada","alguno"],"a":2,"k":"이중부정 no ... nada","t":"몇 년째 그들에 대해 아무 소식도 모른다.","e":"no가 동사 앞에 있으면 뒤에는 nada(아무것도) 같은 부정어를 씁니다. No sé nada de ellos는 '그들에 대해 아무것도 모른다', 즉 '소식이 끊겼다'는 뜻입니다. desde hace años는 '몇 년 전부터'입니다.","x":["alguna: 긍정의 '어떤'이라 no와 짝이 되지 않음 ✗","algo: '무언가'라는 긍정어라 no와 함께 쓰지 않음 ✗","nada: no와 짝을 이루는 '아무것도' → 정답 ✓","alguno: 긍정어이며 명사 없이 이 자리에 맞지 않음 ✗"]},{"id":"G98","q":"____ que este verano el turismo se recuperará al cien por cien.","o":["Es dicho","Se dice","Se dicen","Se están diciendo"],"a":1,"k":"무인칭 se dice","t":"올여름에는 관광이 100% 회복될 것이라고들 한다.","e":"'Se dice que(~라고들 한다)'는 말하는 주체를 밝히지 않는 무인칭 표현입니다. 뒤의 que절 전체가 하나의 내용이므로 동사는 3인칭 단수 dice를 씁니다. Dicen que...도 같은 뜻입니다.","x":["Es dicho: ser + 과거분사의 수동형으로는 이렇게 말하지 않음 ✗","Se dice: 무인칭 '~라고들 한다' → 정답 ✓","Se dicen: 복수형이라 que절(단수 취급)과 맞지 않음 ✗","Se están diciendo: 복수 진행형이라 맞지 않음 ✗"]},{"id":"G99","q":"Seguro que están en casa, ____ veo las luces encendidas.","o":["debido a que","a causa de que","como","porque"],"a":3,"k":"근거의 porque","t":"분명 집에 있을 거야, 불이 켜져 있는 게 보이거든.","e":"porque는 주절 뒤에 와서 '왜 그렇게 말하는지' 근거를 대는 데에도 씁니다. 불이 켜진 것은 집에 있다는 판단의 근거입니다. debido a que, a causa de que는 실제 사건의 원인을 말할 때 쓰며, como는 문장 맨 앞에만 둡니다.","x":["debido a que: 실제 원인을 나타내는 격식 표현이라 판단의 근거에는 어색함 ✗","a causa de que: 실제 원인(불이 켜져서 집에 있다?)이 되어 논리가 맞지 않음 ✗","como: 이유의 como는 문장 맨 앞에만 오므로 이 위치에 맞지 않음 ✗","porque: 말하는 사람의 판단 근거를 덧붙임 → 정답 ✓"]},{"id":"G100","q":"Nadie esperaba que Ignacio ____ las oposiciones.","o":["aprobará","va a aprobar","aprobase","ha aprobado"],"a":2,"k":"esperar que + 접속법 과거","t":"이그나시오가 공무원 시험에 합격할 거라곤 아무도 기대하지 않았다.","e":"'esperar que(~하기를 기대하다)' 뒤에는 접속법을 씁니다. 주절이 과거(esperaba)이므로 접속법 과거 aprobase(=aprobara)가 정답입니다. oposiciones는 스페인의 '공무원·교원 임용 시험'입니다.","x":["aprobará: 직설법 미래라 esperar que 뒤에 맞지 않음 ✗","va a aprobar: 직설법이고 시제도 맞지 않음 ✗","aprobase: 과거 주절에 맞는 접속법 과거 → 정답 ✓","ha aprobado: 직설법 현재완료라 맞지 않음 ✗"]},{"id":"G101","q":"Eloy tiene 15 años, ____, todavía es menor de edad.","o":["en cambio","por el contrario","no obstante","es decir"],"a":3,"k":"담화표지 es decir","t":"엘로이는 15살이다, 즉 아직 미성년자다.","e":"'es decir'는 '즉, 다시 말해'라는 뜻으로 앞의 내용을 다른 말로 풀어 설명할 때 씁니다. 15살이라는 것을 '미성년자'로 바꿔 말하므로 정답입니다. o sea도 비슷한 뜻의 구어 표현입니다.","x":["en cambio: '반면에'라는 대조 표현이라 맞지 않음 ✗","por el contrario: '반대로'라는 뜻이라 맞지 않음 ✗","no obstante: '그럼에도 불구하고'라는 뜻이라 맞지 않음 ✗","es decir: '즉'으로 앞 내용을 풀어 설명 → 정답 ✓"]},{"id":"G102","q":"Nada más ____ a casa, me di cuenta de que había perdido la cartera.","o":["al volver","volviendo","volver","de volver"],"a":2,"k":"nada más + 동사원형","t":"집에 돌아오자마자 지갑을 잃어버린 걸 알았다.","e":"'nada más + 동사원형'은 '~하자마자'라는 뜻입니다. 동사원형을 바로 붙이며 전치사나 al을 넣지 않습니다. 같은 뜻으로 'al + 동사원형(al volver a casa)'이나 'en cuanto volví'도 쓸 수 있습니다.","x":["al volver: nada más와 al을 함께 쓰지 않음 ✗","volviendo: 현재분사는 nada más 뒤에 쓰지 않음 ✗","volver: nada más + 동사원형 → 정답 ✓","de volver: 전치사 de를 넣지 않음 ✗"]},{"id":"G103","q":"¿____ tus amigos españoles viven fuera de España?","o":["Cuántos de","Cuántos","Cuánto","Cuántas de"],"a":0,"k":"cuántos de","t":"너의 스페인 친구들 중 몇 명이 스페인 밖에 사니?","e":"'~ 중 몇 명'은 'cuántos/cuántas de + 정관사·소유사 + 명사'로 씁니다. amigos는 남성 복수이므로 Cuántos de tus amigos가 맞습니다. de 없이 cuántos tus amigos라고 하지 않습니다.","x":["Cuántos de: 남성 복수 + de로 '~ 중 몇 명' → 정답 ✓","Cuántos: 소유사 tus 앞에는 de가 필요함 ✗","Cuánto: 단수형이라 셀 수 있는 복수 명사와 맞지 않음 ✗","Cuántas de: 여성형이라 amigos(남성)와 맞지 않음 ✗"]},{"id":"G104","q":"El autobús ____ salió cinco minutos más tarde de lo previsto.","o":["se","ø","lo","le"],"a":1,"k":"salir(대명사 없음)","t":"버스는 예정보다 5분 늦게 출발했다.","e":"'출발하다, 떠나다'라는 뜻의 salir는 대명사 없이 씁니다. salirse는 '(길·선에서) 벗어나다, 넘치다'라는 다른 뜻입니다. más tarde de lo previsto는 '예정보다 늦게'라는 자주 쓰는 표현입니다.","x":["se: salirse는 '벗어나다/넘치다'라는 뜻이라 맞지 않음 ✗","ø: 대명사 없이 salir(출발하다) → 정답 ✓","lo: salir는 직접목적어를 갖지 않음 ✗","le: 간접목적어가 필요 없는 문장 ✗"]},{"id":"G105","q":"____ que más me gustó del cortometraje fue el final.","o":["Lo","Los","El","La"],"a":0,"k":"lo que","t":"그 단편 영화에서 내가 가장 마음에 들었던 건 결말이었다.","e":"'lo que'는 '~한 것'이라는 뜻의 중성 표현으로, 구체적인 명사를 가리키지 않고 내용 전체를 묶어 말할 때 씁니다. Lo que más me gustó(내가 가장 좋았던 것)가 자연스럽습니다.","x":["Lo: 중성 lo + que로 '~한 것' → 정답 ✓","Los: 남성 복수라 단수 동사 gustó·fue와 맞지 않음 ✗","El: 특정 남성 명사를 가리킬 때 쓰며 여기서는 앞에 명사가 없음 ✗","La: 특정 여성 명사를 가리킬 때 쓰며 여기서는 앞에 명사가 없음 ✗"]},{"id":"G106","q":"No ____ tan negativo, tienes que ver las cosas de otra forma.","o":["sed","sea","sé","seas"],"a":3,"k":"ser 부정명령(tú)","t":"그렇게 부정적으로 굴지 마, 다른 방식으로 바라봐야 해.","e":"뒤의 tienes로 보아 상대는 tú입니다. tú 부정명령은 'no + 접속법 현재'이므로 ser의 접속법 seas를 써서 No seas가 됩니다. 긍정명령이라면 Sé positivo(긍정적이 돼)입니다.","x":["sed: vosotros 긍정명령이라 no와 쓰지 않고 tú와도 맞지 않음 ✗","sea: usted에 대한 명령이라 tienes(tú)와 맞지 않음 ✗","sé: tú 긍정명령이라 no와 함께 쓰지 않음 ✗","seas: tú 부정명령 → 정답 ✓"]},{"id":"G107","q":"____ escuchar sus quejas constantemente.","o":["Me cansa","Cansan","Me cansan","Me cansas"],"a":0,"k":"cansar(동사원형 주어)","t":"그의 불평을 계속 듣는 게 지겹다.","e":"cansar는 gustar처럼 '지치게 하는 것'이 주어, '지친 사람'이 간접목적격 대명사(me)입니다. 주어가 동사원형 escuchar(듣는 것)이므로 동사는 3인칭 단수 cansa입니다. 뒤의 quejas는 escuchar의 목적어일 뿐 주어가 아닙니다.","x":["Me cansa: 동사원형 주어 + 3인칭 단수 → 정답 ✓","Cansan: 사람(me)이 빠졌고 복수라 맞지 않음 ✗","Me cansan: 복수라 동사원형 주어와 수가 맞지 않음 ✗","Me cansas: '네가 나를 지치게 한다'는 뜻이라 문장 구조와 맞지 않음 ✗"]},{"id":"G108","q":"¿Dónde ____ suele sentar tu madre cuando ve la tele? ¿En el sofá o en el sillón?","o":["le","se","ø","se le"],"a":1,"k":"재귀동사 sentarse","t":"너희 어머니는 TV 볼 때 보통 어디에 앉으시니? 소파야, 안락의자야?","e":"'앉다'는 재귀동사 sentarse를 씁니다. 'soler + 동사원형' 구문에서 재귀대명사는 soler 앞에 두거나(se suele sentar) 동사원형 뒤에 붙입니다(suele sentarse). 주어가 3인칭(tu madre)이므로 se가 정답입니다.","x":["le: 간접목적격이라 '앉다'의 재귀 의미가 없음 ✗","se: 3인칭 재귀대명사로 sentarse → 정답 ✓","ø: sentar만 쓰면 '(누군가를) 앉히다'가 되어 목적어가 필요함 ✗","se le: 간접목적어가 끼어들 이유가 없어 비문 ✗"]},{"id":"G109","q":"____ lo sabes todo, explícanoslo tú.","o":["Porque","Hasta que","Ya que","Aunque"],"a":2,"k":"ya que(이유)","t":"네가 다 알고 있으니까, 네가 우리에게 설명해 줘.","e":"'ya que'는 '~이니까, ~인 만큼'이라는 뜻으로 상대도 아는 이유를 문장 앞에 둘 때 자주 씁니다. porque는 보통 주절 뒤에 와서 문장 맨 앞에는 잘 쓰지 않습니다.","x":["Porque: 이유를 나타내지만 보통 문장 맨 앞에 두지 않음 ✗","Hasta que: '~할 때까지'라는 뜻이라 맞지 않음 ✗","Ya que: 문두에서 '~이니까'라는 이유 → 정답 ✓","Aunque: '비록 ~이지만'이라는 양보라 뜻이 맞지 않음 ✗"]},{"id":"G110","q":"Susana es más guapa aún ____ me dijiste.","o":["de lo que","del que","que lo","de que"],"a":0,"k":"más ... de lo que","t":"수사나는 네가 말해 준 것보다 훨씬 더 예쁘다.","e":"비교 대상이 명사가 아니라 '네가 말한 내용' 같은 절일 때는 'más/menos + 형용사 + de lo que + 동사'를 씁니다. guapa는 형용사이므로 중성 lo를 써서 de lo que me dijiste가 됩니다.","x":["de lo que: 형용사 비교 + 절일 때 쓰는 구조 → 정답 ✓","del que: 남성 명사를 비교할 때 쓰며 형용사 비교에는 맞지 않음 ✗","que lo: 이런 비교 구조는 없음 ✗","de que: 이 비교에는 lo가 필요해 틀림 ✗"]},{"id":"G111","q":"Si sigues trabajando tantas horas, no ____ tiempo para tus aficiones.","o":["habrás tenido","tendrías","habrías tenido","tendrás"],"a":3,"k":"si + 현재, 미래","t":"계속 그렇게 오래 일하면 취미에 쓸 시간이 없을 거야.","e":"현실적으로 일어날 수 있는 조건은 'Si + 직설법 현재, 직설법 미래(또는 현재·명령)'로 말합니다. Si sigues...에 맞춰 주절은 tendrás가 정답입니다.","x":["habrás tenido: 미래완료라 시제가 맞지 않음 ✗","tendrías: 가능법은 si + 접속법 과거와 짝을 이룸 ✗","habrías tenido: 과거 사실 반대 가정의 결과라 맞지 않음 ✗","tendrás: si + 현재와 짝을 이루는 미래 → 정답 ✓"]},{"id":"G112","q":"No ____ tarde, que vuestra madre se preocupa.","o":["volvéis","vuelvas","volved","volváis"],"a":3,"k":"vosotros 부정명령","t":"늦게 돌아오지 마, 너희 엄마가 걱정하시니까.","e":"뒤의 vuestra(너희의)로 보아 상대는 vosotros입니다. 부정명령은 'no + 접속법 현재'이므로 volver의 vosotros 접속법 volváis가 정답입니다. vosotros 접속법에서는 어간 모음 변화(o→ue)가 일어나지 않습니다.","x":["volvéis: 직설법 현재라 명령이 아님 ✗","vuelvas: tú 부정명령이라 vuestra와 맞지 않음 ✗","volved: vosotros 긍정명령이라 no와 함께 쓰지 않음 ✗","volváis: vosotros 부정명령 → 정답 ✓"]},{"id":"G113","q":"Intentad ____ el test antes de las cinco, por favor.","o":["a terminar","terminar","que termináis","que terminéis"],"a":1,"k":"intentar + 동사원형","t":"5시 전에 시험을 끝내도록 해 줘, 부탁해.","e":"intentar(시도하다)는 바로 동사원형을 목적어로 받습니다: intentar + 동사원형. 주어가 같으므로 que절이 아니라 동사원형 terminar를 씁니다. 전치사 a는 넣지 않습니다.","x":["a terminar: intentar 뒤에 전치사 a를 넣지 않음 ✗","terminar: intentar + 동사원형 → 정답 ✓","que termináis: 직설법 que절은 intentar와 쓰지 않음 ✗","que terminéis: 주어가 같아 que절이 필요 없음 ✗"]},{"id":"G114","q":"El detenido se negó ____ responder.","o":["en","a","de","por"],"a":1,"k":"negarse a","t":"체포된 사람은 대답하기를 거부했다.","e":"negarse(거부하다)는 전치사 a와 함께 써서 'negarse a + 동사원형'(~하기를 거부하다)이 됩니다. 예: Se negó a firmar. (그는 서명을 거부했다.)","x":["en: negarse와 쓰지 않는 전치사 ✗","a: negarse a + 동사원형 → 정답 ✓","de: negarse와 쓰지 않는 전치사 ✗","por: negarse와 쓰지 않는 전치사 ✗"]},{"id":"G115","q":"No me voy a marchar ____ me dé el dinero que me debe.","o":["mientras","hasta que","en cuanto","después de que"],"a":1,"k":"hasta que + 접속법","t":"당신이 나에게 빚진 돈을 줄 때까지 나는 떠나지 않을 거예요.","e":"'hasta que(~할 때까지)'가 아직 일어나지 않은 미래의 일을 가리키면 접속법을 씁니다(me dé). '돈을 받을 때까지 안 간다'는 뜻이므로 hasta que가 정답입니다.","x":["mientras: '~하는 동안'이라 의미가 맞지 않음 ✗","hasta que: '~할 때까지' + 접속법 → 정답 ✓","en cuanto: '~하자마자'라 '받자마자 안 떠난다'가 되어 논리가 맞지 않음 ✗","después de que: '~한 후에'라 '받고 나서 안 떠난다'가 되어 어색함 ✗"]},{"id":"G116","q":"El hombre ____ conocimos ayer es profesor de física.","o":["el que","al que","quien","el cual"],"a":1,"k":"인칭 a + 관계사","t":"우리가 어제 만난 그 남자는 물리 선생님이다.","e":"사람을 직접목적어로 쓸 때는 앞에 a를 붙입니다(conocimos al hombre). 관계절에서도 이 a가 남아 'al que(= a quien)'가 됩니다. 그래서 al que conocimos가 정답입니다.","x":["el que: 사람 목적어 앞의 a가 빠져 틀림 ✗","al que: a + el que로 사람 직접목적어 → 정답 ✓","quien: a 없이 quien만 쓰면 틀림(a quien은 가능) ✗","el cual: a가 빠졌고 이 위치에 어색함 ✗"]},{"id":"G117","q":"No me opongo ____ que mi hijo se case con ella. ¡Es su vida!","o":["a","con","en","de"],"a":0,"k":"oponerse a","t":"아들이 그녀와 결혼하는 것을 반대하지 않아. 그건 그 애 인생이잖아!","e":"oponerse(반대하다)는 전치사 a와 함께 씁니다: oponerse a algo / a que + 접속법. 뒤에 절이 오면 a que + 접속법(se case)이 됩니다.","x":["a: oponerse a(~에 반대하다) → 정답 ✓","con: oponerse와 쓰지 않는 전치사 ✗","en: oponerse와 쓰지 않는 전치사 ✗","de: oponerse와 쓰지 않는 전치사 ✗"]},{"id":"G118","q":"Tú ____ dijiste eso, ¿no te acuerdas?","o":["mismos","la misma","misma","mismas"],"a":2,"k":"mismo 일치","t":"네가 직접 그 말을 했잖아, 기억 안 나?","e":"'tú mismo/misma'는 '너 자신이, 네가 직접'이라는 강조 표현으로 mismo는 주어의 성·수에 맞춥니다. 보기 중 단수 tú에 맞는 형태는 여성 단수 misma뿐입니다(상대가 남자라면 tú mismo). 관사는 붙이지 않습니다.","x":["mismos: 복수라 단수 tú와 맞지 않음 ✗","la misma: 강조의 mismo 앞에는 관사를 붙이지 않음 ✗","misma: 단수 tú(여성)에 맞춘 강조 → 정답 ✓","mismas: 복수라 맞지 않음 ✗"]},{"id":"G119","q":"De todos esos, ¿____ es tu coche?","o":["quién","qué","cuánto","cuál"],"a":3,"k":"cuál(선택)","t":"그것들 중에서 어느 게 네 차야?","e":"여러 개 중 하나를 고르게 할 때 동사 ser 앞에서는 cuál을 씁니다. ¿Cuál es tu coche?는 '어느 것이 네 차니?'입니다. ¿Qué es...?는 '~가 무엇인가(정의)'를 물을 때 씁니다.","x":["quién: 사람을 물을 때 쓰므로 차에는 맞지 않음 ✗","qué: ser 앞의 qué는 정의를 묻는 질문이 되어 선택의 뜻이 안 됨 ✗","cuánto: '얼마나'라는 양을 묻는 말이라 맞지 않음 ✗","cuál: 여럿 중 선택 '어느 것' → 정답 ✓"]},{"id":"G120","q":"Ayer ____ hasta las tantas.","o":["estaba trabajando","he estado trabajando","trabajaba","estuve trabajando"],"a":3,"k":"단순과거 진행형","t":"어제 나는 밤늦게까지 일했다.","e":"'Ayer(어제)'처럼 끝난 과거 시점에서 일정 시간 동안 계속되다가 끝난 행동은 'estar 단순과거 + 현재분사'(estuve trabajando)로 표현합니다. hasta las tantas는 '밤늦게까지'라는 구어 표현입니다.","x":["estaba trabajando: 다른 사건의 배경이 될 때 쓰며 독립적으로 끝난 행동에는 어색함 ✗","he estado trabajando: 현재완료라 ayer와 함께 쓰지 않음(스페인 기준) ✗","trabajaba: 불완료과거로 습관·배경을 나타내 한정된 어제 일과 맞지 않음 ✗","estuve trabajando: 끝난 기간 동안의 지속 행동 → 정답 ✓"]},{"id":"G121","q":"Los bebés parecen ____ hambrientos.","o":["que están","estar","que estén","estando"],"a":1,"k":"parecer + 동사원형","t":"아기들이 배가 고픈 것 같다.","e":"'parecer + 동사원형'은 '~인 것 같다, ~처럼 보인다'라는 뜻입니다. 주어(los bebés)가 그대로 parecer의 주어가 되고 동사원형 estar가 뒤따릅니다. que절을 쓰려면 Parece que los bebés están hambrientos처럼 구조를 바꿔야 합니다.","x":["que están: 주어가 parecer 앞에 있을 때는 que절이 오지 않음 ✗","estar: parecer + 동사원형 → 정답 ✓","que estén: 접속법 que절이라 구조가 맞지 않음 ✗","estando: 현재분사는 parecer 뒤에 쓰지 않음 ✗"]},{"id":"G122","q":"Me encanta tu ____. ¿Dónde lo has comprado?","o":["pintalabios","pintas labios","pintalabio","pinta labios"],"a":0,"k":"복합명사 pintalabios","t":"네 립스틱 정말 예쁘다. 어디서 샀어?","e":"pintalabios(립스틱)는 동사 pintar + 명사 labios로 만든 복합명사로 한 단어로 붙여 쓰며, 단수와 복수가 같은 형태입니다(el pintalabios, los pintalabios). 비슷한 예: el paraguas(우산), el sacapuntas(연필깎이).","x":["pintalabios: 붙여 쓰는 복합명사로 단수도 -s → 정답 ✓","pintas labios: 띄어 쓰지 않고 동사 부분도 pinta여야 함 ✗","pintalabio: 단수라도 끝의 -s를 빼지 않음 ✗","pinta labios: 띄어 쓰지 않음 ✗"]},{"id":"G123","q":"¿____ no has visto la peli que te recomendé?","o":["Ahora","Todavía","Ya","Aun"],"a":1,"k":"todavía no","t":"내가 추천한 영화 아직도 안 봤어?","e":"'todavía no'는 '아직 ~않다'라는 뜻으로, 기대한 일이 아직 일어나지 않았을 때 씁니다. ¿Todavía no has visto...?는 '아직도 안 봤니?'라는 약간의 놀람을 담습니다. aun(악센트 없음)은 '~조차'라는 뜻이라 다릅니다.","x":["Ahora: '지금'이라는 뜻이라 맞지 않음 ✗","Todavía: todavía no(아직 ~않다) → 정답 ✓","Ya: ya no는 '더 이상 ~않다'라는 뜻이라 맞지 않음 ✗","Aun: 악센트 없는 aun은 '~조차'라는 뜻이라 맞지 않음(aún이면 '아직') ✗"]},{"id":"G124","q":"Ya me han dado ____ diploma. ¡Qué alegría!","o":["al","ø","la","el"],"a":3,"k":"-a로 끝나는 남성명사","t":"드디어 학위증을 받았어. 너무 기뻐!","e":"diploma는 -a로 끝나지만 그리스어에서 온 -ma 단어라 남성 명사입니다(el diploma). 비슷한 예: el problema, el tema, el idioma, el clima. 이미 정해진 '내' 학위증이므로 정관사 el을 씁니다.","x":["al: a + el이라 직접목적어 앞에 쓰지 않음 ✗","ø: 특정한 대상이라 관사 없이 쓰면 어색함 ✗","la: diploma는 남성 명사라 여성 관사는 틀림 ✗","el: 남성 명사 diploma의 정관사 → 정답 ✓"]},{"id":"G125","q":"____ cinco meses en México.","o":["Llevo","Estoy llevando","He llevado","Me llevo"],"a":0,"k":"llevar + 시간(기간)","t":"멕시코에 온 지 5개월 됐다.","e":"'llevar + 시간 + 장소/상태'는 '~에 있은 지 (시간)이 되다'라는 뜻입니다. Llevo cinco meses en México는 '멕시코에서 5개월째 지내고 있다'입니다. 이 뜻의 llevar는 진행형이나 재귀형으로 쓰지 않습니다.","x":["Llevo: 기간을 나타내는 llevar 현재형 → 정답 ✓","Estoy llevando: 이 뜻의 llevar는 진행형으로 쓰지 않음 ✗","He llevado: 현재완료라 현재까지 계속되는 상태 표현에 어색함 ✗","Me llevo: llevarse는 '가져가다'라는 다른 뜻 ✗"]},{"id":"G126","q":"Ya te lo he dicho varias veces, no ____ ropa sin habértela probado antes.","o":["compra","compres","compréis","comprad"],"a":1,"k":"tú 부정명령","t":"벌써 여러 번 말했잖아, 입어 보지도 않고 옷을 사지 마.","e":"뒤의 habértela(te = 너)로 보아 상대는 tú입니다. tú 부정명령은 'no + 접속법 현재'이므로 comprar의 접속법 compres가 정답입니다. sin habértela probado는 '그것을 입어 보지 않고'입니다.","x":["compra: tú 긍정명령이라 no와 쓰지 않음 ✗","compres: tú 부정명령 → 정답 ✓","compréis: vosotros 부정명령이라 te와 맞지 않음 ✗","comprad: vosotros 긍정명령이라 맞지 않음 ✗"]},{"id":"G127","q":"Me alegra ____ que te guste tu nuevo trabajo.","o":["de","a","ø","por"],"a":2,"k":"me alegra que","t":"네가 새 직장을 마음에 들어 해서 기뻐.","e":"alegrar는 gustar처럼 '기쁘게 하는 것'이 주어, '기쁜 사람'이 간접목적격(me)인 구조입니다: Me alegra que + 접속법. 전치사는 필요 없습니다. 재귀동사 alegrarse를 쓰면 Me alegro de que...처럼 de가 필요합니다.","x":["de: me alegro de que에서는 쓰지만 me alegra que에는 쓰지 않음 ✗","a: 이 구조에 쓰지 않는 전치사 ✗","ø: me alegra que + 접속법, 전치사 없음 → 정답 ✓","por: 이 구조에 쓰지 않는 전치사 ✗"]},{"id":"G128","q":"A lo mejor ____ ese programa por su poca audiencia.","o":["estén quitando","han quitado","hayan quitado","quitaran"],"a":1,"k":"a lo mejor + 직설법","t":"시청률이 낮아서 아마 그 프로그램을 없앴나 봐.","e":"'a lo mejor(아마, 어쩌면)'는 추측을 나타내지만 예외적으로 뒤에 직설법을 씁니다. 이미 일어났을 일을 추측하므로 현재완료 han quitado가 정답입니다. quizás, tal vez는 직설법·접속법 모두 가능합니다.","x":["estén quitando: 접속법이라 a lo mejor 뒤에 쓰지 않음 ✗","han quitado: 직설법 현재완료 → 정답 ✓","hayan quitado: 접속법이라 a lo mejor 뒤에 쓰지 않음 ✗","quitaran: 접속법 과거라 맞지 않음 ✗"]},{"id":"G129","q":"Me ____ mejor el examen si me hubiese esforzado más.","o":["saldría","había salido","salía","habría salido"],"a":3,"k":"과거 사실 반대 가정","t":"내가 더 노력했더라면 시험을 더 잘 봤을 텐데.","e":"과거 사실과 반대되는 가정은 'si + 접속법 과거완료(hubiese esforzado), 가능법 완료(habría + 과거분사)'로 말합니다. 그래서 habría salido가 정답입니다. salirle bien/mal algo a alguien은 '~가 잘/잘못되다'입니다.","x":["saldría: 단순 가능법은 현재·미래 가정의 결과라 과거 가정과 맞지 않음 ✗","había salido: 직설법 과거완료라 가정의 결과가 아님 ✗","salía: 직설법 불완료과거라 맞지 않음 ✗","habría salido: 가능법 완료로 과거 반대 가정의 결과 → 정답 ✓"]},{"id":"G130","q":"Está claro que ____ bien la gastronomía argentina.","o":["conocieran","hayan conocido","conocen","conozcan"],"a":2,"k":"está claro que + 직설법","t":"그들이 아르헨티나 음식을 잘 안다는 건 분명하다.","e":"'Está claro que(~는 분명하다)'처럼 확실함을 나타내는 표현 뒤에는 직설법을 씁니다. 그래서 conocer의 직설법 현재 conocen이 정답입니다. 부정 No está claro que 뒤에는 접속법을 씁니다.","x":["conocieran: 접속법 과거라 확실성 표현 뒤에 맞지 않음 ✗","hayan conocido: 접속법 현재완료라 맞지 않음 ✗","conocen: 직설법 현재 → 정답 ✓","conozcan: 접속법 현재라 맞지 않음 ✗"]},{"id":"G131","q":"En nuestra nueva casa ____ tiene su propio dormitorio.","o":["cada uno","cada","uno de cada uno","cada uno de"],"a":0,"k":"cada uno","t":"우리 새 집에서는 각자 자기 방이 있다.","e":"cada는 항상 뒤에 명사가 와야 합니다(cada persona). 명사 없이 '각자, 각각'이라고 쓰려면 대명사 cada uno/cada una를 씁니다. 그래서 cada uno tiene가 정답입니다.","x":["cada uno: 명사 없이 쓰는 '각자' → 정답 ✓","cada: 뒤에 명사가 와야 해 단독으로 쓸 수 없음 ✗","uno de cada uno: 이런 표현은 없음 ✗","cada uno de: 뒤에 de nosotros 같은 말이 와야 함 ✗"]},{"id":"G132","q":"Ojalá ____ mucho éxito.","o":["tienes","tendrías","tengas","tendrás"],"a":2,"k":"ojalá + 접속법 현재","t":"크게 성공하길 바라.","e":"ojalá 뒤에는 접속법을 씁니다. 상대의 앞날을 바라는, 실현 가능한 소망이므로 접속법 현재 tengas가 정답입니다. 축하·응원할 때 자주 쓰는 표현입니다.","x":["tienes: 직설법이라 ojalá 뒤에 쓰지 않음 ✗","tendrías: 가능법이라 ojalá 뒤에 쓰지 않음 ✗","tengas: 접속법 현재로 실현 가능한 바람 → 정답 ✓","tendrás: 직설법 미래라 ojalá 뒤에 쓰지 않음 ✗"]},{"id":"G133","q":"Eugenia, ____ es española, vive en Portugal.","o":["que","cual","el cual","ella que"],"a":0,"k":"설명적 관계절 que","t":"에우헤니아는 스페인 사람인데 포르투갈에 산다.","e":"쉼표로 둘러싸인 설명적 관계절(추가 정보를 덧붙이는 관계절)에서는 que, quien, la cual을 쓸 수 있습니다. 보기 중에는 que가 맞습니다. Eugenia는 여성이므로 el cual은 성이 맞지 않습니다.","x":["que: 설명적 관계절을 이끄는 관계대명사 → 정답 ✓","cual: 관사 없이 단독으로 쓸 수 없음 ✗","el cual: 남성형이라 여성 Eugenia와 맞지 않음(la cual은 가능) ✗","ella que: 이런 관계 구조는 없음 ✗"]},{"id":"G134","q":"____ reír cuando el niño se acercó a ellos.","o":["Vinieron a","Llegaron a","Se echaron a","Fueron a"],"a":2,"k":"echarse a + 동사원형","t":"아이가 그들에게 다가가자 그들은 웃음을 터뜨렸다.","e":"'echarse a + 동사원형'은 '갑자기 ~하기 시작하다'라는 뜻으로 특히 reír(웃다), llorar(울다), correr(뛰다)와 자주 씁니다. echarse a reír는 '웃음을 터뜨리다'입니다.","x":["Vinieron a: venir a는 '결국 ~하게 되다/~하러 오다'라는 뜻이라 맞지 않음 ✗","Llegaron a: '마침내 ~하기에 이르다'라는 뜻이라 맞지 않음 ✗","Se echaron a: '갑자기 ~하기 시작하다' → 정답 ✓","Fueron a: '~하러 갔다/~하려 했다'라는 뜻이라 맞지 않음 ✗"]},{"id":"G135","q":"¿Cuándo ____ que te habían seleccionado para el certamen?","o":["sabías","habías sabido","supieras","supiste"],"a":3,"k":"saber 단순과거(알게 되다)","t":"너는 대회에 선발됐다는 걸 언제 알았니?","e":"saber를 단순과거(supe, supiste)로 쓰면 '알게 되다, 알아내다'라는 순간적인 뜻이 됩니다. '언제 알게 됐는지' 특정 순간을 묻으므로 supiste가 정답입니다. 불완료과거 sabía는 '이미 알고 있었다'는 상태입니다.","x":["sabías: '알고 있었다'라는 상태라 '언제 알게 됐는지'와 맞지 않음 ✗","habías sabido: 과거완료라 시점이 맞지 않음 ✗","supieras: 접속법 과거라 의문문 주절에 쓰지 않음 ✗","supiste: 단순과거로 '알게 되었다' → 정답 ✓"]},{"id":"G136","q":"¿____ mucha gente en la fiesta de César?","o":["Hubo","Han habido","Hubieron","Habían"],"a":0,"k":"무인칭 haber 단수","t":"세사르의 파티에 사람이 많았니?","e":"'~이 있다'라는 존재의 haber는 무인칭이라 뒤의 명사가 복수여도 항상 3인칭 단수로 씁니다(hay, hubo, había, ha habido). 끝난 행사(파티)이므로 단순과거 hubo가 정답입니다. 중남미 구어에서 hubieron, habían을 쓰기도 하지만 표준 문법에서는 틀린 형태입니다.","x":["Hubo: 무인칭 haber의 단수 단순과거 → 정답 ✓","Han habido: 무인칭 haber는 복수로 쓰지 않음(ha habido가 맞음) ✗","Hubieron: 존재의 haber를 복수로 쓰는 흔한 오류 ✗","Habían: 복수형이고 시제도 맞지 않는 오류 형태 ✗"]},{"id":"G137","q":"Estamos interesados ____ trabajar con ustedes.","o":["de","a","en","sobre"],"a":2,"k":"interesado en","t":"저희는 귀사와 함께 일하는 데 관심이 있습니다.","e":"'estar interesado/a en + 명사·동사원형'은 '~에 관심이 있다'라는 뜻으로 전치사 en을 씁니다. 동사 interesarse도 en과 함께 씁니다(Me intereso en/por...). 비즈니스 이메일에서 자주 쓰는 표현입니다.","x":["de: interesado와 쓰지 않는 전치사 ✗","a: interesado와 쓰지 않는 전치사 ✗","en: interesado en(~에 관심 있는) → 정답 ✓","sobre: '~에 관해'라는 뜻으로 interesado와 쓰지 않음 ✗"]},{"id":"G138","q":"Juan se esfuerza menos ____ Pablo, por eso obtiene peores resultados.","o":["como","de","que","tanto que"],"a":2,"k":"menos ... que","t":"후안은 파블로보다 덜 노력해서 결과가 더 나쁘다.","e":"우열 비교는 'más/menos ... que + 비교 대상'으로 만듭니다. Juan se esfuerza menos que Pablo는 '후안은 파블로보다 덜 노력한다'입니다. 숫자 앞에서만 de를 씁니다(menos de diez).","x":["como: 동등비교(tanto como)에 쓰며 menos와는 쓰지 않음 ✗","de: 숫자 앞에서만 쓰므로 사람 비교에는 틀림 ✗","que: menos ... que(~보다 덜) → 정답 ✓","tanto que: '너무 ~해서'라는 결과 표현이라 맞지 않음 ✗"]},{"id":"G139","q":"____ que me den el alta médica esta semana.","o":["Pueden","Se puede","Puede","Puedo"],"a":2,"k":"puede que + 접속법","t":"이번 주에 퇴원 허가를 받을 수도 있어.","e":"'Puede que + 접속법'은 '~일지도 모른다'라는 가능성 표현으로, puede는 항상 3인칭 단수로 고정됩니다. que절의 주어(누군가가 나에게 퇴원 허가를 줌)와 상관없이 Puede que입니다. dar el alta는 '퇴원시키다'입니다.","x":["Pueden: 복수형으로 쓰지 않는 고정 표현 ✗","Se puede: '~할 수 있다(허용)'라는 뜻이라 맞지 않음 ✗","Puede: 3인칭 단수 고정의 puede que → 정답 ✓","Puedo: 1인칭이라 이 고정 표현에 맞지 않음 ✗"]},{"id":"G140","q":"Mi tía se ____ volvió vegetariana hace muchos años.","o":["lo","las","la","ø"],"a":3,"k":"volverse(~이 되다)","t":"우리 이모는 아주 오래전에 채식주의자가 되었다.","e":"'volverse + 형용사/명사'는 '~이 되다(성격·성향이 바뀌다)'라는 뜻으로 재귀대명사 se만 필요합니다. 이미 se가 있으므로 빈칸에는 아무것도 넣지 않습니다. 비슷한 표현: hacerse vegetariano.","x":["lo: volverse에는 직접목적격이 필요 없음 ✗","las: 가리킬 대상이 없어 비문 ✗","la: 가리킬 대상이 없어 비문 ✗","ø: se volvió만으로 완성 → 정답 ✓"]},{"id":"G141","q":"Gloria no ha llegado todavía, ____ se ha confundido con la hora.","o":["es posible que","puede","puede que","a lo mejor"],"a":3,"k":"a lo mejor + 직설법","t":"글로리아가 아직 안 왔네, 아마 시간을 착각했나 봐.","e":"빈칸 뒤의 동사 se ha confundido는 직설법입니다. 추측 표현 중 a lo mejor는 직설법과 쓰므로 정답입니다. es posible que, puede que는 접속법(se haya confundido)과 써야 합니다.","x":["es posible que: 접속법(se haya confundido)이 필요함 ✗","puede: que가 빠져 구조가 성립하지 않음 ✗","puede que: 접속법이 필요해 직설법 se ha confundido와 맞지 않음 ✗","a lo mejor: 직설법과 쓰는 추측 표현 → 정답 ✓"]},{"id":"G142","q":"¿Este es el lugar ____ os conocisteis papá y tú?","o":["adónde","dónde","de donde","donde"],"a":3,"k":"관계부사 donde","t":"여기가 아빠랑 너희가 처음 만난 곳이니?","e":"장소 명사(el lugar)를 꾸미는 관계부사 donde는 악센트 없이 씁니다(= en el que). 악센트가 있는 dónde, adónde는 의문사입니다. conocerse는 '서로 알게 되다, 처음 만나다'입니다.","x":["adónde: 악센트 있는 의문사이고 '어디로'라는 방향이라 맞지 않음 ✗","dónde: 악센트가 있으면 의문사라 관계절에 쓰지 않음 ✗","de donde: '~로부터'라는 출발점이라 의미가 맞지 않음 ✗","donde: 장소를 꾸미는 관계부사 → 정답 ✓"]},{"id":"G143","q":"Confío plenamente ____ ella.","o":["de","sobre","a","en"],"a":3,"k":"confiar en","t":"나는 그녀를 전적으로 믿는다.","e":"confiar(믿다, 신뢰하다)는 전치사 en과 함께 씁니다: confiar en alguien/algo. plenamente는 '전적으로, 완전히'입니다. 예: Confío en ti. (난 너를 믿어.)","x":["de: confiar와 쓰지 않는 전치사(fiarse de는 가능) ✗","sobre: confiar와 쓰지 않는 전치사 ✗","a: confiar와 쓰지 않는 전치사 ✗","en: confiar en(~을 믿다) → 정답 ✓"]},{"id":"G144","q":"____ sigáis haciendo tanto ruido, os van a echar de la sala.","o":["Con tal de que","Como","Si","Como si"],"a":1,"k":"조건의 como + 접속법","t":"너희가 계속 그렇게 시끄럽게 하면 강당에서 쫓겨날 거야.","e":"como가 접속법과 함께 쓰이면 '만약 ~하면'이라는 조건, 특히 경고·위협의 뉘앙스를 나타냅니다. Como sigáis...는 '계속 ~하면 (큰일 난다)'입니다. si는 접속법 현재와 쓰지 않으므로 Si seguís라고 해야 합니다.","x":["Con tal de que: '~하기만 한다면'이라는 바라는 조건이라 문맥과 맞지 않음 ✗","Como: 접속법과 함께 경고의 조건 '~하면' → 정답 ✓","Si: si 뒤에는 접속법 현재(sigáis)를 쓰지 않음 ✗","Como si: '마치 ~인 것처럼'이라 뜻이 맞지 않음 ✗"]},{"id":"G145","q":"Ahora no me apetece comer ____.","o":["algún","ningún","nada","algo"],"a":2,"k":"이중부정 no ... nada","t":"지금은 아무것도 먹고 싶지 않아.","e":"no가 동사 앞에 있으면 뒤에는 nada(아무것도) 같은 부정어를 씁니다. no me apetece comer nada는 '아무것도 먹고 싶지 않다'입니다. apetecer는 gustar처럼 쓰는 동사로 '~하고 싶다, 당기다'입니다(주로 스페인).","x":["algún: 명사 앞에 쓰는 긍정 형용사라 단독으로 쓸 수 없음 ✗","ningún: 명사 앞에 쓰는 형태라 단독으로 쓸 수 없음 ✗","nada: no와 짝을 이루는 '아무것도' → 정답 ✓","algo: 긍정어라 no 문장에서는 nada를 씀 ✗"]},{"id":"G146","q":"____ cuarenta años algunas cosas eran más complicadas que ahora.","o":["Desde","Desde hace","Hace","Desde hacía"],"a":2,"k":"hace + 시간(~전)","t":"40년 전에는 어떤 일들이 지금보다 더 복잡했다.","e":"'hace + 시간'은 '~전에'라는 뜻으로 과거의 특정 시점을 나타냅니다. Hace cuarenta años는 '40년 전에'입니다. desde hace는 '~ 전부터 (지금까지)'라는 지속을 나타내 과거 시점 묘사와 맞지 않습니다.","x":["Desde: 시간의 양(40년) 앞에는 desde만 쓰지 않음 ✗","Desde hace: '~ 전부터 지금까지'라는 지속이라 과거 묘사와 맞지 않음 ✗","Hace: '~ 전에' → 정답 ✓","Desde hacía: '그때보다 ~ 전부터'라는 과거 기준 지속이라 맞지 않음 ✗"]},{"id":"G147","q":"Estoy convencida ____ que tiene razón.","o":["a","de","en","sobre"],"a":1,"k":"convencido de que","t":"나는 그가 옳다고 확신한다.","e":"'estar convencido/a de + 명사·que절'은 '~을 확신하다'라는 뜻으로 전치사 de가 필요합니다. 확신을 나타내므로 que절에는 직설법(tiene)을 씁니다.","x":["a: convencido와 쓰지 않는 전치사 ✗","de: convencido de que(~을 확신하는) → 정답 ✓","en: convencido와 쓰지 않는 전치사 ✗","sobre: convencido와 쓰지 않는 전치사 ✗"]},{"id":"G148","q":"Juana me preguntó si me ____ la comida española.","o":["gustó","gustase","guste","gustaba"],"a":3,"k":"간접의문 + 시제 일치","t":"후아나는 나에게 스페인 음식을 좋아하는지 물었다.","e":"간접의문문 'preguntar si(~인지 묻다)'에는 직설법을 씁니다. 주절이 과거(preguntó)이고 원래 질문이 현재(¿Te gusta...?)였으므로 시제를 맞춰 불완료과거 gustaba로 바꿉니다.","x":["gustó: 단순과거라 '(그때) 좋았는지'가 되어 원래 현재 질문과 맞지 않음 ✗","gustase: 접속법은 si 간접의문문에 쓰지 않음 ✗","guste: 접속법 현재라 맞지 않음 ✗","gustaba: 현재 → 불완료과거로 시제 일치 → 정답 ✓"]},{"id":"G149","q":"Tanto si quieres ____, tienes que hacer los deberes de la escuela.","o":["como que no","como si no","que si no","como no"],"a":1,"k":"tanto si ... como si no","t":"원하든 원하지 않든 학교 숙제는 해야 해.","e":"'tanto si A como si B'는 'A이든 B이든'이라는 표현입니다. 앞에 tanto si quieres가 나왔으므로 짝으로 como si no(원하지 않든)를 씁니다. 같은 뜻으로 quieras o no도 자주 씁니다.","x":["como que no: 이 짝 표현에 맞지 않음 ✗","como si no: tanto si ... como si no(~든 아니든) → 정답 ✓","que si no: tanto와 짝이 되지 않음 ✗","como no: si가 빠져 짝 구조가 깨짐 ✗"]},{"id":"G150","q":"Dudo que ____ lo que está pasando en la empresa.","o":["están sabiendo","sepáis","sabéis","sabríais"],"a":1,"k":"dudar que + 접속법","t":"너희가 회사에서 무슨 일이 일어나고 있는지 알고 있을지 의심스럽다.","e":"'Dudo que(~인지 의심스럽다)'처럼 의심을 나타내는 동사 뒤에는 접속법을 씁니다. 상대가 vosotros이므로 saber의 vosotros 접속법 현재 sepáis가 정답입니다. 중남미에서는 sepan(ustedes)을 씁니다.","x":["están sabiendo: 직설법 진행형이고 saber는 진행형으로 잘 쓰지 않음 ✗","sepáis: vosotros 접속법 현재 → 정답 ✓","sabéis: 직설법이라 dudar que 뒤에 쓰지 않음 ✗","sabríais: 가능법이라 맞지 않음 ✗"]},{"id":"G151","q":"Me parece bien que ____ a tu madre al médico.","o":["acompañas","acompañarías","acompañes","acompañarás"],"a":2,"k":"감정·평가 + 접속법","t":"네가 어머니를 모시고 병원에 가는 건 좋은 생각 같아.","e":"'Me parece bien que ~(~하는 것이 좋다고 생각해)'처럼 어떤 일에 대한 평가·의견을 말하는 표현 뒤의 que절에는 접속법(바람·감정·평가를 나타낼 때 쓰는 동사 형태)을 씁니다. 주어가 tú이므로 acompañar의 접속법 현재 acompañes가 정답입니다. 예: Me parece bien que vengas. (네가 오는 거 좋아.)","x":["acompañas: 직설법 현재로, 평가 표현 뒤 que절에는 쓰지 않습니다 ✗","acompañarías: 가정법(조건법) 형태라 현재 평가 문장과 맞지 않습니다 ✗","acompañes: acompañar의 접속법 현재 2인칭 단수 → 정답 ✓","acompañarás: 직설법 미래라 평가 표현 뒤에 올 수 없습니다 ✗"]},{"id":"G152","q":"Nos veremos ____ siempre.","o":["dónde","adonde","donde","adónde"],"a":2,"k":"관계부사 donde","t":"늘 보던 곳에서 만나자.","e":"'donde siempre'는 '늘 (만나던) 그곳에서'라는 뜻으로, 장소를 가리키는 관계부사 donde를 씁니다. 의문문이나 간접 의문이 아니므로 악센트가 없는 donde가 맞습니다. 이동 방향(~로)이 아니라 만나는 장소를 말하므로 adonde도 아닙니다.","x":["dónde: 악센트가 있는 의문사(어디)로, 질문이 아니므로 ✗","adonde: '~로 (가는 곳)'처럼 이동 방향을 나타낼 때 씁니다. verse는 이동이 아니라 ✗","donde: 장소를 나타내는 관계부사 → 정답 ✓","adónde: '어디로?'라는 의문사로, 질문이 아니어서 ✗"]},{"id":"G153","q":"Ese no es un trabajo ____ estoy capacitado.","o":["con el cual","al cual","para el cual","del cual"],"a":2,"k":"전치사 + 관계대명사","t":"그건 내가 할 능력이 있는 일이 아니야.","e":"'estar capacitado para ~(~할 능력·자격이 있다)'는 전치사 para와 함께 씁니다. 관계절에서도 형용사가 요구하는 전치사를 관계대명사 앞에 그대로 두어 'para el cual'이 됩니다. 선행사 un trabajo가 남성 단수라서 el cual입니다.","x":["con el cual: capacitado는 con과 쓰지 않습니다 ✗","al cual: 'a + el cual'로, capacitado 뒤에 a는 오지 않습니다 ✗","para el cual: 'capacitado para'의 para를 살린 형태 → 정답 ✓","del cual: capacitado de라는 결합은 쓰지 않습니다 ✗"]},{"id":"G154","q":"No saldréis ____ terminéis vuestros deberes.","o":["para que","hasta que","antes de","hasta"],"a":1,"k":"hasta que + 접속법","t":"너희들은 숙제를 다 끝낼 때까지 나가지 못한다.","e":"'hasta que(~할 때까지)'는 뒤에 절(주어+동사)이 옵니다. 아직 일어나지 않은 미래의 일이므로 접속법 terminéis를 씁니다. terminéis는 vosotros 형태로 스페인에서 쓰며, 중남미에서는 ustedes(terminen)를 씁니다.","x":["para que: '~하도록(목적)'이라 '숙제를 끝내도록 나가지 않는다'는 어색한 뜻이 됩니다 ✗","hasta que: '~할 때까지' + 접속법 → 정답 ✓","antes de: 뒤에 동사원형이 와야 하고, 뜻도 '끝내기 전에'가 되어 ✗","hasta: 전치사라 뒤에 활용된 동사(절)가 바로 올 수 없습니다 ✗"]},{"id":"G155","q":"Si te ____ la cabeza, habla con tu doctora.","o":["va doliendo","sigue a doler","sigue doliendo","lleva doliendo"],"a":2,"k":"seguir + 현재분사","t":"계속 머리가 아프면 담당 의사 선생님과 상의해.","e":"'seguir + 현재분사(-ando/-iendo)'는 '계속 ~하고 있다'라는 뜻으로 어떤 상태가 이어지는 것을 나타냅니다. '머리가 계속 아프면'이므로 sigue doliendo가 정답입니다. 예: Sigue lloviendo. (계속 비가 와.)","x":["va doliendo: 'ir + 현재분사'는 '점점 ~해 간다'는 점진적 변화를 말해 어색합니다 ✗","sigue a doler: seguir 뒤에는 'a + 동사원형'이 아니라 현재분사가 옵니다 ✗","sigue doliendo: '계속 아프다' → 정답 ✓","lleva doliendo: 'llevar + 현재분사'는 보통 기간(dos días 등)과 함께 써야 자연스럽습니다 ✗"]},{"id":"G156","q":"____ que menos me gusta de esta ciudad es la falta de espacios verdes.","o":["La","Lo","ø","El"],"a":1,"k":"중성관사 lo que","t":"이 도시에서 내가 가장 싫어하는 점은 녹지 공간이 부족하다는 것이다.","e":"'lo que ~'는 '~하는 것(점)'이라는 뜻으로, 특정한 명사가 아니라 막연한 내용·사실을 가리킬 때 씁니다. 'Lo que menos me gusta'는 '내가 가장 덜 좋아하는 점'이라는 자주 쓰는 표현입니다. lo는 성(남성/여성)이 없는 중성 관사입니다.","x":["La: 여성 명사를 가리킬 때 쓰는데, 여기서는 특정 명사가 없어 ✗","Lo: 막연한 '~하는 것'을 나타내는 중성 관사 → 정답 ✓","ø: 관사 없이 que만 쓰면 문장이 성립하지 않습니다 ✗","El: 남성 명사를 가리킬 때 쓰는데, 가리키는 명사가 없어 ✗"]},{"id":"G157","q":"¿Cuándo van a abrir ____ aula de informática?","o":["una","el","la","alguna"],"a":1,"k":"el + 강세 a 여성명사","t":"컴퓨터실은 언제 여나요?","e":"aula(교실)는 여성 명사지만, 강세가 있는 a-/ha-로 시작하는 여성 단수 명사 앞에서는 발음 때문에 정관사 la 대신 el을 씁니다. 여기서는 특정한 '그 컴퓨터실'을 말하므로 정관사 el이 정답입니다. 예: el agua fría(차가운 물), el hambre(배고픔).","x":["una: 부정관사(하나의)라 특정 교실을 말하는 문맥과 맞지 않습니다 ✗","el: 강세 a로 시작하는 여성 명사 aula 앞의 정관사 → 정답 ✓","la: aula처럼 강세 a로 시작하는 여성 단수 명사 앞에서는 쓰지 않습니다 ✗","alguna: '어떤'이라는 뜻이라 언제 여느냐는 질문과 어울리지 않습니다 ✗"]},{"id":"G158","q":"Ángela es una amiga ____ de la infancia.","o":["de mí","mi","mía","la mía"],"a":2,"k":"소유형용사 후치형","t":"앙헬라는 어릴 적부터의 내 친구다.","e":"'una amiga mía'는 '내 친구 중 한 명'이라는 뜻으로, 명사 뒤에 오는 소유형용사(mío, mía, míos, mías)를 씁니다. 부정관사 una와 함께 쓸 때는 앞에 오는 mi를 쓸 수 없고, 뒤에 오는 mía를 명사 성·수에 맞춰 씁니다.","x":["de mí: 'de + 나'라는 형태는 소유를 나타낼 때 쓰지 않습니다 ✗","mi: 명사 앞에만 오는 형태라 una amiga 뒤에 쓸 수 없습니다 ✗","mía: 명사 뒤에 오는 여성 단수 소유형용사 → 정답 ✓","la mía: '내 것'이라는 소유대명사로, 명사 뒤에 붙이지 않습니다 ✗"]},{"id":"G159","q":"Ese vestido no es ____ más me gusta, prefiero aquel.","o":["que","al que","el que","lo que"],"a":2,"k":"관계사 el que","t":"그 원피스는 내가 가장 좋아하는 게 아니야, 저게 더 좋아.","e":"'el que'는 '~하는 것(그것)'이라는 뜻으로, 앞에 나온 남성 명사(vestido)를 대신합니다. 'no es el que más me gusta'는 '내가 가장 좋아하는 그 옷이 아니다'라는 뜻입니다. 막연한 내용이 아닌 구체적인 물건을 가리키므로 lo que가 아니라 el que입니다.","x":["que: 선행사 없이 단독으로 쓰면 '~하는 것'이라는 뜻이 되지 않습니다 ✗","al que: 'a + el que'로, gustar 구문의 주어 자리에 a가 붙으면 안 됩니다 ✗","el que: 남성 명사 vestido를 대신하는 '~하는 것' → 정답 ✓","lo que: 막연한 내용을 가리키는 중성형이라 구체적인 옷에는 ✗"]},{"id":"G160","q":"¿Quién crees que ____ el primer premio?","o":["se llevase","se va a llevar","se está llevando","se lleve"],"a":1,"k":"creer 의문문 + 직설법","t":"누가 1등 상을 탈 거라고 생각해?","e":"'¿Quién crees que ~?(누가 ~라고 생각해?)'처럼 creer(믿다, 생각하다)가 긍정이나 의문사 의문문으로 쓰이면 que절에는 직설법이 옵니다. 앞으로의 일을 예측하므로 'ir a + 동사원형' 미래 표현인 se va a llevar가 정답입니다. 'llevarse un premio'는 '상을 타다'라는 뜻입니다.","x":["se llevase: 접속법 과거로, 부정이 아닌 creer 뒤에서는 쓰지 않습니다 ✗","se va a llevar: 직설법 미래 표현 'ir a + 동사원형' → 정답 ✓","se está llevando: '지금 타고 있는 중'이라 상을 받는 상황과 어색합니다 ✗","se lleve: 접속법 현재로, 긍정 의문의 creer 뒤에는 쓰지 않습니다 ✗"]},{"id":"G161","q":"____ claro que no nos van a ayudar sin pedir nada a cambio.","o":["Quedan","Quede","Se queda","Queda"],"a":3,"k":"quedar claro","t":"그들이 대가 없이 우리를 도와주지 않을 거라는 게 분명하다.","e":"'quedar claro que ~'는 '~라는 것이 분명하다, 명확해지다'라는 관용 표현입니다. 주어는 que 이하의 내용(하나의 사실)이므로 3인칭 단수 queda를 씁니다. 사실을 단언하므로 직설법이며, 재귀형 quedarse는 쓰지 않습니다.","x":["Quedan: 3인칭 복수라 주어인 que절(단수 취급)과 맞지 않습니다 ✗","Quede: 접속법이라 사실을 단언하는 주절에 쓰지 않습니다 ✗","Se queda: quedarse는 '머물다'라는 뜻이라 이 표현에 쓰지 않습니다 ✗","Queda: 'queda claro que(~은 분명하다)' → 정답 ✓"]},{"id":"G162","q":"Aunque ____ mucho, no me siento preparada para aprobar.","o":["estudiaba","habría estudiado","estaba estudiando","haya estudiado"],"a":3,"k":"aunque + 접속법","t":"공부를 많이 했지만(했을지라도), 합격할 준비가 됐다는 느낌이 들지 않는다.","e":"aunque(~이지만, ~이더라도) 뒤에 접속법을 쓰면 그 내용을 '중요하지 않다'고 넘기거나 상대도 아는 사실로 다룹니다. 이미 공부한 일(현재완료 시점)이고 지금의 느낌과 연결되므로 접속법 현재완료 haya estudiado가 정답입니다. 비교: Aunque llueva, saldré. (비가 오더라도 나갈 거야.)","x":["estudiaba: 직설법 불완료과거로, 현재의 느낌(me siento)과 시제가 어울리지 않습니다 ✗","habría estudiado: 가정법(조건완료)이라 '공부했을 텐데'라는 뜻이 되어 ✗","estaba estudiando: 과거 진행이라 현재 시점 문장과 맞지 않습니다 ✗","haya estudiado: 접속법 현재완료로 양보(~했더라도)를 나타냄 → 정답 ✓"]},{"id":"G163","q":"Felipe nunca ha tenido ____ coche, prefiere usar los medios de transporte públicos.","o":["el","ø","una","un"],"a":1,"k":"관사 생략","t":"펠리페는 차를 가져 본 적이 없다. 대중교통을 이용하는 걸 더 좋아한다.","e":"tener(가지다)의 목적어가 '차라는 것 자체'처럼 종류를 말할 때, 특히 부정문에서는 관사를 생략하는 것이 자연스럽습니다. 'No tengo coche(나는 차가 없다)'처럼 개수가 아니라 소유 여부를 말하기 때문입니다. 따라서 아무것도 넣지 않는 ø가 정답입니다.","x":["el: 특정한 '그 차'가 아니므로 정관사는 ✗","ø: 소유 여부를 말할 때 관사를 생략 → 정답 ✓","una: coche는 남성 명사라 여성 관사는 문법적으로 틀립니다 ✗","un: 문법적으로 불가능하진 않지만, 일반적인 소유 여부를 말할 때는 관사를 생략하는 게 자연스럽습니다 ✗"]},{"id":"G164","q":"Nos aseguró que esa noche ____, pero en realidad estaba de fiesta.","o":["estaba estudiando","estudiaba","ha estado estudiando","estuviera estudiando"],"a":0,"k":"과거진행 (간접화법)","t":"그는 그날 밤 공부하고 있었다고 우리에게 장담했지만, 사실은 파티를 하고 있었다.","e":"과거의 특정 순간(그날 밤)에 '진행 중이던 행동'을 말할 때 'estar의 불완료과거 + 현재분사'인 estaba estudiando를 씁니다. 뒷부분 'estaba de fiesta(파티 중이었다)'와도 대조를 이룹니다. 'asegurar(장담하다)'는 사실을 단언하는 동사라서 뒤에 직설법이 옵니다.","x":["estaba estudiando: 그 순간 진행 중이던 행동(과거진행) → 정답 ✓","estudiaba: 불완료과거로 반복·습관 느낌이 강해, 특정 순간의 진행을 강조하는 데는 덜 적절합니다 ✗","ha estado estudiando: 현재완료진행이라 과거 이야기(aseguró) 속 시제와 맞지 않습니다 ✗","estuviera estudiando: 접속법이라 단언 동사 asegurar 뒤에 쓰지 않습니다 ✗"]},{"id":"G165","q":"No me gusta que me ____ cuando estoy hablando.","o":["interrumpen","interrumpan","interrumpo","están interrumpiendo"],"a":1,"k":"gustar que + 접속법","t":"나는 내가 말하고 있을 때 (사람들이) 끼어드는 게 싫다.","e":"'(No) me gusta que ~'처럼 감정·좋고 싫음을 나타내는 표현 뒤의 que절에는 접속법을 씁니다. 주어가 막연한 '사람들'이므로 3인칭 복수 interrumpan(끼어들다, 방해하다)이 정답입니다. 3인칭 복수로 '일반 사람들'을 나타내는 용법입니다.","x":["interrumpen: 직설법이라 감정 표현 뒤 que절에는 ✗","interrumpan: interrumpir의 접속법 현재 3인칭 복수 → 정답 ✓","interrumpo: 1인칭 직설법 '내가 끼어든다'라는 뜻이라 의미·형태 모두 ✗","están interrumpiendo: 직설법 진행형이라 감정 표현 뒤에 쓰지 않습니다 ✗"]},{"id":"G166","q":"No dispongo ____ dinero suficiente para tener una casa propia.","o":["al","por el","del","con el"],"a":2,"k":"disponer de","t":"나는 내 집을 마련할 만큼 충분한 돈이 없다.","e":"disponer는 '(~을) 가지고 있다, 이용할 수 있다'라는 뜻일 때 항상 전치사 de와 함께 'disponer de ~'로 씁니다. 여기서 de + el = del이 됩니다. 예: Disponemos de poco tiempo. (우리는 시간이 별로 없다.)","x":["al: 'a + el'로, disponer 뒤에 a는 오지 않습니다 ✗","por el: disponer por라는 결합은 없습니다 ✗","del: 'disponer de + el' → 정답 ✓","con el: '~을 가지고 있다'는 뜻으로 disponer con은 쓰지 않습니다 ✗"]},{"id":"G167","q":"A los vecinos les ____ la lotería.","o":["tocaba","estaba tocando","estuvo tocando","ha tocado"],"a":3,"k":"현재완료 (tocar)","t":"이웃들이 복권에 당첨됐다.","e":"'tocar la lotería'는 '(누구에게) 복권이 당첨되다'라는 뜻으로, 당첨된 사람을 간접목적격(les)으로 씁니다. 복권 당첨은 한 번에 끝나는 완료된 일이고 지금과 관련된 소식이므로 현재완료 ha tocado가 정답입니다. 중남미에서는 같은 의미로 단순과거 tocó(Les tocó la lotería)를 더 자주 씁니다.","x":["tocaba: 불완료과거라 반복·배경을 나타내 한 번의 당첨과 맞지 않습니다 ✗","estaba tocando: 진행형이라 순간적인 당첨 사건에 어색합니다 ✗","estuvo tocando: 일정 기간 계속된 행동을 뜻해 당첨과 맞지 않습니다 ✗","ha tocado: 완료된 사건을 현재와 연결하는 현재완료 → 정답 ✓"]},{"id":"G168","q":"Es lógico que tu esposa ____ orgullosa de ti.","o":["esté","es","sea","está"],"a":0,"k":"es lógico que + 접속법","t":"네 아내가 너를 자랑스러워하는 건 당연하다.","e":"'Es lógico que ~(~는 당연하다)'처럼 가치 판단을 나타내는 표현 뒤에는 접속법을 씁니다. 또 'orgulloso/a de ~(~을 자랑스러워하는)'는 감정 상태를 나타내 estar와 함께 쓰므로 estar의 접속법 esté가 정답입니다. ser orgulloso는 '거만하다, 자존심이 세다'라는 성격을 뜻합니다.","x":["esté: estar의 접속법 현재, '자랑스러워하다'라는 상태 → 정답 ✓","es: 직설법이라 가치 판단 표현 뒤에 쓰지 않습니다 ✗","sea: 접속법이긴 하지만 ser orgullosa는 '거만하다'라는 성격이 되어 뜻이 달라집니다 ✗","está: estar는 맞지만 직설법이라 ✗"]},{"id":"G169","q":"Vamos a ahorrar para que ____ comprar nuestra propia vivienda.","o":["podamos","podríamos","pudiéramos","podemos"],"a":0,"k":"para que + 접속법","t":"우리가 우리 집을 살 수 있도록 저축할 거야.","e":"'para que(~하도록)'는 목적을 나타내며 뒤에는 항상 접속법이 옵니다. 주절이 미래(vamos a ahorrar)이므로 접속법 현재 podamos를 씁니다. 주절이 과거라면 pudiéramos가 됩니다. 예: Ahorramos para que pudiéramos viajar. (여행할 수 있도록 저축했다.)","x":["podamos: 접속법 현재 1인칭 복수 → 정답 ✓","podríamos: 가정법(조건법)이라 para que 뒤에 쓰지 않습니다 ✗","pudiéramos: 접속법 과거로, 주절이 과거일 때 씁니다 ✗","podemos: 직설법이라 para que 뒤에 올 수 없습니다 ✗"]},{"id":"G170","q":"Marcelo ____ parece muy joven. ¿Cuántos años tendrá?","o":["ø","lo","se le","se"],"a":0,"k":"parecer (대명사 없음)","t":"마르셀로는 아주 젊어 보인다. 몇 살일까?","e":"'parecer + 형용사'는 '~해 보인다'라는 뜻이고, 주어(Marcelo)만 있으면 대명사가 필요 없습니다. '나에게 젊어 보인다'라고 하려면 'Marcelo me parece joven'처럼 간접목적격을 넣지만, 여기서는 그런 대상이 없으므로 ø가 정답입니다. parecerse(닮다)와 혼동하지 마세요.","x":["ø: 'parecer + 형용사(~해 보인다)'에는 대명사가 필요 없음 → 정답 ✓","lo: 직접목적격(그를)이라 parecer 구문에 쓰지 않습니다 ✗","se le: '그에게 ~하게 되다'라는 구조라 이 문장과 맞지 않습니다 ✗","se: parecerse는 '~와 닮다'라는 뜻이라 의미가 달라집니다 ✗"]},{"id":"G171","q":"Tengo que enviar esta carta ____ correo.","o":["en","por","sobre","a"],"a":1,"k":"전치사 por (수단)","t":"이 편지를 우편으로 보내야 한다.","e":"전달·통신 수단을 나타낼 때는 전치사 por를 씁니다. 'por correo(우편으로)', 'por teléfono(전화로)', 'por correo electrónico(이메일로)'처럼 굳어진 표현입니다. 단, 교통수단은 'en coche(차로)'처럼 en을 씁니다.","x":["en: 교통수단에 쓰며, 우편에는 쓰지 않습니다 ✗","por: 통신·전달 수단 'por correo(우편으로)' → 정답 ✓","sobre: '~위에, ~에 관하여'라는 뜻이라 ✗","a: 방향(~에게, ~로)을 나타내 수단 표현으로 쓰지 않습니다 ✗"]},{"id":"G172","q":"No es capaz ____ distinguir entre el bien y el mal.","o":["sobre","de","en","a"],"a":1,"k":"capaz de","t":"그는 선과 악을 구별할 줄 모른다.","e":"'ser capaz de + 동사원형'은 '~할 능력이 있다, ~할 수 있다'라는 뜻으로 항상 전치사 de를 씁니다. 부정문 'no es capaz de ~'는 '~할 줄 모른다, ~하지 못한다'가 됩니다. 예: Es capaz de todo. (그는 무슨 짓이든 할 수 있다.)","x":["sobre: '~에 관하여'라는 뜻이라 capaz와 쓰지 않습니다 ✗","de: 'capaz de + 동사원형' → 정답 ✓","en: capaz en이라는 결합은 없습니다 ✗","a: capaz a는 틀린 형태입니다 ✗"]},{"id":"G173","q":"Estoy sin blanca, ____ no pueda comprar nada hasta que cobre el sueldo.","o":["por lo que","por lo tanto","de ahí que","así que"],"a":2,"k":"de ahí que + 접속법","t":"나는 빈털터리라서, 월급을 받을 때까지 아무것도 살 수 없다.","e":"'de ahí que(그래서, 그 때문에)'는 결과를 나타내는 연결어인데, 특이하게 뒤에 접속법이 옵니다. 빈칸 뒤의 pueda가 접속법이므로 de ahí que가 정답입니다. 나머지 por lo que, por lo tanto, así que는 모두 '그래서'라는 뜻이지만 뒤에 직설법(puedo)이 와야 합니다. 'estar sin blanca'는 스페인에서 쓰는 '빈털터리이다'라는 관용 표현입니다.","x":["por lo que: '그래서'라는 뜻이지만 뒤에 직설법(puedo)이 옵니다 ✗","por lo tanto: '따라서'라는 뜻이며 직설법과 쓰여 pueda와 맞지 않습니다 ✗","de ahí que: 결과를 나타내며 접속법과 함께 씀 → 정답 ✓","así que: '그러니까'라는 뜻으로 직설법이 와야 해서 ✗"]},{"id":"G174","q":"¿____ te ha parecido el documental?","o":["Cómo","Qué","Cuánto","Cuál"],"a":1,"k":"¿Qué te ha parecido?","t":"그 다큐멘터리 어땠어?","e":"어떤 것에 대한 의견을 물을 때 '¿Qué te ha parecido ~?(~ 어땠어? 어떻게 생각해?)'라는 표현을 씁니다. 대답은 'Me ha parecido interesante(재미있었어)'처럼 합니다. 지역에 따라 '¿Cómo te pareció?'도 쓰지만, 교재는 표준 표현인 ¿Qué te ha parecido?를 정답으로 봅니다. 중남미에서는 단순과거 '¿Qué te pareció?'를 더 많이 씁니다.","x":["Cómo: 일부 지역에서 쓰기도 하지만, 의견을 묻는 표준 표현은 qué입니다 ✗","Qué: '¿Qué te ha parecido?(어땠어?)' → 정답 ✓","Cuánto: '얼마나'라는 양을 묻는 말이라 의견을 묻는 데 맞지 않습니다 ✗","Cuál: 여러 개 중 '어느 것'을 물을 때 쓰므로 ✗"]},{"id":"G175","q":"Tengo un libro que ____ la vida de Dalí.","o":["está narrando","narra","narro","narre"],"a":1,"k":"관계절 + 직설법","t":"나는 달리의 생애를 이야기하는 책을 한 권 가지고 있다.","e":"관계절의 선행사가 실제로 존재하고 알려진 것(내가 가지고 있는 책)이면 관계절 동사는 직설법을 씁니다. 책 내용의 특징을 말하므로 직설법 현재 narra(이야기하다, 서술하다)가 정답입니다. 비교: Busco un libro que narre... (그런 내용의 책을 찾고 있다 → 존재 여부가 불확실해 접속법)","x":["está narrando: 진행형은 책의 내용처럼 지속적 특징을 말할 때 쓰지 않습니다 ✗","narra: 존재하는 선행사에 대한 직설법 현재 → 정답 ✓","narro: 1인칭(내가 이야기한다)이라 주어 un libro와 맞지 않습니다 ✗","narre: 접속법이라 실제로 가지고 있는 책에는 쓰지 않습니다 ✗"]},{"id":"G176","q":"Según ____, ¿qué deberíamos hacer ahora?","o":["tú","ti","te","a ti"],"a":0,"k":"según + 주격 대명사","t":"네 생각에는 우리가 지금 무엇을 해야 할까?","e":"según(~에 따르면)은 특이하게 전치사 뒤인데도 주격 대명사(yo, tú)를 씁니다. 그래서 'según tú(네 말로는, 네 생각에는)', 'según yo'가 됩니다. 같은 성질의 단어로 entre(entre tú y yo)가 있습니다. 대부분의 전치사 뒤에는 mí, ti를 씁니다(para ti).","x":["tú: según 뒤에는 주격 대명사 → 정답 ✓","ti: 일반 전치사 뒤 형태지만 según 뒤에는 쓰지 않습니다 ✗","te: 목적격 대명사라 전치사 뒤에 올 수 없습니다 ✗","a ti: según 뒤에 a를 넣지 않습니다 ✗"]},{"id":"G177","q":"¿Por qué te empeñas ____ negar la evidencia?","o":["de","en","a","con"],"a":1,"k":"empeñarse en","t":"왜 너는 명백한 사실을 굳이 부정하려고 고집하니?","e":"'empeñarse en + 동사원형'은 '~하겠다고 고집하다, 기를 쓰고 ~하다'라는 뜻으로 항상 전치사 en을 씁니다. 예: Se empeñó en pagar la cuenta. (그는 계산하겠다고 고집했다.) 비슷한 동사로 insistir en(~을 고집하다)도 en을 씁니다.","x":["de: empeñarse de라는 결합은 없습니다 ✗","en: 'empeñarse en(~하려고 고집하다)' → 정답 ✓","a: empeñarse 뒤에 a는 쓰지 않습니다 ✗","con: empeñarse con은 틀린 결합입니다 ✗"]},{"id":"G178","q":"No te preocupes, mamá, volveré a la hora que me ____.","o":["digas","dirías","decir","dirás"],"a":0,"k":"관계절 + 접속법(미래)","t":"걱정 마요, 엄마. 엄마가 말하는 시간에 돌아올게요.","e":"아직 정해지지 않은 미래의 것을 가리키는 관계절에는 접속법을 씁니다. 엄마가 앞으로 정해 줄 시간이므로 '(엄마가) 말하는 시간에'는 decir의 접속법 현재 digas가 됩니다. 주절이 미래(volveré)라도 관계절에는 미래형을 쓰지 않습니다.","x":["digas: 미정의 미래를 가리키는 관계절의 접속법 → 정답 ✓","dirías: 가정법(조건법)이라 '말할 텐데'라는 뜻이 되어 ✗","decir: 동사원형이라 주어(tú)가 있는 절에 쓸 수 없습니다 ✗","dirás: 직설법 미래는 이런 관계절에 쓰지 않습니다 ✗"]},{"id":"G179","q":"Esta es la pintura ____ la que te hablé.","o":["en","con","de","a"],"a":2,"k":"hablar de + 관계사","t":"이것이 내가 너에게 말했던 그 그림이다.","e":"'hablar de ~'는 '~에 대해 말하다'라는 뜻입니다. 관계절 'te hablé de la pintura'에서 전치사 de를 관계대명사 앞으로 옮기면 'de la que te hablé'가 됩니다. 선행사 la pintura가 여성 단수라 la que를 씁니다.","x":["en: hablar en은 '~(언어)로 말하다'라는 뜻이라 ✗","con: hablar con은 '~와 이야기하다'로 사람과 쓰여 그림에는 어색합니다 ✗","de: 'hablar de(~에 대해 말하다)' → 정답 ✓","a: hablar a는 '~에게 말하다'로 대상이 사람이어야 합니다 ✗"]},{"id":"G180","q":"Necesito contactar con un traductor ____ hable francés y español.","o":["que","cual","el que","quien"],"a":0,"k":"관계대명사 que","t":"프랑스어와 스페인어를 할 줄 아는 번역가에게 연락해야 해.","e":"전치사 없이 바로 이어지는 일반적인 관계절에서는 관계대명사 que를 씁니다. 또 아직 특정되지 않은 '그런 번역가'를 찾는 것이므로 관계절 동사가 접속법 hable입니다. 'contactar con ~'은 '~와 연락하다'라는 뜻입니다.","x":["que: 전치사 없는 일반 관계절의 관계대명사 → 정답 ✓","cual: 관사 없이 단독으로 관계대명사로 쓰지 않습니다(el cual 형태로 씀) ✗","el que: 전치사 없는 제한적 관계절에서는 쓰지 않습니다 ✗","quien: 사람을 가리키지만, 쉼표 없는 제한적 관계절의 주어로는 쓰지 않습니다 ✗"]},{"id":"G181","q":"¿Quieres que quedemos ____ la última vez?","o":["donde","adonde","de dónde","dónde"],"a":0,"k":"관계부사 donde","t":"지난번 그곳에서 만날까?","e":"'donde la última vez'는 '지난번에 (만났던) 곳에서'라는 뜻으로, 동사가 생략된 관계부사 donde 구문입니다. 질문 문장이긴 하지만 빈칸 자리는 '어디?'를 묻는 것이 아니라 장소를 가리키므로 악센트 없는 donde를 씁니다. 'quedar'는 스페인에서 '(약속하여) 만나다'라는 뜻으로 많이 씁니다.","x":["donde: 장소를 가리키는 관계부사 → 정답 ✓","adonde: '~로(방향)'라는 뜻이라 만나는 장소에는 맞지 않습니다 ✗","de dónde: '어디에서부터?'라는 의문 표현이라 ✗","dónde: 악센트가 있는 의문사로, 여기서는 '어디?'를 묻는 게 아니라서 ✗"]},{"id":"G182","q":"Antes me gustaba que me ____ mi madre a la escuela, pero ahora prefiero ir solo.","o":["lleve","llevó","llevaría","llevara"],"a":3,"k":"접속법 과거 (gustar)","t":"예전에는 엄마가 나를 학교에 데려다주는 게 좋았는데, 지금은 혼자 가는 게 더 좋다.","e":"'gustar que ~' 뒤에는 접속법이 오고, 주절이 과거(me gustaba)이므로 시제를 맞춰 접속법 과거 llevara를 씁니다. 이것을 '시제 일치'라고 합니다. 현재라면 'Me gusta que me lleve'가 됩니다. llevara 대신 llevase도 같은 뜻으로 씁니다.","x":["lleve: 접속법 현재라 주절이 과거(gustaba)일 때는 ✗","llevó: 직설법 단순과거라 감정 표현 뒤에 쓰지 않습니다 ✗","llevaría: 가정법(조건법)이라 que절 접속법 자리에 맞지 않습니다 ✗","llevara: 주절 과거에 맞춘 접속법 과거 → 정답 ✓"]},{"id":"G183","q":"Se escaparon de noche para que nadie los ____.","o":["vio","veía","vería","viera"],"a":3,"k":"para que + 접속법 과거","t":"그들은 아무도 자기들을 보지 못하도록 밤에 도망쳤다.","e":"목적을 나타내는 'para que(~하도록)' 뒤에는 항상 접속법을 씁니다. 주절이 단순과거(se escaparon)이므로 접속법 과거 viera가 정답입니다. 'nadie los viera'에서 los는 '그들을'이라는 직접목적격 대명사입니다.","x":["vio: 직설법 단순과거라 para que 뒤에 쓸 수 없습니다 ✗","veía: 직설법 불완료과거라 ✗","vería: 가정법(조건법)이라 para que 뒤에 쓰지 않습니다 ✗","viera: 과거 주절에 맞춘 접속법 과거 → 정답 ✓"]},{"id":"G184","q":"____ señora Suárez ha cancelado su cita médica.","o":["La","Una","Un","ø"],"a":0,"k":"경칭 앞 정관사","t":"수아레스 부인이 진료 예약을 취소했다.","e":"señor, señora, doctor 같은 경칭 뒤에 이름을 붙여 그 사람에 대해 이야기할 때는 앞에 정관사(el, la)를 붙입니다. 그래서 'La señora Suárez'가 됩니다. 단, 그 사람에게 직접 말을 걸 때는 관사를 쓰지 않습니다. 예: Buenos días, señora Suárez. (안녕하세요, 수아레스 부인.)","x":["La: 경칭 + 이름으로 3인칭으로 말할 때의 정관사 → 정답 ✓","Una: 부정관사라 특정 인물을 가리키는 문장과 맞지 않습니다 ✗","Un: 남성 부정관사라 señora와 성이 맞지 않습니다 ✗","ø: 직접 부를 때는 관사를 빼지만 3인칭 서술에서는 관사가 필요합니다 ✗"]},{"id":"G185","q":"¿Por qué no le pides a tu jefa que te ____ unos días libres?","o":["de","dé","da","dará"],"a":1,"k":"dé (접속법, 악센트)","t":"상사에게 며칠 휴가를 달라고 부탁하는 게 어때?","e":"'pedir que ~(~해 달라고 부탁하다)' 뒤의 que절에는 접속법을 씁니다. dar의 접속법 현재 3인칭 단수는 dé이고, 전치사 de(~의)와 구별하기 위해 악센트를 붙입니다. 'días libres'는 '쉬는 날, 휴가'라는 뜻입니다.","x":["de: 악센트 없는 de는 전치사(~의)라서 동사 자리에 올 수 없습니다 ✗","dé: dar의 접속법 현재 3인칭 단수 → 정답 ✓","da: 직설법이라 pedir que 뒤에 쓰지 않습니다 ✗","dará: 직설법 미래라 부탁 표현 뒤에 쓰지 않습니다 ✗"]},{"id":"G186","q":"Esther siempre dice ____ piensa.","o":["lo que","el que","que","la que"],"a":0,"k":"lo que (~하는 것)","t":"에스테르는 항상 생각하는 것을 그대로 말한다.","e":"'lo que ~'는 '~하는 것'이라는 뜻으로, 특정 명사가 아닌 막연한 내용을 가리킵니다. 'dice lo que piensa'는 '생각하는 것을 말한다', 즉 솔직하게 말한다는 뜻입니다. 선행사가 없으므로 중성형 lo que를 씁니다.","x":["lo que: 막연한 내용 '~하는 것' → 정답 ✓","el que: 앞에 나온 남성 명사를 대신할 때 쓰는데 그런 명사가 없습니다 ✗","que: 'dice que piensa'는 '생각한다고 말한다'라는 다른 뜻이 됩니다 ✗","la que: 여성 명사를 대신할 때 쓰므로 ✗"]},{"id":"G187","q":"Mis padres están ____ la casa de los vecinos.","o":["a","hasta","hacia","en"],"a":3,"k":"전치사 en (장소)","t":"우리 부모님은 이웃집에 계신다.","e":"estar(있다)처럼 어떤 장소에 '있음'을 나타낼 때는 전치사 en(~에)을 씁니다. 'estar en casa(집에 있다)', 'estar en la oficina(사무실에 있다)'처럼 씁니다. a는 ir a(~로 가다)처럼 이동 방향을 나타낼 때 씁니다.","x":["a: 이동 방향(~로)을 나타내 estar와 함께 위치를 말할 때는 ✗","hasta: '~까지'라는 범위·끝점이라 위치 표현에 맞지 않습니다 ✗","hacia: '~쪽으로'라는 방향이라 ✗","en: 위치(~에 있다) → 정답 ✓"]},{"id":"G188","q":"No entendemos que ____ por esa tontería.","o":["te enfades","te enfadas","estás enfadándote","has enfadado"],"a":0,"k":"entender que + 접속법","t":"우리는 네가 그런 시시한 일로 화를 내는 게 이해가 안 돼.","e":"'No entiendo que ~'는 '~하는 것이 이해가 안 된다'라는 뜻으로, 상대의 행동에 대한 놀람·불만(평가)을 나타내 que절에 접속법을 씁니다. enfadarse(화내다)의 접속법 현재 2인칭 te enfades가 정답입니다. 중남미에서는 enfadarse 대신 enojarse를 많이 씁니다(te enojes).","x":["te enfades: 평가·감정을 나타내는 접속법 현재 → 정답 ✓","te enfadas: 직설법이라 이 문맥에서는 ✗","estás enfadándote: 직설법 진행형이라 ✗","has enfadado: 재귀대명사 te가 빠져 있고 직설법이라 ✗"]},{"id":"G189","q":"Marina ____ parece mucho a su madre.","o":["le","la","ø","se"],"a":3,"k":"parecerse a","t":"마리나는 엄마를 많이 닮았다.","e":"'parecerse a ~'는 재귀동사로 '~와 닮다'라는 뜻입니다. 주어가 Marina(3인칭 단수)이므로 재귀대명사 se를 씁니다. parecer(~처럼 보이다)와 뜻이 다르니 주의하세요. 예: Me parezco a mi padre. (나는 아빠를 닮았다.)","x":["le: 간접목적격이라 '~에게 ~처럼 보이다'가 되어 뜻이 맞지 않습니다 ✗","la: 직접목적격(그녀를)이라 이 구조에 쓰지 않습니다 ✗","ø: se 없이 parecer만 쓰면 '닮다'라는 뜻이 되지 않습니다 ✗","se: 'parecerse a(~를 닮다)'의 재귀대명사 → 정답 ✓"]},{"id":"G190","q":"Ese es el hospital ____ que nació mi hija.","o":["para el","en el","al","del"],"a":1,"k":"en el que (장소)","t":"저기가 내 딸이 태어난 병원이다.","e":"'nacer en ~(~에서 태어나다)'처럼 장소를 나타내는 전치사 en을 관계대명사 앞에 두어 'en el que'가 됩니다. 선행사 el hospital이 남성 단수이므로 el que입니다. 'en el que' 대신 'donde'를 써도 같은 뜻입니다(el hospital donde nació).","x":["para el: '~을 위한'이라는 목적이라 태어난 장소와 맞지 않습니다 ✗","en el: 'nacer en'의 장소 전치사 en → 정답 ✓","al: 'a + el'로 방향을 나타내 '태어난 곳'에 쓰지 않습니다 ✗","del: 'de + el'로 '~로부터'라는 뜻이라 ✗"]},{"id":"G191","q":"Es vergonzoso que les ____ en ese tono a sus padres.","o":["hable","está hablando","hablaría","habla"],"a":0,"k":"es + 형용사 + que + 접속법","t":"그가 부모님께 그런 말투로 말하는 건 부끄러운 일이다.","e":"'Es vergonzoso que ~(~하는 것은 부끄러운 일이다)'처럼 'ser + 평가 형용사 + que' 구문 뒤에는 접속법을 씁니다. 그래서 hablar의 접속법 현재 3인칭 hable가 정답입니다. 'en ese tono'는 '그런 말투(어조)로'라는 뜻입니다.","x":["hable: 평가 표현 뒤 접속법 현재 → 정답 ✓","está hablando: 직설법 진행형이라 ✗","hablaría: 가정법(조건법)이라 ✗","habla: 직설법이라 평가 표현 뒤에 쓰지 않습니다 ✗"]},{"id":"G192","q":"¿Podrías poner estos libros ____ la mesa del profesor?","o":["a","para","hacia","en"],"a":3,"k":"전치사 en (위치)","t":"이 책들을 선생님 책상 위에 올려 줄 수 있니?","e":"poner(놓다)와 함께 어디에 두는지를 말할 때는 전치사 en(~에, ~위에)을 씁니다. 'poner en la mesa'는 '책상 위에 놓다'입니다. 위에 있음을 강조하려면 'sobre la mesa'도 쓸 수 있습니다.","x":["a: 이동 방향을 나타내 '놓는 위치'에는 쓰지 않습니다 ✗","para: '~을 위해, ~용으로'라는 뜻이라 ✗","hacia: '~쪽으로'라는 방향이라 ✗","en: 놓는 위치(~에) → 정답 ✓"]},{"id":"G193","q":"____ aquella época se encontraba trabajo fácilmente.","o":["De","Con","En","A"],"a":2,"k":"en + 시기","t":"그 시절에는 일자리를 쉽게 구할 수 있었다.","e":"시대·시기를 나타낼 때는 전치사 en을 씁니다. 'en aquella época(그 시절에)', 'en verano(여름에)', 'en 1990(1990년에)'처럼 씁니다. 'se encontraba trabajo'는 무인칭 se 구문으로 '(사람들은) 일자리를 구했다'는 뜻입니다.","x":["De: 'de + 시기'는 '~의, ~부터'라는 뜻이라 ✗","Con: '~와 함께'라는 뜻이라 시기 표현에 맞지 않습니다 ✗","En: 시기를 나타내는 en → 정답 ✓","A: 'a las tres(3시에)'처럼 시각에 쓰며 época에는 쓰지 않습니다 ✗"]},{"id":"G194","q":"Recibirá su pedido ____ dos semanas.","o":["a","desde","entre","dentro de"],"a":3,"k":"dentro de (시간)","t":"2주 후에 주문하신 상품을 받으실 겁니다.","e":"'dentro de + 기간'은 '(지금부터) ~ 후에'라는 뜻으로 미래 시점을 말할 때 씁니다. 예: Vuelvo dentro de una hora. (한 시간 뒤에 돌아올게.) 'en dos semanas'도 비슷한 뜻으로 쓰며, 특히 중남미에서 자주 씁니다.","x":["a: 'a los dos días(이틀 후에)'처럼 정관사와 함께 과거 이야기에 쓰는 형태라 ✗","desde: '~부터'라는 시작점이라 ✗","entre: '~사이에'라는 뜻이라 기간 하나만으로는 어색합니다 ✗","dentro de: '~ 후에'(미래) → 정답 ✓"]},{"id":"G195","q":"¿Cuándo ____ estos edificios?","o":["fueron restaurado","fue restaurados","fue restaurado","fueron restaurados"],"a":3,"k":"수동태 (일치)","t":"이 건물들은 언제 복원되었나요?","e":"수동태는 'ser + 과거분사'로 만들고, ser와 과거분사 모두 주어에 성·수를 맞춥니다. 주어 estos edificios가 남성 복수이므로 fueron(ser 3인칭 복수 과거) + restaurados(남성 복수)가 됩니다. 이것을 능동으로 바꾸면 '¿Cuándo restauraron estos edificios?'입니다.","x":["fueron restaurado: 과거분사가 단수라 복수 주어와 맞지 않습니다 ✗","fue restaurados: ser가 단수라 복수 주어와 맞지 않습니다 ✗","fue restaurado: 둘 다 단수라 복수 주어 edificios와 맞지 않습니다 ✗","fueron restaurados: 동사·분사 모두 남성 복수에 일치 → 정답 ✓"]},{"id":"G196","q":"En esta barriada ____ muy bien.","o":["se viven","nos vivimos","se vive","nos vive"],"a":2,"k":"무인칭 se","t":"이 동네에서는 아주 살기 좋다.","e":"특정 주어 없이 '사람들은 일반적으로 ~한다'라고 말할 때는 '무인칭 se + 3인칭 단수 동사'를 씁니다. 'se vive bien'은 '(사람들이) 잘 산다, 살기 좋다'는 뜻입니다. 목적어가 없는 자동사(vivir)는 항상 단수로 씁니다.","x":["se viven: 무인칭 se 구문은 vivir 같은 자동사일 때 단수로만 씁니다 ✗","nos vivimos: vivir는 재귀동사가 아니라 nos를 붙이지 않습니다 ✗","se vive: 무인칭 se + 3인칭 단수 → 정답 ✓","nos vive: 대명사와 동사의 인칭이 맞지 않는 틀린 형태입니다 ✗"]},{"id":"G197","q":"No falté a la reunión porque ____ enfermo, sino porque mi auto se había averiado.","o":["estuviera","habría estado","habré estado","estaría"],"a":0,"k":"no porque + 접속법","t":"내가 회의에 빠진 건 아파서가 아니라, 차가 고장 났기 때문이었다.","e":"'no porque A, sino porque B'(A 때문이 아니라 B 때문에)에서 부정되는 이유 A에는 접속법을 씁니다. 실제 이유가 아니라 부정하는 내용이기 때문입니다. 주절이 과거이므로 접속법 과거 estuviera가 정답입니다. 'auto'는 중남미에서 많이 쓰고 스페인에서는 'coche'를 주로 씁니다.","x":["estuviera: 부정되는 이유에 쓰는 접속법 과거 → 정답 ✓","habría estado: 가정법(조건완료)이라 '아팠을 텐데'라는 뜻이 되어 ✗","habré estado: 직설법 미래완료라 과거 문맥과 맞지 않습니다 ✗","estaría: 가정법(조건법)이라 부정되는 이유 자리에 쓰지 않습니다 ✗"]},{"id":"G198","q":"Alfonso ____ dos años en un taller de mecánica.","o":["dejó de trabajar","empezó a trabajar","llevó trabajando","estuvo trabajando"],"a":3,"k":"estar + 현재분사 (기간)","t":"알폰소는 자동차 정비소에서 2년 동안 일했다.","e":"과거에 일정 기간 동안 계속된 행동이 끝났을 때는 'estar의 단순과거 + 현재분사'(estuvo trabajando)를 씁니다. 'dos años(2년 동안)'라는 기간 표현과 잘 어울립니다. 'llevar + 현재분사'는 보통 현재까지 이어지는 기간에 씁니다(Lleva dos años trabajando = 2년째 일하고 있다).","x":["dejó de trabajar: '일을 그만두었다'라서 '2년'이라는 기간과 맞지 않습니다 ✗","empezó a trabajar: '일하기 시작했다'라서 기간 표현과 어울리지 않습니다 ✗","llevó trabajando: llevar + 현재분사는 주로 현재/불완료과거로 쓰며 단순과거로는 어색합니다 ✗","estuvo trabajando: 과거 일정 기간 계속된 행동 → 정답 ✓"]},{"id":"G199","q":"Tanto si te gusta ____ no, vas a hacer tus deberes ahora mismo.","o":["como si","o si","y si","o bien"],"a":0,"k":"tanto si... como si","t":"좋든 싫든, 너는 지금 당장 숙제를 할 거야.","e":"'tanto si A como si B'는 'A든 B든 상관없이'라는 뜻의 상관 표현입니다. 'Tanto si te gusta como si no'는 '네가 좋아하든 좋아하지 않든'이라는 뜻으로 자주 쓰입니다. tanto와 짝을 이루는 말은 como입니다.","x":["como si: 'tanto si ~ como si ~'의 짝 → 정답 ✓","o si: tanto와 짝을 이루지 않습니다 ✗","y si: '그리고 만약'이라는 뜻이라 tanto 구문에 맞지 않습니다 ✗","o bien: '또는'이라는 뜻이지만 tanto si와 짝을 이루지 않습니다 ✗"]},{"id":"G200","q":"____ de salir cuando me di cuenta de que me había dejado la cartera en casa.","o":["He acabado","Había acabado","Acababa","Acabé"],"a":2,"k":"acabar de + 동사원형","t":"막 나가려던 참에 지갑을 집에 두고 온 것을 깨달았다.","e":"'acabar de + 동사원형'은 '방금 ~했다'라는 뜻입니다. 과거 이야기에서 '그때 막 ~했었다'라고 할 때는 불완료과거 acababa de를 씁니다. 그 순간의 배경을 나타내고, 이어지는 사건(me di cuenta)은 단순과거로 씁니다. 예: Acababa de llegar cuando sonó el teléfono. (막 도착했을 때 전화가 울렸다.)","x":["He acabado: 현재완료라 과거 이야기(me di cuenta)와 시제가 맞지 않습니다 ✗","Había acabado: 대과거라 '방금 ~했었다'는 acabar de 표현에서는 쓰지 않습니다 ✗","Acababa: 과거의 '막 ~했다' = acababa de → 정답 ✓","Acabé: 'acabé de salir'는 '나가는 것을 끝냈다'라는 뜻이 되어 어색합니다 ✗"]},{"id":"G201","q":"Vivo ____ las afueras de Madrid.","o":["de","a","sobre","para"],"a":1,"k":"전치사 a (las afueras)","t":"나는 마드리드 교외에 산다.","e":"'las afueras(교외, 외곽)'는 '~ 바깥쪽'이라는 거리 개념이 있어 'a las afueras de ~'라는 표현이 널리 쓰입니다. 표준적으로는 'en las afueras'도 많이 쓰지만, 보기 중에서는 a가 정답입니다. 예: Viven a las afueras de la ciudad. (그들은 도시 외곽에 산다.)","x":["de: 'vivo de'는 '~으로 먹고산다'라는 다른 뜻이 됩니다 ✗","a: 'a las afueras de(~의 교외에)' → 정답 ✓","sobre: '~위에'라는 뜻이라 어울리지 않습니다 ✗","para: '~을 위해'라는 목적을 나타내 ✗"]},{"id":"G202","q":"Podemos vernos ____ te venga mejor.","o":["donde","adónde","dónde","adonde"],"a":0,"k":"donde + 접속법","t":"너한테 더 편한 곳에서 만나도 돼.","e":"'donde te venga mejor'는 '너에게 더 편한 곳에서'라는 뜻의 관계부사 구문입니다. 아직 정해지지 않은 장소라 동사가 접속법(venga)입니다. 질문이 아니므로 악센트 없는 donde를 쓰고, 이동 방향(~로)이 아니라 장소이므로 adonde도 아닙니다. 'venir bien/mejor'는 '(시간·장소가) 편하다, 형편이 좋다'는 뜻입니다.","x":["donde: 장소를 나타내는 관계부사 → 정답 ✓","adónde: '어디로?'를 묻는 의문사라 ✗","dónde: '어디?'를 묻는 의문사라 평서문에 쓰지 않습니다 ✗","adonde: 이동 방향을 나타내 vernos(만나다)와 맞지 않습니다 ✗"]},{"id":"G203","q":"¿Por qué se fue sin despedirse ____ nadie?","o":["con","por","de","a"],"a":2,"k":"despedirse de","t":"그는 왜 아무에게도 작별 인사를 하지 않고 떠났을까?","e":"'despedirse de ~'는 '~에게 작별 인사를 하다'라는 뜻으로 항상 전치사 de를 씁니다. 'sin despedirse de nadie'는 '누구에게도 인사하지 않고'입니다. 예: Me despedí de mis amigos. (친구들에게 작별 인사를 했다.)","x":["con: despedirse con은 쓰지 않습니다 ✗","por: despedirse por는 틀린 결합입니다 ✗","de: 'despedirse de(~에게 작별 인사하다)' → 정답 ✓","a: despedirse 뒤에 a를 쓰지 않습니다 ✗"]},{"id":"G204","q":"¿Qué os parece si quedamos ____ las 10 de la mañana?","o":["por","en","entre","sobre"],"a":3,"k":"sobre (대략의 시간)","t":"오전 10시쯤 만나는 거 어때?","e":"'sobre + 시각'은 '~시쯤, ~경에'라는 대략적인 시간을 나타냅니다. 'sobre las 10'은 '10시쯤'입니다. 같은 뜻으로 'hacia las 10', 'a eso de las 10'도 씁니다. 정확한 시각은 'a las 10'입니다.","x":["por: 'por la mañana(아침에)'처럼 시간대에 쓰며, 정확한 시각 앞에는 쓰지 않습니다 ✗","en: 시각 앞에는 en을 쓰지 않습니다 ✗","entre: '~ 사이에'라서 시각이 두 개 필요합니다(entre las 10 y las 11) ✗","sobre: '~시쯤' → 정답 ✓"]},{"id":"G205","q":"Tengo la sensación ____ que algo malo va a pasar.","o":["de","con","a","sobre"],"a":0,"k":"sensación de que","t":"뭔가 나쁜 일이 일어날 것 같은 느낌이 든다.","e":"명사 뒤에 que절이 그 명사의 내용을 설명할 때는 'de que'를 씁니다. 'la sensación de que ~(~라는 느낌)', 'la idea de que ~(~라는 생각)', 'el hecho de que ~(~라는 사실)'처럼 씁니다. de를 빼는 것은 틀린 용법(queísmo)입니다.","x":["de: '명사 + de que'로 내용 설명 → 정답 ✓","con: sensación con que는 쓰지 않습니다 ✗","a: sensación 뒤에 a que는 오지 않습니다 ✗","sobre: '~에 관한'이라는 뜻이지만 que절과 함께 이렇게 쓰지 않습니다 ✗"]},{"id":"G206","q":"No ____ en contactar con nosotros si tiene alguna pregunta.","o":["dudas","dudad","duda","dude"],"a":3,"k":"usted 부정 명령","t":"질문이 있으시면 주저하지 말고 저희에게 연락해 주세요.","e":"'si tiene'로 보아 상대를 usted(당신)로 대하고 있습니다. 부정 명령은 접속법 현재를 쓰므로 usted 부정 명령은 'No dude'가 됩니다. 'no dudar en + 동사원형'은 '주저하지 말고 ~하다'라는 공손한 안내문 표현입니다.","x":["dudas: 직설법 tú 형태라 부정 명령으로 쓰지 않습니다 ✗","dudad: vosotros 긍정 명령이라 no와 함께 쓸 수 없고 인칭도 맞지 않습니다 ✗","duda: tú 긍정 명령(또는 직설법)이라 ✗","dude: usted 부정 명령(접속법 현재) → 정답 ✓"]},{"id":"G207","q":"¿Cuántas veces por semana ____ el pelo?","o":["te lavas","tú lavas","lavas","lavarte"],"a":0,"k":"재귀동사 lavarse","t":"일주일에 몇 번 머리를 감니?","e":"자기 신체 일부를 씻을 때는 재귀동사 lavarse를 쓰고, 신체 부위에는 소유형용사 대신 정관사를 씁니다. 그래서 'te lavas el pelo(너는 머리를 감는다)'가 됩니다. 'lavas el pelo'만 쓰면 누구의 머리인지 불분명해집니다.","x":["te lavas: 재귀동사 lavarse의 tú 형태 → 정답 ✓","tú lavas: 재귀대명사 te가 없어 '자기 머리를 감다'라는 뜻이 되지 않습니다 ✗","lavas: 재귀대명사가 빠져 있어 ✗","lavarte: 동사원형이라 활용된 동사가 필요한 자리에 맞지 않습니다 ✗"]},{"id":"G208","q":"Supongo que ya ____ de lo ocurrido.","o":["hayas enterado","has enterado","te has enterado","te hayas enterado"],"a":2,"k":"suponer que + 직설법","t":"이미 그 일에 대해 알고 있을 거라고 생각해.","e":"'Supongo que ~(~라고 생각해/짐작해)'는 긍정 문장일 때 que절에 직설법을 씁니다. enterarse de(~을 알게 되다)는 재귀동사이므로 te가 꼭 필요해서 'te has enterado'가 정답입니다. 'lo ocurrido'는 '일어난 일'이라는 뜻입니다.","x":["hayas enterado: 재귀대명사 te가 없고 접속법이라 ✗","has enterado: 재귀대명사 te가 빠져 있습니다 ✗","te has enterado: 재귀동사 + 직설법 현재완료 → 정답 ✓","te hayas enterado: 접속법이라 긍정의 suponer 뒤에는 쓰지 않습니다 ✗"]},{"id":"G209","q":"____ del mal tiempo, fui a la playa a nadar un rato.","o":["Pese","Aun así","Incluso","A pesar"],"a":3,"k":"a pesar de","t":"날씨가 나빴지만 나는 잠시 수영하러 해변에 갔다.","e":"'a pesar de ~'는 '~에도 불구하고'라는 뜻으로 명사가 옵니다. 빈칸 뒤 'del mal tiempo'에 de가 이미 있으므로 'A pesar'가 정답입니다(a pesar + del). pese도 같은 뜻이지만 'pese a'로 써야 하므로 'pese del'은 틀립니다.","x":["Pese: 'pese a(~에도 불구하고)'로 쓰므로 뒤에 del이 오면 틀립니다 ✗","Aun así: '그럼에도'라는 부사구로, 뒤에 명사를 바로 받지 않습니다 ✗","Incluso: '~조차'라는 뜻이라 문장 구조와 맞지 않습니다 ✗","A pesar: 'a pesar de(~에도 불구하고)' → 정답 ✓"]},{"id":"G210","q":"No creo que Jesús ____ el examen. Se pasó todo el fin de semana estudiando.","o":["haya suspendido","ha suspendido","suspendió","hubiese suspendido"],"a":0,"k":"no creer que + 접속법","t":"헤수스가 시험에 떨어졌다고는 생각하지 않아. 주말 내내 공부했거든.","e":"'No creo que ~(~라고 생각하지 않는다)'처럼 creer가 부정문일 때는 의심을 나타내므로 que절에 접속법을 씁니다. 이미 끝난 시험 결과를 말하므로 접속법 현재완료 haya suspendido가 정답입니다. suspender는 스페인에서 '(시험에) 떨어지다'라는 뜻이고, 중남미에서는 reprobar를 주로 씁니다.","x":["haya suspendido: 부정의 creer 뒤 접속법 현재완료 → 정답 ✓","ha suspendido: 직설법이라 no creo que 뒤에 쓰지 않습니다 ✗","suspendió: 직설법 단순과거라 ✗","hubiese suspendido: 접속법 대과거로, 주절이 현재(no creo)일 때는 어색합니다 ✗"]},{"id":"G211","q":"No nos iremos de aquí ____ nos den la explicación que nos deben.","o":["hasta que","después de que","para cuando","mientras"],"a":0,"k":"hasta que + 접속법","t":"우리에게 해 주어야 할 설명을 들을 때까지 우리는 여기서 떠나지 않을 거야.","e":"'hasta que(~할 때까지)' 뒤에 아직 일어나지 않은 미래의 일이 오면 접속법을 씁니다. 빈칸 뒤 'nos den(우리에게 주다)'이 접속법이고, '설명을 들을 때까지 떠나지 않는다'는 뜻이므로 hasta que가 정답입니다.","x":["hasta que: '~할 때까지' + 접속법 → 정답 ✓","después de que: '~한 뒤에'라는 뜻이라 '설명을 들은 뒤에 떠나지 않는다'는 어색한 의미가 됩니다 ✗","para cuando: '~할 때쯤에는'이라는 뜻이라 문맥과 맞지 않습니다 ✗","mientras: '~하는 동안'이라 뜻이 맞지 않습니다 ✗"]},{"id":"G212","q":"Es tristísimo que ____ tanto paro juvenil en nuestro país.","o":["está","hay","esté","haya"],"a":3,"k":"haber 접속법","t":"우리나라에 청년 실업이 이렇게 많다는 것은 정말 슬픈 일이다.","e":"'Es tristísimo que ~(~는 아주 슬픈 일이다)'처럼 감정·평가 표현 뒤에는 접속법을 씁니다. '~이 있다'라는 존재 표현은 haber(hay)를 쓰므로, 그 접속법 현재 haya가 정답입니다. paro는 스페인에서 '실업'이라는 뜻이고, 중남미에서는 desempleo를 주로 씁니다.","x":["está: estar는 특정한 것의 위치를 말할 때 쓰며, 존재(~이 있다)를 말할 때는 haber를 씁니다 ✗","hay: haber는 맞지만 직설법이라 평가 표현 뒤에는 ✗","esté: 접속법이지만 estar라서 존재 표현에 맞지 않습니다 ✗","haya: haber의 접속법 현재 → 정답 ✓"]},{"id":"G213","q":"No entiendo ____ de lo que ha explicado la maestra.","o":["algún","nada","algo","alguno"],"a":1,"k":"이중부정 nada","t":"선생님이 설명한 것 중 아무것도 이해가 안 돼.","e":"스페인어는 부정문에서 이중부정을 씁니다. 'No entiendo nada'는 '아무것도 이해하지 못한다'라는 뜻으로, no와 nada가 함께 쓰여도 긍정이 되지 않습니다. algo(무언가)는 긍정문에서 쓰고, 부정문에서는 nada로 바뀝니다.","x":["algún: 명사 앞에 쓰는 형용사라 단독으로 쓸 수 없고, 부정문에도 맞지 않습니다 ✗","nada: 부정문의 '아무것도' → 정답 ✓","algo: '무언가'는 긍정문에서 쓰고 부정문에서는 nada로 바꿉니다 ✗","alguno: '어떤 것'이라는 뜻으로, 부정문에서는 ninguno를 씁니다 ✗"]},{"id":"G214","q":"¿No te das cuenta de que ____ equivocado?","o":["estés","estás","eres","seas"],"a":1,"k":"darse cuenta + 직설법","t":"네가 틀렸다는 걸 모르겠니?","e":"'darse cuenta de que ~(~을 깨닫다)'는 사실을 인식하는 동사라서 que절에 직설법을 씁니다. 부정 의문문이지만 '틀렸다'는 사실을 전제로 묻고 있으므로 직설법을 유지합니다. 또 'equivocado(틀린)'는 일시적 상태라 estar를 씁니다.","x":["estés: 접속법이라 사실을 인식하는 darse cuenta 뒤에는 ✗","estás: estar의 직설법 현재 → 정답 ✓","eres: ser equivocado는 쓰지 않습니다. 틀린 상태는 estar로 씁니다 ✗","seas: ser이고 접속법이라 둘 다 맞지 않습니다 ✗"]},{"id":"G215","q":"Nos ____ que hubieras venido a nuestra boda, pero entendemos que no pudieras.","o":["gustaría","habría gustado","gustaba","ha gustado"],"a":1,"k":"조건완료 + 접속법 대과거","t":"네가 우리 결혼식에 왔으면 좋았을 텐데, 그래도 올 수 없었던 건 이해해.","e":"과거에 이루어지지 않은 바람(~했으면 좋았을 텐데)은 '조건완료(habría + 과거분사)'로 표현합니다. 그래서 'Nos habría gustado que hubieras venido'가 됩니다. que절의 hubieras venido(접속법 대과거)도 과거의 이루어지지 않은 일을 나타냅니다.","x":["gustaría: 조건법 단순형은 현재·미래의 바람이라 과거 결혼식에는 ✗","habría gustado: 과거의 이루어지지 않은 바람(조건완료) → 정답 ✓","gustaba: 직설법 불완료과거라 '좋아했다'는 사실 서술이 되어 ✗","ha gustado: 현재완료라 '좋았다'는 사실이 되어 오지 않은 상황과 모순됩니다 ✗"]},{"id":"G216","q":"No te imaginas ____ bien que se come en ese restaurante.","o":["cómo","lo","el","que"],"a":1,"k":"lo + 부사 + que","t":"그 식당이 얼마나 맛있는지 넌 상상도 못 할 거야.","e":"'lo + 형용사/부사 + que'는 '얼마나 ~한지'라는 강조 표현입니다. 'lo bien que se come'는 '얼마나 잘 먹는지(맛있는지)'라는 뜻입니다. 예: No sabes lo cansada que estoy. (내가 얼마나 피곤한지 넌 몰라.)","x":["cómo: '¿Cómo?'는 방법을 물으며, 'cómo bien que'라는 형태는 쓰지 않습니다 ✗","lo: 'lo + 부사 + que(얼마나 ~한지)' → 정답 ✓","el: 남성 관사는 부사 bien 앞에 쓰지 않습니다 ✗","que: 'que bien que'는 틀린 형태입니다 ✗"]},{"id":"G217","q":"Te dije que ____ a tiempo y así ha sido.","o":["llegara","llegaré","llegaría","llegue"],"a":2,"k":"과거 속 미래 (조건법)","t":"내가 제시간에 도착할 거라고 말했지, 정말 그렇게 됐잖아.","e":"과거 시점(te dije)에서 '앞으로 ~할 것'이라고 말한 것을 전할 때는 조건법(과거 속의 미래)을 씁니다. 직접화법 'Llegaré a tiempo'가 간접화법으로 바뀌면 'Te dije que llegaría a tiempo'가 됩니다. decir가 사실 전달일 때는 직설법을 쓴다는 점도 기억하세요.","x":["llegara: 접속법 과거는 decir가 '~하라고 명령하다'일 때 씁니다(Te dije que llegaras = 도착하라고 했다) ✗","llegaré: 직설법 미래라 과거 시점(dije)의 간접화법에는 어색합니다 ✗","llegaría: 과거 속 미래를 나타내는 조건법 → 정답 ✓","llegue: 접속법 현재라 사실 전달 문장에 맞지 않습니다 ✗"]},{"id":"G218","q":"____ mitad de mis amigos sigue viviendo con sus padres.","o":["ø","El","Lo","La"],"a":3,"k":"la mitad","t":"내 친구들 중 절반은 아직 부모님과 함께 살고 있다.","e":"mitad(절반)는 여성 명사이며, '~의 절반'이라고 할 때는 항상 정관사를 붙여 'la mitad de ~'라고 씁니다. 동사는 보통 la mitad에 맞춰 단수(sigue)로 씁니다. 예: La mitad de la clase está enferma. (반의 절반이 아프다.)","x":["ø: mitad 앞에는 정관사가 필요합니다 ✗","El: mitad는 여성 명사라 남성 관사는 ✗","Lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗","La: 'la mitad de(~의 절반)' → 정답 ✓"]},{"id":"G219","q":"Para mí, lo mejor sería que les ____ la verdad.","o":["dirías","decías","dijeras","dirás"],"a":2,"k":"sería que + 접속법 과거","t":"내 생각에는 그들에게 사실대로 말하는 게 가장 좋을 것 같아.","e":"'lo mejor es que ~(가장 좋은 건 ~하는 것이다)' 뒤에는 접속법이 옵니다. 주절이 조건법(sería)이면 시제를 맞춰 접속법 과거를 씁니다. 그래서 decir의 접속법 과거 dijeras가 정답입니다. 현재형이라면 'Lo mejor es que les digas la verdad'가 됩니다.","x":["dirías: 조건법이라 que절 접속법 자리에 쓰지 않습니다 ✗","decías: 직설법 불완료과거라 ✗","dijeras: 조건법 주절에 맞춘 접속법 과거 → 정답 ✓","dirás: 직설법 미래라 ✗"]},{"id":"G220","q":"¿Escuchas ____ ese ruido?","o":["ø","de","a","por"],"a":0,"k":"사물 목적어 (a 없음)","t":"저 소리 들려?","e":"직접목적어가 사물일 때는 전치사 a를 쓰지 않습니다. ruido(소리)는 사람이 아니므로 'Escuchas ese ruido'처럼 바로 목적어를 씁니다. 사람이 목적어일 때만 'Escucho a mi madre(엄마 말을 듣는다)'처럼 a를 넣습니다.","x":["ø: 사물 직접목적어에는 전치사를 넣지 않음 → 정답 ✓","de: escuchar de는 쓰지 않습니다 ✗","a: 사람 목적어 앞에 쓰는 a라서 소리에는 ✗","por: '~ 때문에, ~을 통해'라는 뜻이라 ✗"]},{"id":"G221","q":"A esas niñas ____ conozco muy bien.","o":["se las","les","los","las"],"a":3,"k":"직접목적격 대명사 중복","t":"그 여자아이들은 내가 아주 잘 안다.","e":"직접목적어가 동사 앞으로 나오면(A esas niñas) 그것을 받는 직접목적격 대명사를 동사 앞에 다시 써야 합니다. conocer(알다)의 목적어는 직접목적어이고, niñas가 여성 복수이므로 las가 정답입니다. 예: Este libro lo leí ayer. (이 책은 어제 읽었다.)","x":["se las: se는 필요 없고, 대명사가 하나만 필요합니다 ✗","les: 간접목적격(~에게)이라 conocer의 목적어에는 쓰지 않습니다 ✗","los: 남성 복수라 niñas와 성이 맞지 않습니다 ✗","las: 여성 복수 직접목적격 → 정답 ✓"]},{"id":"G222","q":"Si Alicia ____ aquí, no tendríamos este problema ahora.","o":["estaría","esté","haya estado","estuviera"],"a":3,"k":"가정문 (현재 사실 반대)","t":"알리시아가 여기 있다면 지금 우리는 이 문제를 겪지 않을 텐데.","e":"현재 사실과 반대되는 가정(실제로는 여기 없음)은 'Si + 접속법 과거, 조건법' 구조로 씁니다. 주절이 'no tendríamos(조건법)'이므로 si절은 접속법 과거 estuviera가 정답입니다. si 뒤에는 조건법이나 접속법 현재를 쓰지 않는다는 점을 기억하세요.","x":["estaría: si 바로 뒤에는 조건법을 쓰지 않습니다 ✗","esté: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","haya estado: si 뒤에 접속법 현재완료는 이런 가정문에 쓰지 않습니다 ✗","estuviera: 현재 사실 반대 가정의 접속법 과거 → 정답 ✓"]},{"id":"G223","q":"¿Qué te pareció ____ final de la película?","o":["ø","el","al","la"],"a":1,"k":"el final","t":"영화 결말 어땠어?","e":"final(결말, 끝)은 남성 명사이고, 특정 영화의 '그 결말'이므로 정관사 el을 씁니다. '¿Qué te pareció ~?'의 주어가 el final이며, gustar처럼 사람(te)이 간접목적격입니다. 그래서 a를 붙인 al은 쓰지 않습니다.","x":["ø: 특정한 결말이므로 관사가 필요합니다 ✗","el: 남성 명사 final의 정관사 → 정답 ✓","al: 'a + el'로 parecer의 주어 앞에 a를 붙이면 안 됩니다 ✗","la: final은 '결말'의 뜻일 때 남성 명사라 ✗"]},{"id":"G224","q":"Dudo que Julia ____ mejor que tú.","o":["ha cantado","canta","está cantando","cante"],"a":3,"k":"dudar que + 접속법","t":"훌리아가 너보다 노래를 잘하는지 의심스러워.","e":"dudar(의심하다)처럼 의심·불확실을 나타내는 동사 뒤의 que절에는 접속법을 씁니다. 현재의 능력을 말하므로 cantar의 접속법 현재 cante가 정답입니다. 예: Dudo que venga. (그가 올지 의문이다.)","x":["ha cantado: 직설법이라 dudar 뒤에 쓰지 않습니다 ✗","canta: 직설법이라 의심 표현 뒤에는 ✗","está cantando: 직설법 진행형이라 ✗","cante: 의심 표현 뒤 접속법 현재 → 정답 ✓"]},{"id":"G225","q":"No me parece bien que ____ con ese chico.","o":["saldrías","saldrás","sales","salgas"],"a":3,"k":"평가 + 접속법","t":"네가 그 남자애와 사귀는 건 마음에 들지 않아.","e":"'No me parece bien que ~(~하는 것이 좋지 않다고 생각해)'는 평가를 나타내는 표현이라 뒤에 접속법이 옵니다. salir(나가다)의 접속법 현재 2인칭은 불규칙형 salgas입니다. 'salir con alguien'은 '누구와 사귀다, 데이트하다'라는 뜻입니다.","x":["saldrías: 조건법이라 평가 표현 뒤에 쓰지 않습니다 ✗","saldrás: 직설법 미래라 ✗","sales: 직설법 현재라 ✗","salgas: salir의 접속법 현재 2인칭 단수 → 정답 ✓"]},{"id":"G226","q":"¿Por qué no estás listo aún? Vamos a llegar tarde ____ tu culpa.","o":["de","para","a","por"],"a":3,"k":"por (원인)","t":"왜 아직 준비가 안 됐어? 너 때문에 늦겠어.","e":"원인·이유를 나타낼 때는 전치사 por를 씁니다. 'por tu culpa'는 '네 탓에, 너 때문에'라는 뜻의 굳어진 표현입니다. para는 목적·목적지를 나타내므로 원인에는 쓰지 않습니다.","x":["de: 'de tu culpa'는 쓰지 않습니다 ✗","para: 목적(~을 위해)이라 원인을 나타내지 않습니다 ✗","a: 'a tu culpa'는 틀린 표현입니다 ✗","por: 원인 'por tu culpa(너 때문에)' → 정답 ✓"]},{"id":"G227","q":"¿Qué te pareció que le ____ el Goya a esa actriz?","o":["darían","han dado","dieron","dieran"],"a":3,"k":"parecer que (평가) + 접속법","t":"그 여배우가 고야상을 받은 것에 대해 어떻게 생각했어?","e":"'¿Qué te pareció que ~?'는 '~한 것을 어떻게 생각했니?'라고 평가를 묻는 표현이라 que절에 접속법이 옵니다. 주절이 과거(pareció)이므로 접속법 과거 dieran이 정답입니다. 'dieran'의 주어는 막연한 '그들(심사위원)'을 뜻하는 3인칭 복수입니다. 고야상(Premios Goya)은 스페인의 영화상입니다.","x":["darían: 조건법이라 평가 표현의 que절에 쓰지 않습니다 ✗","han dado: 직설법 현재완료라 ✗","dieron: 직설법 단순과거라 평가를 묻는 que절에는 ✗","dieran: 과거 평가 표현 뒤 접속법 과거 → 정답 ✓"]},{"id":"G228","q":"Parecía que iba a llover, ____, decidimos hacer la barbacoa otro día.","o":["por lo tanto","sin embargo","en cambio","puesto que"],"a":0,"k":"por lo tanto (결과)","t":"비가 올 것 같았다. 그래서 우리는 바비큐를 다른 날 하기로 했다.","e":"앞 내용(비가 올 것 같음)의 결과(바비큐 연기)를 이어 줄 때는 'por lo tanto(그러므로, 그래서)'를 씁니다. 쉼표 사이에 넣어 문장을 연결하는 연결어입니다. sin embargo나 en cambio는 반대·대조를 나타내 문맥과 맞지 않습니다.","x":["por lo tanto: 결과 '그래서, 따라서' → 정답 ✓","sin embargo: '그러나'라는 반대라서 ✗","en cambio: '반면에'라는 대조라 ✗","puesto que: '~이므로'라는 이유를 나타내 원인과 결과가 뒤바뀝니다 ✗"]},{"id":"G229","q":"Lucía nos dijo que ____ embarazada de su tercer hijo.","o":["estaba","estuviera","estaría","estuvo"],"a":0,"k":"간접화법 (estar)","t":"루시아는 셋째 아이를 임신 중이라고 우리에게 말했다.","e":"'Lucía dijo: Estoy embarazada'를 간접화법으로 바꾸면 과거 시점에 맞춰 현재가 불완료과거로 바뀌어 'dijo que estaba embarazada'가 됩니다. decir가 정보를 전달할 때는 직설법을 씁니다. embarazada(임신한)는 상태라서 estar를 씁니다.","x":["estaba: 간접화법의 직설법 불완료과거 → 정답 ✓","estuviera: 접속법은 decir가 명령·부탁을 전할 때 씁니다 ✗","estaría: 조건법은 원래 미래였던 말을 전할 때 씁니다 ✗","estuvo: 단순과거는 일정 기간이 끝난 상태로, 진행 중인 임신 상태와 맞지 않습니다 ✗"]},{"id":"G230","q":"No ____ que Isabel y Alberto se habían prometido.","o":["he sabido","había sabido","sabía","supe"],"a":2,"k":"saber 불완료과거","t":"이사벨과 알베르토가 약혼한 줄 몰랐어.","e":"'No sabía que ~'는 '(그때까지) ~인 줄 몰랐다'라는 뜻으로, 지금 막 알게 된 사실에 놀랄 때 자주 씁니다. 과거의 지식 상태를 나타내므로 불완료과거 sabía를 씁니다. 'prometerse'는 '약혼하다'라는 뜻입니다.","x":["he sabido: 현재완료라 '몰랐다'라는 과거 상태를 나타내지 못합니다 ✗","había sabido: 대과거라 문맥에 맞지 않습니다 ✗","sabía: 과거의 지식 상태 'no sabía que(~인 줄 몰랐다)' → 정답 ✓","supe: saber의 단순과거는 '알게 되었다'라는 뜻이 되어 ✗"]},{"id":"G231","q":"Dame ____ cinco minutos, por favor.","o":["a","por","de","ø"],"a":3,"k":"시간 표현 (전치사 없음)","t":"5분만 시간을 줘, 부탁이야.","e":"dar(주다)의 직접목적어가 'cinco minutos(5분)'이므로 전치사 없이 바로 씁니다. 'Dame cinco minutos'는 '5분만 줘'라는 자주 쓰는 표현입니다. 'Dame un momento(잠깐만)'도 같은 구조입니다.","x":["a: 사물 목적어 앞에 a를 넣지 않습니다 ✗","por: 'por cinco minutos'는 '5분 동안'이라 dame와 어울리지 않습니다 ✗","de: 'de cinco minutos'는 '5분짜리'라는 뜻이라 ✗","ø: 직접목적어를 바로 씀 → 정답 ✓"]},{"id":"G232","q":"¿Todavía ____ ese programa?","o":["tienes visto","llevas viendo","llevas visto","sigues viendo"],"a":3,"k":"seguir + 현재분사","t":"아직도 그 프로그램을 보고 있어?","e":"'seguir + 현재분사'는 '여전히(계속) ~하고 있다'라는 뜻으로, todavía(아직도)와 잘 어울립니다. '¿Todavía sigues viendo...?'는 '아직도 계속 보고 있어?'라는 뜻입니다. 'llevar + 현재분사'는 'llevas dos años viendo'처럼 기간 표현이 필요합니다.","x":["tienes visto: 'tener + 과거분사'는 일부에서 쓰지만 이 뜻으로는 쓰지 않습니다 ✗","llevas viendo: 기간(예: dos años) 없이는 어색합니다 ✗","llevas visto: 'llevar + 과거분사'는 횟수·양과 함께 써서 문맥과 맞지 않습니다 ✗","sigues viendo: '여전히 보고 있다' → 정답 ✓"]},{"id":"G233","q":"Una vez que ____ el documento, debe firmarlo y mandarlo por correo.","o":["recibiera","haya recibido","había recibido","ha recibido"],"a":1,"k":"una vez que + 접속법","t":"서류를 받으시면, 서명해서 우편으로 보내셔야 합니다.","e":"'una vez que(일단 ~하면, ~한 다음에)'는 시간 접속사로, 미래의 일을 말할 때 접속법을 씁니다. '받은 다음에'라는 완료의 의미이므로 접속법 현재완료 haya recibido가 정답입니다. 예: Una vez que termines, avísame. (끝나면 알려 줘.)","x":["recibiera: 접속법 과거라 현재·미래 지시(debe)와 시제가 맞지 않습니다 ✗","haya recibido: 미래 완료의 의미를 나타내는 접속법 현재완료 → 정답 ✓","había recibido: 직설법 대과거라 미래 일과 맞지 않습니다 ✗","ha recibido: 직설법이라 미래 일을 나타내는 시간절에 쓰지 않습니다 ✗"]},{"id":"G234","q":"Te llamaré en cuanto ____ de la academia.","o":["salga","salgo","saldría","saldré"],"a":0,"k":"en cuanto + 접속법","t":"학원에서 나오자마자 너한테 전화할게.","e":"'en cuanto(~하자마자)'처럼 시간을 나타내는 접속사 뒤에 미래의 일이 오면 접속법 현재를 씁니다. 주절이 미래(llamaré)이므로 salir의 접속법 현재 salga가 정답입니다. 시간절에는 미래형(saldré)을 쓰지 않는다는 점이 한국어·영어와 다릅니다.","x":["salga: 미래 시간절의 접속법 현재 → 정답 ✓","salgo: 직설법은 습관적인 일을 말할 때 씁니다 ✗","saldría: 조건법이라 ✗","saldré: 시간절에는 미래형을 쓰지 않습니다 ✗"]},{"id":"G235","q":"¿Cuántos coches ____ en España el año pasado?","o":["son vendidos","se vendió","se vendieron","se vendían"],"a":2,"k":"수동 se (복수)","t":"작년에 스페인에서 차가 몇 대 팔렸나요?","e":"'se + 3인칭 동사'로 수동의 뜻(~이 팔리다)을 나타내는 '수동 se' 구문은 동사를 주어(팔린 물건)의 수에 맞춥니다. coches가 복수이므로 se vendieron이 됩니다. 'el año pasado'라는 완료된 기간이므로 단순과거를 씁니다.","x":["son vendidos: 현재 시제라 el año pasado와 맞지 않습니다 ✗","se vendió: 단수라 복수 주어 coches와 맞지 않습니다 ✗","se vendieron: 복수 일치 + 단순과거 → 정답 ✓","se vendían: 불완료과거라 끝난 기간(작년) 전체의 결과를 묻는 데 맞지 않습니다 ✗"]},{"id":"G236","q":"Se dice que esa mansión ____ encantada.","o":["es","sea","esté","está"],"a":3,"k":"estar + 상태 형용사","t":"그 저택에는 유령이 나온다고들 한다.","e":"'Se dice que ~(~라고들 한다)'는 정보를 전하는 표현이라 뒤에 직설법이 옵니다. encantada(유령이 나오는, 마법에 걸린)는 상태를 나타내는 과거분사형 형용사라 estar와 씁니다. 'una casa encantada'는 '유령의 집'입니다.","x":["es: ser는 본질·성격을 나타내며, '유령이 나오는' 상태에는 estar를 씁니다 ✗","sea: 접속법이고 ser라서 ✗","esté: estar는 맞지만 접속법이라 정보 전달 표현 뒤에는 ✗","está: 상태를 나타내는 estar 직설법 → 정답 ✓"]},{"id":"G237","q":"El suelo todavía está ____ fregar. ¿Por qué no lo ha hecho nadie?","o":["para","a","por","hasta"],"a":2,"k":"estar por + 동사원형","t":"바닥이 아직 걸레질이 안 되어 있어. 왜 아무도 안 했어?","e":"'estar por + 동사원형'은 '아직 ~되지 않은 상태이다, ~해야 할 것으로 남아 있다'라는 뜻입니다. 'El suelo está por fregar'는 '바닥을 아직 닦지 않았다'는 뜻입니다. 같은 뜻으로 'estar sin + 동사원형(sin fregar)'도 씁니다. fregar는 스페인에서 '걸레질하다, 설거지하다'라는 뜻입니다.","x":["para: 'estar para + 동사원형'은 '막 ~하려던 참이다'라는 뜻이라 ✗","a: 'estar a fregar'는 쓰지 않는 표현입니다 ✗","por: 'estar por + 동사원형(아직 ~되지 않음)' → 정답 ✓","hasta: 'hasta fregar'는 '닦을 때까지'라는 뜻이라 문장이 성립하지 않습니다 ✗"]},{"id":"G238","q":"Puede que ____ luego a casa de Elena.","o":["iría","voy","vaya","iré"],"a":2,"k":"puede que + 접속법","t":"나중에 엘레나네 집에 갈지도 몰라.","e":"'Puede que ~'는 '~일지도 모른다'라는 가능성을 나타내는 표현으로, 뒤에 항상 접속법을 씁니다. 그래서 ir의 접속법 현재 vaya가 정답입니다. 비슷하게 'Es posible que ~', 'Quizás ~'도 접속법과 자주 씁니다.","x":["iría: 조건법이라 puede que 뒤에 쓰지 않습니다 ✗","voy: 직설법이라 ✗","vaya: ir의 접속법 현재 → 정답 ✓","iré: 직설법 미래라 puede que 뒤에는 ✗"]},{"id":"G239","q":"Me he comprado un vestido que me ____ genial.","o":["siente","sienta","sentase","sentaría"],"a":1,"k":"sentar bien (어울리다)","t":"나한테 아주 잘 어울리는 원피스를 샀어.","e":"'sentar bien/genial a alguien'은 '(옷 등이) ~에게 잘 어울리다'라는 뜻입니다. 실제로 산 원피스의 특징을 말하므로 관계절에 직설법 sienta를 씁니다. sentar는 e→ie로 변하는 동사라 sienta가 됩니다. sentir(느끼다)의 접속법 sienta와 헷갈리지 마세요.","x":["siente: sentir(느끼다)의 직설법 형태라 뜻이 맞지 않습니다 ✗","sienta: sentar(어울리다)의 직설법 현재 3인칭 → 정답 ✓","sentase: 접속법 과거라 실제 산 옷에 대한 서술에는 ✗","sentaría: 조건법이라 '어울릴 텐데'라는 뜻이 되어 ✗"]},{"id":"G240","q":"Mi novio siempre me espera ____ la salida de la oficina.","o":["entre","contra","a","de"],"a":2,"k":"a la salida","t":"내 남자친구는 늘 사무실 출구에서 나를 기다린다.","e":"'a la salida de ~'는 '~의 출구에서, ~가 끝나고 나올 때'라는 뜻의 굳어진 표현입니다. 장소와 시간(퇴근할 때)의 의미가 함께 있습니다. 예: Te espero a la salida del cine. (영화관 나오는 곳에서 기다릴게.)","x":["entre: '~ 사이에'라는 뜻이라 ✗","contra: '~에 반하여, ~에 기대어'라는 뜻이라 ✗","a: 'a la salida(출구에서, 나올 때)' → 정답 ✓","de: 'de la salida'는 '출구로부터'라는 뜻이라 문맥과 맞지 않습니다 ✗"]},{"id":"G241","q":"Estaba preparándome para ir al banco cuando, de repente, ____ cuenta de que era domingo.","o":["me estaba dando cuenta","me había dado cuenta","me di","me daba"],"a":2,"k":"단순과거 vs 불완료과거","t":"은행에 갈 준비를 하고 있었는데, 갑자기 일요일이라는 걸 깨달았다.","e":"과거 이야기에서 배경(준비하고 있던 중, estaba preparándome)은 불완료과거로, 그 순간 갑자기 일어난 사건은 단순과거로 씁니다. 'de repente(갑자기)'가 있으므로 darse cuenta의 단순과거 me di가 정답입니다. 빈칸 뒤에 cuenta가 이미 있다는 점도 확인하세요.","x":["me estaba dando cuenta: 빈칸 뒤에 cuenta가 또 있어 중복되고, 진행형도 맞지 않습니다 ✗","me había dado cuenta: cuenta가 중복되고 대과거라 '갑자기'와 맞지 않습니다 ✗","me di: 갑자기 일어난 사건의 단순과거 → 정답 ✓","me daba: 불완료과거라 갑작스러운 순간의 사건에는 ✗"]},{"id":"G242","q":"No son primos, ____ hermanos.","o":["sino","aunque","pero","si no"],"a":0,"k":"sino (A가 아니라 B)","t":"그들은 사촌이 아니라 형제다.","e":"'no A, sino B'는 'A가 아니라 B'라는 뜻으로, 앞의 내용을 부정하고 바로잡을 때 sino를 씁니다. pero는 '하지만'이라는 일반적인 반대에 쓰고, 부정한 것을 대신하는 말을 제시할 때는 sino를 씁니다. 'si no(만약 ~하지 않으면)'와 띄어쓰기에 주의하세요.","x":["sino: 'no A, sino B(A가 아니라 B)' → 정답 ✓","aunque: '~이지만'이라 뜻이 맞지 않습니다 ✗","pero: 바로잡는 'A가 아니라 B' 구문에는 sino를 씁니다 ✗","si no: '만약 ~이 아니면'이라는 조건이라 ✗"]},{"id":"G243","q":"En ese momento comprendí que no ____ a ver a Carla.","o":["volvía","volvería","volví","volviera"],"a":1,"k":"과거 속 미래 (조건법)","t":"그 순간 나는 다시는 카를라를 보지 못할 거라는 것을 깨달았다.","e":"과거 시점(comprendí, 깨달았다)에서 바라본 '그 이후의 일'은 조건법(과거 속의 미래)으로 나타냅니다. 'volver a + 동사원형'은 '다시 ~하다'라는 뜻이라 'no volvería a ver'는 '다시는 보지 못할 것'입니다. comprender(깨닫다)는 사실 인식이라 접속법을 쓰지 않습니다.","x":["volvía: 불완료과거라 '그 이후의 일(미래)'이라는 뜻이 약합니다 ✗","volvería: 과거 속 미래를 나타내는 조건법 → 정답 ✓","volví: 단순과거라 '다시 보지 않았다'는 이미 일어난 사실이 되어 ✗","volviera: 접속법이라 사실 인식 동사 뒤에 쓰지 않습니다 ✗"]},{"id":"G244","q":"Ya nos hemos acostumbrado ____ nuestra vida en Francia.","o":["sobre","en","de","a"],"a":3,"k":"acostumbrarse a","t":"우리는 이제 프랑스 생활에 익숙해졌다.","e":"'acostumbrarse a ~'는 '~에 익숙해지다'라는 뜻으로 항상 전치사 a를 씁니다. 뒤에 명사나 동사원형이 올 수 있습니다. 예: Me he acostumbrado a madrugar. (일찍 일어나는 것에 익숙해졌다.)","x":["sobre: acostumbrarse sobre는 쓰지 않습니다 ✗","en: acostumbrarse en은 틀린 결합입니다 ✗","de: 'acostumbrarse de'는 쓰지 않습니다 ✗","a: 'acostumbrarse a(~에 익숙해지다)' → 정답 ✓"]},{"id":"G245","q":"Oiga, aquí no puede estar, ____ inmediatamente.","o":["salga","salid","sal","sale"],"a":0,"k":"usted 긍정 명령","t":"저기요, 여기 계시면 안 됩니다. 당장 나가 주세요.","e":"'Oiga(저기요)'와 'puede'로 보아 상대를 usted로 부르고 있습니다. usted에 대한 명령은 접속법 현재 형태를 쓰므로 salir의 usted 명령은 salga입니다. sal은 tú 명령, salid는 vosotros 명령입니다.","x":["salga: usted 명령형 → 정답 ✓","salid: vosotros 명령이라 인칭이 맞지 않습니다 ✗","sal: tú 명령이라 usted로 대하는 상대에게는 ✗","sale: 직설법 현재(그/당신이 나간다)라 명령이 아닙니다 ✗"]},{"id":"G246","q":"Se enamoró de ella ____ verla.","o":["en cuanto","mientras","nada más","cuando"],"a":2,"k":"nada más + 동사원형","t":"그는 그녀를 보자마자 사랑에 빠졌다.","e":"'nada más + 동사원형'은 '~하자마자'라는 뜻입니다. 빈칸 뒤에 'verla(그녀를 보다)'라는 동사원형이 오므로 nada más가 정답입니다. 같은 뜻으로 'al + 동사원형(al verla)'도 씁니다. en cuanto나 cuando 뒤에는 활용된 동사가 와야 합니다(en cuanto la vio).","x":["en cuanto: '~하자마자'라는 뜻이지만 뒤에 활용된 동사가 와야 합니다 ✗","mientras: '~하는 동안'이라 뜻이 맞지 않고, 활용된 동사가 필요합니다 ✗","nada más: '~하자마자' + 동사원형 → 정답 ✓","cuando: 접속사라 뒤에 동사원형이 올 수 없습니다 ✗"]},{"id":"G247","q":"____, te llamo un poco más tarde.","o":["Estaba cocinando","He estado cocinando","Estoy cocinando","Cocino"],"a":2,"k":"현재진행형","t":"지금 요리하는 중이야, 조금 있다가 전화할게.","e":"말하는 지금 이 순간 진행 중인 행동은 'estar의 현재 + 현재분사'(estoy cocinando)로 나타냅니다. 그래서 '지금 바빠서 나중에 전화할게'라는 이유가 됩니다. 단순 현재 cocino는 습관(나는 요리를 한다)에 더 가깝습니다.","x":["Estaba cocinando: 과거진행이라 현재 상황을 설명하지 못합니다 ✗","He estado cocinando: '(지금까지) 요리하고 있었다'라 지금 진행 중이라는 이유가 약합니다 ✗","Estoy cocinando: 지금 진행 중인 행동 → 정답 ✓","Cocino: 단순 현재로 습관을 나타내 '지금 하는 중'이라는 뜻이 약합니다 ✗"]},{"id":"G248","q":"Niñas, ____ aquí hasta que vuelva vuestra madre.","o":["quedad","quedaos","quedarse","quedáis"],"a":1,"k":"vosotros 명령 + 재귀","t":"얘들아, 엄마가 돌아올 때까지 여기 있어.","e":"vosotros 긍정 명령은 동사원형의 -r을 -d로 바꿔 만들지만(quedad), 재귀대명사 os가 붙으면 -d가 빠져 quedaos가 됩니다. quedarse(머물다)는 재귀동사이므로 quedaos가 정답입니다. 중남미에서는 vosotros 대신 ustedes를 써서 'quédense'라고 합니다.","x":["quedad: 재귀대명사가 없어 quedarse(머물다)의 뜻이 되지 않습니다 ✗","quedaos: vosotros 긍정 명령 + os(-d 탈락) → 정답 ✓","quedarse: 동사원형이라 명령으로 쓰지 않습니다 ✗","quedáis: 직설법 현재(너희는 머문다)라 명령이 아닙니다 ✗"]},{"id":"G249","q":"Por favor, no ____ des tantos caramelos al niño.","o":["los","le","lo","les"],"a":1,"k":"간접목적격 le","t":"제발 아이에게 사탕을 그렇게 많이 주지 마.","e":"dar(주다)에서 받는 사람은 간접목적격(~에게)입니다. 'al niño(아이에게)'가 3인칭 단수이므로 le를 씁니다. 스페인어에서는 'a + 사람'이 있어도 간접목적격 대명사를 함께 쓰는 것이 자연스럽습니다. 부정 명령이므로 대명사는 동사 앞에 옵니다.","x":["los: 직접목적격 남성 복수(그것들을)라 받는 사람에게 쓰지 않습니다 ✗","le: 3인칭 단수 간접목적격(그에게) → 정답 ✓","lo: 직접목적격(그를/그것을)이라 ✗","les: 3인칭 복수라 단수인 el niño와 맞지 않습니다 ✗"]},{"id":"G250","q":"Anoche ____ una pesadilla.","o":["tenía","tuve","he tenido","estuve teniendo"],"a":1,"k":"단순과거 (anoche)","t":"어젯밤 나는 악몽을 꿨다.","e":"'anoche(어젯밤)'처럼 끝난 과거 시점에 한 번 일어난 사건은 단순과거로 씁니다. tener의 단순과거 1인칭은 불규칙형 tuve입니다. 'tener una pesadilla'는 '악몽을 꾸다'라는 표현입니다.","x":["tenía: 불완료과거는 배경·습관에 써서 한 번의 사건에는 ✗","tuve: 끝난 과거의 사건 → 정답 ✓","he tenido: 현재완료는 anoche와 잘 쓰지 않습니다(스페인 일부 지역 제외) ✗","estuve teniendo: 일정 기간 계속된 행동이라 악몽 한 번에는 어색합니다 ✗"]},{"id":"G251","q":"Por favor, ____ ya, que es muy tarde.","o":["os acostáis","acostad","acostáis","acostaos"],"a":3,"k":"vosotros 명령 + 재귀","t":"제발 이제 자, 너무 늦었어.","e":"acostarse(잠자리에 들다)는 재귀동사입니다. vosotros 긍정 명령은 acostad인데, 재귀대명사 os를 붙이면 -d가 빠져 acostaos가 됩니다. 긍정 명령에서는 대명사가 동사 뒤에 붙습니다. 중남미에서는 ustedes 명령 'acuéstense'를 씁니다.","x":["os acostáis: 직설법 현재(너희는 잔다)라 명령이 아닙니다 ✗","acostad: 재귀대명사가 없어 '(누군가를) 눕혀라'라는 뜻이 됩니다 ✗","acostáis: 직설법 현재이고 재귀대명사도 없습니다 ✗","acostaos: vosotros 긍정 명령 + os(-d 탈락) → 정답 ✓"]},{"id":"G252","q":"Le canté una nana al bebé ____ se durmiera.","o":["a que","ya que","para","para que"],"a":3,"k":"para que + 접속법","t":"나는 아기가 잠들도록 자장가를 불러 주었다.","e":"주절의 주어(나)와 잠드는 사람(아기)이 다를 때 목적을 나타내려면 'para que + 접속법'을 씁니다. 빈칸 뒤 'se durmiera'가 접속법 과거이므로 para que가 정답입니다. 주어가 같으면 'para + 동사원형'을 씁니다(Canté para relajarme).","x":["a que: 'a que'는 이동·목적 동사 뒤에서만 쓰며 여기서는 어색합니다 ✗","ya que: '~이므로'라는 이유라 뜻이 맞지 않습니다 ✗","para: 뒤에 동사원형이 와야 하는데 활용된 동사(se durmiera)가 옵니다 ✗","para que: 주어가 다를 때의 목적 + 접속법 → 정답 ✓"]},{"id":"G253","q":"No se corte y ____ lo que piensa.","o":["digan","diga","di","decid"],"a":1,"k":"usted 명령","t":"사양하지 마시고 생각하시는 걸 말씀해 주세요.","e":"'No se corte'는 usted에 대한 부정 명령(사양하지 마세요, 망설이지 마세요)이고, 'piensa'도 3인칭(usted)입니다. 그래서 이어지는 긍정 명령도 usted 형태인 diga(decir의 접속법 현재)를 씁니다. 'cortarse'는 스페인 구어로 '쑥스러워하다, 사양하다'라는 뜻입니다.","x":["digan: ustedes(여러분) 명령이라 단수 usted와 맞지 않습니다 ✗","diga: usted 긍정 명령 → 정답 ✓","di: tú 명령이라 usted로 대하는 문장과 맞지 않습니다 ✗","decid: vosotros 명령이라 ✗"]},{"id":"G254","q":"____ con Pili cuando de pronto me dio un dolor en el pecho.","o":["Estuve hablando","Estaba hablando","Hablé","He estado hablando"],"a":1,"k":"과거진행 (배경)","t":"필리와 이야기하고 있었는데 갑자기 가슴에 통증이 왔다.","e":"과거에 어떤 일이 진행 중이던 중에 다른 사건이 끼어들 때, 진행 중이던 배경은 'estar의 불완료과거 + 현재분사'(estaba hablando)로, 끼어든 사건은 단순과거(me dio)로 씁니다. 'cuando de pronto(그때 갑자기)'가 이 구조의 신호입니다.","x":["Estuve hablando: 끝난 기간의 행동이라 다른 사건이 끼어드는 배경으로 쓰지 않습니다 ✗","Estaba hablando: 과거 진행 중이던 배경 → 정답 ✓","Hablé: 단순과거라 '이야기했다'는 끝난 사건이 되어 ✗","He estado hablando: 현재완료진행이라 과거 이야기와 맞지 않습니다 ✗"]},{"id":"G255","q":"Con su privilegiada voz, esa cantante cautivó ____ la audiencia.","o":["de","a","en","ø"],"a":1,"k":"사람 목적어 앞 a","t":"그 가수는 특별한 목소리로 관객을 사로잡았다.","e":"직접목적어가 사람이나 사람들의 집단일 때는 앞에 전치사 a를 붙입니다(인칭의 a). la audiencia(관객, 청중)는 사람들의 무리이므로 'cautivó a la audiencia'가 됩니다. cautivar는 '매료시키다, 사로잡다'라는 뜻입니다.","x":["de: cautivar de는 쓰지 않습니다 ✗","a: 사람(집단) 목적어 앞의 인칭 a → 정답 ✓","en: cautivar en은 틀린 결합입니다 ✗","ø: 목적어가 사람들(관객)이므로 a를 넣는 것이 맞습니다 ✗"]},{"id":"G256","q":"____ veía a su dueña, el perro se volvía loco de alegría.","o":["Desde","Antes de que","Tan pronto como","Al"],"a":2,"k":"tan pronto como","t":"주인을 보기만 하면 그 개는 기뻐서 어쩔 줄 몰라 했다.","e":"'tan pronto como(~하자마자, ~하기만 하면)'는 시간 접속사입니다. 과거의 반복된 습관을 말하므로 직설법 불완료과거(veía, se volvía)를 씁니다. 미래 일이라면 접속법을 씁니다(Tan pronto como la vea...). 'volverse loco de alegría'는 '기뻐서 미칠 지경이 되다'라는 뜻입니다.","x":["Desde: '~부터'라는 전치사라 뒤에 활용된 동사절이 바로 올 수 없습니다 ✗","Antes de que: '~하기 전에'라 뜻이 맞지 않고 접속법이 필요합니다 ✗","Tan pronto como: '~하자마자' + 직설법(과거 습관) → 정답 ✓","Al: 'al + 동사원형'으로 써야 하므로 활용된 동사 veía와 맞지 않습니다 ✗"]},{"id":"G257","q":"Chicas, ____ cuidado al cruzar la carretera.","o":["tened","tienen","tenéis","ten"],"a":0,"k":"vosotros 명령 (tener)","t":"얘들아, 길 건널 때 조심해.","e":"'Chicas(얘들아)'는 친한 사이의 여러 명이므로 스페인에서는 vosotros 명령을 씁니다. vosotros 긍정 명령은 동사원형 끝의 -r을 -d로 바꿔 tener → tened가 됩니다. 'tener cuidado'는 '조심하다'라는 표현입니다. 중남미에서는 ustedes 명령 'tengan cuidado'를 씁니다.","x":["tened: vosotros 긍정 명령 → 정답 ✓","tienen: 직설법 현재(ustedes)라 명령이 아닙니다 ✗","tenéis: 직설법 현재(vosotros)라 명령이 아닙니다 ✗","ten: tú 명령이라 여러 명(chicas)에게 쓰지 않습니다 ✗"]},{"id":"G258","q":"Que tengas éxito o fracases depende ____ ti.","o":["de","para","por","a"],"a":0,"k":"depender de","t":"네가 성공하든 실패하든 그건 너에게 달려 있다.","e":"'depender de ~'는 '~에 달려 있다'라는 뜻으로 항상 전치사 de를 씁니다. 'depende de ti'는 '너에게 달렸어'입니다. 문장 앞의 'Que tengas éxito o fracases'는 que절 전체가 주어인 구조로, 이때 접속법을 씁니다.","x":["de: 'depender de(~에 달려 있다)' → 정답 ✓","para: depender para는 쓰지 않습니다 ✗","por: depender por는 틀린 결합입니다 ✗","a: depender a는 쓰지 않습니다 ✗"]},{"id":"G259","q":"Me parece que el gato ____.","o":["se haya escapado","se ha escapado","se escapase","se escape"],"a":1,"k":"parecer que + 직설법","t":"고양이가 도망간 것 같아.","e":"'Me parece que ~(~인 것 같다)'는 긍정문일 때 의견을 말하는 표현이라 que절에 직설법을 씁니다. 방금 일어난 일이므로 현재완료 se ha escapado가 정답입니다. 부정문 'No me parece que ~'가 되면 접속법(se haya escapado)을 씁니다.","x":["se haya escapado: 접속법이라 긍정의 parecer que 뒤에는 쓰지 않습니다 ✗","se ha escapado: 직설법 현재완료 → 정답 ✓","se escapase: 접속법 과거라 ✗","se escape: 접속법 현재라 ✗"]},{"id":"G260","q":"Teniendo en cuenta que apenas ha venido gente a la fiesta, ____ mejor cancelarla.","o":["estaría siendo","habría sido","ha sido","sería"],"a":1,"k":"조건완료 (과거 판단)","t":"파티에 사람이 거의 오지 않은 걸 고려하면, 취소하는 게 나았을 것이다.","e":"이미 일어난 일(사람이 거의 안 옴)을 보고 '~하는 게 나았을 텐데'라고 과거에 대한 아쉬움을 말할 때는 조건완료(habría + 과거분사)를 씁니다. 'habría sido mejor cancelarla'는 '취소했으면 더 좋았을 것이다'라는 뜻입니다. apenas는 '거의 ~않다'라는 뜻입니다.","x":["estaría siendo: ser의 진행형은 이런 판단 표현에 쓰지 않습니다 ✗","habría sido: 과거에 대한 가정적 판단(조건완료) → 정답 ✓","ha sido: 현재완료라 '취소한 것이 좋았다'는 사실이 되어 ✗","sería: 현재·미래 판단이라 이미 열린 파티에는 덜 적절합니다 ✗"]},{"id":"G261","q":"Hemos presenciado ____ accidente muy cerca de aquí.","o":["una","a un","un","ø"],"a":2,"k":"부정관사 un","t":"우리는 이 근처에서 사고를 목격했다.","e":"처음 언급하는 불특정한 하나의 사건은 부정관사(un, una)를 씁니다. accidente(사고)는 남성 명사이므로 un입니다. presenciar(목격하다)의 목적어가 사물이므로 전치사 a는 필요 없습니다.","x":["una: accidente는 남성 명사라 여성 관사는 ✗","a un: 사물 목적어 앞에는 인칭의 a를 쓰지 않습니다 ✗","un: 남성 단수 부정관사 → 정답 ✓","ø: 셀 수 있는 단수 명사 목적어라 관사가 필요합니다 ✗"]},{"id":"G262","q":"¿Otra vez ____ han perdido las llaves?","o":["a ti se","te se","a ti las","se te"],"a":3,"k":"se + 간접목적격 (비의도)","t":"또 열쇠를 잃어버렸어?","e":"'se + 간접목적격 대명사 + 동사'는 의도하지 않은 사고(~이 그만 ~해 버렸다)를 나타냅니다. 'Se te han perdido las llaves'는 '(너도 모르게) 열쇠가 없어졌다'는 뜻으로, 주어는 las llaves(복수)입니다. 대명사 순서는 항상 se가 먼저 옵니다(se te, se me, se le).","x":["a ti se: 'a ti'를 넣을 수는 있지만 이 경우 te도 함께 필요해서 'A ti se te'가 되어야 합니다 ✗","te se: 대명사 순서가 틀렸습니다. se가 항상 먼저 옵니다 ✗","a ti las: las는 직접목적격이고 se가 없어 비의도 구문이 되지 않습니다 ✗","se te: 비의도의 se + 간접목적격 te → 정답 ✓"]},{"id":"G263","q":"____ su avanzada edad, lleva una vida muy activa.","o":["Según","A causa de","A pesar de","Debido a"],"a":2,"k":"a pesar de (양보)","t":"고령인데도 그는 아주 활동적인 삶을 산다.","e":"'a pesar de + 명사'는 '~에도 불구하고'라는 양보의 뜻입니다. 나이가 많은데 오히려 활동적이라는 반대되는 내용이므로 a pesar de가 정답입니다. a causa de, debido a는 '~ 때문에'라는 원인을 나타내 뜻이 반대가 됩니다.","x":["Según: '~에 따르면'이라 뜻이 맞지 않습니다 ✗","A causa de: '~ 때문에'라는 원인이라 의미가 반대가 됩니다 ✗","A pesar de: '~에도 불구하고' → 정답 ✓","Debido a: '~ 때문에'라는 원인이라 ✗"]},{"id":"G264","q":"No me gusta ____ que me llamen por teléfono después de las 11 de la noche.","o":["nada","bastante","alguno","algo"],"a":0,"k":"no ... nada (강조)","t":"나는 밤 11시 이후에 전화 오는 게 정말 싫다.","e":"'No me gusta nada ~'는 '~이 전혀(조금도) 마음에 들지 않는다'라는 강한 부정입니다. 여기서 nada는 '아무것도'가 아니라 '전혀'라는 부사로 쓰였습니다. 이중부정이라 no와 nada를 함께 씁니다.","x":["nada: 'no ... nada(전혀 ~ 않다)' → 정답 ✓","bastante: '꽤'라는 뜻이라 no와 함께 쓰면 '그다지 좋아하지 않는다'로 어색합니다 ✗","alguno: 형용사/대명사라 이 자리에 쓰지 않습니다 ✗","algo: 긍정문용 '조금'이라 부정문에서는 nada로 바꿉니다 ✗"]},{"id":"G265","q":"Mi madre me pidió que me ____ en casa con mi hermano pequeño.","o":["quedaré","quedaría","quedo","quedara"],"a":3,"k":"pedir que + 접속법 과거","t":"엄마는 나에게 남동생과 함께 집에 있으라고 부탁했다.","e":"'pedir que(~해 달라고 부탁하다)' 뒤에는 접속법을 씁니다. 주절이 과거(pidió)이므로 접속법 과거 quedara를 씁니다. quedarse(머물다)는 재귀동사이므로 'me quedara'가 됩니다.","x":["quedaré: 직설법 미래라 부탁 표현 뒤에는 ✗","quedaría: 조건법이라 ✗","quedo: 직설법 현재라 ✗","quedara: 과거 주절에 맞춘 접속법 과거 → 정답 ✓"]},{"id":"G266","q":"____ no he terminado de leer este libro.","o":["Todavía","Ya","Casi","Aun"],"a":0,"k":"todavía no","t":"나는 아직 이 책을 다 읽지 못했다.","e":"'todavía no ~'는 '아직 ~하지 않았다'라는 뜻입니다. 'Todavía no he terminado'는 '아직 끝내지 못했다'입니다. 같은 뜻으로 악센트가 있는 'aún'도 쓸 수 있지만, 악센트 없는 'aun'은 '~조차(incluso)'라는 다른 뜻입니다.","x":["Todavía: 'todavía no(아직 ~ 않다)' → 정답 ✓","Ya: 'ya no'는 '더 이상 ~ 않다'라는 뜻이라 문맥과 맞지 않습니다 ✗","Casi: '거의'라서 'casi no he terminado'는 어색합니다 ✗","Aun: 악센트가 없으면 '~조차'라는 뜻이라 ✗(aún이면 가능)"]},{"id":"G267","q":"Federico García Lorca ____ en 1936.","o":["había fallecido","falleció","fallecía","estuvo falleciendo"],"a":1,"k":"단순과거 (역사적 사실)","t":"페데리코 가르시아 로르카는 1936년에 사망했다.","e":"특정 연도에 일어나 끝난 일, 특히 역사적 사건은 단순과거로 씁니다. 사망은 한 순간에 일어나는 사건이므로 falleció가 정답입니다. fallecer는 morir(죽다)의 정중한 표현입니다. 로르카는 스페인의 유명한 시인·극작가입니다.","x":["había fallecido: 대과거라 다른 과거 시점보다 앞섰다는 기준이 없어 ✗","falleció: 특정 시점의 완료된 사건 → 정답 ✓","fallecía: 불완료과거라 한 번의 사망 사건에는 ✗","estuvo falleciendo: 순간적 사건인 사망에 진행형을 쓰지 않습니다 ✗"]},{"id":"G268","q":"Creo que en el futuro los coches ____ más ligeros que ahora.","o":["sean","serán","estarán siendo","habrán sido"],"a":1,"k":"creer que + 직설법 미래","t":"나는 미래에는 자동차가 지금보다 가벼워질 거라고 생각한다.","e":"'Creo que ~(~라고 생각한다)'가 긍정문이면 que절에 직설법을 씁니다. 'en el futuro(미래에)'라는 표현이 있으므로 ser의 직설법 미래 serán이 정답입니다. 'No creo que ~'라면 접속법(sean)을 씁니다.","x":["sean: 접속법이라 긍정의 creer 뒤에는 ✗","serán: 직설법 미래 → 정답 ✓","estarán siendo: 미래진행형은 이런 예측에 쓰지 않습니다 ✗","habrán sido: 미래완료라 '~였을 것이다'라는 뜻이 되어 ✗"]},{"id":"G269","q":"Ana me pidió que le ____ el documento por correo electrónico.","o":["enviara","envío","enviaré","enviaría"],"a":0,"k":"pedir que + 접속법 과거","t":"아나는 나에게 그 서류를 이메일로 보내 달라고 부탁했다.","e":"'pedir que' 뒤에는 접속법을 쓰고, 주절이 과거(pidió)이므로 접속법 과거를 씁니다. 그래서 enviar의 접속법 과거 1인칭 enviara가 정답입니다. 'le'는 Ana(그녀에게)를 가리키는 간접목적격입니다.","x":["enviara: 과거 주절에 맞춘 접속법 과거 → 정답 ✓","envío: 직설법 현재라 ✗","enviaré: 직설법 미래라 ✗","enviaría: 조건법이라 pedir que 뒤에 쓰지 않습니다 ✗"]},{"id":"G270","q":"Alba se ha enamorado ____ José Miguel.","o":["con","hacia","por","de"],"a":3,"k":"enamorarse de","t":"알바는 호세 미겔에게 반했다(사랑에 빠졌다).","e":"'enamorarse de ~'는 '~와 사랑에 빠지다, ~에게 반하다'라는 뜻으로 전치사 de를 씁니다. 한국어로 '~와'라고 해서 con을 쓰지 않도록 주의하세요. 예: Me enamoré de Sevilla. (나는 세비야에 반했다.)","x":["con: 한국어 '~와'에 끌려 쓰기 쉽지만 enamorarse con은 틀립니다 ✗","hacia: '~쪽으로'라는 방향이라 ✗","por: enamorarse por는 쓰지 않습니다 ✗","de: 'enamorarse de(~에게 반하다)' → 정답 ✓"]},{"id":"G271","q":"Ana no es de Barcelona, pero Susana sí ____ es.","o":["se","la","le","lo"],"a":3,"k":"중성 대명사 lo","t":"아나는 바르셀로나 출신이 아니지만, 수사나는 그렇다.","e":"ser, estar, parecer 뒤에 오는 보어(여기서는 'de Barcelona')를 대신할 때는 성·수와 관계없이 중성 대명사 lo를 씁니다. 'Susana sí lo es'는 '수사나는 (바르셀로나 출신이) 맞다'라는 뜻입니다. 주어가 여성이어도 la를 쓰지 않습니다.","x":["se: 재귀대명사라 보어를 대신할 수 없습니다 ✗","la: 보어를 받는 대명사는 여성 주어라도 lo입니다 ✗","le: 간접목적격이라 보어 자리에 쓰지 않습니다 ✗","lo: ser의 보어를 대신하는 중성 대명사 → 정답 ✓"]},{"id":"G272","q":"____ sobrino mío está trabajando en Estados Unidos.","o":["Lo","Uno","El","Un"],"a":3,"k":"un + 명사 + 소유 후치형","t":"내 조카 한 명이 미국에서 일하고 있다.","e":"'Un sobrino mío'는 '내 조카들 중 한 명'이라는 뜻으로, 부정관사 un + 명사 + 뒤에 오는 소유형용사(mío)의 구조입니다. 정관사 el과 mío를 함께 쓰면 '그 조카'처럼 특정한 의미가 되어 어색해지고, 보통 'mi sobrino'라고 합니다.","x":["Lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗","Uno: 명사 앞에서는 uno가 un으로 줄어듭니다 ✗","El: 'el sobrino mío'는 특정·강조 용법이라 일반적이지 않습니다 ✗","Un: '내 조카 한 명' = un sobrino mío → 정답 ✓"]},{"id":"G273","q":"¿Me dejas tu diccionario ____ latín?","o":["de la","del","en","de"],"a":3,"k":"de + 언어 (관사 없음)","t":"네 라틴어 사전 좀 빌려줄래?","e":"'diccionario de latín(라틴어 사전)'처럼 '명사 + de + 명사'로 종류나 분야를 나타낼 때는 de 뒤에 관사를 쓰지 않습니다. 같은 예로 'clase de inglés(영어 수업)', 'profesor de música(음악 선생님)'가 있습니다.","x":["de la: latín은 남성 명사이고, 종류를 나타낼 때 관사를 넣지 않습니다 ✗","del: 'de + el'로 관사가 들어가 종류 표현에 어색합니다 ✗","en: 'diccionario en latín'은 '라틴어로 쓰인 사전'이라는 뜻이라 일반적인 표현이 아닙니다 ✗","de: 종류를 나타내는 '명사 + de + 명사' → 정답 ✓"]},{"id":"G274","q":"Almudena ____ triste, ¿qué le habrá pasado?","o":["le parece","parece se","se parece","parece"],"a":3,"k":"parecer + 형용사","t":"알무데나가 슬퍼 보여. 무슨 일이 있었을까?","e":"'parecer + 형용사'는 '~해 보인다'라는 뜻으로, 대명사 없이 씁니다. 'Almudena parece triste'는 '알무데나가 슬퍼 보인다'입니다. 'se parece'는 parecerse(닮다)라서 뜻이 달라집니다. '¿qué le habrá pasado?'의 미래완료는 과거에 대한 추측(~했을까?)을 나타냅니다.","x":["le parece: '그에게 ~처럼 보인다'는 구조로, 주어가 Almudena인 문장과 맞지 않습니다 ✗","parece se: 대명사 위치가 틀린 형태입니다 ✗","se parece: parecerse는 '닮다'라는 뜻이라 ✗","parece: 'parecer + 형용사(~해 보인다)' → 정답 ✓"]},{"id":"G275","q":"No quiero que me ____ más de lo que merezco.","o":["pagues","pagarías","pagas","pagarás"],"a":0,"k":"querer que + 접속법","t":"내가 받을 만한 것보다 더 많이 나에게 돈을 주는 건 원하지 않아.","e":"'querer que(~하기를 원하다)'처럼 바람을 나타내는 동사 뒤에 주어가 바뀌는 que절이 오면 접속법을 씁니다. 그래서 pagar의 접속법 현재 2인칭 pagues가 정답입니다. pagar는 접속법에서 발음을 유지하려고 g 뒤에 u가 들어갑니다(pague, pagues).","x":["pagues: 바람 표현 뒤 접속법 현재 → 정답 ✓","pagarías: 조건법이라 ✗","pagas: 직설법이라 querer que 뒤에는 ✗","pagarás: 직설법 미래라 ✗"]},{"id":"G276","q":"Ayer hacía mucho frío; ____, fuimos a dar un paseo por la playa.","o":["en cambio","aun así","aunque","por el contrario"],"a":1,"k":"aun así (그럼에도)","t":"어제는 아주 추웠다. 그런데도 우리는 해변으로 산책을 갔다.","e":"'aun así'는 '그럼에도, 그런데도'라는 뜻으로, 앞의 내용(추위)에도 불구하고 예상과 다른 행동을 했을 때 씁니다. 세미콜론 뒤에 쉼표와 함께 오는 연결어 자리이므로 aun así가 정답입니다. aunque는 접속사라 이 자리에 쓰지 않습니다.","x":["en cambio: '반면에'라는 두 대상의 대조라 ✗","aun así: '그럼에도 불구하고' → 정답 ✓","aunque: 접속사(~이지만)라 '; ____,' 같은 연결어 자리에는 맞지 않습니다 ✗","por el contrario: '반대로'라는 대조라 양보의 뜻과 다릅니다 ✗"]},{"id":"G277","q":"¿Me ayudas ____ hacer la tarea de la escuela?","o":["a","ø","por","de"],"a":0,"k":"ayudar a","t":"학교 숙제 하는 거 도와줄래?","e":"'ayudar a + 동사원형'은 '~하는 것을 돕다'라는 뜻으로 항상 전치사 a를 씁니다. 예: Te ayudo a llevar las bolsas. (봉지 드는 거 도와줄게.) 'la tarea'는 중남미에서 주로 '숙제'라는 뜻이고, 스페인에서는 'los deberes'를 많이 씁니다.","x":["a: 'ayudar a + 동사원형' → 정답 ✓","ø: ayudar 뒤 동사원형 앞에는 a가 필요합니다 ✗","por: ayudar por는 쓰지 않습니다 ✗","de: ayudar de는 틀린 결합입니다 ✗"]},{"id":"G278","q":"¿Cuándo ____ Carlos y Celia?","o":["rompieron","se rompían","rompían","se rompieron"],"a":0,"k":"romper (헤어지다)","t":"카를로스와 셀리아는 언제 헤어졌어?","e":"romper는 사람 사이에 쓰면 '(연인이) 헤어지다'라는 뜻이며, 이때는 재귀대명사 없이 씁니다. 언제 헤어졌는지 끝난 과거 사건을 묻기 때문에 단순과거 rompieron이 정답입니다. romperse는 '(물건이) 깨지다, 부러지다'라는 뜻입니다.","x":["rompieron: '헤어지다'의 단순과거 → 정답 ✓","se rompían: romperse는 '깨지다'이고 불완료과거라 ✗","rompían: 불완료과거라 한 번 끝난 사건(헤어짐)에는 ✗","se rompieron: '(물건이) 깨졌다'라는 뜻이 되어 ✗"]},{"id":"G279","q":"Odiamos ____ el autobús, por eso preferimos caminar hasta nuestra escuela.","o":["que esperemos","a esperar","esperando","esperar"],"a":3,"k":"감정동사 + 동사원형","t":"우리는 버스 기다리는 게 너무 싫어서 학교까지 걸어가는 게 더 좋다.","e":"odiar(싫어하다), gustar처럼 감정을 나타내는 동사 뒤에서 그 행동을 하는 사람이 주어와 같을 때는 동사원형을 씁니다. 주어가 다를 때만 'que + 접속법'을 씁니다(Odiamos que nos hagan esperar). 그래서 esperar가 정답입니다.","x":["que esperemos: 주어가 같을 때는 que절 대신 동사원형을 씁니다 ✗","a esperar: odiar 뒤에 a를 넣지 않습니다 ✗","esperando: 영어(-ing)처럼 현재분사를 목적어로 쓰지 않습니다 ✗","esperar: 주어가 같을 때의 동사원형 → 정답 ✓"]},{"id":"G280","q":"Al escuchar mi respuesta, me miró ____.","o":["sorprenda","sorprendida","sorprendiendo","sorprendente"],"a":1,"k":"과거분사 (형용사)","t":"내 대답을 듣고 그녀는 놀란 눈으로 나를 쳐다봤다.","e":"sorprendido/a(놀란)는 과거분사가 형용사로 쓰여 '놀란 상태로'라는 뜻이 됩니다. 쳐다본 사람의 상태를 나타내며, 주어(그녀)에 맞춰 여성형 sorprendida가 됩니다. sorprendente는 '놀라운(남을 놀라게 하는)'이라는 뜻이라 다릅니다.","x":["sorprenda: 접속법 동사형이라 형용사 자리에 쓰지 않습니다 ✗","sorprendida: '놀란(상태)' 여성형 → 정답 ✓","sorprendiendo: '놀라게 하면서'라는 뜻이 되어 맞지 않습니다 ✗","sorprendente: '놀라운(남을 놀라게 하는)'이라는 뜻이라 ✗"]},{"id":"G281","q":"El bolso que ____ has regalado a María del Carmen es precioso.","o":["la","le","ø","les"],"a":1,"k":"간접목적격 le","t":"네가 마리아 델 카르멘에게 선물한 가방 정말 예쁘다.","e":"regalar(선물하다)에서 선물을 받는 사람은 간접목적격입니다. 'a María del Carmen(마리아 델 카르멘에게)'은 3인칭 단수이므로 le를 씁니다. 여성이라도 간접목적격은 le입니다(la는 직접목적격).","x":["la: 여성 직접목적격(그녀를)이라 받는 사람에게는 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓","ø: 'a + 사람'이 있을 때 le를 함께 쓰는 것이 자연스러운 스페인어입니다 ✗","les: 복수라 한 사람에게는 ✗"]},{"id":"G282","q":"Hoy estamos ____ 1 de junio.","o":["a","para","por","en"],"a":0,"k":"estar a + 날짜","t":"오늘은 6월 1일이다.","e":"날짜를 말할 때 'estar a + 날짜' 구조를 씁니다. 'Estamos a 1 de junio'는 '오늘은 6월 1일이다'라는 뜻입니다. 같은 뜻으로 'Hoy es 1 de junio'도 씁니다. 날짜를 물을 때는 '¿A qué estamos hoy?'라고 합니다.","x":["a: 'estar a + 날짜' → 정답 ✓","para: 'para el 1 de junio'는 '6월 1일까지'라는 기한이라 ✗","por: 날짜 표현에 쓰지 않습니다 ✗","en: 'estar en'은 장소에 쓰고 날짜 표현에는 쓰지 않습니다 ✗"]},{"id":"G283","q":"____ una peli cuando llegó Martina.","o":["Hemos estado viendo","Estábamos viendo","Estuvimos viendo","Veíamos"],"a":1,"k":"과거진행 (배경)","t":"마르티나가 왔을 때 우리는 영화를 보고 있었다.","e":"과거에 진행 중이던 행동(영화 보는 중)에 다른 사건(마르티나 도착)이 일어났을 때, 배경은 'estar의 불완료과거 + 현재분사'(estábamos viendo)로 씁니다. 'cuando llegó'의 단순과거가 그 순간의 사건입니다. peli는 película(영화)의 구어 줄임말입니다.","x":["Hemos estado viendo: 현재완료진행이라 과거 이야기에 맞지 않습니다 ✗","Estábamos viendo: 그 순간 진행 중이던 배경 → 정답 ✓","Estuvimos viendo: 끝난 기간의 행동이라 배경으로 쓰지 않습니다 ✗","Veíamos: 불완료과거로도 가능하지만, 그 순간 진행 중이라는 뜻은 진행형이 더 정확합니다 ✗"]},{"id":"G284","q":"No me gusta el resultado del trabajo. ____, tendré que hacerlo otra vez.","o":["Por consiguiente","Así que","Consecuente","Consiguiente"],"a":0,"k":"por consiguiente","t":"작업 결과가 마음에 들지 않는다. 따라서 다시 해야 할 것이다.","e":"'por consiguiente'는 '따라서, 그러므로'라는 뜻의 결과 연결어로, 문장 맨 앞에서 쉼표와 함께 쓸 수 있습니다. 'por lo tanto'와 같은 뜻의 다소 격식 있는 표현입니다. 'así que'는 보통 두 절을 한 문장 안에서 이어 줄 때 씁니다.","x":["Por consiguiente: '따라서' → 정답 ✓","Así que: '그래서'라는 뜻이지만 보통 마침표 뒤 문장 첫머리에서 쉼표와 함께 쓰지 않습니다 ✗","Consecuente: '일관된'이라는 형용사라 연결어가 아닙니다 ✗","Consiguiente: 'por'가 빠진 형용사(결과로 생기는)라서 ✗"]},{"id":"G285","q":"Me preocupa el futuro ____ planeta.","o":["de la","del","a la","al"],"a":1,"k":"del (de + el)","t":"나는 지구의 미래가 걱정된다.","e":"planeta는 -a로 끝나지만 남성 명사(el planeta)입니다. 그래서 'de + el = del'이 되어 'el futuro del planeta'가 됩니다. 비슷하게 el problema, el idioma, el mapa도 -a로 끝나는 남성 명사입니다.","x":["de la: planeta는 남성 명사라 여성 관사는 ✗","del: 'de + el planeta(지구의)' → 정답 ✓","a la: 여성 관사이고 방향을 나타내 ✗","al: 'a + el'로 '~에게, ~로'라는 뜻이라 소유 관계를 나타내지 못합니다 ✗"]},{"id":"G286","q":"No te recomiendo leer ese libro ____ que tengas un nivel muy alto de inglés.","o":["excepto si","de no ser","si no","a no ser"],"a":3,"k":"a no ser que + 접속법","t":"영어 실력이 아주 높지 않다면 그 책을 읽는 건 추천하지 않아.","e":"'a no ser que(~하지 않는 한, ~이 아니라면)'는 예외 조건을 나타내는 접속사로, 뒤에 항상 접속법이 옵니다. 빈칸 뒤 'que tengas'에 que와 접속법이 있으므로 a no ser가 정답입니다. 같은 뜻으로 'salvo que', 'excepto que'도 씁니다.","x":["excepto si: 'excepto si' 뒤에는 que 없이 직설법이 옵니다 ✗","de no ser: 'de no ser que'라는 형태는 일반적이지 않습니다(de no ser por ~가 일반적) ✗","si no: 'si no que'는 틀린 형태입니다 ✗","a no ser: 'a no ser que + 접속법' → 정답 ✓"]},{"id":"G287","q":"¿Quién ____ dijo eso a Esther?","o":["lo","se lo","le","la"],"a":2,"k":"간접목적격 le","t":"누가 에스테르에게 그 말을 했니?","e":"decir(말하다)에서 말을 듣는 사람은 간접목적격입니다. 'a Esther'가 3인칭 단수이므로 le를 씁니다. 직접목적어 eso가 동사 뒤에 명사로 나와 있으므로 lo를 따로 쓰지 않습니다. 대명사로 바꾸면 '¿Quién se lo dijo?'가 됩니다.","x":["lo: 직접목적격인데, 동사 뒤에 eso가 이미 있어 중복됩니다 ✗","se lo: lo가 eso와 중복되므로 이 문장에서는 쓰지 않습니다 ✗","le: 3인칭 단수 간접목적격(그녀에게) → 정답 ✓","la: 직접목적격(그녀를)이라 말을 듣는 사람에게 쓰지 않습니다 ✗"]},{"id":"G288","q":"Es tímido, ____ no habla mucho.","o":["pese a que","aunque","por eso","de ahí que"],"a":2,"k":"por eso (결과)","t":"그는 수줍음이 많아서 말을 많이 하지 않는다.","e":"'por eso'는 '그래서, 그 때문에'라는 결과 연결어입니다. 수줍음(원인) → 말을 많이 하지 않음(결과)이므로 por eso가 정답이며, 뒤에 직설법(habla)이 옵니다. de ahí que도 결과를 나타내지만 뒤에 접속법(hable)이 와야 합니다.","x":["pese a que: '~에도 불구하고'라는 양보라 뜻이 맞지 않습니다 ✗","aunque: '~이지만'이라 원인과 결과 관계가 아닙니다 ✗","por eso: '그래서' + 직설법 → 정답 ✓","de ahí que: 결과를 나타내지만 뒤에 접속법(hable)이 와야 해서 ✗"]},{"id":"G289","q":"No soporto a la gente que ____ todo el rato a los demás.","o":["critican","critique","critiquen","critica"],"a":3,"k":"관계절 + 직설법 (gente)","t":"나는 늘 다른 사람들을 비판하는 사람들을 참을 수 없다.","e":"gente(사람들)는 뜻은 복수지만 문법적으로는 단수 명사라서 동사도 3인칭 단수(critica)를 씁니다. 또 그런 사람들이 실제로 존재한다고 보고 말하는 것이므로 관계절에 직설법을 씁니다. 'todo el rato'는 '늘, 계속'이라는 뜻입니다.","x":["critican: gente는 단수 취급하므로 복수 동사는 ✗","critique: 접속법이라 실제 존재하는 사람들에 대한 서술에는 ✗","critiquen: 복수이고 접속법이라 ✗","critica: 단수 + 직설법 → 정답 ✓"]},{"id":"G290","q":"Esperaré hasta que ____ mi madre.","o":["volverá","volviera","vuelve","vuelva"],"a":3,"k":"hasta que + 접속법","t":"엄마가 돌아올 때까지 기다릴게.","e":"'hasta que(~할 때까지)' 뒤에 아직 일어나지 않은 미래의 일이 오면 접속법 현재를 씁니다. 주절이 미래(esperaré)이므로 volver의 접속법 현재 vuelva가 정답입니다. volver는 o→ue로 변하는 동사입니다.","x":["volverá: 시간절에는 미래형을 쓰지 않습니다 ✗","volviera: 접속법 과거라 주절이 미래일 때는 ✗","vuelve: 직설법은 습관이나 사실일 때 씁니다 ✗","vuelva: 미래 시간절의 접속법 현재 → 정답 ✓"]},{"id":"G291","q":"Estos son los ____ alumnos de la facultad.","o":["más mejores","más mejor","mejor","mejores"],"a":3,"k":"불규칙 최상급 mejores","t":"이들이 학부에서 가장 우수한 학생들이다.","e":"bueno(좋은)의 비교급·최상급은 불규칙형 mejor입니다. 이미 '더 좋은'이라는 뜻이라 앞에 más를 붙이지 않습니다. 최상급은 '정관사 + mejor(es) + 명사'로 쓰고, alumnos가 복수이므로 mejores가 됩니다.","x":["más mejores: mejor에 이미 '더'의 뜻이 있어 más를 붙이면 틀립니다 ✗","más mejor: más 중복이고 수도 맞지 않습니다 ✗","mejor: 복수 명사 alumnos와 수가 맞지 않습니다 ✗","mejores: 복수형 최상급 → 정답 ✓"]},{"id":"G292","q":"No me gusta ____ té, prefiero el café.","o":["ø","un","la","el"],"a":3,"k":"gustar + 정관사","t":"나는 차(茶)를 좋아하지 않는다. 커피가 더 좋다.","e":"gustar 구문에서 좋아하거나 싫어하는 대상을 일반적으로 말할 때는 정관사를 붙입니다. 'Me gusta el café(나는 커피를 좋아한다)'처럼 té(차)는 남성 명사라 el을 씁니다. 뒷문장 'prefiero el café'도 같은 원리입니다.","x":["ø: gustar의 주어(일반적 대상)에는 정관사가 필요합니다 ✗","un: '차 한 잔'이라는 뜻이 되어 일반적인 취향과 맞지 않습니다 ✗","la: té는 남성 명사라 ✗","el: gustar 구문의 일반 대상 + 남성 정관사 → 정답 ✓"]},{"id":"G293","q":"Ese hombre, ____ es mi vecino, trabaja en el ayuntamiento.","o":["el que","que","cuyo","cual"],"a":1,"k":"설명적 관계절 que","t":"그 남자는 내 이웃인데, 시청에서 일한다.","e":"쉼표 사이에 들어가 선행사를 덧붙여 설명하는 관계절(설명적 관계절)에서 주어 역할을 할 때는 que를 가장 많이 씁니다. 'Ese hombre, que es mi vecino, ...'는 '그 남자는, (그는) 내 이웃인데'라는 뜻입니다. 이 자리에는 'el cual'이나 'quien'도 가능하지만 'el que'는 어색합니다.","x":["el que: 쉼표 사이의 주어 관계절에는 잘 쓰지 않습니다 ✗","que: 설명적 관계절의 주어 → 정답 ✓","cuyo: '~의'라는 소유 관계사라 뒤에 명사가 와야 합니다 ✗","cual: 관사 없이 단독으로 관계대명사로 쓰지 않습니다(el cual) ✗"]},{"id":"G294","q":"____ analizado el texto, comentaréis las ideas principales.","o":["Tan pronto como","Cuando","Una vez","En cuanto"],"a":2,"k":"una vez + 과거분사","t":"글을 분석하고 나면, 너희들은 주요 내용에 대해 이야기하게 될 거야.","e":"'una vez + 과거분사'는 '일단 ~하고 나면, ~한 뒤에'라는 뜻의 분사 구문입니다. 'Una vez analizado el texto'는 '글이 분석되고 나면'이라는 뜻입니다. 나머지 접속사(tan pronto como, cuando, en cuanto)는 뒤에 활용된 동사가 와야 합니다.","x":["Tan pronto como: 접속사라 뒤에 활용된 동사(hayáis analizado)가 필요합니다 ✗","Cuando: 뒤에 활용된 동사가 와야 합니다 ✗","Una vez: 'una vez + 과거분사' 구문 → 정답 ✓","En cuanto: 활용된 동사가 필요해서 과거분사만으로는 ✗"]},{"id":"G295","q":"Este no es mi libro, el mío es ____ que está lleno de anotaciones.","o":["alguno","uno","un","lo"],"a":1,"k":"부정대명사 uno","t":"이건 내 책이 아니야. 내 책은 메모가 가득한 거야.","e":"'uno que ~'는 '~하는 것(하나)'이라는 뜻으로, 앞에 나온 명사(libro)를 대신하는 부정대명사입니다. 명사 없이 단독으로 쓸 때는 un이 아니라 uno를 씁니다. 'anotaciones'는 '메모, 주석'이라는 뜻입니다.","x":["alguno: '어떤 것'이라는 막연한 뜻이라 자기 책을 설명하는 데 어색합니다 ✗","uno: 명사를 대신하는 '~하는 것(하나)' → 정답 ✓","un: 명사 앞에서만 쓰는 형태라 단독으로는 ✗","lo: 중성이라 libro처럼 구체적인 명사를 대신하지 않습니다 ✗"]},{"id":"G296","q":"Todos ____ hayan terminado el ejercicio pueden salir al recreo.","o":["que","los que","los quienes","cuales"],"a":1,"k":"todos los que","t":"연습 문제를 다 끝낸 사람은 모두 쉬는 시간에 나가도 된다.","e":"'todos los que ~'는 '~하는 사람은 모두'라는 뜻입니다. 선행사가 없는 관계절에서는 관사 + que(los que)를 씁니다. 아직 누가 끝낼지 모르므로 관계절 동사가 접속법(hayan terminado)입니다.","x":["que: 'todos que'는 관사가 빠진 틀린 형태입니다 ✗","los que: 'todos los que(~하는 사람 모두)' → 정답 ✓","los quienes: quien 앞에는 관사를 붙이지 않습니다 ✗","cuales: 관사 없이 관계대명사로 쓰지 않습니다 ✗"]},{"id":"G297","q":"____ día me acordé de la fiesta de graduación y de lo bien que lo pasamos.","o":["Otros","La otra","El otro","Una otra"],"a":2,"k":"el otro día","t":"얼마 전에 졸업 파티와 우리가 얼마나 즐거웠는지가 떠올랐다.","e":"'el otro día'는 '요전 날, 얼마 전에'라는 굳어진 표현입니다. día는 남성 명사이므로 el otro를 씁니다. otro 앞에는 부정관사 un/una를 쓰지 않는다는 점도 기억하세요(otro día = 다른 날).","x":["Otros: 복수라 단수 día와 맞지 않습니다 ✗","La otra: día는 -a로 끝나지만 남성 명사라 ✗","El otro: 'el otro día(요전 날)' → 정답 ✓","Una otra: otro 앞에 부정관사를 쓰지 않고, 성도 맞지 않습니다 ✗"]},{"id":"G298","q":"Lo siento, tengo mucho ____ hacer, no puedo atenderte en este momento.","o":["de","a","que","lo cual"],"a":2,"k":"tener mucho que + 동사원형","t":"미안해, 할 일이 많아서 지금은 너를 도와줄 수가 없어.","e":"'tener (mucho/algo/nada) que + 동사원형'은 '~할 것이 (많이) 있다'라는 뜻입니다. 'tengo mucho que hacer'는 '할 일이 많다'입니다. 'tener que + 동사원형(~해야 한다)'과 같은 que를 씁니다.","x":["de: 'tener mucho de hacer'는 틀린 형태입니다 ✗","a: 'tener mucho a hacer'는 프랑스어식 표현이라 스페인어에서는 쓰지 않습니다 ✗","que: 'tener mucho que hacer(할 일이 많다)' → 정답 ✓","lo cual: 관계대명사라 이 자리에 쓰지 않습니다 ✗"]},{"id":"G299","q":"Te pido que me ____.","o":["perdones","perdonas","has perdonado","estés perdonando"],"a":0,"k":"pedir que + 접속법","t":"나를 용서해 달라고 부탁할게.","e":"'pedir que(~해 달라고 부탁하다)' 뒤에는 접속법을 씁니다. 주절이 현재(pido)이므로 perdonar의 접속법 현재 2인칭 perdones가 정답입니다. 'Te pido que me perdones'는 정중하게 사과할 때 쓰는 표현입니다.","x":["perdones: 부탁 표현 뒤 접속법 현재 → 정답 ✓","perdonas: 직설법이라 pedir que 뒤에는 ✗","has perdonado: 직설법 현재완료라 ✗","estés perdonando: 접속법이지만 진행형이라 부탁 내용으로 어색합니다 ✗"]},{"id":"G300","q":"Cuando salí del trabajo, las tiendas ya ____.","o":["cerraron","han cerrado","habían cerrado","cerraban"],"a":2,"k":"대과거","t":"내가 퇴근했을 때 가게들은 이미 문을 닫은 상태였다.","e":"과거의 한 시점(퇴근했을 때)보다 더 먼저 끝난 일은 대과거(había + 과거분사)로 씁니다. 'ya(이미)'와 함께 '그때는 이미 닫혀 있었다'는 뜻이므로 habían cerrado가 정답입니다. 예: Cuando llegué, la película ya había empezado. (도착했을 때 영화는 이미 시작했었다.)","x":["cerraron: 단순과거라 '내가 나왔을 때 (그때) 닫았다'가 되어 ya와 맞지 않습니다 ✗","han cerrado: 현재완료라 과거 이야기와 시제가 맞지 않습니다 ✗","habían cerrado: 과거보다 앞선 완료(대과거) → 정답 ✓","cerraban: 불완료과거라 '닫고 있었다/닫곤 했다'는 뜻이 되어 ✗"]},{"id":"G301","q":"____ no me apetece, tengo que ponerme a estudiar ahora mismo.","o":["Aunque","Ya que","Como","Así que"],"a":0,"k":"양보 접속사 aunque","t":"내키지는 않지만, 나는 지금 당장 공부를 시작해야 한다.","e":"앞 절(내키지 않는다)과 뒷 절(공부해야 한다)이 서로 반대되는 내용이므로 '~이지만, ~에도 불구하고'를 뜻하는 양보 접속사 aunque가 필요합니다. aunque 뒤에 직설법(실제 사실을 말하는 동사 형태)을 쓰면 '실제로 ~하지만'이라는 사실을 인정하는 뜻이 됩니다. 예: Aunque llueve, salgo. (비가 오지만 나간다.)","x":["Aunque: '~이지만'이라는 양보의 뜻으로 두 절의 대립 관계와 맞습니다 ✓","Ya que: '~이니까'라는 이유를 나타내므로 '내키지 않으니까 공부해야 한다'가 되어 어색합니다 ✗","Como: 문장 앞에서 '~이기 때문에'라는 이유를 나타내므로 의미가 맞지 않습니다 ✗","Así que: '그래서'라는 결과를 나타내며 문장 맨 앞에서 이런 식으로 쓰지 않습니다 ✗"]},{"id":"G302","q":"Creo que acudieron al acto ____ quinientas personas aproximadamente.","o":["las","algo","unas","algunas"],"a":2,"k":"대략의 수 unos/unas","t":"내 생각에 그 행사에는 대략 오백 명 정도가 왔던 것 같다.","e":"숫자 앞에 부정관사 복수형 unos/unas를 붙이면 '약, 대략'이라는 뜻이 됩니다. personas가 여성 복수이므로 unas를 씁니다. 문장 끝의 aproximadamente(대략)와 함께 어림수를 강조합니다. 예: Tiene unos treinta años. (그는 서른 살쯤 됐다.)","x":["las: 정관사로 '그 오백 명'이라는 특정한 사람들을 가리키게 되어 어림수 의미가 사라집니다 ✗","algo: '무언가, 약간'이라는 뜻으로 숫자 앞에서 '대략'의 의미로 쓰지 않습니다 ✗","unas: 숫자 앞에서 '대략, ~쯤'을 뜻하며 여성 복수 personas와 일치합니다 ✓","algunas: '몇몇의'라는 뜻으로 정확한 숫자 앞에 쓰지 않습니다 ✗"]},{"id":"G303","q":"Estoy ____ dieta, por eso me notas más delgado.","o":["de","en","a","por"],"a":2,"k":"estar a dieta","t":"나는 다이어트 중이야, 그래서 내가 더 날씬해 보이는 거야.","e":"'다이어트 중이다'는 스페인어로 estar a dieta라는 고정 표현을 씁니다. 전치사 a가 '어떤 상태·관리 아래에 있다'는 의미를 줍니다. 일상 회화에서는 estar de dieta도 자주 들리지만 교재는 표준형인 a dieta를 정답으로 봅니다. 예: Mi madre está a dieta. (엄마는 다이어트 중이다.)","x":["de: 구어에서 estar de dieta도 쓰이지만 이 교재의 표준 표현은 a dieta입니다 ✗","en: estar en dieta라고는 하지 않습니다 ✗","a: estar a dieta(다이어트 중이다)라는 고정 표현 → 정답 ✓","por: por는 이유·경유를 나타내므로 이 표현과 맞지 않습니다 ✗"]},{"id":"G304","q":"No he cobrado todavía, ____ no puedo gastar nada en este momento.","o":["pero","pese a que","por eso","de ahí que"],"a":2,"k":"결과 연결어 por eso","t":"아직 월급을 받지 못해서 지금은 아무것도 쓸 수 없다.","e":"앞 절(돈을 아직 못 받았다)이 원인, 뒷 절(쓸 수 없다)이 결과이므로 '그래서'를 뜻하는 por eso가 자연스럽습니다. 같은 결과의 뜻을 가진 de ahí que는 뒤에 반드시 접속법(바람·의심·감정·추론 등을 나타내는 동사 형태)이 와야 하는데, 여기서는 직설법 puedo가 왔으므로 쓸 수 없습니다.","x":["pero: '하지만'이라는 대조의 뜻이라 원인-결과 관계와 맞지 않습니다 ✗","pese a que: '~에도 불구하고'라는 양보의 뜻이라 의미가 반대가 됩니다 ✗","por eso: '그래서'라는 결과를 나타내며 뒤에 직설법이 와도 됩니다 ✓","de ahí que: '그래서'라는 뜻이지만 뒤에 접속법(pueda)이 와야 하므로 ✗"]},{"id":"G305","q":"Ya había salido de casa cuando me ____ cuenta de que había dejado las llaves dentro.","o":["he dado","di","daba","había dado"],"a":1,"k":"단순과거 vs 대과거","t":"내가 이미 집을 나섰을 때, 열쇠를 안에 두고 왔다는 것을 깨달았다.","e":"darse cuenta de(~을 깨닫다)는 과거의 한 순간에 일어난 일이므로 단순과거(점과거, 과거에 끝난 한 번의 사건) di를 씁니다. 집을 나선 것(había salido)은 그보다 더 이전의 일이라 대과거로 표현되어 있습니다. '이미 ~했었는데, 그때 ~했다'라는 시간 순서를 잘 기억하세요.","x":["he dado: 현재완료로 현재와 연결된 시점을 나타내 과거 이야기 흐름과 맞지 않습니다 ✗","di: 과거의 한 순간에 깨달은 사건을 나타내는 단순과거 → 정답 ✓","daba: 불완료과거(과거의 반복·배경)라 순간적인 깨달음과 맞지 않습니다 ✗","había dado: 대과거면 집을 나서기 전에 깨달은 것이 되어 시간 순서가 어긋납니다 ✗"]},{"id":"G306","q":"____ por la tienda cuando podáis.","o":["Pasen","Pase","Paséis","Pasaos"],"a":3,"k":"재귀동사 명령형 vosotros","t":"너희들 시간 될 때 가게에 들러.","e":"cuando podáis(너희가 할 수 있을 때)를 보면 상대는 vosotros(너희들)입니다. pasarse(들르다)의 vosotros 긍정 명령형은 pasad + os인데, 재귀대명사 os가 붙으면 끝의 -d가 탈락해 pasaos가 됩니다. 예: Sentaos aquí. (너희 여기 앉아.) 참고로 중남미에서는 vosotros 대신 ustedes를 써서 Pásense라고 합니다.","x":["Pasen: ustedes(여러분) 명령형이라 podáis(vosotros)와 인칭이 맞지 않습니다 ✗","Pase: usted(당신) 명령형이라 인칭이 맞지 않습니다 ✗","Paséis: 접속법 현재형으로 긍정 명령에는 쓰지 않고 부정 명령(no paséis)에 씁니다 ✗","Pasaos: pasad + os에서 -d가 탈락한 vosotros 긍정 명령형 → 정답 ✓"]},{"id":"G307","q":"No está claro que el acusado ____ solo.","o":["haya actuado","actuaba","actuaría","ha actuado"],"a":0,"k":"의심 표현+접속법","t":"피고인이 혼자 행동했는지는 분명하지 않다.","e":"No está claro que(~은 분명하지 않다)는 의심·불확실성을 나타내므로 뒤에 접속법이 와야 합니다. 범행은 이미 과거에 일어난 일이므로 접속법 현재완료 haya actuado를 씁니다. 반대로 Está claro que(~은 분명하다)라면 직설법 ha actuado를 씁니다.","x":["haya actuado: 의심 표현 뒤 접속법 현재완료로 과거 행위를 나타냄 → 정답 ✓","actuaba: 직설법 불완료과거라 의심 표현 뒤에 쓸 수 없습니다 ✗","actuaría: 가능법(조건법)이라 이 구조에 맞지 않습니다 ✗","ha actuado: 직설법이라 no está claro que 뒤에 올 수 없습니다 ✗"]},{"id":"G308","q":"¿____ dónde venís con los zapatos llenos de barro?","o":["A","De","Sobre","En"],"a":1,"k":"¿De dónde?","t":"너희들 신발에 진흙을 잔뜩 묻히고 어디서 오는 거야?","e":"venir(오다)는 출발점을 나타낼 때 전치사 de를 쓰므로 '어디에서 오니?'는 ¿De dónde venís?가 됩니다. 반대로 '어디로 가니?'는 ¿Adónde vais?처럼 a를 씁니다. venís는 vosotros형이며, 중남미에서는 ¿De dónde vienen?이라고 합니다.","x":["A: 방향(~로)을 나타내므로 venir와 함께 '어디로 오니'가 되어 어색합니다 ✗","De: 출발점(~에서)을 나타내 venir와 잘 어울립니다 ✓","Sobre: '~위에, ~에 관하여'라는 뜻이라 맞지 않습니다 ✗","En: 장소 안(~에서 머무름)을 나타내 이동의 출발점에는 쓰지 않습니다 ✗"]},{"id":"G309","q":"____ aquí donde se casaron.","o":["Estaba","Estuvo","Fue","Era"],"a":2,"k":"강조 구문 ser","t":"그들이 결혼한 곳은 바로 여기였다.","e":"'바로 ~인 것은 ~이다'처럼 어떤 부분을 강조하는 구문(분열문)에서는 동사 ser를 씁니다. 결혼은 과거에 한 번 일어난 사건이므로 ser의 단순과거 fue가 자연스럽습니다. 예: Fue Juan quien lo dijo. (그걸 말한 건 바로 후안이었다.)","x":["Estaba: estar는 강조 구문에 쓰지 않습니다 ✗","Estuvo: estar는 강조 구문에 쓰지 않습니다 ✗","Fue: 과거의 한 사건을 강조하는 ser의 단순과거 → 정답 ✓","Era: ser이지만 불완료과거라 한 번의 사건(결혼)을 강조하기에 덜 자연스럽습니다 ✗"]},{"id":"G310","q":"Esperaré a ____ mi marido del trabajo para darle la noticia.","o":["que saldrá","que salga","que sale","salir"],"a":1,"k":"esperar a que+접속법","t":"남편에게 소식을 전하려고 남편이 퇴근할 때까지 기다릴 거야.","e":"esperar a que(~할 때까지 기다리다) 뒤에는 아직 일어나지 않은 미래의 일이므로 접속법이 옵니다. 주어가 서로 다르기 때문에(나는 기다리고, 남편은 나온다) 동사원형이 아니라 que + 접속법 salga를 씁니다. 예: Espera a que llegue el autobús. (버스가 올 때까지 기다려.)","x":["que saldrá: 직설법 미래라 esperar a que 뒤에 쓸 수 없습니다 ✗","que salga: 미래의 일을 나타내는 접속법 현재 → 정답 ✓","que sale: 직설법 현재라 이 구조에 맞지 않습니다 ✗","salir: 동사원형은 주어가 같을 때만 쓰는데 여기는 주어가 달라 ✗"]},{"id":"G311","q":"¿Puedes explicarnos el ____ de tu reacción?","o":["porqué","porque","por que","por qué"],"a":0,"k":"porqué/por qué 구별","t":"네가 그렇게 반응한 이유를 우리에게 설명해 줄 수 있니?","e":"관사 el 뒤에서 '이유'라는 명사로 쓰일 때는 붙여 쓰고 악센트를 찍은 porqué를 씁니다. el porqué = la razón(이유)로 바꿔 보면 쉽게 확인할 수 있습니다. 비교: ¿Por qué? (왜?), porque (왜냐하면), por que (전치사 por + 관계사 que).","x":["porqué: '이유'를 뜻하는 명사로 관사 el 뒤에 씁니다 ✓","porque: '왜냐하면'이라는 접속사라 관사 뒤에 올 수 없습니다 ✗","por que: 전치사+관계사(~하는 그것 때문에)라 명사 자리에 맞지 않습니다 ✗","por qué: '왜'라는 의문사라 관사 뒤 명사 자리에 쓰지 않습니다 ✗"]},{"id":"G312","q":"¿____ famoso escritor nació en Granada?","o":["Dónde","Qué","Cuál","Quién"],"a":1,"k":"의문사 qué+명사","t":"어떤 유명한 작가가 그라나다에서 태어났니?","e":"의문사 바로 뒤에 명사(famoso escritor)가 올 때는 qué를 씁니다. '어떤 작가?'처럼 명사를 꾸미는 의문사는 스페인 표준어에서 qué입니다. cuál은 보통 명사 없이 단독으로 쓰거나 ser 동사 앞에 씁니다(¿Cuál es tu libro favorito?).","x":["Dónde: '어디'라는 장소 의문사라 명사를 꾸밀 수 없습니다 ✗","Qué: 명사 앞에서 '어떤'을 뜻하는 의문사 → 정답 ✓","Cuál: 명사 바로 앞에 쓰는 것은 일부 중남미 구어에서만 보이고 표준은 아닙니다 ✗","Quién: '누구'라는 뜻으로 명사 앞에 붙여 쓰지 않습니다 ✗"]},{"id":"G313","q":"Creo que ____ un buen trabajo cuando termines tus estudios.","o":["encuentras","encontrarás","encontrases","encuentres"],"a":1,"k":"creer que+직설법","t":"네가 학업을 마치면 좋은 일자리를 찾을 거라고 생각해.","e":"긍정문 Creo que(~라고 생각한다)는 말하는 사람이 사실이라고 믿는 내용이므로 직설법을 씁니다. 학업을 마친 뒤의 미래 일이므로 직설법 미래 encontrarás가 맞습니다. 반대로 No creo que처럼 부정이 되면 접속법(encuentres)을 씁니다.","x":["encuentras: 직설법 현재라 미래의 일(공부 마친 후)에 덜 맞습니다 ✗","encontrarás: 미래의 일을 믿음으로 표현하는 직설법 미래 → 정답 ✓","encontrases: 접속법 과거라 긍정 creo que 뒤에 오지 않습니다 ✗","encuentres: 접속법은 no creo que 같은 부정문 뒤에 씁니다 ✗"]},{"id":"G314","q":"____ de la fiesta sin despedirse de nadie.","o":["Se fueran","Se fueron","Fueron","Ellos fueron"],"a":1,"k":"irse 단순과거","t":"그들은 아무에게도 인사하지 않고 파티를 떠났다.","e":"'(어떤 장소를) 떠나다'는 재귀동사 irse를 씁니다. 과거에 한 번 일어난 일이므로 3인칭 복수 단순과거 se fueron이 정답입니다. ir(가다)만 쓰면 '떠나다'가 아니라 '갔다' 혹은 ser의 과거(이었다)로 오해됩니다.","x":["Se fueran: 접속법 과거라 평서문의 주동사로 쓸 수 없습니다 ✗","Se fueron: '떠났다'는 irse의 3인칭 복수 단순과거 → 정답 ✓","Fueron: se가 없으면 '떠나다'의 뜻이 되지 않습니다 ✗","Ellos fueron: 역시 se가 없어 '떠났다'가 아니며, 주어를 굳이 넣을 필요도 없습니다 ✗"]},{"id":"G315","q":"No deberíamos llegar tarde, ____ démonos prisa.","o":["conque","aunque","en cambio","sin embargo"],"a":0,"k":"결과 접속사 conque","t":"우리 늦으면 안 되니까, 서두르자.","e":"conque는 '그러니까, 그러므로'라는 결과를 나타내는 접속사로 구어에서 자주 쓰입니다. 앞 절(늦으면 안 된다)이 이유이고, 뒷 절(서두르자)이 그 결과이므로 conque가 맞습니다. con que(~으로써)와 혼동하지 않도록 붙여 쓰는 것에 주의하세요.","x":["conque: '그러니까'라는 결과 접속사 → 정답 ✓","aunque: '~이지만'이라는 양보라 의미가 맞지 않습니다 ✗","en cambio: '반면에'라는 대조 표현이라 맞지 않습니다 ✗","sin embargo: '그러나'라는 역접이라 의미가 반대가 됩니다 ✗"]},{"id":"G316","q":"Según ____, ¿qué deberíamos hacer ahora?","o":["de ti","ti","tú","para ti"],"a":2,"k":"según+주격 대명사","t":"네 생각에는 우리가 이제 뭘 해야 할까?","e":"según(~에 따르면)은 특별한 전치사로, 뒤에 인칭대명사가 올 때 전치격(mí, ti)이 아니라 주격(yo, tú)을 씁니다. 그래서 según tú, según yo가 맞습니다. entre도 마찬가지로 entre tú y yo라고 합니다.","x":["de ti: según 뒤에 다른 전치사를 겹쳐 쓰지 않습니다 ✗","ti: 대부분의 전치사 뒤에는 ti를 쓰지만 según은 예외입니다 ✗","tú: según 뒤에는 주격 대명사를 씁니다 ✓","para ti: '너에게는'이라는 뜻이 되어 según과 겹칩니다 ✗"]},{"id":"G317","q":"Los señores López ____ su mejor ropa los domingos.","o":["están poniendo","se ponen","ponen","poniéndose"],"a":1,"k":"ponerse(옷을 입다)","t":"로페스 부부는 일요일마다 가장 좋은 옷을 입는다.","e":"'(자기 몸에) 옷을 입다'는 재귀동사 ponerse를 씁니다. los domingos(일요일마다)는 습관을 나타내므로 직설법 현재 se ponen이 자연스럽습니다. poner만 쓰면 '(무언가를) 놓다, 두다'라는 뜻이 됩니다.","x":["están poniendo: 진행형이고 se도 없어 습관의 '옷을 입다'가 되지 않습니다 ✗","se ponen: 습관적으로 옷을 입는다는 재귀동사 현재형 → 정답 ✓","ponen: se가 없으면 '놓다'라는 뜻이 됩니다 ✗","poniéndose: 현재분사만으로는 문장의 주동사가 될 수 없습니다 ✗"]},{"id":"G318","q":"¿Qué tipo ____ ropa venden en esa tienda?","o":["de la","ø","la","de"],"a":3,"k":"tipo de+명사","t":"그 가게에서는 어떤 종류의 옷을 팔아?","e":"tipo de(~의 종류)는 뒤에 관사 없이 명사를 바로 붙입니다. 종류를 말할 때는 특정한 것이 아니라 일반적인 개념이므로 관사를 쓰지 않습니다. 예: ¿Qué tipo de música te gusta? (어떤 종류의 음악을 좋아해?)","x":["de la: tipo de 뒤에 관사를 넣지 않습니다 ✗","ø: 전치사 de 없이는 tipo와 ropa가 연결되지 않습니다 ✗","la: de가 빠져 있고 관사도 불필요합니다 ✗","de: tipo de + 무관사 명사 → 정답 ✓"]},{"id":"G319","q":"Pablo siempre desconfía ____ aquellos que no conoce.","o":["por","de","en","a"],"a":1,"k":"desconfiar de","t":"파블로는 자기가 모르는 사람들을 늘 믿지 않는다.","e":"desconfiar(믿지 않다, 의심하다)는 항상 전치사 de와 함께 씁니다. 반대말 confiar(믿다)는 en을 써서 confiar en alguien이라고 하니 함께 외워 두세요. aquellos que no conoce는 '그가 모르는 사람들'이라는 뜻입니다.","x":["por: desconfiar와 어울리는 전치사가 아닙니다 ✗","de: desconfiar de(~을 믿지 않다)라는 고정 결합 → 정답 ✓","en: confiar en(~을 믿다)에 쓰는 전치사입니다 ✗","a: desconfiar와 함께 쓰지 않습니다 ✗"]},{"id":"G320","q":"El pronóstico del tiempo para ese día era malo, de ahí que ____ aplazar el viaje.","o":["decidíamos","decidiríamos","decidimos","decidiéramos"],"a":3,"k":"de ahí que+접속법","t":"그날 일기예보가 나빴고, 그래서 우리는 여행을 미루기로 했다.","e":"de ahí que(그래서, 그런 까닭에)는 결과를 나타내지만 특이하게 뒤에 접속법을 씁니다. 과거 이야기(era malo)이므로 접속법 과거 decidiéramos가 맞습니다. 현재라면 de ahí que decidamos가 됩니다.","x":["decidíamos: 직설법이라 de ahí que 뒤에 올 수 없습니다 ✗","decidiríamos: 가능법(조건법)이라 이 구조에 맞지 않습니다 ✗","decidimos: 직설법 단순과거라 de ahí que 뒤에 쓸 수 없습니다 ✗","decidiéramos: de ahí que 뒤 과거 시제의 접속법 → 정답 ✓"]},{"id":"G321","q":"Ojalá ____ en la misma clase.","o":["estaremos","estuviéramos","estamos","estaríamos"],"a":1,"k":"ojalá+접속법 과거","t":"우리가 같은 반이라면 좋을 텐데.","e":"ojalá(~하면 좋겠다)는 항상 접속법과 함께 씁니다. 접속법 과거 estuviéramos를 쓰면 '실현 가능성이 낮거나 현재 사실과 다른 바람'을 나타냅니다. 실현 가능성이 있는 바람이라면 접속법 현재 estemos를 씁니다.","x":["estaremos: 직설법 미래라 ojalá 뒤에 쓰지 않습니다 ✗","estuviéramos: ojalá + 접속법 과거로 실현이 어려운 바람 → 정답 ✓","estamos: 직설법 현재라 ojalá 뒤에 쓰지 않습니다 ✗","estaríamos: 가능법(조건법)이라 ojalá와 함께 쓰지 않습니다 ✗"]},{"id":"G322","q":"Es indignante que tantos políticos de este país ____ corruptos.","o":["sean","son","serían","están siendo"],"a":0,"k":"가치 판단+접속법","t":"이 나라의 그렇게 많은 정치인들이 부패했다는 것은 분통 터지는 일이다.","e":"Es indignante que(~라니 분하다)처럼 감정이나 가치 판단을 나타내는 표현 뒤에는 접속법을 씁니다. 부패한 성질은 ser로 표현하므로 ser의 접속법 현재 3인칭 복수 sean이 맞습니다. 비슷한 표현: Es triste que..., Es increíble que...","x":["sean: 감정·판단 표현 뒤의 접속법 현재 → 정답 ✓","son: 직설법이라 es indignante que 뒤에 올 수 없습니다 ✗","serían: 가능법(조건법)이라 맞지 않습니다 ✗","están siendo: 직설법 진행형이라 맞지 않습니다 ✗"]},{"id":"G323","q":"Ojalá ____ bien todos los ocupantes del vehículo accidentado.","o":["estén","estarán","estarían","están"],"a":0,"k":"ojalá+접속법 현재","t":"사고 난 차량에 타고 있던 사람들이 모두 무사하기를 바란다.","e":"ojalá 뒤에는 접속법이 오고, 현재 실현 가능한 바람에는 접속법 현재를 씁니다. '무사하다, 건강하다'는 상태이므로 estar bien을 쓰고, 주어 todos los ocupantes가 3인칭 복수라서 estén이 됩니다.","x":["estén: ojalá + 접속법 현재, 3인칭 복수 → 정답 ✓","estarán: 직설법 미래라 ojalá와 함께 쓰지 않습니다 ✗","estarían: 가능법(조건법)이라 ojalá와 함께 쓰지 않습니다 ✗","están: 직설법 현재라 ojalá 뒤에 쓰지 않습니다 ✗"]},{"id":"G324","q":"Sus padres son ricos, ____ tenga un auto tan caro sin haber trabajado nunca.","o":["para que","aunque","de ahí que","ya que"],"a":2,"k":"de ahí que+접속법","t":"그의 부모님이 부자다, 그래서 한 번도 일해 본 적 없이 그렇게 비싼 차를 가지고 있는 거다.","e":"빈칸 뒤 동사가 접속법 tenga라는 점이 결정적인 힌트입니다. 결과(그래서)를 나타내면서 접속법을 요구하는 연결어는 de ahí que입니다. 앞 절(부모가 부자)이 원인, 뒷 절(비싼 차)이 결과라는 의미도 맞습니다. auto는 중남미에서 많이 쓰는 말로, 스페인에서는 coche라고 합니다.","x":["para que: '~하도록'이라는 목적이라 의미가 맞지 않습니다 ✗","aunque: '~이지만'이라는 양보라 원인-결과 관계와 맞지 않습니다 ✗","de ahí que: 결과를 나타내며 뒤에 접속법 tenga를 씁니다 ✓","ya que: '~이니까'라는 이유를 나타내며 보통 직설법이 와서 맞지 않습니다 ✗"]},{"id":"G325","q":"Señores González, ____ al final del documento, por favor.","o":["firmad","firmáis","firman","firmen"],"a":3,"k":"ustedes 명령형","t":"곤살레스 씨 부부, 서류 맨 끝에 서명해 주세요.","e":"Señores González(곤살레스 씨 부부/여러분)는 존칭 복수 ustedes로 대하는 상대입니다. ustedes의 긍정 명령형은 접속법 현재 3인칭 복수형과 같으므로 firmen이 맞습니다. 참고로 중남미에서는 친한 사이의 복수에도 ustedes를 쓰므로 이 형태가 더욱 자주 쓰입니다.","x":["firmad: vosotros(너희들) 명령형이라 존칭 상대에게 맞지 않습니다 ✗","firmáis: 직설법 현재 vosotros형이라 명령이 아닙니다 ✗","firman: 직설법 현재 '그들은 서명한다'라서 명령이 아닙니다 ✗","firmen: ustedes 긍정 명령형 → 정답 ✓"]},{"id":"G326","q":"Celebraremos el cumpleaños en el bar de Julio, ____ se te ocurre una idea mejor.","o":["salvo que","excepto","a no ser que","excepto si"],"a":3,"k":"excepto si+직설법","t":"네가 더 좋은 생각이 떠오르지 않는 한, 생일은 훌리오의 바에서 축하할 거야.","e":"빈칸 뒤 동사가 직설법 현재 ocurre라는 점이 핵심입니다. '~가 아니라면'을 뜻하는 표현 중 excepto si(=salvo si)는 si 때문에 직설법을 씁니다. 반면 salvo que, a no ser que는 접속법(ocurra)을 요구합니다.","x":["salvo que: 뒤에 접속법(ocurra)이 와야 해서 ocurre와 맞지 않습니다 ✗","excepto: 단독으로는 뒤에 절을 연결할 수 없습니다 ✗","a no ser que: 뒤에 접속법이 와야 하므로 ✗","excepto si: si 조건절처럼 직설법 ocurre와 함께 씁니다 ✓"]},{"id":"G327","q":"Laura ____ por ahí que tenéis problemas económicos.","o":["acaba diciendo","va diciendo","lleva diciendo","lleva dicho"],"a":1,"k":"ir+현재분사","t":"라우라가 너희가 경제적으로 어렵다고 여기저기 말하고 다닌다.","e":"ir + 현재분사(-ando/-iendo)는 '~하고 다니다, 점점 ~하다'라는 뜻의 동사 우회 표현입니다. por ahí(여기저기, 이곳저곳)와 함께 쓰여 '여기저기 말하고 다니다'라는 의미가 됩니다. 예: Va contando mentiras. (거짓말을 하고 다닌다.)","x":["acaba diciendo: '결국 ~라고 말하게 되다'라는 뜻이라 por ahí와 어울리지 않습니다 ✗","va diciendo: '~라고 말하고 다닌다' → 정답 ✓","lleva diciendo: '(얼마 동안) 계속 말해 왔다'는 뜻으로 보통 기간 표현이 필요합니다 ✗","lleva dicho: 과거분사로 '지금까지 ~를 말했다'는 뜻이라 맞지 않습니다 ✗"]},{"id":"G328","q":"Necesito saber si ____ de vosotras puede ayudarme con esta tarea.","o":["alguien","alguno","alguna","algunas"],"a":2,"k":"부정어 alguno/a","t":"너희들 중 누군가 이 과제를 도와줄 수 있는지 알아야겠어.","e":"'~중의 누군가'는 alguno/alguna de로 표현합니다. vosotras가 여성 복수이므로 여성 단수 alguna를 쓰고, 동사 puede도 단수입니다. alguien(누군가)은 뒤에 de + 집단을 붙여 쓰지 않습니다.","x":["alguien: '누군가'이지만 de vosotras처럼 집단을 한정하는 말과 함께 쓰지 않습니다 ✗","alguno: 남성형이라 vosotras(여성)와 성이 맞지 않습니다 ✗","alguna: 여성 단수 '~중 누군가'로 vosotras, puede와 일치 → 정답 ✓","algunas: 복수라 단수 동사 puede와 맞지 않습니다 ✗"]},{"id":"G329","q":"Inés gana la mitad ____ Sara.","o":["de lo que","de","lo que","que"],"a":3,"k":"배수 비교 la mitad que","t":"이네스는 사라의 절반만큼 번다.","e":"la mitad(절반), el doble(두 배), el triple(세 배) 같은 배수 표현 뒤에 비교 대상을 쓸 때는 que를 씁니다. 그래서 la mitad que Sara가 맞습니다. 뒤에 동사를 넣어 절로 말할 때는 la mitad de lo que gana Sara(사라가 버는 것의 절반)처럼 쓸 수도 있습니다.","x":["de lo que: 뒤에 동사가 있는 절(de lo que gana Sara)이 와야 자연스럽습니다 ✗","de: 배수 비교에서 사람을 비교할 때 de를 쓰지 않습니다 ✗","lo que: 비교의 연결어가 없어 문법적으로 틀립니다 ✗","que: 배수 표현 + que + 비교 대상 → 정답 ✓"]},{"id":"G330","q":"No creo que ____ terminar el proyecto antes del viernes.","o":["podamos","podemos","vamos a poder","podremos"],"a":0,"k":"no creer que+접속법","t":"금요일 전에 프로젝트를 끝낼 수 있을 것 같지 않다.","e":"No creo que(~라고 생각하지 않는다)는 의심을 나타내므로 뒤에 접속법이 와야 합니다. poder의 접속법 현재 1인칭 복수 podamos가 정답입니다. 접속법 현재는 미래의 의미도 함께 나타낼 수 있어 antes del viernes(금요일 전)와도 잘 맞습니다.","x":["podamos: no creo que 뒤의 접속법 현재 → 정답 ✓","podemos: 직설법이라 부정 의견 표현 뒤에 쓰지 않습니다 ✗","vamos a poder: 직설법 미래 표현이라 맞지 않습니다 ✗","podremos: 직설법 미래라 no creo que 뒤에 쓰지 않습니다 ✗"]},{"id":"G331","q":"Tengo un ordenador que ____ perfectamente después de tanto tiempo.","o":["funcionaría","funcionando","funcione","funciona"],"a":3,"k":"관계절 직설법","t":"나는 그렇게 오래됐는데도 완벽하게 작동하는 컴퓨터를 가지고 있다.","e":"관계절이 꾸미는 대상(un ordenador)이 실제로 존재하고 내가 알고 있는 것이면 관계절 안에서 직설법을 씁니다. 여기서는 내가 실제로 가진 컴퓨터이므로 funciona가 맞습니다. 반대로 Busco un ordenador que funcione bien.(잘 작동하는 컴퓨터를 찾는다)처럼 존재가 불확실하면 접속법을 씁니다. ordenador는 스페인, computadora는 중남미에서 주로 씁니다.","x":["funcionaría: 가능법(조건법)이라 실제 존재하는 사물의 현재 상태와 맞지 않습니다 ✗","funcionando: 현재분사는 관계절의 동사가 될 수 없습니다 ✗","funcione: 접속법은 존재가 불확실한 대상에 쓰므로 ✗","funciona: 실제 가진 컴퓨터를 꾸미는 직설법 현재 → 정답 ✓"]},{"id":"G332","q":"____ que fueses más comprensiva con este asunto.","o":["Esperé","Esperaba","Esperaré","Espero"],"a":1,"k":"시제 일치 esperaba","t":"나는 네가 이 문제에 대해 좀 더 이해심을 보여 주길 바랐어.","e":"종속절의 동사가 접속법 과거 fueses이므로, 시제 일치에 따라 주절도 과거 시제여야 합니다. '계속 바라고 있었다'는 과거의 지속적인 마음 상태이므로 불완료과거 esperaba가 가장 자연스럽습니다. 이 표현은 '기대했는데 실망했다'는 뉘앙스를 줍니다.","x":["Esperé: 단순과거도 과거이지만 마음 상태를 나타내기엔 불완료과거보다 부자연스럽습니다 ✗","Esperaba: 과거의 기대(마음 상태)를 나타내며 fueses와 시제가 일치 → 정답 ✓","Esperaré: 미래형이라 접속법 과거 fueses와 시제가 맞지 않습니다 ✗","Espero: 현재형이면 보통 접속법 현재 seas가 와야 합니다 ✗"]},{"id":"G333","q":"Estos zapatos cuestan el doble ____ esos.","o":["cual","como","que","cuanto"],"a":2,"k":"배수 비교 el doble que","t":"이 신발은 저것들보다 두 배 비싸다.","e":"el doble(두 배), el triple(세 배) 같은 배수 표현 뒤에서 비교 대상을 연결할 때는 que를 씁니다. 그래서 cuestan el doble que esos(저것들의 두 배 값이다)가 됩니다. 예: Come el triple que yo. (그는 나보다 세 배나 먹는다.)","x":["cual: 관계사·의문사로 비교에 쓰지 않습니다 ✗","como: 동등 비교(tan... como)에 쓰는 말이라 배수 비교에는 맞지 않습니다 ✗","que: 배수 표현 + que + 비교 대상 → 정답 ✓","cuanto: '~하는 만큼'이라는 뜻이라 이 구조에 맞지 않습니다 ✗"]},{"id":"G334","q":"No quiero que a mis hijos les ____ de nada.","o":["faltara","falte","falta","faltará"],"a":1,"k":"querer que+접속법","t":"나는 내 아이들에게 아무것도 부족하지 않기를 바란다.","e":"querer que(~하기를 원하다)는 바람을 나타내므로 뒤에 접속법이 옵니다. 주절이 현재(quiero)이므로 접속법 현재 falte를 씁니다. faltar(부족하다)는 gustar처럼 '부족한 사람'을 간접목적격 대명사(les)로 나타냅니다.","x":["faltara: 접속법 과거라 현재형 quiero와 시제가 맞지 않습니다 ✗","falte: 현재형 querer que 뒤의 접속법 현재 → 정답 ✓","falta: 직설법이라 바람 표현 뒤에 쓸 수 없습니다 ✗","faltará: 직설법 미래라 querer que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G335","q":"____ está lloviendo a mares, ha salido a pasear a los perros.","o":["Como","Ya que","Así que","Aunque"],"a":3,"k":"양보 aunque","t":"비가 억수같이 쏟아지는데도 그는 개들을 산책시키러 나갔다.","e":"비가 많이 오는 것과 산책하러 나간 것은 예상과 반대되는 관계이므로 양보 접속사 aunque(~에도 불구하고)가 필요합니다. llover a mares는 '비가 억수같이 쏟아지다'라는 관용 표현입니다. 실제 일어나는 사실이라 aunque 뒤에 직설법 está lloviendo가 왔습니다.","x":["Como: '~이기 때문에'라는 이유라 의미가 맞지 않습니다 ✗","Ya que: '~이니까'라는 이유라 의미가 맞지 않습니다 ✗","Así que: '그래서'라는 결과로 문장 맨 앞에 이렇게 쓰지 않습니다 ✗","Aunque: 예상과 반대되는 사실을 잇는 양보 접속사 → 정답 ✓"]},{"id":"G336","q":"Si de verdad le ____ nuestra oferta, ya habría dicho algo.","o":["interesaría","interesará","interesara","interese"],"a":2,"k":"현재 사실 반대 가정","t":"정말로 그가 우리 제안에 관심이 있다면, 벌써 뭔가 말했을 것이다.","e":"현재 사실과 반대되는 가정(사실은 관심이 없다)은 si + 접속법 과거로 씁니다. 그래서 si le interesara가 맞습니다. 결과절 ya habría dicho algo는 가능법 완료형으로 '(그랬다면) 이미 말했을 텐데'를 나타냅니다. si 뒤에는 가능법(interesaría)이나 접속법 현재(interese)를 쓰지 않는다는 점을 꼭 기억하세요.","x":["interesaría: si 조건절에는 가능법(조건법)을 쓰지 않습니다 ✗","interesará: si 조건절에 직설법 미래를 쓰지 않습니다 ✗","interesara: 사실과 반대되는 가정을 나타내는 접속법 과거 → 정답 ✓","interese: si 뒤에 접속법 현재는 쓰지 않습니다 ✗"]},{"id":"G337","q":"¿Cuántas veces ____ ejercicio físico la semana pasada?","o":["has hecho","hacías","estabas haciendo","hiciste"],"a":3,"k":"단순과거 la semana pasada","t":"지난주에 운동을 몇 번 했니?","e":"la semana pasada(지난주)는 이미 끝난 과거 기간이므로 단순과거 hiciste를 씁니다. ¿Cuántas veces?(몇 번?)처럼 횟수를 세는 것도 완결된 행위로 보기 때문에 단순과거가 어울립니다. 스페인에서는 esta semana(이번 주)처럼 아직 끝나지 않은 기간이면 현재완료 has hecho를 씁니다.","x":["has hecho: 현재완료는 아직 끝나지 않은 기간(이번 주 등)에 씁니다 ✗","hacías: 불완료과거라 횟수를 세는 완결된 행위와 맞지 않습니다 ✗","estabas haciendo: 과거진행형이라 횟수 질문에 맞지 않습니다 ✗","hiciste: 끝난 과거 기간의 완결된 행위를 나타내는 단순과거 → 정답 ✓"]},{"id":"G338","q":"Supongo que Carmen ya ____ del notición.","o":["se haya enterado","se enterase","se ha enterado","se entera"],"a":2,"k":"suponer que+직설법","t":"카르멘은 그 엄청난 소식을 이미 알았을 거라고 생각해.","e":"Supongo que(~라고 짐작한다)는 말하는 사람이 사실일 것이라고 여기는 내용이므로 직설법을 씁니다. ya(이미)와 함께 현재와 연결된 완료된 일을 나타내므로 현재완료 se ha enterado가 맞습니다. notición은 noticia(소식)에 크기를 강조하는 접미사 -ón이 붙은 말로 '대박 소식'이라는 뜻입니다.","x":["se haya enterado: 접속법이라 긍정 suponer que 뒤에 쓰지 않습니다 ✗","se enterase: 접속법 과거라 맞지 않습니다 ✗","se ha enterado: 추측을 나타내는 suponer que 뒤의 직설법 현재완료 → 정답 ✓","se entera: 직설법 현재로 ya(이미)와 함께 완료 의미를 나타내지 못합니다 ✗"]},{"id":"G339","q":"____ no me digáis quién ha roto la ventana, os voy a castigar a todos.","o":["Si","Con tal de que","Debido a que","Como"],"a":3,"k":"como+접속법(조건)","t":"누가 창문을 깼는지 말하지 않으면, 너희 모두를 벌줄 거야.","e":"como 뒤에 접속법이 오면 '만약 ~하면(~하기만 해 봐)'이라는 위협·경고의 조건을 나타냅니다. 빈칸 뒤 digáis가 접속법이라는 점이 핵심 힌트입니다. 같은 의미를 si로 말하면 Si no me decís...(직설법)가 되어야 합니다. 예: Como llegues tarde, me enfado. (늦기만 해 봐, 화낼 거야.)","x":["Si: si 조건절에는 접속법 현재(digáis)를 쓰지 않고 직설법 decís를 씁니다 ✗","Con tal de que: '~하기만 한다면'이라는 긍정적 조건이라 위협의 의미와 맞지 않습니다 ✗","Debido a que: '~때문에'라는 이유이고 뒤에 직설법이 와야 합니다 ✗","Como: 뒤에 접속법이 오면 위협적인 조건 '~하면'을 나타냄 → 정답 ✓"]},{"id":"G340","q":"¿Dónde dicen que ____ estos cuadros?","o":["será expuestos","serán expuestos","serán expuesto","será expuesta"],"a":1,"k":"수동태 ser+과거분사","t":"이 그림들이 어디에 전시될 거라고 하니?","e":"ser + 과거분사로 만드는 수동태에서는 과거분사가 주어의 성·수에 일치해야 합니다. 주어 estos cuadros(이 그림들)가 남성 복수이므로 동사는 serán, 과거분사는 expuestos가 됩니다. exponer(전시하다)의 과거분사는 불규칙형 expuesto입니다.","x":["será expuestos: 동사가 단수라 복수 주어와 맞지 않습니다 ✗","serán expuestos: 동사와 과거분사가 모두 남성 복수와 일치 → 정답 ✓","serán expuesto: 과거분사가 단수라 주어와 일치하지 않습니다 ✗","será expuesta: 단수·여성형이라 주어와 성·수가 맞지 않습니다 ✗"]},{"id":"G341","q":"Trabajo en el ____ piso de ese rascacielos.","o":["vigésimo primero","vigésimoprimero","vigésimo primer","vigésima primer"],"a":2,"k":"서수 vigésimo primer","t":"나는 저 고층 빌딩의 21층에서 일한다.","e":"21번째는 vigésimo primero인데, 남성 단수 명사(piso) 앞에서는 primero가 primer로 줄어듭니다(어미 탈락). 그래서 el vigésimo primer piso가 됩니다. 붙여 쓰면 악센트 없이 vigesimoprimer라고 씁니다. 참고로 일상에서는 el piso veintiuno라고 기수로 말하는 경우도 많습니다.","x":["vigésimo primero: 명사 앞에서는 primero가 primer로 줄어야 합니다 ✗","vigésimoprimero: 붙여 쓸 때는 악센트가 없고, 명사 앞이라 primer여야 합니다 ✗","vigésimo primer: 남성 명사 앞에서 어미가 탈락한 올바른 형태 → 정답 ✓","vigésima primer: piso는 남성인데 vigésima는 여성형이라 ✗"]},{"id":"G342","q":"Quiero contarte la idea que ____ ha ocurrido.","o":["se","me","se me","me se"],"a":2,"k":"무의지의 se","t":"내게 떠오른 아이디어를 너에게 말해 주고 싶어.","e":"ocurrirse(생각이 떠오르다)는 '의도하지 않게 어떤 일이 일어남'을 나타내는 se + 간접목적격 대명사 구조를 씁니다. 순서는 항상 se가 먼저, 그다음 me/te/le입니다. 그래서 la idea que se me ha ocurrido(내게 떠오른 생각)가 됩니다. 예: Se me olvidó. (깜빡 잊어버렸다.)","x":["se: '누구에게' 떠올랐는지 나타내는 me가 빠져 있습니다 ✗","me: se가 없으면 '생각이 떠오르다'의 구조가 완성되지 않습니다 ✗","se me: se + 간접목적격 대명사 순서의 올바른 형태 → 정답 ✓","me se: 순서가 틀렸습니다. se가 항상 먼저 옵니다 ✗"]},{"id":"G343","q":"Fui allí en persona ____ que me devolvieran mi dinero.","o":["ya","con el fin de","puesto","a causa de"],"a":1,"k":"목적 con el fin de","t":"내 돈을 돌려받기 위해 직접 그곳에 갔다.","e":"con el fin de(~할 목적으로, ~하기 위해)는 목적을 나타내는 표현입니다. 뒤에 동사원형이 오거나, 여기처럼 주어가 다를 때는 que + 접속법(devolvieran)이 옵니다. para que와 비슷한 뜻의 좀 더 격식 있는 표현입니다.","x":["ya: ya que(~이니까)의 일부일 뿐 단독으로는 접속사가 될 수 없습니다 ✗","con el fin de: '~하기 위해'라는 목적 표현으로 que + 접속법과 연결 → 정답 ✓","puesto: puesto que(~이니까)의 일부일 뿐이고 이유를 나타내 목적과 맞지 않습니다 ✗","a causa de: '~때문에'라는 원인을 나타내 목적의 의미와 맞지 않습니다 ✗"]},{"id":"G344","q":"Ni una sola persona suspendió el examen, ____ facilísimo.","o":["fuera","sería","va a ser","será"],"a":1,"k":"과거 추측의 가능법","t":"단 한 명도 시험에 떨어지지 않았어, 아마 엄청 쉬웠나 봐.","e":"가능법(조건법, -ría 형태)은 과거 일에 대한 추측을 나타낼 수 있습니다. '시험이 엄청 쉬웠을 것이다'라는 과거 추측이므로 sería를 씁니다. 비교: 현재 추측은 미래형(será), 과거 추측은 가능법(sería). 예: Serían las diez. (10시쯤이었을 거야.)","x":["fuera: 접속법 과거라 독립된 추측 문장에 쓰지 않습니다 ✗","sería: 과거 사실에 대한 추측을 나타내는 가능법 → 정답 ✓","va a ser: 미래를 나타내 과거의 시험에 맞지 않습니다 ✗","será: 현재 일에 대한 추측이라 과거 시험(suspendió)과 시제가 맞지 않습니다 ✗"]},{"id":"G345","q":"Vamos a ir a la cafetería ____ te hablé.","o":["de la","la que","de la que","de que"],"a":2,"k":"관계사 de la que","t":"내가 너에게 얘기했던 그 카페에 가자.","e":"hablar de(~에 대해 말하다)는 전치사 de가 필요하므로, 관계절에서도 전치사를 관계사 앞에 둡니다. 선행사 la cafetería가 여성 단수라서 de la que가 됩니다. de la cual도 같은 뜻으로 쓸 수 있습니다. 예: el libro del que te hablé (내가 말했던 책)","x":["de la: 관계사 que가 빠져 절을 연결할 수 없습니다 ✗","la que: hablar de에 필요한 전치사 de가 빠졌습니다 ✗","de la que: 전치사 + 관사 + que로 hablar de와 선행사 cafetería를 연결 → 정답 ✓","de que: 관사가 없으면 관계사로서 선행사를 받지 못합니다 ✗"]},{"id":"G346","q":"Disculpe, ¿____ decirme dónde hay una farmacia por aquí?","o":["podría","podrás","puedes","podrías"],"a":0,"k":"정중한 부탁 podría","t":"실례합니다, 이 근처에 약국이 어디 있는지 알려 주시겠어요?","e":"Disculpe(실례합니다)는 usted에게 쓰는 형태이므로 동사도 usted형이어야 합니다. 가능법(조건법) podría를 쓰면 '~해 주실 수 있을까요?'라는 정중한 부탁이 됩니다. 처음 보는 사람에게 길을 물을 때 아주 유용한 표현입니다.","x":["podría: usted에게 쓰는 정중한 부탁의 가능법 → 정답 ✓","podrás: 미래형 tú형이라 정중한 부탁도 아니고 인칭도 맞지 않습니다 ✗","puedes: tú형이라 disculpe(usted)와 인칭이 맞지 않습니다 ✗","podrías: 정중하지만 tú형이라 disculpe와 맞지 않습니다 ✗"]},{"id":"G347","q":"¡____ bien que estemos todos!","o":["Cuánto","Qué","Cuál","Cómo"],"a":1,"k":"감탄문 qué","t":"우리 모두 함께 있다니 정말 좋다!","e":"감탄문 '¡Qué + 형용사/부사!'는 '정말 ~하다!'라는 뜻입니다. ¡Qué bien!(정말 잘됐다!) 뒤에 que + 접속법을 붙여 '~해서 정말 좋다'라고 감정의 이유를 덧붙입니다. 감정 표현이므로 estemos가 접속법입니다.","x":["Cuánto: '얼마나 많이'라는 뜻으로 bien과 바로 결합하지 않습니다 ✗","Qué: ¡Qué bien que...!(~라니 정말 좋다)라는 감탄 구문 → 정답 ✓","Cuál: '어느 것'이라는 뜻으로 감탄문에 쓰지 않습니다 ✗","Cómo: 감탄문에서는 동사와 함께 써서(¡Cómo llueve!) bien 앞에는 오지 않습니다 ✗"]},{"id":"G348","q":"Se dice que ____ perro es el mejor amigo del hombre.","o":["ø","un","el","uno"],"a":2,"k":"총칭의 정관사","t":"개는 인간의 가장 좋은 친구라고들 한다.","e":"어떤 종류 전체를 일반적으로 말할 때(총칭) 스페인어는 정관사를 씁니다. el perro는 '특정한 개'가 아니라 '개라는 동물 전체'를 뜻합니다. 예: El café es bueno para despertarse. (커피는 잠 깨는 데 좋다.)","x":["ø: 주어 자리의 단수 가산명사는 관사 없이 쓸 수 없습니다 ✗","un: '어떤 한 마리 개'가 되어 일반적인 진리를 나타내기 어렵습니다 ✗","el: 종 전체를 가리키는 총칭의 정관사 → 정답 ✓","uno: 명사 앞에서는 un으로 줄어야 하며 의미도 맞지 않습니다 ✗"]},{"id":"G349","q":"Quedé en el puesto ____ de la carrera.","o":["decimotercer","decimotercero","décimotercero","décimo tercer"],"a":1,"k":"서수 decimotercero","t":"나는 경주에서 13위를 했다.","e":"서수가 명사 뒤에 올 때는 어미가 줄지 않으므로 el puesto decimotercero(13번째 자리)가 됩니다. 반대로 명사 앞에 오면 decimotercer puesto처럼 줄어듭니다. 또 decimo-로 붙여 쓸 때는 décimo의 악센트가 없어집니다.","x":["decimotercer: 명사 앞에서만 쓰는 줄어든 형태라 명사 뒤에는 맞지 않습니다 ✗","decimotercero: 명사 뒤에 오는 서수의 완전한 형태 → 정답 ✓","décimotercero: 붙여 쓸 때는 악센트를 찍지 않습니다 ✗","décimo tercer: 명사 뒤에서는 tercero로 줄지 않습니다 ✗"]},{"id":"G350","q":"Nuestros resultados son ____ que los vuestros.","o":["peor","más peores","peores","tan peores"],"a":2,"k":"불규칙 비교급 peor","t":"우리 결과가 너희 것보다 더 나쁘다.","e":"malo(나쁜)의 비교급은 más malo가 아니라 불규칙형 peor(더 나쁜)입니다. 주어 nuestros resultados가 복수이므로 peores가 됩니다. peor 자체에 이미 '더'의 의미가 있어 más를 붙이면 안 됩니다. 비슷한 예: mejor(더 좋은), mayor, menor.","x":["peor: 단수형이라 복수 주어 resultados와 일치하지 않습니다 ✗","más peores: peor 자체가 비교급이라 más를 중복할 수 없습니다 ✗","peores: 복수 주어와 일치하는 불규칙 비교급 → 정답 ✓","tan peores: tan은 동등 비교(tan... como)에 쓰며 peor와 결합하지 않습니다 ✗"]},{"id":"G351","q":"Ignacio es alto y moreno, ____, su hermano es bajito y entrado en carnes.","o":["por el contrario","por tanto","por eso","por lo cual"],"a":0,"k":"대조 por el contrario","t":"이그나시오는 키가 크고 피부가 가무잡잡하지만, 반대로 그의 동생은 키가 작고 통통하다.","e":"두 형제의 외모가 정반대이므로 '반대로, 그에 반해'를 뜻하는 por el contrario를 씁니다. 나머지 보기는 모두 '그래서'라는 결과를 나타냅니다. entrado en carnes는 '살집이 있는, 통통한'이라는 완곡한 표현입니다.","x":["por el contrario: '반대로'라는 대조 연결어 → 정답 ✓","por tanto: '그러므로'라는 결과를 나타내 의미가 맞지 않습니다 ✗","por eso: '그래서'라는 결과를 나타내 의미가 맞지 않습니다 ✗","por lo cual: '그로 인해'라는 결과를 나타내 의미가 맞지 않습니다 ✗"]},{"id":"G352","q":"Cuando empecé a aprender español, me ____ vergüenza hablar con hispanohablantes.","o":["dio","ha dado","había dado","daba"],"a":3,"k":"불완료과거(과거 상태)","t":"내가 스페인어를 배우기 시작했을 때, 원어민과 말하는 게 부끄러웠다.","e":"과거의 일정 기간 동안 지속된 감정이나 상태는 불완료과거로 표현합니다. 배우기 시작했을 무렵 늘 느끼던 부끄러움이므로 daba가 맞습니다. dar vergüenza는 '부끄럽게 만들다'라는 뜻으로 gustar처럼 느끼는 사람을 me, te 등으로 씁니다.","x":["dio: 단순과거라 한 번의 순간적인 감정이 되어 지속되던 상태와 맞지 않습니다 ✗","ha dado: 현재완료라 과거 이야기와 맞지 않습니다 ✗","había dado: 대과거라 배우기 시작하기 전의 일이 되어 버립니다 ✗","daba: 과거에 지속된 감정 상태를 나타내는 불완료과거 → 정답 ✓"]},{"id":"G353","q":"Soy consciente ____ mis defectos.","o":["de","con","a","sobre"],"a":0,"k":"consciente de","t":"나는 내 결점들을 잘 알고 있다.","e":"ser consciente de(~을 자각하다, 인식하다)는 항상 전치사 de와 함께 씁니다. 뒤에 절이 올 때도 de que를 씁니다: Soy consciente de que me equivoqué. (내가 실수한 걸 알고 있다.)","x":["de: consciente de라는 고정 결합 → 정답 ✓","con: consciente와 함께 쓰지 않는 전치사입니다 ✗","a: consciente와 함께 쓰지 않는 전치사입니다 ✗","sobre: '~에 관하여'라는 뜻이지만 consciente와 결합하지 않습니다 ✗"]},{"id":"G354","q":"¿Cuándo ____ el nuevo centro comercial?","o":["se inaugure","serán inaugurados","será inaugurado","inaugurará"],"a":2,"k":"수동태 미래","t":"새 쇼핑센터는 언제 개장될까?","e":"주어 el nuevo centro comercial(새 쇼핑센터)이 남성 단수이고, '개장되다'라는 수동의 의미이므로 ser + 과거분사 수동태를 씁니다. 미래의 일이므로 será inaugurado가 됩니다. 같은 뜻으로 ¿Cuándo se inaugurará...?라고도 할 수 있습니다.","x":["se inaugure: 접속법이라 의문문의 주동사로 쓸 수 없습니다 ✗","serán inaugurados: 복수형이라 단수 주어와 맞지 않습니다 ✗","será inaugurado: 남성 단수 주어와 일치하는 미래 수동태 → 정답 ✓","inaugurará: 능동형이라 '쇼핑센터가 (무언가를) 개장한다'는 이상한 뜻이 됩니다 ✗"]},{"id":"G355","q":"No puedo vivir sin ____.","o":["ti","tu","tú","te"],"a":0,"k":"전치격 대명사 ti","t":"나는 너 없이는 살 수 없어.","e":"전치사(sin, para, de, con 등) 뒤에 오는 인칭대명사는 전치격 형태를 씁니다. 1·2인칭 단수는 mí, ti이므로 sin ti가 맞습니다. 단, con과 결합할 때는 conmigo, contigo라는 특별한 형태가 됩니다. ti에는 악센트를 찍지 않습니다.","x":["ti: 전치사 sin 뒤에 오는 전치격 대명사 → 정답 ✓","tu: '너의'라는 소유사라 뒤에 명사가 필요합니다 ✗","tú: 주격 대명사라 일반 전치사 뒤에 쓰지 않습니다 ✗","te: 목적격 대명사라 전치사 뒤에 쓰지 않습니다 ✗"]},{"id":"G356","q":"No ____ contestar a la pregunta que me hizo el agente de policía.","o":["sepa","supe","estaba sabiendo","estuve sabiendo"],"a":1,"k":"saber 단순과거","t":"경찰관이 내게 한 질문에 답하지 못했다.","e":"saber를 단순과거(supe)로 쓰면 '(그 순간에) ~할 줄 알았다/몰랐다'라는 한 번의 결과를 나타냅니다. 경찰관이 질문한 그 순간에 답하지 못한 것이므로 no supe가 맞습니다. saber는 상태 동사라 진행형(estaba sabiendo)으로 쓰지 않습니다.","x":["sepa: 접속법이라 평서문의 주동사로 쓸 수 없습니다 ✗","supe: 과거 특정 순간에 답할 줄 몰랐음을 나타내는 단순과거 → 정답 ✓","estaba sabiendo: saber는 진행형으로 쓰지 않습니다 ✗","estuve sabiendo: saber는 진행형으로 쓰지 않습니다 ✗"]},{"id":"G357","q":"¿Alguna vez ____ una carta de amor?","o":["has estado escribiendo","estuviste escribiendo","has escrito","escribías"],"a":2,"k":"경험의 현재완료","t":"너 연애편지를 써 본 적 있니?","e":"¿Alguna vez...?(~해 본 적 있니?)처럼 지금까지의 인생 경험을 물을 때는 현재완료를 씁니다. 그래서 has escrito가 맞습니다. 중남미에서는 단순과거 ¿Alguna vez escribiste...?도 흔히 쓰지만, 보기에는 진행형만 있어 정답이 아닙니다.","x":["has estado escribiendo: 진행형이라 '써 본 경험'이 아니라 '계속 쓰고 있었다'가 됩니다 ✗","estuviste escribiendo: 과거진행형이라 경험을 묻는 의미가 되지 않습니다 ✗","has escrito: 경험을 나타내는 현재완료 → 정답 ✓","escribías: 불완료과거라 과거 습관을 나타내 경험 질문과 맞지 않습니다 ✗"]},{"id":"G358","q":"La madre le dijo al niño que ____ bien antes de empezar a comer.","o":["siente","se sienta","sentara","se sentara"],"a":3,"k":"간접 명령+접속법 과거","t":"엄마는 아이에게 밥 먹기 전에 바르게 앉으라고 말했다.","e":"decir que가 명령·요청을 전달할 때는 뒤에 접속법을 씁니다. 주절이 과거(dijo)이므로 접속법 과거를 쓰고, '앉다'는 재귀동사 sentarse이므로 se sentara가 됩니다. 직접화법으로 바꾸면 '¡Siéntate bien!'(바르게 앉아!)입니다.","x":["siente: 재귀대명사가 없고 시제도 현재라 맞지 않습니다 ✗","se sienta: 직설법이라 명령 전달이 아니라 '앉는다는 사실'을 전하는 문장이 됩니다 ✗","sentara: 접속법 과거이지만 재귀대명사 se가 빠졌습니다 ✗","se sentara: 과거 시점의 명령 전달, 재귀동사 접속법 과거 → 정답 ✓"]},{"id":"G359","q":"Ten cuidado con Ignacio, es ____ zorro.","o":["el","ø","un","uno"],"a":2,"k":"비유의 부정관사","t":"이그나시오 조심해, 그는 교활한 여우 같은 사람이야.","e":"사람을 동물 등에 비유하여 성격을 나타낼 때는 부정관사 un을 씁니다. es un zorro는 '그는 (교활한) 여우다'라는 비유적 표현입니다. 단순히 직업·국적을 말할 때는 관사 없이 쓰지만(Es médico), 비유나 평가를 할 때는 un이 필요합니다.","x":["el: '바로 그 여우'가 되어 비유 표현이 되지 않습니다 ✗","ø: 관사가 없으면 비유적 평가의 뜻이 살지 않습니다 ✗","un: 사람의 특징을 동물에 비유하는 부정관사 → 정답 ✓","uno: 명사 앞에서는 un으로 줄어야 합니다 ✗"]},{"id":"G360","q":"Supongo que os ____ de la noticia.","o":["enteraseis","hayáis enterado","enterabais","habéis enterado"],"a":3,"k":"suponer que+직설법","t":"너희도 그 소식을 들었겠지.","e":"Supongo que(~라고 짐작한다)는 사실일 가능성이 높다고 생각하는 내용이므로 직설법을 씁니다. 현재와 연결된 완료된 일이므로 현재완료 os habéis enterado가 맞습니다. 중남미에서는 vosotros 대신 ustedes를 써서 se han enterado라고 합니다.","x":["enteraseis: 접속법 과거라 suponer que 뒤에 오지 않습니다 ✗","hayáis enterado: 접속법이라 긍정 suponer que 뒤에 오지 않습니다 ✗","enterabais: 불완료과거라 '소식을 알게 된' 완료 의미와 맞지 않습니다 ✗","habéis enterado: suponer que 뒤의 직설법 현재완료 → 정답 ✓"]},{"id":"G361","q":"Están sorprendidos ____ esperaban un resultado mucho mejor.","o":["a pesar de que","por","porque","como"],"a":2,"k":"이유 접속사 porque","t":"그들은 훨씬 더 좋은 결과를 기대했기 때문에 놀랐다.","e":"빈칸 뒤의 절(더 좋은 결과를 기대했다)은 앞 절(놀랐다)의 이유입니다. 문장 중간에서 이유를 잇는 접속사는 porque입니다. como도 이유를 나타내지만 반드시 문장 맨 앞에 와야 합니다(Como esperaban..., están sorprendidos).","x":["a pesar de que: '~에도 불구하고'라는 양보라 의미가 맞지 않습니다 ✗","por: 전치사라 뒤에 동사가 있는 절을 바로 연결할 수 없습니다 ✗","porque: 문장 중간에서 이유를 나타내는 접속사 → 정답 ✓","como: 이유의 como는 문장 앞에만 오므로 이 위치에 맞지 않습니다 ✗"]},{"id":"G362","q":"Es improbable que Esther ____ tarde, es muy puntual.","o":["está llegando","llegará","llegue","va a llegar"],"a":2,"k":"가능성 표현+접속법","t":"에스테르가 늦게 올 리는 없어, 그녀는 아주 시간을 잘 지키거든.","e":"Es improbable que(~할 것 같지 않다)는 가능성·의심을 나타내므로 뒤에 접속법을 씁니다. 미래의 일도 접속법 현재로 나타내므로 llegue가 맞습니다. 같은 부류 표현: Es posible que, Es probable que, Es imposible que.","x":["está llegando: 직설법 진행형이라 가능성 표현 뒤에 쓸 수 없습니다 ✗","llegará: 직설법 미래라 es improbable que 뒤에 쓸 수 없습니다 ✗","llegue: 가능성 판단 뒤의 접속법 현재 → 정답 ✓","va a llegar: 직설법 미래 표현이라 맞지 않습니다 ✗"]},{"id":"G363","q":"Odio ____ ruido en mi bloque los domingos por la mañana.","o":["que hacen","están haciendo","que hagan","hacer"],"a":2,"k":"감정 동사+que+접속법","t":"나는 일요일 아침에 우리 건물에서 사람들이 소음을 내는 게 너무 싫다.","e":"odiar(몹시 싫어하다) 같은 감정 동사 뒤에 다른 주어의 행동이 오면 que + 접속법을 씁니다. 싫어하는 사람(나)과 소음을 내는 사람(그들)이 다르므로 que hagan이 맞습니다. 주어가 같으면 동사원형을 씁니다: Odio hacer ruido. (나는 소음 내는 게 싫다.)","x":["que hacen: 직설법이라 감정 동사 뒤에 쓸 수 없습니다 ✗","están haciendo: 동사가 두 개 연달아 와서 문장이 성립하지 않습니다 ✗","que hagan: 다른 주어의 행동을 나타내는 접속법 → 정답 ✓","hacer: 동사원형은 '내가 소음을 내는 것'이 되어 의미가 달라집니다 ✗"]},{"id":"G364","q":"No ____, todo va a salir bien.","o":["te preocupes","estás preocupándote","te estás preocupando","te preocupas"],"a":0,"k":"부정 명령 tú","t":"걱정하지 마, 다 잘될 거야.","e":"tú에 대한 부정 명령은 'no + 접속법 현재'로 만듭니다. preocuparse(걱정하다)는 재귀동사이므로 no te preocupes가 됩니다. 부정 명령에서는 대명사가 동사 앞에 옵니다(긍정 명령은 preocúpate처럼 뒤에 붙음).","x":["te preocupes: no + 접속법 현재로 만든 tú 부정 명령 → 정답 ✓","estás preocupándote: 직설법 진행형이라 명령이 아닙니다 ✗","te estás preocupando: 직설법 진행형이라 명령이 아닙니다 ✗","te preocupas: 직설법 현재라 '걱정하지 않는다'는 평서문이 됩니다 ✗"]},{"id":"G365","q":"La otra noche Ana y Elena ____ hasta la medianoche.","o":["han charlado","han estado charlando","charlaban","estuvieron charlando"],"a":3,"k":"과거 진행 estuvieron","t":"며칠 전 밤에 아나와 엘레나는 자정까지 수다를 떨었다.","e":"la otra noche(며칠 전 밤)는 이미 끝난 과거 시점이고, hasta la medianoche(자정까지)로 행위의 끝이 정해져 있습니다. 이렇게 시작과 끝이 있는 과거의 지속 행위는 estar의 단순과거 + 현재분사, 즉 estuvieron charlando로 표현합니다.","x":["han charlado: 현재완료라 끝난 과거 시점(la otra noche)과 맞지 않습니다 ✗","han estado charlando: 현재완료 진행형이라 끝난 과거 시점과 맞지 않습니다 ✗","charlaban: 불완료과거는 끝이 정해진(hasta) 행위에 잘 쓰지 않습니다 ✗","estuvieron charlando: 끝난 과거의 일정 기간 동안 계속된 행위 → 정답 ✓"]},{"id":"G366","q":"No quiero que me ____, me gusta trabajar aquí.","o":["despedirán","despidiesen","despiden","despidan"],"a":3,"k":"querer que+접속법","t":"나는 해고당하고 싶지 않아, 여기서 일하는 게 좋거든.","e":"No quiero que(~하지 않기를 바란다)는 바람을 나타내므로 뒤에 접속법이 옵니다. 주절이 현재이므로 접속법 현재 despidan이 맞습니다. despedir(해고하다)는 e→i로 바뀌는 어간 변화 동사라 despidan이 됩니다. 주어를 밝히지 않은 3인칭 복수는 '(누군가가) 나를 해고하다'라는 무인칭의 뜻입니다.","x":["despedirán: 직설법 미래라 querer que 뒤에 쓸 수 없습니다 ✗","despidiesen: 접속법 과거라 현재형 quiero와 시제가 맞지 않습니다 ✗","despiden: 직설법 현재라 바람 표현 뒤에 쓸 수 없습니다 ✗","despidan: 현재형 querer que 뒤의 접속법 현재 → 정답 ✓"]},{"id":"G367","q":"____ trabajo aquí, todo me va mejor.","o":["Hasta que","Antes de que","Desde que","Después de que"],"a":2,"k":"desde que(~한 이후로)","t":"여기서 일한 이후로 모든 일이 더 잘 풀린다.","e":"desde que는 '~한 이후로(지금까지 계속)'라는 뜻으로, 과거에 시작해서 지금까지 이어지는 일을 나타냅니다. 이미 일어난 사실이라 뒤에 직설법(trabajo)이 옵니다. 예: Desde que vivo aquí, estoy más tranquilo. (여기 산 이후로 더 편안하다.)","x":["Hasta que: '~할 때까지'라는 뜻이라 '여기서 일할 때까지 잘 풀린다'는 어색한 의미가 됩니다 ✗","Antes de que: '~하기 전에'라는 뜻이고 뒤에 접속법이 와야 합니다 ✗","Desde que: '~한 이후로'를 뜻하며 직설법과 함께 씀 → 정답 ✓","Después de que: '~한 후에'라는 뜻이지만 지금까지의 지속을 나타내지 않고 미래라면 접속법이 와야 합니다 ✗"]},{"id":"G368","q":"¡Por fin ____ fumar! Sin duda es lo mejor para tu salud.","o":["has acabado de","has tenido que","has dejado de","te has puesto a"],"a":2,"k":"dejar de+동사원형","t":"드디어 담배를 끊었구나! 그게 확실히 네 건강에 제일 좋아.","e":"dejar de + 동사원형은 '~하는 것을 그만두다, 끊다'라는 뜻입니다. 담배를 끊는 것이 건강에 좋다는 문맥에 꼭 맞습니다. 예: Dejé de beber café. (커피를 끊었다.)","x":["has acabado de: '방금 ~했다' 또는 '~을 다 끝냈다'라는 뜻이라 문맥에 맞지 않습니다 ✗","has tenido que: '~해야 했다'라는 의무라 건강에 좋다는 문맥과 맞지 않습니다 ✗","has dejado de: '~하는 것을 그만두었다(끊었다)' → 정답 ✓","te has puesto a: '~하기 시작했다'라서 흡연을 시작한 게 됩니다 ✗"]},{"id":"G369","q":"____ la puerta al salir, por favor.","o":["Cerre","Cierras","Cerra","Cierra"],"a":3,"k":"tú 긍정 명령","t":"나갈 때 문 좀 닫아 줘.","e":"tú에 대한 긍정 명령은 대부분 직설법 현재 3인칭 단수와 같은 형태입니다. cerrar(닫다)는 e→ie로 바뀌는 어간 변화 동사이므로 cierra가 됩니다. al salir는 '나갈 때'라는 뜻입니다.","x":["Cerre: 존재하지 않는 형태입니다(usted 명령은 cierre) ✗","Cierras: 직설법 현재 '너는 닫는다'라서 명령이 아닙니다 ✗","Cerra: 어간 변화(e→ie)를 하지 않아 틀린 형태입니다 ✗","Cierra: 어간이 바뀐 tú 긍정 명령형 → 정답 ✓"]},{"id":"G370","q":"Fernando dijo que nos ____ cuando tuviera tiempo.","o":["llamase","llamaría","llamaba","llamó"],"a":1,"k":"간접화법 가능법","t":"페르난도는 시간이 있을 때 우리에게 전화하겠다고 말했다.","e":"간접화법에서 과거 시점 기준의 미래(그때 기준으로 앞으로 할 일)는 가능법(조건법)으로 나타냅니다. 직접화법 'Os llamaré cuando tenga tiempo'(시간 날 때 전화할게)가 과거로 옮겨지면 nos llamaría cuando tuviera tiempo가 됩니다.","x":["llamase: 접속법이라 '~하라고 했다'는 명령 전달이 되어 의미가 달라집니다 ✗","llamaría: 과거 기준의 미래를 나타내는 가능법 → 정답 ✓","llamaba: 불완료과거라 약속한 미래 행위를 나타내지 못합니다 ✗","llamó: 단순과거라 '이미 전화했다'는 뜻이 되어 cuando tuviera와 맞지 않습니다 ✗"]},{"id":"G371","q":"____ mejor de la película fue el final.","o":["La","ø","El","Lo"],"a":3,"k":"중성 관사 lo","t":"그 영화에서 가장 좋았던 점은 결말이었다.","e":"중성 관사 lo + 형용사는 '~한 것, ~한 점'이라는 추상적 의미를 만듭니다. lo mejor는 '가장 좋은 점'이라는 뜻입니다. 특정 명사를 가리키지 않으므로 남성 el이나 여성 la가 아니라 lo를 씁니다. 예: Lo bueno es que... (좋은 점은 ~이다)","x":["La: 여성 명사가 따로 없으므로 맞지 않습니다 ✗","ø: 관사 없이는 mejor가 명사처럼 쓰일 수 없습니다 ✗","El: 남성 명사를 가리킬 때 쓰며, 추상적 '~한 점'은 lo를 씁니다 ✗","Lo: lo + 형용사로 '가장 좋은 점' → 정답 ✓"]},{"id":"G372","q":"____ ver a Mariana con su nuevo novio.","o":["Acabo por","Dejo de","Acabo de","Llego a"],"a":2,"k":"acabar de+동사원형","t":"방금 마리아나를 새 남자친구와 함께 있는 걸 봤어.","e":"acabar de + 동사원형은 '방금 ~했다'라는 아주 가까운 과거를 나타냅니다. 동사는 현재형이지만 의미는 '방금 일어난 일'입니다. 예: Acabo de llegar. (방금 도착했어.)","x":["Acabo por: '결국 ~하게 되다'라는 뜻이라 문맥에 맞지 않습니다 ✗","Dejo de: '~하는 것을 그만두다'라는 뜻이라 의미가 맞지 않습니다 ✗","Acabo de: '방금 ~했다'를 나타내는 동사 우회 표현 → 정답 ✓","Llego a: '마침내 ~하기에 이르다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G373","q":"____ las 4 de la tarde cuando escuchamos la detonación.","o":["Estarían","Estarán","Serían","Serán"],"a":2,"k":"과거 시각 추측 serían","t":"우리가 폭발음을 들었을 때는 오후 4시쯤이었을 것이다.","e":"시각을 말할 때는 ser를 씁니다(Son las cuatro). 과거의 시각을 추측할 때는 가능법을 쓰므로 Serían las 4(4시쯤이었을 것이다)가 됩니다. 현재의 시각을 추측하면 미래형 Serán las 4(지금 4시쯤일 거야)를 씁니다.","x":["Estarían: 시각은 estar가 아니라 ser로 말합니다 ✗","Estarán: 시각은 ser로 말하며 시제도 과거와 맞지 않습니다 ✗","Serían: 과거 시각을 추측하는 ser의 가능법 → 정답 ✓","Serán: 현재 시각의 추측이라 과거(escuchamos)와 맞지 않습니다 ✗"]},{"id":"G374","q":"Si ____ más paciente, te sentirías mejor.","o":["fueras","eres","serás","eras"],"a":0,"k":"si+접속법 과거 가정","t":"네가 좀 더 인내심이 있다면, 기분이 더 나아질 텐데.","e":"결과절에 가능법 sentirías(~할 텐데)가 있으면, 조건절은 si + 접속법 과거를 써서 현재 사실과 다르거나 가능성이 낮은 가정을 나타냅니다. 그래서 si fueras가 맞습니다. 인내심 같은 성격은 ser로 표현합니다.","x":["fueras: 가능법 결과절과 짝을 이루는 접속법 과거 → 정답 ✓","eres: 직설법 현재면 결과절도 직설법(te sientes)이어야 합니다 ✗","serás: si 조건절에는 미래형을 쓰지 않습니다 ✗","eras: 직설법 불완료과거라 가능법 결과절과 맞지 않습니다 ✗"]},{"id":"G375","q":"No ____ desobedientes con vuestra madre.","o":["seáis","sean","seas","sed"],"a":0,"k":"vosotros 부정 명령","t":"너희 엄마 말을 안 듣는 버릇없는 아이가 되지 마라.","e":"vuestra madre(너희 엄마)를 보면 상대는 vosotros입니다. 부정 명령은 no + 접속법 현재이므로 ser의 vosotros 접속법 현재 seáis를 씁니다. 긍정 명령은 sed(~해라)입니다. 중남미에서는 ustedes를 써서 No sean desobedientes라고 합니다.","x":["seáis: no + 접속법 현재 vosotros형의 부정 명령 → 정답 ✓","sean: ustedes형이라 vuestra(vosotros)와 인칭이 맞지 않습니다 ✗","seas: tú형 단수라 복수 상대에게 맞지 않습니다 ✗","sed: 긍정 명령형이라 no와 함께 쓸 수 없습니다 ✗"]},{"id":"G376","q":"¿Quieres que ____ una moto cuando lleguemos a la isla?","o":["alquilaremos","alquilemos","alquilamos","alquilaríamos"],"a":1,"k":"querer que+접속법","t":"섬에 도착하면 우리 오토바이를 빌릴까?","e":"¿Quieres que...?는 '내가/우리가 ~하기를 원하니?' 즉 '~할까?'라는 제안 표현이며, 뒤에 접속법을 씁니다. 주어가 우리(nosotros)이므로 접속법 현재 alquilemos가 맞습니다. 예: ¿Quieres que te ayude? (도와줄까?)","x":["alquilaremos: 직설법 미래라 querer que 뒤에 쓸 수 없습니다 ✗","alquilemos: 제안을 나타내는 querer que + 접속법 현재 → 정답 ✓","alquilamos: 직설법 현재라 querer que 뒤에 쓸 수 없습니다 ✗","alquilaríamos: 가능법이라 querer que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G377","q":"No ____ hablarle así a tu padre. ¡Que sea la última vez!","o":["te eches a","acabes por","vuelvas a","dejes de"],"a":2,"k":"volver a+동사원형","t":"다시는 아빠한테 그렇게 말하지 마. 이번이 마지막이야!","e":"volver a + 동사원형은 '다시 ~하다'라는 뜻입니다. 부정 명령 no vuelvas a hablar는 '다시는 그렇게 말하지 마라'라는 강한 경고가 됩니다. ¡Que sea la última vez!(이번이 마지막이길!)와 잘 어울립니다.","x":["te eches a: echarse a는 '갑자기 ~하기 시작하다'라는 뜻으로 hablar와 어울리지 않습니다 ✗","acabes por: '결국 ~하게 되다'라는 뜻이라 문맥에 맞지 않습니다 ✗","vuelvas a: '다시 ~하다'로 '다시는 그러지 마라'라는 경고 → 정답 ✓","dejes de: no dejes de는 '꼭 ~해라(그만두지 마라)'라는 뜻이 되어 의미가 반대입니다 ✗"]},{"id":"G378","q":"¿Les digo a los chicos que ____ un poco más tarde?","o":["vinieran","estén viniendo","vendrían","vengan"],"a":3,"k":"간접 명령 decir que","t":"애들한테 조금 더 늦게 오라고 말할까?","e":"decir que가 '~하라고 말하다'라는 명령·요청을 전달할 때는 뒤에 접속법이 옵니다. 주절이 현재(digo)이므로 접속법 현재 vengan을 씁니다. 직접화법으로 바꾸면 'Venid un poco más tarde'(좀 더 늦게 와)입니다.","x":["vinieran: 접속법 과거라 현재형 digo와 시제가 맞지 않습니다 ✗","estén viniendo: 진행형 접속법이라 '오는 중이라고' 말하는 어색한 뜻이 됩니다 ✗","vendrían: 가능법이라 명령 전달이 되지 않습니다 ✗","vengan: 현재 시점의 명령 전달, 접속법 현재 → 정답 ✓"]},{"id":"G379","q":"Si tienes frío, ____ el abrigo.","o":["pones","ponte","pon te","pon"],"a":1,"k":"재귀동사 긍정 명령","t":"추우면 외투를 입어.","e":"ponerse(옷을 입다)의 tú 긍정 명령은 불규칙형 pon에 재귀대명사 te를 붙여 한 단어로 씁니다. 그래서 ponte가 됩니다. 긍정 명령에서는 대명사가 동사 뒤에 붙어서 띄어 쓰지 않습니다.","x":["pones: 직설법 현재라 명령이 아닙니다 ✗","ponte: pon + te를 붙여 쓴 tú 긍정 명령 → 정답 ✓","pon te: 대명사는 긍정 명령 뒤에 붙여 써야 하므로 띄어 쓰면 틀립니다 ✗","pon: te가 없으면 '외투를 (어딘가에) 놓아라'라는 뜻이 됩니다 ✗"]},{"id":"G380","q":"Llevamos cuatro años ____ en esta urbanización.","o":["residir","a residir","residido","residiendo"],"a":3,"k":"llevar+기간+현재분사","t":"우리는 이 주택단지에서 4년째 살고 있다.","e":"llevar + 기간 + 현재분사는 '(얼마 동안) 계속 ~하고 있다'라는 뜻입니다. Llevamos cuatro años residiendo는 '4년째 거주하고 있다'가 됩니다. 같은 뜻으로 Hace cuatro años que residimos aquí라고도 합니다.","x":["residir: 동사원형은 llevar + 기간 구문에 쓰지 않습니다 ✗","a residir: llevar a는 '~로 이끌다'라는 뜻이라 맞지 않습니다 ✗","residido: 과거분사는 이 구문에 쓰지 않습니다 ✗","residiendo: llevar + 기간 + 현재분사의 계속 표현 → 정답 ✓"]},{"id":"G381","q":"No es lógico que no ____ el trabajo que le han ofrecido, pues es mejor que el que tiene ahora.","o":["acepte","ha aceptado","acepta","acepará"],"a":0,"k":"가치 판단+접속법","t":"그가 제안받은 일을 받아들이지 않는 건 말이 안 돼, 지금 하는 일보다 더 좋은 일이니까.","e":"No es lógico que(~하는 것은 논리적이지 않다)는 가치 판단 표현이므로 뒤에 접속법이 옵니다. 그래서 aceptar의 접속법 현재 acepte가 맞습니다. 비슷한 표현: Es normal que, Es raro que, Es lógico que.","x":["acepte: 가치 판단 표현 뒤의 접속법 현재 → 정답 ✓","ha aceptado: 직설법이라 es lógico que 뒤에 쓸 수 없습니다 ✗","acepta: 직설법 현재라 가치 판단 표현 뒤에 쓸 수 없습니다 ✗","acepará: 철자가 틀린 형태이며 직설법 미래 aceptará여도 맞지 않습니다 ✗"]},{"id":"G382","q":"____ dos días, yo no sabía nada sobre ese asunto.","o":["Desde hace","Hasta","Antes","Hasta hace"],"a":3,"k":"hasta hace(~전까지)","t":"이틀 전까지만 해도 나는 그 일에 대해 아무것도 몰랐다.","e":"hasta hace + 기간은 '(지금으로부터) ~전까지'라는 뜻입니다. hace dos días가 '이틀 전'이고, 앞에 hasta(~까지)가 붙어 '이틀 전까지는 몰랐다(그 후로 알게 됨)'라는 의미가 됩니다. 비교: desde hace dos días(이틀 전부터).","x":["Desde hace: '~전부터'라는 뜻이라 '이틀 전부터 몰랐다'는 어색한 의미가 됩니다 ✗","Hasta: 기간 앞에 hace가 없어 '이틀까지'가 되어 어색합니다 ✗","Antes: antes de dos días처럼 쓰려면 de가 필요하고 의미도 맞지 않습니다 ✗","Hasta hace: '~전까지'라는 시간 표현 → 정답 ✓"]},{"id":"G383","q":"Mariana dice que ____ harta de las quejas de su marido.","o":["sea","esté","está","es"],"a":2,"k":"decir que+직설법","t":"마리아나는 남편의 불평에 질렸다고 말한다.","e":"decir que가 단순히 사실을 전달할 때는 직설법을 씁니다(명령을 전달할 때만 접속법). estar harto/a de는 '~에 질리다, 지긋지긋하다'라는 상태 표현이므로 ser가 아니라 estar를 씁니다. 그래서 está가 맞습니다.","x":["sea: 접속법이고 ser라서 이중으로 맞지 않습니다 ✗","esté: estar는 맞지만 사실 전달에는 접속법을 쓰지 않습니다 ✗","está: 사실 전달의 직설법 + 상태를 나타내는 estar → 정답 ✓","es: harta는 일시적 상태라 ser와 쓰지 않습니다 ✗"]},{"id":"G384","q":"Todas las entradas para ese concierto ____ rapidísimo.","o":["fue vendida","fueron vendida","se vendieron","se vendió"],"a":2,"k":"수동의 se","t":"그 콘서트 표가 전부 순식간에 팔렸다.","e":"'팔렸다'처럼 행위자를 밝히지 않는 수동 의미는 수동의 se(se + 3인칭 동사)로 자주 표현합니다. 주어 todas las entradas가 복수이므로 동사도 복수 se vendieron이 됩니다. ser 수동태로 쓴다면 fueron vendidas가 되어야 하지만 보기에 없습니다.","x":["fue vendida: 단수형이라 복수 주어와 맞지 않습니다 ✗","fueron vendida: 과거분사 vendida가 복수(vendidas)가 아니라 틀립니다 ✗","se vendieron: 복수 주어와 일치하는 수동의 se → 정답 ✓","se vendió: 단수 동사라 복수 주어 entradas와 일치하지 않습니다 ✗"]},{"id":"G385","q":"¿Otra vez ____ ha olvidado el libro?","o":["te se","te","te lo","se te"],"a":3,"k":"무의지의 se","t":"너 또 책을 깜빡했어?","e":"olvidarse를 '의도치 않게 잊어버리다'라는 뜻으로 쓸 때 se + 간접목적격 대명사 + 동사 구조를 씁니다. 대명사 순서는 항상 se가 먼저이므로 se te ha olvidado가 맞습니다. 이때 잊어버린 것(el libro)이 문법상 주어가 됩니다.","x":["te se: 순서가 틀렸습니다. se가 항상 먼저 옵니다 ✗","te: se가 없으면 olvidar의 이 구조가 성립하지 않습니다 ✗","te lo: el libro가 이미 있어 lo가 중복되고 se도 빠졌습니다 ✗","se te: se + 간접목적격 대명사 순서의 올바른 형태 → 정답 ✓"]},{"id":"G386","q":"Yo no como ____ cosa, tengo una alimentación sana.","o":["uno cualquiera","cualquiera","cualquier","una cualquiera"],"a":2,"k":"cualquier(어떤 ~든)","t":"나는 아무거나 먹지 않아, 건강하게 먹는 편이야.","e":"cualquiera(어떤 것이든)는 명사 앞에 올 때 끝의 -a가 떨어져 cualquier가 됩니다. 남성·여성 명사 모두에 쓰므로 cualquier cosa(아무것이나)가 맞습니다. 명사 뒤에 오면 una cosa cualquiera(아무거나 하나)처럼 cualquiera를 씁니다.","x":["uno cualquiera: '아무 사람 하나'라는 뜻으로 명사 앞에 쓰지 않습니다 ✗","cualquiera: 명사 앞에서는 cualquier로 줄어야 합니다 ✗","cualquier: 명사 앞에서 줄어든 형태 → 정답 ✓","una cualquiera: 명사 앞에 올 수 없고 '하찮은 여자'라는 경멸적 뜻도 있습니다 ✗"]},{"id":"G387","q":"En mi opinión, ____ felicidad no está en las cosas materiales.","o":["el","ø","la","una"],"a":2,"k":"추상명사 정관사","t":"내 생각에 행복은 물질적인 것에 있지 않다.","e":"felicidad(행복)처럼 추상적인 개념을 일반적으로 말할 때, 특히 주어 자리에서는 정관사를 씁니다. 그래서 la felicidad가 맞습니다. 한국어에는 관사가 없어 빠뜨리기 쉬우니 주의하세요. 예: El amor es ciego. (사랑은 맹목적이다.)","x":["el: felicidad는 여성 명사라 el을 쓸 수 없습니다 ✗","ø: 주어 자리의 추상명사는 보통 관사가 필요합니다 ✗","la: 여성 추상명사를 일반적으로 말하는 정관사 → 정답 ✓","una: '어떤 하나의 행복'이 되어 일반적 진술에 맞지 않습니다 ✗"]},{"id":"G388","q":"Yo no sé ____ sobre ese asunto.","o":["ninguno","alguno","algo","nada"],"a":3,"k":"이중 부정 nada","t":"나는 그 일에 대해 아무것도 모른다.","e":"스페인어는 동사 앞에 no가 있으면 뒤에 부정어(nada, nadie, ninguno)를 함께 쓰는 이중 부정이 정상입니다. '아무것도 ~않다'는 nada를 씁니다. 예: No veo a nadie. (아무도 안 보인다.)","x":["ninguno: '아무도/어느 것도'라는 뜻으로 사물 전체를 가리키는 '아무것도'에는 nada를 씁니다 ✗","alguno: 긍정어라 no와 함께 쓰지 않습니다 ✗","algo: '무언가'라는 긍정어라 부정문에서는 nada로 바뀝니다 ✗","nada: no와 함께 쓰는 '아무것도' → 정답 ✓"]},{"id":"G389","q":"No me gusta que me hable ____ fuera tonto.","o":["como si","si","como que","como"],"a":0,"k":"como si+접속법 과거","t":"그가 나를 바보 취급하듯이 말하는 게 싫다.","e":"como si(마치 ~인 것처럼)는 항상 접속법 과거(또는 과거완료)와 함께 씁니다. 빈칸 뒤의 fuera가 접속법 과거라는 점이 힌트입니다. 예: Habla como si lo supiera todo. (그는 마치 모든 걸 아는 것처럼 말한다.)","x":["como si: '마치 ~인 것처럼'으로 접속법 과거 fuera와 짝을 이룸 → 정답 ✓","si: '만약 ~라면'이라는 조건이라 의미가 맞지 않습니다 ✗","como que: '~인 것처럼'의 구어 표현이지만 접속법 과거와 결합하지 않습니다 ✗","como: '~처럼, ~대로'라는 뜻으로 접속법 과거 fuera와 바로 결합하지 않습니다 ✗"]},{"id":"G390","q":"Nadie comprende el ____ de su inesperada reacción.","o":["porque","por que","por qué","porqué"],"a":3,"k":"명사 porqué","t":"아무도 그의 예상치 못한 반응의 이유를 이해하지 못한다.","e":"관사 el 뒤에서 '이유'라는 명사로 쓰일 때는 붙여 쓰고 악센트를 찍은 porqué를 씁니다. el porqué de... = la razón de...(~의 이유)로 바꿔 보면 쉽게 확인할 수 있습니다. 명사이므로 복수형 los porqués도 가능합니다.","x":["porque: '왜냐하면'이라는 접속사라 관사 뒤에 올 수 없습니다 ✗","por que: 전치사 + 관계사라 명사 자리에 맞지 않습니다 ✗","por qué: '왜'라는 의문사라 관사 뒤 명사 자리에 쓰지 않습니다 ✗","porqué: '이유'를 뜻하는 명사 → 정답 ✓"]},{"id":"G391","q":"____ se sientan en la primera fila son los mejores estudiantes.","o":["Los que","Quien","Que","Los cuales"],"a":0,"k":"관계사 los que","t":"맨 앞줄에 앉는 사람들이 가장 우수한 학생들이다.","e":"선행사 없이 '~하는 사람들'이라고 말할 때는 관사 + que(el que, la que, los que, las que)를 씁니다. 동사 se sientan과 son이 복수이므로 los que가 맞습니다. 예: Los que estudian aprueban. (공부하는 사람들은 합격한다.)","x":["Los que: 선행사 없이 '~하는 사람들'을 뜻하는 복수 관계사 → 정답 ✓","Quien: 단수이므로 복수 동사 se sientan, son과 맞지 않습니다 ✗","Que: 관사 없이 que만으로는 선행사 없는 '~하는 사람'을 나타낼 수 없습니다 ✗","Los cuales: 반드시 앞에 선행사가 있어야 하므로 문장 맨 앞에 쓰지 않습니다 ✗"]},{"id":"G392","q":"Personalmente no conozco a nadie que ____ coreano.","o":["hablen","habla","hablan","hable"],"a":3,"k":"부정 선행사+접속법","t":"나는 개인적으로 한국어를 하는 사람을 아무도 모른다.","e":"관계절이 꾸미는 대상이 존재하지 않거나(nadie) 불확실할 때는 관계절에 접속법을 씁니다. nadie(아무도)는 단수이므로 hablar의 접속법 현재 3인칭 단수 hable가 맞습니다. 비교: Conozco a alguien que habla coreano. (한국어를 하는 사람을 알고 있다 → 직설법)","x":["hablen: 접속법이지만 복수형이라 nadie(단수)와 맞지 않습니다 ✗","habla: 직설법이라 존재하지 않는 대상을 꾸밀 수 없습니다 ✗","hablan: 직설법 복수형이라 이중으로 맞지 않습니다 ✗","hable: 존재하지 않는 대상을 꾸미는 접속법 단수 → 정답 ✓"]},{"id":"G393","q":"Este texto no ha sido corregido ____ ningún profesor.","o":["sobre","desde","por","de"],"a":2,"k":"수동태 행위자 por","t":"이 글은 어떤 선생님도 교정하지 않았다.","e":"ser + 과거분사 수동태에서 행위자(누구에 의해)는 전치사 por로 나타냅니다. 그래서 corregido por ningún profesor(어떤 선생님에 의해서도 교정되지 않은)가 됩니다. 예: El libro fue escrito por Cervantes. (그 책은 세르반테스가 썼다.)","x":["sobre: '~위에, ~에 관하여'라는 뜻이라 행위자를 나타내지 않습니다 ✗","desde: '~부터'라는 출발점을 나타내 맞지 않습니다 ✗","por: 수동태의 행위자를 나타내는 전치사 → 정답 ✓","de: 옛 문체에서만 행위자로 쓰였고 현대 수동태에서는 por를 씁니다 ✗"]},{"id":"G394","q":"¿____ cuándo sales con Rosa?","o":["Hasta","Desde","De","Hacia"],"a":1,"k":"¿Desde cuándo?","t":"너 로사랑 언제부터 사귀었어?","e":"'언제부터?'라고 시작 시점을 묻고, 그때부터 지금까지 이어지는 일을 물을 때는 ¿Desde cuándo...? + 현재형을 씁니다. salir con alguien은 '~와 사귀다(데이트하다)'라는 뜻입니다. 대답 예: Desde el verano pasado. (작년 여름부터.)","x":["Hasta: '언제까지'라는 뜻이라 사귄 시작 시점을 묻지 않습니다 ✗","Desde: '언제부터'를 묻는 전치사 → 정답 ✓","De: de cuándo는 '언제의 것인지'라는 뜻으로 의미가 맞지 않습니다 ✗","Hacia: '~무렵, ~쪽으로'라는 뜻이라 이 질문에 맞지 않습니다 ✗"]},{"id":"G395","q":"Tanto si te gusta ____ no, tienes que comerte toda la comida.","o":["aunque","como que","como si","que si"],"a":2,"k":"tanto si... como si","t":"좋든 싫든, 너는 음식을 다 먹어야 해.","e":"tanto si... como si...는 '~이든 ~이든 (상관없이)'이라는 고정 구문입니다. tanto si te gusta como si no는 '네가 좋아하든 안 좋아하든'이라는 뜻입니다. si가 들어가므로 직설법(gusta)을 씁니다.","x":["aunque: tanto si와 짝을 이루지 않아 구문이 완성되지 않습니다 ✗","como que: tanto si... como si 구문의 형태가 아닙니다 ✗","como si: tanto si와 짝을 이루어 '~이든 아니든'을 만듦 → 정답 ✓","que si: tanto si 다음에는 como si가 와야 합니다 ✗"]},{"id":"G396","q":"Esa pregunta es difícil ____ responder.","o":["de","en","por","a"],"a":0,"k":"형용사+de+동사원형","t":"그 질문은 대답하기 어렵다.","e":"difícil, fácil, imposible 같은 형용사 뒤에 '~하기에'라는 뜻으로 동사원형을 붙일 때, 주어가 그 동작의 대상이면 전치사 de를 씁니다. Esa pregunta es difícil de responder(그 질문은 대답하기 어렵다). 반면 Es difícil responder esa pregunta처럼 비인칭으로 쓰면 de가 없습니다.","x":["de: 형용사 + de + 동사원형(~하기에 어려운) → 정답 ✓","en: difícil과 동사원형 사이에 쓰지 않습니다 ✗","por: 이유를 나타내 이 구조에 맞지 않습니다 ✗","a: difícil 뒤에 동사원형을 연결하는 전치사로 쓰지 않습니다 ✗"]},{"id":"G397","q":"____ había visto la película, no me acordaba de casi nada.","o":["Como","Así que","Ya que","Aunque"],"a":3,"k":"양보 aunque","t":"그 영화를 본 적이 있었지만, 거의 아무것도 기억나지 않았다.","e":"영화를 봤다는 사실과 기억이 안 난다는 사실은 예상과 반대되는 관계이므로 양보 접속사 aunque(~이지만)를 씁니다. 실제 일어난 사실을 인정하는 것이므로 aunque 뒤에 직설법(había visto)이 왔습니다.","x":["Como: '~이기 때문에'라는 이유라 의미가 맞지 않습니다 ✗","Así que: '그래서'라는 결과이며 문장 맨 앞에 이렇게 쓰지 않습니다 ✗","Ya que: '~이니까'라는 이유라 의미가 맞지 않습니다 ✗","Aunque: 대립되는 두 사실을 잇는 양보 접속사 → 정답 ✓"]},{"id":"G398","q":"No suelo beber ____ té.","o":["un","ø","del","el"],"a":1,"k":"불가산명사 무관사","t":"나는 차를 잘 마시지 않는다.","e":"té(차), café, agua 같은 셀 수 없는 명사를 막연히 '(어떤 양의) 차'라고 말할 때, 특히 동사의 목적어 자리에서는 관사를 쓰지 않습니다. 그래서 No suelo beber té가 맞습니다. 특정한 차를 가리킬 때만 el té de mi abuela처럼 관사를 씁니다.","x":["un: '차 한 잔'이라는 뜻이 되어 습관적 진술에 어색합니다 ✗","ø: 막연한 불가산명사 목적어는 관사 없이 씁니다 ✓","del: '그 차 중 일부'라는 부분 표현은 스페인어에서 이렇게 쓰지 않습니다 ✗","el: '그 특정한 차'를 가리키게 되어 일반적 습관과 맞지 않습니다 ✗"]},{"id":"G399","q":"Se ha gastado más dinero ____ pensaba.","o":["como","de que","que","del que"],"a":3,"k":"비교 del que+절","t":"그는 생각했던 것보다 더 많은 돈을 썼다.","e":"비교 대상이 동사가 있는 절(pensaba)일 때는 que 대신 de + 관사 + que를 씁니다. 관사는 비교되는 명사(dinero, 남성 단수)에 맞춰 el이 되고, de + el이 합쳐져 del que가 됩니다. 예: Compré más libros de los que necesitaba. (필요한 것보다 책을 더 샀다.)","x":["como: 동등 비교(tanto... como)에 쓰는 말이라 más와 함께 쓰지 않습니다 ✗","de que: 관사가 빠져 있어 비교 대상 dinero를 받지 못합니다 ✗","que: 비교 대상이 절일 때는 que만으로는 부족합니다 ✗","del que: 남성 명사 dinero에 맞춘 de + el + que → 정답 ✓"]},{"id":"G400","q":"Supongo que ____ de bajón porque se ha peleado con su novio.","o":["está","es","sea","esté"],"a":0,"k":"estar de bajón","t":"남자친구랑 싸워서 그녀가 우울해하는 것 같아.","e":"Supongo que(~라고 짐작한다)는 사실일 것이라고 여기는 내용이므로 직설법을 씁니다. estar de bajón은 '기분이 처지다, 우울하다'라는 구어 표현으로 일시적인 상태라 estar를 씁니다. 그래서 está가 맞습니다.","x":["está: suponer que 뒤의 직설법 + 일시적 상태 estar → 정답 ✓","es: estar de bajón이라는 상태 표현에 ser를 쓰지 않습니다 ✗","sea: 접속법이고 ser라서 맞지 않습니다 ✗","esté: 긍정 suponer que 뒤에는 접속법을 쓰지 않습니다 ✗"]},{"id":"G401","q":"Hemos venido ____ nos digas en persona qué te pasa con nosotros.","o":["hasta que","a que","porque","ya que"],"a":1,"k":"이동동사+a que(목적)","t":"너희가 우리에게 무슨 불만이 있는지 직접 말해 달라고 우리가 왔다.","e":"venir, ir 같은 이동 동사 뒤에서 '~하러, ~하기 위해'라는 목적은 a + 동사원형 또는 주어가 다르면 a que + 접속법으로 나타냅니다. 빈칸 뒤 digas가 접속법이라는 점이 힌트입니다. 예: Vengo a que me expliques esto. (네가 이거 설명해 달라고 왔어.)","x":["hasta que: '~할 때까지'라는 뜻이라 목적의 의미가 되지 않습니다 ✗","a que: 이동 동사 뒤에서 목적을 나타내며 접속법과 함께 씀 → 정답 ✓","porque: '~때문에'라는 이유이고 뒤에 직설법이 와야 합니다 ✗","ya que: '~이니까'라는 이유이고 뒤에 직설법이 와야 합니다 ✗"]},{"id":"G402","q":"¿____ la pizza entera tú solo?","o":["Has comido","Comiste","Te has comido","Tú has comido"],"a":2,"k":"강조의 재귀 comerse","t":"너 혼자서 피자를 통째로 다 먹었어?","e":"comer에 재귀대명사를 붙인 comerse는 '(전부) 먹어 치우다'라는 완료·강조의 뉘앙스를 줍니다. la pizza entera(피자 한 판 전체)처럼 양이 정해진 대상을 다 먹었을 때 아주 자연스럽습니다. 예: Me he bebido toda la botella. (병 하나를 다 마셔 버렸다.)","x":["Has comido: 문법적으로 가능하지만 '통째로 다 먹었다'는 강조 의미가 약합니다 ✗","Comiste: 역시 가능하지만 전부 먹어 치운 뉘앙스를 나타내지 못합니다 ✗","Te has comido: '(전부) 먹어 치웠다'를 강조하는 comerse → 정답 ✓","Tú has comido: 문장 끝에 tú solo가 있어 주어가 중복되고 강조 의미도 없습니다 ✗"]},{"id":"G403","q":"Mándame un mensaje ____ salgas de la escuela.","o":["después de","en cuanto","cuándo","antes"],"a":1,"k":"en cuanto+접속법","t":"학교에서 나오자마자 나한테 메시지 보내.","e":"en cuanto는 '~하자마자'라는 뜻의 시간 접속사입니다. 미래의 일(아직 학교에서 나오지 않음)을 나타낼 때는 뒤에 접속법을 쓰므로 salgas가 왔습니다. 예: En cuanto llegue, te llamo. (도착하자마자 전화할게.)","x":["después de: 뒤에 절을 연결하려면 después de que가 되어야 합니다 ✗","en cuanto: '~하자마자'를 뜻하며 접속법과 함께 미래를 나타냄 → 정답 ✓","cuándo: 악센트가 있는 의문사라 시간 접속사로 쓸 수 없습니다 ✗","antes: 뒤에 절을 연결하려면 antes de que가 필요합니다 ✗"]},{"id":"G404","q":"____ a punto de salir cuando escuchamos el estruendo.","o":["Estábamos","Estuvimos","Fuimos","Éramos"],"a":0,"k":"estar a punto de","t":"우리가 막 나가려던 참에 굉음이 들렸다.","e":"estar a punto de + 동사원형은 '막 ~하려던 참이다'라는 뜻입니다. 과거 이야기에서 다른 사건(굉음)이 끼어들 때의 배경 상황이므로 불완료과거 estábamos를 씁니다. 예: Estaba a punto de dormirme cuando sonó el teléfono. (막 잠들려는데 전화가 울렸다.)","x":["Estábamos: 사건의 배경이 되는 상황을 나타내는 불완료과거 → 정답 ✓","Estuvimos: 단순과거라 다른 사건의 배경을 나타내기에 맞지 않습니다 ✗","Fuimos: a punto de는 estar와 함께 씁니다 ✗","Éramos: a punto de는 ser가 아니라 estar와 씁니다 ✗"]},{"id":"G405","q":"Los pantalones de campana ____ mucho en los años 60.","o":["se llevaban","se hubieran llevado","se llevasen","se han llevado"],"a":0,"k":"과거 유행 se llevaban","t":"나팔바지는 60년대에 많이 유행했다.","e":"llevarse는 '(옷 등이) 유행하다'라는 뜻으로 쓰입니다. en los años 60(60년대에)는 과거의 일정 기간 동안 계속된 상황이므로 불완료과거 se llevaban이 맞습니다. 주어 los pantalones가 복수라서 동사도 복수입니다. 예: Ahora se llevan los colores claros. (요즘은 밝은 색이 유행이다.)","x":["se llevaban: 과거 일정 기간의 유행을 나타내는 불완료과거 → 정답 ✓","se hubieran llevado: 접속법 과거완료라 평서문의 주동사로 쓸 수 없습니다 ✗","se llevasen: 접속법 과거라 평서문의 주동사로 쓸 수 없습니다 ✗","se han llevado: 현재완료라 이미 끝난 60년대와 맞지 않습니다 ✗"]},{"id":"G406","q":"Javier ____ parece muchísimo a su abuelo.","o":["ø","lo","se","le"],"a":2,"k":"parecerse a","t":"하비에르는 할아버지를 정말 많이 닮았다.","e":"'~와 닮다'는 재귀동사 parecerse a를 씁니다. parecer만 쓰면 '~처럼 보이다'라는 뜻이 되므로 se가 꼭 필요합니다. 예: Me parezco a mi madre. (나는 엄마를 닮았다.)","x":["ø: se가 없으면 '닮다'의 뜻이 되지 않습니다 ✗","lo: 직접목적격 대명사라 parecer와 맞지 않습니다 ✗","se: parecerse a(~를 닮다)의 재귀대명사 → 정답 ✓","le: le parece는 '그에게 ~처럼 보이다'라는 뜻이 됩니다 ✗"]},{"id":"G407","q":"¿Por qué no ____ una vuelta por el centro?","o":["damos","demos","démonos","diéramos"],"a":0,"k":"제안 ¿Por qué no...?","t":"우리 시내 한 바퀴 돌러 가는 거 어때?","e":"¿Por qué no + 직설법 현재?는 '~하는 게 어때?'라는 가벼운 제안 표현입니다. nosotros형이므로 damos를 씁니다. dar una vuelta는 '한 바퀴 돌다, 산책하다'라는 뜻입니다. 예: ¿Por qué no vamos al cine? (영화 보러 가는 게 어때?)","x":["damos: 제안 표현 ¿Por qué no + 직설법 현재 → 정답 ✓","demos: 접속법이라 ¿Por qué no...? 뒤에 쓰지 않습니다 ✗","démonos: 재귀 명령형이라 이 구문에 맞지 않습니다 ✗","diéramos: 접속법 과거라 이 구문에 쓰지 않습니다 ✗"]},{"id":"G408","q":"Me prometiste que ____ conmigo.","o":["vendrías","vengas","vinieras","viniste"],"a":0,"k":"간접화법 가능법","t":"너 나랑 같이 오겠다고 약속했잖아.","e":"prometer que(~하겠다고 약속하다)는 약속의 내용(사실)을 전달하므로 직설법 계열을 씁니다. 주절이 과거(prometiste)이고, 그 시점 기준으로 미래의 일이므로 가능법 vendrías를 씁니다. 직접화법으로는 'Vendré contigo'(너랑 같이 갈게)입니다.","x":["vendrías: 과거 기준의 미래를 나타내는 가능법 → 정답 ✓","vengas: 접속법 현재라 사실을 전달하는 prometer que 뒤에 오지 않습니다 ✗","vinieras: 접속법 과거라 약속 내용을 전달하는 문장에 맞지 않습니다 ✗","viniste: 단순과거라 '이미 왔다'가 되어 약속의 의미와 맞지 않습니다 ✗"]},{"id":"G409","q":"No se preocupe, lo haré ____ usted diga.","o":["cómo","como","dónde","cuándo"],"a":1,"k":"관계부사 como","t":"걱정하지 마세요, 말씀하시는 대로 할게요.","e":"como(악센트 없음)는 '~하는 대로, ~하는 방식으로'라는 관계부사입니다. 의문문이 아니므로 악센트를 찍지 않습니다. como usted diga는 '당신이 말하는 대로'이며, 아직 정해지지 않은 미래의 지시라서 접속법 diga를 씁니다.","x":["cómo: 악센트가 있으면 '어떻게'라는 의문사가 되어 맞지 않습니다 ✗","como: '~하는 대로'라는 관계부사 → 정답 ✓","dónde: '어디'라는 의문사라 의미가 맞지 않습니다 ✗","cuándo: '언제'라는 의문사라 의미가 맞지 않습니다 ✗"]},{"id":"G410","q":"Si no nos dices ____ te pasa, no podremos ayudarte.","o":["que","lo que","lo qué","lo cual"],"a":1,"k":"중성 관계사 lo que","t":"너한테 무슨 일이 있는지 말해 주지 않으면 우리가 도와줄 수 없어.","e":"lo que는 '~하는 것'이라는 뜻의 중성 관계사로, 앞에 선행사가 없을 때 씁니다. lo que te pasa는 '너에게 일어나고 있는 일'입니다. 같은 뜻으로 의문사 qué(악센트 있음)를 써서 qué te pasa라고도 할 수 있습니다.","x":["que: 악센트 없는 que는 선행사가 필요한 관계사라 맞지 않습니다(의문사라면 qué) ✗","lo que: 선행사 없는 '~하는 것' → 정답 ✓","lo qué: lo que에는 악센트를 찍지 않습니다 ✗","lo cual: 앞 문장 전체를 받을 때만 쓰며 선행사 없이 쓰지 않습니다 ✗"]},{"id":"G411","q":"Todavía no le he contado nada, voy a ____ en persona.","o":["decírselo","decir se lo","decir lo","decirse"],"a":0,"k":"대명사 결합 se lo","t":"아직 그에게 아무 말도 안 했어, 직접 만나서 말할 거야.","e":"동사원형 뒤에 간접목적격(le)과 직접목적격(lo)이 함께 붙을 때, le는 se로 바뀌어 se + lo 순서가 됩니다. 동사원형 뒤에 대명사를 붙여 한 단어로 쓰고, 강세 위치를 지키기 위해 악센트를 찍어 decírselo가 됩니다.","x":["decírselo: 동사원형 + se + lo를 붙여 쓰고 악센트를 찍은 올바른 형태 → 정답 ✓","decir se lo: 대명사는 동사원형 뒤에 붙여 써야 합니다 ✗","decir lo: 띄어 쓴 것도 틀리고 '그에게(se)'도 빠졌습니다 ✗","decirse: '스스로에게 말하다'라는 뜻이 되고 lo도 빠졌습니다 ✗"]},{"id":"G412","q":"Lo mejor sería que ____ de vacaciones en septiembre.","o":["nos fuéramos","nos iremos","nos iríamos","nos íbamos"],"a":0,"k":"lo mejor sería que","t":"9월에 휴가를 떠나는 게 제일 좋을 것 같아.","e":"Lo mejor sería que(~하는 것이 가장 좋을 것이다)는 가치 판단 표현으로 뒤에 접속법이 옵니다. 주절이 가능법 sería이므로 시제 일치에 따라 접속법 과거 nos fuéramos를 씁니다. irse de vacaciones는 '휴가를 떠나다'라는 뜻입니다.","x":["nos fuéramos: 가능법 sería와 시제가 맞는 접속법 과거 → 정답 ✓","nos iremos: 직설법 미래라 가치 판단 표현 뒤에 쓸 수 없습니다 ✗","nos iríamos: 가능법이라 que절 안에 쓸 수 없습니다 ✗","nos íbamos: 직설법 불완료과거라 맞지 않습니다 ✗"]},{"id":"G413","q":"¿Qué ____ hacer los domingos cuando eras pequeño?","o":["suelas","solías","soliste","sueles"],"a":1,"k":"soler 불완료과거","t":"어렸을 때 일요일마다 보통 뭘 하곤 했어?","e":"soler + 동사원형은 '보통 ~하다, ~하곤 하다'라는 습관을 나타냅니다. cuando eras pequeño(네가 어렸을 때)는 과거의 습관이므로 불완료과거 solías를 씁니다. soler는 습관을 나타내는 동사라 단순과거(soliste)는 거의 쓰지 않습니다.","x":["suelas: 접속법 현재라 의문문의 주동사로 쓸 수 없습니다 ✗","solías: 과거 습관을 나타내는 불완료과거 → 정답 ✓","soliste: soler는 단순과거로 거의 쓰지 않습니다 ✗","sueles: 현재 습관이라 cuando eras pequeño와 맞지 않습니다 ✗"]},{"id":"G414","q":"El otro día soñé que ____ volar.","o":["pudiera","podía","pueda","pude"],"a":1,"k":"soñar que+직설법","t":"며칠 전에 내가 날 수 있는 꿈을 꿨다.","e":"soñar que(~하는 꿈을 꾸다)는 꿈의 내용을 사실처럼 서술하므로 직설법을 씁니다. 꿈속의 상황(날 수 있는 능력)은 배경 묘사이므로 불완료과거 podía가 자연스럽습니다. 예: Soñé que estaba en París. (파리에 있는 꿈을 꿨다.)","x":["pudiera: 접속법이라 soñar que 뒤에 쓰지 않습니다 ✗","podía: 꿈속 상황을 묘사하는 직설법 불완료과거 → 정답 ✓","pueda: 접속법 현재라 시제와 법 모두 맞지 않습니다 ✗","pude: 단순과거라 '(한 번) 날 수 있었다'는 결과가 되어 상황 묘사로 덜 자연스럽습니다 ✗"]},{"id":"G415","q":"Este es el cajón ____ pongo los cubiertos.","o":["donde","por el que","al que","adonde"],"a":0,"k":"관계부사 donde","t":"이게 내가 수저를 넣어 두는 서랍이다.","e":"장소를 나타내는 선행사(el cajón, 서랍)를 받아 '~하는 곳'이라고 할 때 관계부사 donde를 씁니다. 같은 뜻으로 en el que라고도 할 수 있습니다. 이동 방향(~로)을 나타낼 때만 adonde를 씁니다.","x":["donde: 장소 선행사를 받는 관계부사 → 정답 ✓","por el que: '~을 통해서'라는 뜻이라 서랍 안에 넣는 의미와 맞지 않습니다 ✗","al que: '~에게/~로'라는 뜻이라 poner와 어울리지 않습니다 ✗","adonde: 이동 방향(~로 가다)에 쓰며 poner와는 쓰지 않습니다 ✗"]},{"id":"G416","q":"____ mi auto se había estropeado, tuve que ir en tren.","o":["Como","Porque","Aunque","Pese a que"],"a":0,"k":"이유 como(문두)","t":"내 차가 고장 나서 기차를 타고 가야 했다.","e":"문장 맨 앞에서 '~이기 때문에'라는 이유를 나타낼 때는 como를 씁니다. porque는 보통 주절 뒤에 와서 문장 맨 앞에는 잘 쓰지 않습니다. auto는 중남미에서 많이 쓰는 말이고 스페인에서는 coche라고 합니다.","x":["Como: 문장 앞에서 이유를 나타내는 접속사 → 정답 ✓","Porque: 이유를 나타내지만 문장 맨 앞에는 잘 쓰지 않습니다 ✗","Aunque: '~이지만'이라는 양보라 의미가 맞지 않습니다 ✗","Pese a que: '~에도 불구하고'라는 양보라 의미가 맞지 않습니다 ✗"]},{"id":"G417","q":"Este plato de pasta ____ en menos de media hora.","o":["preparas","se prepara","preparan","prepara"],"a":1,"k":"수동/무인칭 se","t":"이 파스타 요리는 30분도 안 걸려서 만들어진다.","e":"'(누구든) ~하면 ~된다'처럼 행위자를 특정하지 않을 때 수동의 se(se + 3인칭 동사)를 씁니다. 주어 este plato가 단수이므로 se prepara가 됩니다. 요리법이나 설명서에서 자주 쓰는 형태입니다. 예: Se habla español. (스페인어 사용 가능.)","x":["preparas: '네가 준비한다'가 되어 주어 este plato와 맞지 않습니다 ✗","se prepara: 행위자를 밝히지 않는 수동의 se → 정답 ✓","preparan: 복수 동사라 단수 주어와 맞지 않고 '그들이 준비한다'가 됩니다 ✗","prepara: '이 요리가 (무언가를) 준비한다'는 이상한 뜻이 됩니다 ✗"]},{"id":"G418","q":"Esa de ____ es la computadora que hay que arreglar.","o":["por aquí","acá","allí","aquí"],"a":2,"k":"esa de allí","t":"저기 있는 저것이 수리해야 할 컴퓨터야.","e":"지시사 esa(그것/저것) 뒤에 de + 장소 부사를 붙여 '~에 있는 그것'이라고 위치를 구체적으로 나타냅니다. 지시사와 장소 부사는 거리감을 맞추는 것이 원칙이라, 말하는 사람에게서 떨어진 ese/esa는 ahí나 allí와 어울립니다. computadora는 중남미 표현이고 스페인에서는 ordenador라고 합니다.","x":["por aquí: '이 근처에'라는 뜻으로 de 뒤에 와서 지시사를 꾸미기 어색합니다 ✗","acá: '여기'라는 가까운 장소라 거리감이 있는 esa와 어울리지 않습니다 ✗","allí: 떨어진 장소를 나타내 esa와 거리감이 맞음 → 정답 ✓","aquí: '여기'라는 가까운 장소라 esa와 거리감이 맞지 않습니다(esta de aquí가 자연스러움) ✗"]},{"id":"G419","q":"No ____ ahí, que esa silla está rota.","o":["sientes","sientas","te sientes","te sientas"],"a":2,"k":"부정 명령 재귀","t":"거기 앉지 마, 그 의자는 부러졌어.","e":"tú 부정 명령은 no + 접속법 현재입니다. sentarse(앉다)는 재귀동사이고 e→ie 어간 변화를 하므로 no te sientes가 됩니다. 긍정 명령이라면 siéntate입니다.","x":["sientes: 재귀대명사가 없고, sentir(느끼다)의 직설법 형태와도 같아 혼동됩니다 ✗","sientas: 재귀대명사가 없고 직설법 현재(앉는다)라 명령이 아닙니다 ✗","te sientes: no + 재귀대명사 + 접속법 현재로 만든 tú 부정 명령 → 정답 ✓","te sientas: 직설법 현재라 '너는 앉지 않는다'는 평서문이 됩니다 ✗"]},{"id":"G420","q":"Perdone, ¿____ abrir la ventana?","o":["se importaría","le importaría","te importaría","la importaría"],"a":1,"k":"importar 정중한 부탁","t":"실례합니다, 창문 좀 열어 주시겠어요?","e":"importar(~이 신경 쓰이다)는 gustar처럼 '신경 쓰는 사람'을 간접목적격 대명사로 씁니다. Perdone가 usted형이므로 usted의 간접목적격 le를 써서 ¿Le importaría...?(~해 주시면 곤란하실까요?)가 됩니다. 가능법 importaría가 정중함을 더합니다.","x":["se importaría: importar는 이 뜻일 때 재귀형으로 쓰지 않습니다 ✗","le importaría: usted에게 쓰는 간접목적격 + 가능법의 정중한 부탁 → 정답 ✓","te importaría: tú형이라 perdone(usted)와 인칭이 맞지 않습니다 ✗","la importaría: 직접목적격 la를 쓰는 것은 la-ísmo로 표준 문법이 아닙니다 ✗"]},{"id":"G421","q":"¿Cuántos museos ____ desde que vives en esta ciudad?","o":["visitabas","estabas visitando","has visitado","habías visitado"],"a":2,"k":"desde que+현재완료","t":"이 도시에 산 이후로 박물관을 몇 군데 가 봤어?","e":"desde que vives aquí(여기 산 이후로)는 과거부터 지금까지 이어지는 기간이므로, 그 기간 동안의 경험을 묻는 데는 현재완료를 씁니다. 그래서 has visitado가 맞습니다. 현재와 연결된 기간 = 현재완료라고 기억하세요.","x":["visitabas: 불완료과거라 지금까지 이어지는 기간과 맞지 않습니다 ✗","estabas visitando: 과거진행형이라 경험의 개수를 묻는 질문에 맞지 않습니다 ✗","has visitado: 지금까지의 기간 동안의 경험을 나타내는 현재완료 → 정답 ✓","habías visitado: 대과거라 현재(vives)와 시제가 맞지 않습니다 ✗"]},{"id":"G422","q":"No creo que Marisa ____ antes que nosotros, no es muy puntual.","o":["llegará","llegue","llega","está llegando"],"a":1,"k":"no creer que+접속법","t":"마리사가 우리보다 먼저 도착할 것 같지 않아, 그녀는 시간을 잘 안 지키거든.","e":"No creo que(~라고 생각하지 않는다)는 의심을 나타내므로 뒤에 접속법이 옵니다. 미래의 일도 접속법 현재로 나타내므로 llegue가 맞습니다. 긍정문이라면 Creo que llegará(도착할 거라고 생각해)처럼 직설법을 씁니다.","x":["llegará: 직설법 미래라 no creo que 뒤에 쓸 수 없습니다 ✗","llegue: 의심 표현 뒤의 접속법 현재 → 정답 ✓","llega: 직설법 현재라 no creo que 뒤에 쓸 수 없습니다 ✗","está llegando: 직설법 진행형이라 맞지 않습니다 ✗"]},{"id":"G423","q":"No necesito ayuda, puedo hacerlo por ____.","o":["mí misma","la misma","una misma","yo misma"],"a":0,"k":"por mí misma","t":"도움은 필요 없어, 나 혼자서 할 수 있어.","e":"por + 전치격 대명사 + mismo/a는 '스스로, 혼자 힘으로'라는 뜻입니다. 말하는 사람이 1인칭 단수 여성이므로 por mí misma가 됩니다. 전치사 por 뒤에는 yo가 아니라 mí를 쓴다는 점에 주의하세요. 남성이라면 por mí mismo입니다.","x":["mí misma: 전치사 뒤의 전치격 mí + 여성형 misma → 정답 ✓","la misma: '같은 것(그녀)'이라는 뜻이 되어 1인칭을 나타내지 못합니다 ✗","una misma: '사람이 스스로'라는 일반적 표현으로 por와 함께 이 문맥에 쓰지 않습니다 ✗","yo misma: 전치사 por 뒤에는 주격 yo를 쓰지 않습니다 ✗"]},{"id":"G424","q":"____ esperanza es lo último que se pierde.","o":["Un","Una","ø","La"],"a":3,"k":"추상명사 정관사","t":"희망은 마지막까지 잃지 않는 것이다.","e":"esperanza(희망)처럼 추상명사를 일반적으로 말할 때, 특히 주어 자리에서는 정관사를 씁니다. 여성 명사이므로 la esperanza가 됩니다. La esperanza es lo último que se pierde는 '희망은 끝까지 버리지 않는다'라는 유명한 속담입니다.","x":["Un: esperanza는 여성 명사라 남성 부정관사를 쓸 수 없습니다 ✗","Una: '어떤 하나의 희망'이 되어 일반적 진술(속담)에 맞지 않습니다 ✗","ø: 주어 자리의 추상명사는 관사가 필요합니다 ✗","La: 여성 추상명사를 일반적으로 가리키는 정관사 → 정답 ✓"]},{"id":"G425","q":"Me molesta que me ____ cuando hablo.","o":["interrumpían","interrumpen","interrumpieran","interrumpan"],"a":3,"k":"감정 동사+접속법","t":"나는 내가 말할 때 누가 끼어드는 게 싫다.","e":"Me molesta que(~하는 게 신경 쓰인다, 짜증 난다)는 감정 표현이므로 뒤에 접속법을 씁니다. 주절이 현재(molesta)이므로 접속법 현재 interrumpan이 맞습니다. 주어를 밝히지 않은 3인칭 복수는 '(사람들이) 끼어들다'라는 무인칭의 의미입니다.","x":["interrumpían: 직설법 불완료과거라 감정 표현 뒤에 쓸 수 없습니다 ✗","interrumpen: 직설법 현재라 감정 표현 뒤에 쓸 수 없습니다 ✗","interrumpieran: 접속법 과거라 현재형 molesta와 시제가 맞지 않습니다 ✗","interrumpan: 현재형 감정 표현 뒤의 접속법 현재 → 정답 ✓"]},{"id":"G426","q":"____ obedientes y haced lo que os dice la maestra.","o":["Sean","Sois","Sé","Sed"],"a":3,"k":"vosotros 긍정 명령 sed","t":"말 잘 듣고 선생님이 하라는 대로 해라.","e":"haced(해라)와 os(너희에게)를 보면 상대는 vosotros입니다. ser의 vosotros 긍정 명령형은 sed입니다. obedientes(말 잘 듣는)도 복수형이라 vosotros와 맞습니다. 중남미에서는 ustedes를 써서 Sean obedientes y hagan...이라고 합니다.","x":["Sean: ustedes형이라 haced(vosotros)와 인칭이 맞지 않습니다 ✗","Sois: 직설법 현재라 명령이 아닙니다 ✗","Sé: tú 단수 명령형이라 복수 obedientes와 맞지 않습니다 ✗","Sed: ser의 vosotros 긍정 명령형 → 정답 ✓"]},{"id":"G427","q":"____ me olvidó decirte que el partido de fútbol se ha suspendido.","o":["A mí","ø","Yo","Se"],"a":3,"k":"무의지의 se","t":"축구 경기가 취소됐다는 걸 너한테 말하는 걸 깜빡했어.","e":"olvidarse를 '(의도치 않게) 깜빡하다'라는 뜻으로 쓸 때 se + 간접목적격 대명사 + 동사 구조를 씁니다. 빈칸 뒤에 me가 이미 있으므로 se를 넣어 Se me olvidó가 됩니다. 이때 잊어버린 것(decirte...)이 문법상 주어라서 동사는 3인칭 olvidó입니다.","x":["A mí: 강조로 쓸 수는 있지만 se가 없으면 구조가 완성되지 않습니다 ✗","ø: se가 없으면 me olvidó라는 틀린 문장이 됩니다 ✗","Yo: 주어를 yo로 하면 동사가 olvidé여야 합니다 ✗","Se: se + me + 동사로 무의지의 '깜빡했다'를 만듦 → 정답 ✓"]},{"id":"G428","q":"¿Sabes ____ quién va a casarse Malena?","o":["con","de","a","sobre"],"a":0,"k":"casarse con","t":"말레나가 누구랑 결혼하는지 알아?","e":"casarse(결혼하다)는 '~와 결혼하다'라고 할 때 전치사 con을 씁니다. 의문사 앞에 전치사를 두는 것이 스페인어의 규칙이므로 ¿con quién...?이 됩니다. 한국어 '~에게 시집가다'처럼 a를 쓰지 않도록 주의하세요.","x":["con: casarse con(~와 결혼하다)의 전치사 → 정답 ✓","de: casarse와 함께 상대를 나타내지 않습니다 ✗","a: casarse a라고 하지 않습니다 ✗","sobre: '~에 관하여'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G429","q":"Sandra vive en ____ piso de ese bloque.","o":["el primero","primer","el primer","primero"],"a":2,"k":"서수 어미 탈락 primer","t":"산드라는 저 건물 1층(스페인식 2층)에 산다.","e":"primero(첫 번째)는 남성 단수 명사 앞에서 -o가 떨어져 primer가 됩니다. 특정한 층을 가리키므로 정관사 el도 필요해 el primer piso가 됩니다. 참고로 스페인에서 primer piso는 지상층(planta baja) 바로 위층, 즉 한국식으로 2층을 뜻하는 경우가 많습니다.","x":["el primero: 명사 앞에서는 primer로 줄어야 합니다 ✗","primer: 형태는 맞지만 관사 el이 빠졌습니다 ✗","el primer: 관사 + 어미가 탈락한 서수 → 정답 ✓","primero: 관사도 없고 명사 앞에서 줄지도 않아 틀립니다 ✗"]},{"id":"G430","q":"Es muy egocéntrico, sólo habla de ____.","o":["sí mismo","lo mismo","consigo mismo","mismo"],"a":0,"k":"재귀 전치격 sí mismo","t":"그는 아주 자기중심적이라 자기 얘기만 한다.","e":"전치사 뒤에서 주어 자신(그 자신)을 가리킬 때는 재귀 전치격 대명사 sí를 쓰고, 강조로 mismo를 붙입니다. hablar de sí mismo는 '자기 자신에 대해 말하다'입니다. 다만 con과 결합할 때만 consigo가 됩니다(consigo mismo).","x":["sí mismo: 전치사 de 뒤에서 주어 자신을 가리키는 재귀 표현 → 정답 ✓","lo mismo: '같은 것'이라는 뜻이라 의미가 맞지 않습니다 ✗","consigo mismo: con과 결합한 형태라 de 뒤에 다시 쓸 수 없습니다 ✗","mismo: 대명사 없이 mismo만으로는 '자기 자신'을 나타내지 못합니다 ✗"]},{"id":"G431","q":"____ cura de esta iglesia es muy amable.","o":["El","Los","La","Las"],"a":0,"k":"성에 따른 의미 차이","t":"이 성당의 신부님은 아주 친절하다.","e":"cura는 관사의 성에 따라 뜻이 달라집니다. el cura는 '(가톨릭) 신부, 사제', la cura는 '치료(법)'입니다. 친절하다는 말과 iglesia(성당)를 보면 사람인 el cura가 맞습니다. 동사 es가 단수라 복수 관사는 쓸 수 없습니다.","x":["El: el cura(신부님)로 문맥과 일치 → 정답 ✓","Los: 복수 관사라 단수 동사 es와 맞지 않습니다 ✗","La: la cura는 '치료'라는 뜻이라 친절할 수 없습니다 ✗","Las: 복수 여성 관사라 수와 의미 모두 맞지 않습니다 ✗"]},{"id":"G432","q":"Conozco a una profesora ____ da clases de ruso en línea.","o":["que","cual","la que","quien"],"a":0,"k":"관계사 que","t":"나는 온라인으로 러시아어 수업을 하는 선생님을 한 분 알고 있다.","e":"선행사(una profesora) 바로 뒤에 쉼표 없이 오는 한정 관계절에서는 주어 역할을 하는 관계사로 que를 씁니다. quien은 쉼표가 있는 설명적 관계절이나 전치사 뒤에서 주로 씁니다. 실제로 아는 사람이라 관계절 동사는 직설법 da입니다.","x":["que: 쉼표 없는 한정 관계절의 주격 관계사 → 정답 ✓","cual: 관사 없이 단독으로 관계사로 쓰지 않습니다(la cual) ✗","la que: 전치사 없이 선행사 바로 뒤에서 이렇게 쓰지 않습니다 ✗","quien: 쉼표 없는 한정 관계절의 주어로는 쓰지 않습니다 ✗"]},{"id":"G433","q":"Ayer ____ un texto de inglés a español todo el día.","o":["había traducido","traducía","estuve traduciendo","estaba traduciendo"],"a":2,"k":"estuve+현재분사","t":"어제 하루 종일 영어 텍스트를 스페인어로 번역했다.","e":"ayer(어제)와 todo el día(하루 종일)는 끝이 정해진 과거의 기간입니다. 이런 기간 동안 계속된 행위는 estar의 단순과거 + 현재분사, 즉 estuve traduciendo로 표현합니다. 비교: Estaba traduciendo cuando llamaste.(네가 전화했을 때 번역하던 중이었다)처럼 배경 상황에는 estaba를 씁니다.","x":["había traducido: 대과거라 다른 과거 시점보다 앞선 일이 되어 맞지 않습니다 ✗","traducía: 불완료과거라 끝이 정해진 기간(todo el día)과 잘 어울리지 않습니다 ✗","estuve traduciendo: 끝난 과거 기간 동안 계속된 행위 → 정답 ✓","estaba traduciendo: 다른 사건의 배경일 때 쓰며 정해진 기간 전체를 나타내지 않습니다 ✗"]},{"id":"G434","q":"Solucioné el problema antes de que ____ los invitados. ¡Menos mal!","o":["vendrán","vinieran","vienen","vendrían"],"a":1,"k":"antes de que+접속법","t":"손님들이 오기 전에 문제를 해결했다. 다행이다!","e":"antes de que(~하기 전에)는 항상 접속법을 씁니다. 주절이 과거(solucioné)이므로 시제 일치에 따라 접속법 과거 vinieran이 맞습니다. ¡Menos mal!은 '다행이다!'라는 감탄 표현입니다.","x":["vendrán: 직설법 미래라 antes de que 뒤에 쓸 수 없습니다 ✗","vinieran: antes de que + 과거 시제의 접속법 → 정답 ✓","vienen: 직설법 현재라 antes de que 뒤에 쓸 수 없습니다 ✗","vendrían: 가능법이라 antes de que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G435","q":"¿Para qué quieres que ____ otra vez el fontanero?","o":["está viniendo","viene","venga","vendrá"],"a":2,"k":"querer que+접속법","t":"배관공이 또 오기를 왜 원하는 거야?","e":"querer que(~하기를 원하다)는 바람을 나타내므로 뒤에 접속법을 씁니다. 주절이 현재(quieres)이므로 venir의 접속법 현재 venga가 맞습니다. ¿Para qué...?는 '무엇 때문에, 무슨 목적으로?'라는 뜻입니다. fontanero는 스페인 표현이고 중남미에서는 plomero라고 합니다.","x":["está viniendo: 직설법 진행형이라 querer que 뒤에 쓸 수 없습니다 ✗","viene: 직설법 현재라 바람 표현 뒤에 쓸 수 없습니다 ✗","venga: querer que 뒤의 접속법 현재 → 정답 ✓","vendrá: 직설법 미래라 querer que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G436","q":"____ mejor de mi trabajo es la flexibilidad horaria.","o":["Lo","ø","La","El"],"a":0,"k":"lo+형용사","t":"내 일에서 가장 좋은 점은 근무 시간이 유연하다는 것이다.","e":"중성 관사 lo + 형용사는 '~한 것, ~한 점'이라는 추상적 의미를 만듭니다. lo mejor de mi trabajo는 '내 일의 가장 좋은 점'입니다. 뒤의 la flexibilidad가 여성 명사지만 lo mejor는 특정 명사를 가리키지 않으므로 la를 쓰지 않습니다.","x":["Lo: lo + 형용사로 '가장 좋은 점' → 정답 ✓","ø: 관사가 없으면 mejor가 명사처럼 쓰일 수 없습니다 ✗","La: 뒤의 flexibilidad에 맞춘 것처럼 보이지만 '~한 점'은 lo로 씁니다 ✗","El: 남성 명사를 가리킬 때 쓰며 추상적 의미는 lo입니다 ✗"]},{"id":"G437","q":"¿Me pone ____ café, por favor?","o":["otro","otra","una otra","un otro"],"a":0,"k":"otro(관사 없이)","t":"커피 한 잔 더 주시겠어요?","e":"otro/otra(다른, 하나 더)는 앞에 부정관사 un/una를 붙이지 않습니다. 영어 another를 직역해서 un otro라고 하지 않도록 주의하세요. café는 남성 명사이므로 otro café가 맞습니다. ¿Me pone...?는 스페인에서 주문할 때 쓰는 표현입니다.","x":["otro: 관사 없이 쓰는 남성형 '하나 더' → 정답 ✓","otra: 여성형이라 남성 명사 café와 맞지 않습니다 ✗","una otra: otro 앞에는 부정관사를 쓰지 않고 성도 맞지 않습니다 ✗","un otro: otro 앞에는 부정관사를 쓰지 않습니다 ✗"]},{"id":"G438","q":"¿Todavía no ____ la pintura que empezaste el año pasado?","o":["has estado terminando","terminabas","habías terminado","has terminado"],"a":3,"k":"todavía no+현재완료","t":"작년에 시작한 그림을 아직도 다 못 끝냈어?","e":"todavía no(아직 ~않았다)는 과거부터 지금까지 완료되지 않은 일을 말하므로 현재완료와 잘 어울립니다. 그래서 has terminado가 맞습니다. 대답 예: No, todavía no la he terminado. (아니, 아직 못 끝냈어.)","x":["has estado terminando: 진행형이라 '완료했는지'를 묻는 의미가 되지 않습니다 ✗","terminabas: 불완료과거라 현재까지의 완료 여부를 나타내지 못합니다 ✗","habías terminado: 대과거라 현재 시점의 질문과 맞지 않습니다 ✗","has terminado: 현재까지의 완료 여부를 묻는 현재완료 → 정답 ✓"]},{"id":"G439","q":"Está claro que suspendió el test ____ no iba preparado.","o":["porque","como","así que","aunque"],"a":0,"k":"이유 porque","t":"준비를 안 하고 갔으니까 시험에 떨어진 게 분명해.","e":"빈칸 뒤의 절(준비가 안 됐다)은 앞 절(시험에 떨어졌다)의 이유이므로, 문장 중간에서 이유를 잇는 porque를 씁니다. como도 이유를 나타내지만 문장 맨 앞에만 옵니다. suspender는 스페인에서 '(시험에) 떨어지다'라는 뜻입니다.","x":["porque: 문장 중간에서 이유를 나타내는 접속사 → 정답 ✓","como: 이유의 como는 문장 맨 앞에만 와서 이 위치에 맞지 않습니다 ✗","así que: '그래서'라는 결과라 원인과 결과가 뒤바뀝니다 ✗","aunque: '~이지만'이라는 양보라 의미가 맞지 않습니다 ✗"]},{"id":"G440","q":"Mándame un mensaje ____ salgas de tu casa.","o":["después","antes","hasta que","cuando"],"a":3,"k":"cuando+접속법(미래)","t":"집에서 나설 때 나한테 메시지 보내.","e":"cuando(~할 때)가 미래의 일을 가리키면 뒤에 접속법을 씁니다. 빈칸 뒤의 salgas가 접속법이라 cuando와 짝이 맞습니다. 예: Cuando tenga tiempo, te llamo. (시간 날 때 전화할게.) 습관이나 과거 사실이면 직설법을 씁니다.","x":["después: 절을 연결하려면 después de que가 필요합니다 ✗","antes: 절을 연결하려면 antes de que가 필요합니다 ✗","hasta que: '~할 때까지'라는 뜻이라 메시지를 보내는 시점과 맞지 않습니다 ✗","cuando: 미래의 시점을 나타내며 접속법 salgas와 연결 → 정답 ✓"]},{"id":"G441","q":"Aquí no hay ____ supermercado.","o":["ninguno","ningún","algún","alguno"],"a":1,"k":"ningún(어미 탈락)","t":"여기에는 슈퍼마켓이 하나도 없다.","e":"ninguno(어떤 ~도 없는)는 남성 단수 명사 앞에서 -o가 떨어져 ningún이 되고 악센트가 붙습니다. no hay와 함께 이중 부정을 이루어 '하나도 없다'는 뜻이 됩니다. 비슷한 예: alguno → algún, uno → un.","x":["ninguno: 명사 앞에서는 ningún으로 줄어야 합니다 ✗","ningún: 남성 단수 명사 앞에서 줄어든 부정어 → 정답 ✓","algún: 긍정어라 부정문 no hay와 맞지 않습니다 ✗","alguno: 긍정어이고 명사 앞에서 줄지도 않아 틀립니다 ✗"]},{"id":"G442","q":"Ojalá ____ trabajo pronto.","o":["encuentre","encontrará","encontraba","encuentra"],"a":0,"k":"ojalá+접속법 현재","t":"빨리 일자리를 구하면 좋겠다.","e":"ojalá(~하면 좋겠다)는 항상 접속법과 함께 씁니다. 실현 가능한 미래의 바람(pronto, 곧)이므로 접속법 현재 encuentre가 맞습니다. 실현 가능성이 낮다고 느끼면 접속법 과거 encontrara를 씁니다.","x":["encuentre: ojalá + 접속법 현재의 실현 가능한 바람 → 정답 ✓","encontrará: 직설법 미래라 ojalá와 함께 쓰지 않습니다 ✗","encontraba: 직설법 불완료과거라 ojalá와 함께 쓰지 않습니다 ✗","encuentra: 직설법 현재라 ojalá와 함께 쓰지 않습니다 ✗"]},{"id":"G443","q":"¿Queda ____ leche o ya se ha acabado?","o":["la","una","ø","de la"],"a":2,"k":"불가산명사 무관사","t":"우유 남았어, 아니면 벌써 다 떨어졌어?","e":"leche(우유) 같은 셀 수 없는 명사를 '(약간의) 우유'라는 막연한 양으로 말할 때는 관사를 쓰지 않습니다. ¿Queda leche?는 '우유가 (조금이라도) 남았니?'라는 뜻입니다. 프랑스어처럼 de la를 붙이는 부분관사는 스페인어에 없습니다.","x":["la: '그 우유'라는 특정한 것이 되어 막연한 양을 묻는 질문과 맞지 않습니다 ✗","una: 셀 수 없는 명사에 부정관사를 붙이지 않습니다 ✗","ø: 막연한 양의 불가산명사는 관사 없이 씀 → 정답 ✓","de la: 스페인어에는 이런 부분관사 용법이 없습니다 ✗"]},{"id":"G444","q":"No sé qué hora es... ____ las dos y pico.","o":["estarán siendo","son","serían","serán"],"a":3,"k":"현재 추측의 미래형","t":"몇 시인지 모르겠어... 두 시 조금 넘었을 거야.","e":"스페인어에서 미래형은 현재 일에 대한 추측을 나타낼 수 있습니다. 시각은 ser로 말하므로 serán las dos(두 시쯤일 거야)가 됩니다. y pico는 '~하고 조금 넘은'이라는 구어 표현입니다. 과거 시각을 추측할 때는 serían을 씁니다.","x":["estarán siendo: ser는 이런 진행형으로 쓰지 않습니다 ✗","son: 단정적인 표현이라 no sé(모르겠다)와 어울리지 않습니다 ✗","serían: 과거 시각의 추측이라 현재 시각에는 맞지 않습니다 ✗","serán: 현재 시각을 추측하는 미래형 → 정답 ✓"]},{"id":"G445","q":"Si hubiéramos salido de casa un poco antes, no ____ el tren.","o":["perdiéramos","habríamos perdido","habíamos perdido","perderemos"],"a":1,"k":"과거 사실 반대 가정","t":"우리가 집에서 조금만 더 일찍 나왔더라면 기차를 놓치지 않았을 텐데.","e":"과거 사실과 반대되는 가정은 si + 접속법 과거완료(hubiéramos salido), 결과절은 가능법 완료(habríamos perdido)로 씁니다. '~했더라면 ~했을 텐데'라는 한국어와 똑같은 구조입니다. 실제로는 늦게 나와서 기차를 놓쳤다는 뜻입니다.","x":["perdiéramos: 접속법 과거라 결과절에 쓸 수 없습니다 ✗","habríamos perdido: 과거 사실 반대의 결과를 나타내는 가능법 완료 → 정답 ✓","habíamos perdido: 직설법 대과거라 가정의 결과를 나타내지 못합니다 ✗","perderemos: 직설법 미래라 과거 가정과 시제가 맞지 않습니다 ✗"]},{"id":"G446","q":"¿Dónde prefieren ____?","o":["sentarse","sentar se","sentar","se sentar"],"a":0,"k":"동사원형+재귀대명사","t":"어디에 앉고 싶으세요?","e":"preferir + 동사원형 구조에서 재귀동사 sentarse(앉다)는 재귀대명사를 동사원형 뒤에 붙여 한 단어로 씁니다. 주어가 ustedes(prefieren)이므로 재귀대명사는 se가 되어 sentarse입니다. ¿Dónde se prefieren sentar?처럼 활용된 동사 앞에 둘 수도 있습니다.","x":["sentarse: 동사원형 뒤에 재귀대명사를 붙여 쓴 형태 → 정답 ✓","sentar se: 대명사를 동사원형 뒤에 띄어 쓰지 않습니다 ✗","sentar: 재귀대명사가 없으면 '(누군가를) 앉히다'라는 뜻이 됩니다 ✗","se sentar: 대명사를 동사원형 바로 앞에 둘 수 없습니다 ✗"]},{"id":"G447","q":"Mañana, a esta misma hora, ____ a Córdoba.","o":["estábamos llegando","llegásemos","estaremos llegando","llegando"],"a":2,"k":"미래 진행형","t":"내일 이 시간쯤에는 우리가 코르도바에 도착하고 있을 거야.","e":"미래의 특정 시점(mañana a esta misma hora, 내일 이 시간)에 진행 중일 행위는 estar의 미래형 + 현재분사, 즉 미래 진행형 estaremos llegando로 나타냅니다. 예: A las ocho estaré cenando. (8시에는 저녁을 먹고 있을 거야.)","x":["estábamos llegando: 과거진행형이라 mañana(내일)와 맞지 않습니다 ✗","llegásemos: 접속법 과거라 평서문의 주동사로 쓸 수 없습니다 ✗","estaremos llegando: 미래 특정 시점의 진행을 나타내는 미래 진행형 → 정답 ✓","llegando: 현재분사만으로는 문장의 주동사가 될 수 없습니다 ✗"]},{"id":"G448","q":"Esperamos que ____ una estancia agradable en nuestro hotel.","o":["habrían tenido","hayan tenido","han tenido","hubiesen tenido"],"a":1,"k":"esperar que+접속법 완료","t":"저희 호텔에서 즐거운 시간을 보내셨기를 바랍니다.","e":"esperar que(~하기를 바라다)는 뒤에 접속법이 옵니다. 주절이 현재(esperamos)이고, 숙박은 이미 끝난(현재와 연결된) 일이므로 접속법 현재완료 hayan tenido가 맞습니다. 체크아웃하는 손님에게 호텔이 쓰는 정중한 인사입니다.","x":["habrían tenido: 가능법 완료라 esperar que 뒤에 쓸 수 없습니다 ✗","hayan tenido: 현재 주절 + 이미 끝난 일의 접속법 현재완료 → 정답 ✓","han tenido: 직설법이라 바람 표현 뒤에 쓸 수 없습니다 ✗","hubiesen tenido: 접속법 과거완료라 현재형 esperamos와 시제가 맞지 않습니다 ✗"]},{"id":"G449","q":"En esta ciudad ____ varios museos interesantes.","o":["están","tiene","hay","son"],"a":2,"k":"hay(존재)","t":"이 도시에는 흥미로운 박물관이 여러 개 있다.","e":"정해지지 않은 대상이 '있다'고 존재를 말할 때는 hay를 씁니다. varios museos(여러 박물관)처럼 부정적인(특정되지 않은) 수량 표현과 함께 쓰며, 복수라도 hay는 형태가 변하지 않습니다. 특정한 대상의 위치를 말할 때는 estar를 씁니다(El museo está en el centro).","x":["están: 특정한 대상의 위치를 말할 때 쓰며 varios와 함께 존재를 나타내지 않습니다 ✗","tiene: 주어가 ciudad가 되려면 en이 없어야 합니다(Esta ciudad tiene...) ✗","hay: 불특정 대상의 존재를 나타내는 무인칭 동사 → 정답 ✓","son: ser는 존재를 나타내지 않습니다 ✗"]},{"id":"G450","q":"No quiero ser ____ en salir al escenario.","o":["la primera","el primer","la primer","lo primero"],"a":0,"k":"서수의 명사적 용법","t":"나는 무대에 첫 번째로 나가는 사람이 되고 싶지 않다.","e":"서수 primero가 명사 없이 '첫 번째 사람'을 뜻할 때는 어미가 줄지 않고 성·수에 맞춰 씁니다. 보기 중 여성형 la primera가 유일하게 올바른 형태이므로 말하는 사람이 여성임을 알 수 있습니다. 남성이라면 el primero가 됩니다. ser el/la primero/a en + 동사원형은 '처음으로 ~하는 사람이 되다'입니다.","x":["la primera: 명사 없이 '첫 번째 사람(여성)'을 나타내는 올바른 형태 → 정답 ✓","el primer: primer는 명사 앞에서만 쓰므로 뒤에 명사가 없으면 틀립니다 ✗","la primer: 여성형에는 어미 탈락이 없어 la primera여야 합니다 ✗","lo primero: '첫 번째 일(것)'이라는 사물·추상적 의미라 사람에게 쓰지 않습니다 ✗"]},{"id":"G451","q":"Si estuviera en tu lugar, no ____ qué hacer.","o":["sabía","sabría","sabré","supiese"],"a":1,"k":"가정문의 조건법","t":"내가 네 입장이라면 무엇을 해야 할지 모를 거야.","e":"'Si + 접속법 과거(estuviera)'는 현재 사실과 반대되는 가정(~라면)을 나타냅니다. 이때 결과 부분에는 조건법 단순형(~할 텐데)을 씁니다. saber의 조건법은 불규칙으로 sabr- 어간을 써서 sabría가 됩니다.","x":["sabía: 직설법 불완료과거(알고 있었다)로, 가정문의 결과절에 맞지 않습니다 ✗","sabría: saber의 조건법(알 텐데) → 비현실 가정의 결과로 정답 ✓","sabré: 미래형(알게 될 것이다)으로, 'Si + 접속법 과거'와 짝이 맞지 않습니다 ✗","supiese: 접속법 과거로 si절에 쓰는 형태이지 결과절에는 쓰지 않습니다 ✗"]},{"id":"G452","q":"Deja el libro ____ te he dicho, por favor.","o":["donde","adonde","en dónde","dónde"],"a":0,"k":"관계부사 donde","t":"내가 말한 곳에 책을 놔 줘.","e":"'내가 말한 곳에'처럼 장소를 가리키는 관계부사(앞 내용과 문장을 이어 주는 말)는 악센트 없는 donde를 씁니다. 의문문이 아니므로 dónde처럼 악센트를 찍지 않습니다. dejar(놓다)는 이동이 아니라 머무는 위치를 나타내므로 adonde가 아닌 donde가 맞습니다.","x":["donde: 장소를 나타내는 관계부사(~하는 곳에) → 정답 ✓","adonde: '~하는 곳으로'라는 방향을 나타내 ir 같은 이동 동사와 씁니다 ✗","en dónde: 악센트가 있는 의문사 형태라 관계사 자리에 맞지 않습니다 ✗","dónde: 의문사(어디)로, 의문문이나 간접의문문에 씁니다 ✗"]},{"id":"G453","q":"____ que quieran convencerme, no voy a cambiar de idea.","o":["Incluso","Dado","Por mucho","Aun"],"a":2,"k":"양보 por mucho que","t":"아무리 그들이 나를 설득하려 해도 나는 생각을 바꾸지 않을 거야.","e":"'Por mucho que + 접속법'은 '아무리 ~해도'라는 강한 양보를 나타냅니다. 뒤에 que가 바로 붙어 있으므로 que와 결합하는 표현이 필요합니다. 예: Por mucho que corras, no llegarás(아무리 뛰어도 못 도착할 거야).","x":["Incluso: '~조차'라는 뜻의 부사로 que와 결합해 양보절을 만들지 않습니다 ✗","Dado: 'dado que(~이므로)'는 이유를 나타내 의미가 반대입니다 ✗","Por mucho: 'por mucho que + 접속법'(아무리 ~해도) → 정답 ✓","Aun: 'aun cuando/aun si'로는 쓰지만 'aun que'라는 형태는 없습니다 ✗"]},{"id":"G454","q":"No nos gustó el servicio de ese restaurante, ____ decidimos no volver por allí.","o":["aunque","debido a que","por lo que","porque"],"a":2,"k":"결과 접속사","t":"그 식당의 서비스가 마음에 들지 않아서 우리는 거기에 다시 가지 않기로 했다.","e":"앞 문장(서비스가 별로였다)이 원인이고, 뒤 문장(다시 안 가기로 했다)이 결과입니다. 그래서 '그래서, 그러므로'라는 결과를 나타내는 por lo que가 알맞습니다. por lo que는 앞 문장 전체를 받아 '그 때문에'라는 뜻이 됩니다.","x":["aunque: '비록 ~이지만'이라는 양보로 의미가 맞지 않습니다 ✗","debido a que: '~때문에'로 이유를 이끌므로 원인·결과 순서가 뒤바뀝니다 ✗","por lo que: '그래서, 그 때문에'라는 결과 연결어 → 정답 ✓","porque: '왜냐하면'으로 뒤에 이유가 와야 해서 맞지 않습니다 ✗"]},{"id":"G455","q":"No me importa el color, puedo escribir con ____ de esos bolígrafos.","o":["un cualquier","cualquier","cualquiera","una cualquiera"],"a":2,"k":"cualquiera 용법","t":"색깔은 상관없어, 저 볼펜들 중 아무거나로 쓸 수 있어.","e":"'cualquier'는 명사 앞에서만 쓰는 줄임형이고(cualquier bolígrafo), 명사 없이 대명사로 쓸 때나 'de + 명사'가 뒤따를 때는 cualquiera를 씁니다. 'cualquiera de esos bolígrafos'는 '저 볼펜들 중 아무거나'라는 뜻입니다.","x":["un cualquier: 관사와 cualquier를 함께 쓰는 형태는 없습니다 ✗","cualquier: 명사 바로 앞에서만 쓰는 형태로 de 앞에는 못 씁니다 ✗","cualquiera: 대명사로 '(그중) 아무거나' → 정답 ✓","una cualquiera: '하찮은 여자'라는 경멸적 표현으로 의미가 전혀 다릅니다 ✗"]},{"id":"G456","q":"El albañil hizo un trabajo mediocre, yo mismo lo ____ mejor.","o":["habré hecho","habría hecho","estaría haciendo","estaré haciendo"],"a":1,"k":"조건법 완료","t":"그 미장이는 형편없는 일을 했어, 내가 직접 했어도 더 잘했을 거야.","e":"과거에 실제로 일어나지 않은 일(내가 직접 하는 것)을 상상하며 '~했을 텐데'라고 말할 때는 조건법 완료(habría + 과거분사)를 씁니다. 숨은 조건 'si lo hubiera hecho yo(내가 했더라면)'가 생략된 문장으로 보면 됩니다.","x":["habré hecho: 미래완료(~했을 것이다, 미래 시점 완료·추측)로 비현실 과거와 맞지 않습니다 ✗","habría hecho: 조건법 완료(~했을 텐데) → 정답 ✓","estaría haciendo: '~하고 있을 텐데'로 진행 의미라 완료된 일에 맞지 않습니다 ✗","estaré haciendo: 미래 진행형(~하고 있을 것이다)으로 의미가 맞지 않습니다 ✗"]},{"id":"G457","q":"Es evidente que estos niños ____ muy listos.","o":["estén siendo","sean","fueran","son"],"a":3,"k":"확실성 표현+직설법","t":"이 아이들이 아주 똑똑하다는 것은 분명하다.","e":"'Es evidente que(~은 분명하다)'처럼 확실함을 나타내는 표현 뒤에는 직설법(사실을 말하는 동사 형태)을 씁니다. 반대로 'No es evidente que'처럼 부정하면 접속법을 씁니다. 지금 아이들이 똑똑하다는 일반적 사실이므로 현재형 son이 맞습니다.","x":["estén siendo: 접속법 현재진행으로, 확실성 표현 뒤에 쓰지 않습니다 ✗","sean: 접속법 현재로, 의심·부정 표현 뒤에 쓰는 형태입니다 ✗","fueran: 접속법 과거로 시제와 법 모두 맞지 않습니다 ✗","son: 직설법 현재(~이다) → 정답 ✓"]},{"id":"G458","q":"Si viviéramos cerca, nos ____ más a menudo.","o":["viéramos","veríamos","vimos","veremos"],"a":1,"k":"가정문의 조건법","t":"우리가 가까이 산다면 더 자주 볼 텐데.","e":"'Si + 접속법 과거(viviéramos)'는 현재 사실과 다른 가정입니다. 결과절에는 조건법(~할 텐데)을 써야 하므로 vernos(서로 만나다)의 1인칭 복수 조건법 nos veríamos가 맞습니다.","x":["viéramos: 접속법 과거로 si절에 쓰는 형태라 결과절에는 맞지 않습니다 ✗","veríamos: 조건법(만날 텐데) → 정답 ✓","vimos: 단순과거(만났다)로 가정문 결과에 맞지 않습니다 ✗","veremos: 미래형으로, 'Si + 직설법 현재'와 짝을 이룹니다 ✗"]},{"id":"G459","q":"¿Te importa llamarme más tarde? Es que ____ salir.","o":["vuelvo a","estoy a punto de","echo a","me pongo a"],"a":1,"k":"동사 우언법","t":"나중에 전화해 줄래? 나 막 나가려던 참이거든.","e":"'estar a punto de + 동사원형'은 '막 ~하려던 참이다'라는 뜻입니다. 지금 전화를 못 받는 이유를 설명하는 상황이므로 곧 나가려 한다는 의미가 자연스럽습니다. 'Es que ~'는 '~거든요'처럼 이유를 덧붙이는 회화 표현입니다.","x":["vuelvo a: 'volver a + 동사원형'은 '다시 ~하다'로 의미가 맞지 않습니다 ✗","estoy a punto de: '막 ~하려는 참이다' → 정답 ✓","echo a: 'echar a + 동사원형'은 '갑자기 ~하기 시작하다'(echar a correr)로 맞지 않습니다 ✗","me pongo a: 'ponerse a'는 '~하기 시작하다'로, salir와 어울리지 않습니다 ✗"]},{"id":"G460","q":"No te preocupes por el trabajo. ____ importante es que te recuperes pronto de tu enfermedad.","o":["El","Esto","Lo","Esta"],"a":2,"k":"중성관사 lo","t":"일 걱정은 하지 마. 중요한 건 네가 병에서 빨리 회복하는 거야.","e":"'lo + 형용사'는 '~한 것, ~한 점'이라는 추상적인 개념을 만듭니다. 'Lo importante'는 '중요한 것'이라는 뜻입니다. 특정 명사를 꾸미는 것이 아니므로 남성·여성 관사(el, la)가 아니라 중성관사 lo를 씁니다.","x":["El: 남성 명사 앞에 쓰는 관사라 추상 개념을 만들지 못합니다 ✗","Esto: '이것'이라는 지시대명사로 형용사 앞에 오지 않습니다 ✗","Lo: 중성관사로 'lo importante(중요한 것)' → 정답 ✓","Esta: 여성 지시형용사(이~)로 문장 구조와 맞지 않습니다 ✗"]},{"id":"G461","q":"En este parque hay ____ árboles altísimos.","o":["los","unos","unas","las"],"a":1,"k":"부정관사 복수","t":"이 공원에는 아주 키 큰 나무들이 있다.","e":"'hay(~이 있다)' 뒤에는 정관사(el, los 등)를 쓰지 않고, 부정관사나 무관사를 씁니다. árbol은 남성 명사이므로 복수 부정관사 unos가 맞습니다. unos는 '몇몇의, 어떤'이라는 뜻을 더합니다.","x":["los: 정관사로 hay 뒤에는 쓰지 않습니다 ✗","unos: 남성 복수 부정관사 → 정답 ✓","unas: 여성 복수형인데 árboles는 남성이라 ✗","las: 여성 정관사라 성도 맞지 않고 hay와도 어울리지 않습니다 ✗"]},{"id":"G462","q":"Me gustaría ser ____ guía turístico.","o":["ø","la","un","el"],"a":0,"k":"직업 앞 관사 생략","t":"나는 관광 가이드가 되고 싶다.","e":"ser 동사 뒤에 직업을 말할 때는 보통 관사를 쓰지 않습니다(Soy profesor, 나는 교사다). 따라서 'ser guía turístico'처럼 빈칸을 비우는 것이 맞습니다. 단, 'un guía muy bueno'처럼 직업에 수식어를 붙여 특징을 말할 땐 부정관사를 씁니다.","x":["ø: 직업 앞에서는 관사를 생략 → 정답 ✓","la: 여성 정관사이고 guía turístico(남성)와도 맞지 않습니다 ✗","un: 수식 없이 직업만 말할 때는 쓰지 않습니다 ✗","el: 특정한 가이드를 가리키는 게 아니어서 ✗"]},{"id":"G463","q":"____ peor del verano en el sur de España es que hace demasiado calor.","o":["Un","Lo","Uno","El"],"a":1,"k":"중성관사 lo","t":"남부 스페인 여름의 가장 나쁜 점은 너무 덥다는 것이다.","e":"'lo + 비교급/형용사'는 '~한 점'이라는 추상적 의미를 만듭니다. 'Lo peor'는 '가장 나쁜 점'입니다. 같은 방식으로 'lo mejor(가장 좋은 점)'도 자주 씁니다.","x":["Un: 부정관사로 형용사를 추상명사로 만들지 못합니다 ✗","Lo: 'lo peor(가장 나쁜 점)' → 정답 ✓","Uno: '하나, 어떤 사람'이라는 대명사로 맞지 않습니다 ✗","El: 'el peor'는 '가장 나쁜 (남성 명사)'라는 뜻으로 뒤에 명사가 생략된 경우에만 씁니다 ✗"]},{"id":"G464","q":"No sé dónde vive Eva, ____ mi hermana sí lo sabe.","o":["pero","pues","así que","por eso"],"a":0,"k":"대조 접속사 pero","t":"에바가 어디 사는지 나는 모르지만, 내 여동생은 알아.","e":"앞 문장(나는 모른다)과 뒤 문장(동생은 안다)이 서로 반대되는 내용이므로 '하지만'이라는 대조 접속사 pero를 씁니다. 'sí'는 앞 내용과 대비해 '~는 (정말) 한다'고 강조하는 말입니다.","x":["pero: '하지만'이라는 대조 → 정답 ✓","pues: '왜냐하면/그러니까'로 이유·결과를 나타내 맞지 않습니다 ✗","así que: '그래서'로 결과를 나타내 의미가 맞지 않습니다 ✗","por eso: '그 때문에'라는 결과 표현이라 ✗"]},{"id":"G465","q":"El otro día ____ una película que me encantó.","o":["veía","he visto","estaba viendo","vi"],"a":3,"k":"단순과거","t":"며칠 전에 나는 정말 마음에 드는 영화를 한 편 봤다.","e":"'El otro día(며칠 전에)'처럼 이미 끝난 과거 시점에 한 번 일어나고 완료된 사건은 단순과거(pretérito indefinido)로 말합니다. 영화 보기는 그날 끝난 하나의 사건이므로 vi가 맞습니다.","x":["veía: 불완료과거로 과거의 습관이나 배경 묘사에 씁니다 ✗","he visto: 현재완료로, 'el otro día' 같은 끝난 시점 표현과 어울리지 않습니다(스페인 기준) ✗","estaba viendo: 과거진행으로 '보고 있던 중'이라 완료된 사건에 맞지 않습니다 ✗","vi: 단순과거(봤다) → 정답 ✓"]},{"id":"G466","q":"No creo que Juan ____ de acuerdo con vosotros.","o":["está","es","esté","sea"],"a":2,"k":"부정 의견+접속법","t":"후안이 너희와 의견이 같다고는 생각하지 않아.","e":"'creo que'는 직설법을 쓰지만, 'No creo que'처럼 부정하면 확신이 없어지므로 접속법(의심을 나타내는 형태)을 씁니다. 또한 '동의하다'는 'estar de acuerdo'라는 고정 표현이므로 estar의 접속법 esté가 정답입니다.","x":["está: 직설법이라 'No creo que' 뒤에 맞지 않습니다 ✗","es: ser 직설법이고, de acuerdo는 estar와 씁니다 ✗","esté: estar의 접속법 현재 → 정답 ✓","sea: 접속법이지만 ser라서 'estar de acuerdo' 표현과 맞지 않습니다 ✗"]},{"id":"G467","q":"____ mejor de mi trabajo es la flexibilidad horaria.","o":["Lo","El","La","Lo más"],"a":0,"k":"중성관사 lo","t":"내 일의 가장 좋은 점은 근무 시간이 유연하다는 것이다.","e":"'lo mejor'는 '가장 좋은 점'이라는 추상적 표현입니다. mejor 자체가 이미 '더 좋은/가장 좋은'이라는 비교급이므로 más를 또 붙이지 않습니다. 예: Lo mejor del viaje fue la comida(여행에서 제일 좋았던 건 음식이었다).","x":["Lo: 'lo mejor(가장 좋은 점)' → 정답 ✓","El: 'el mejor'는 뒤에 남성 명사가 있을 때 쓰므로 추상적 의미가 되지 않습니다 ✗","La: 여성 정관사로, 'la flexibilidad'가 주어가 아니라 보어라서 맞지 않습니다 ✗","Lo más: mejor는 이미 비교급이라 'más mejor'는 틀린 표현입니다 ✗"]},{"id":"G468","q":"¿Cuándo es ____ cumpleaños de tu hermano?","o":["los","las","el","ø"],"a":2,"k":"정관사","t":"네 남동생 생일이 언제야?","e":"cumpleaños는 단수·복수 형태가 같지만, 한 사람의 생일은 단수로 취급해 남성 단수 정관사 el을 씁니다. '형의 생일'처럼 특정한 것을 가리키므로 관사가 필요합니다.","x":["los: 복수 관사로, 한 사람의 생일 하나에는 맞지 않습니다 ✗","las: 여성 복수 관사라 성·수 모두 맞지 않습니다 ✗","el: 남성 단수 정관사 → 정답 ✓","ø: 특정한 것을 가리키는 주어 자리라 관사를 생략할 수 없습니다 ✗"]},{"id":"G469","q":"Nos contestó como si le ____ nuestra pregunta.","o":["molestaría","hubiese molestado","habría molestado","había molestado"],"a":1,"k":"como si+접속법","t":"그는 마치 우리 질문이 기분 나빴다는 듯이 대답했다.","e":"'como si(마치 ~인 것처럼)' 뒤에는 항상 접속법 과거 또는 과거완료를 씁니다. 질문이 대답보다 먼저 일어난 일이므로 과거완료 접속법 hubiese molestado(기분 상하게 했던 것처럼)가 맞습니다. hubiera molestado와 같은 뜻입니다.","x":["molestaría: 조건법은 como si 뒤에 쓰지 않습니다 ✗","hubiese molestado: 접속법 과거완료 → 정답 ✓","habría molestado: 조건법 완료로 como si 뒤에 쓸 수 없습니다 ✗","había molestado: 직설법 과거완료로 como si 뒤에 쓰지 않습니다 ✗"]},{"id":"G470","q":"Ana nos invitó ____ su casa el otro día.","o":["ø","en","a","para"],"a":2,"k":"invitar a","t":"아나가 며칠 전에 우리를 자기 집에 초대했다.","e":"invitar(초대하다)는 '어디에/무엇에' 초대하는지를 말할 때 전치사 a를 씁니다. 예: invitar a cenar(저녁 식사에 초대하다), invitar a una fiesta(파티에 초대하다). 집으로 '가는' 방향의 의미가 있어 en이 아닌 a입니다.","x":["ø: invitar 뒤 장소는 전치사 없이 쓸 수 없습니다 ✗","en: 위치(~안에)를 나타내 초대의 방향 의미와 맞지 않습니다 ✗","a: 'invitar a + 장소/활동' → 정답 ✓","para: 목적·대상(~을 위해)을 나타내 이 구조에 맞지 않습니다 ✗"]},{"id":"G471","q":"____ el examen cuando se hayan sentado todos.","o":["Haber empezado","Empezaremos","Empezar","Empezáramos"],"a":1,"k":"cuando+접속법, 미래","t":"모두 자리에 앉으면 시험을 시작하겠습니다.","e":"'cuando + 접속법(se hayan sentado)'은 아직 일어나지 않은 미래의 시점을 나타냅니다. 이런 문장에서 주절에는 미래형(또는 명령형, 현재형)을 씁니다. 따라서 '우리는 시작할 것이다'인 Empezaremos가 정답입니다.","x":["Haber empezado: 동사원형 완료형으로 주절의 동사가 될 수 없습니다 ✗","Empezaremos: 직설법 미래(시작할 것이다) → 정답 ✓","Empezar: 동사원형이라 주어가 있는 문장의 동사가 될 수 없습니다 ✗","Empezáramos: 접속법 과거로 주절에 쓰지 않습니다 ✗"]},{"id":"G472","q":"No debemos renunciar ____ nuestros sueños.","o":["a","en","con","de"],"a":0,"k":"renunciar a","t":"우리는 우리의 꿈을 포기해서는 안 된다.","e":"renunciar(포기하다, 단념하다)는 항상 전치사 a와 함께 씁니다. 'renunciar a algo'는 '~을 포기하다'라는 뜻입니다. 예: Renunció a su puesto(그는 자리에서 물러났다).","x":["a: 'renunciar a(~을 포기하다)' → 정답 ✓","en: renunciar와 함께 쓰지 않는 전치사입니다 ✗","con: renunciar와 짝을 이루지 않습니다 ✗","de: 'desistir de'와 혼동하기 쉽지만 renunciar는 a를 씁니다 ✗"]},{"id":"G473","q":"Esa casa es diez veces ____ grande que aquella.","o":["más","tan","tanto","ø"],"a":0,"k":"배수 비교","t":"그 집은 저 집보다 열 배 더 크다.","e":"'~배 더 ~하다'는 '숫자 + veces + más + 형용사 + que'로 말합니다. 뒤에 que가 있으므로 우월 비교 más가 필요합니다. tan은 'tan ~ como(~만큼 ~한)'처럼 como와 짝을 이룹니다.","x":["más: 'diez veces más grande que(열 배 더 큰)' → 정답 ✓","tan: 동등 비교로 que가 아닌 como와 씁니다 ✗","tanto: 명사·동사를 수식하는 동등 비교로 형용사 앞에 쓰지 않습니다 ✗","ø: más가 없으면 비교 구문 'que aquella'가 성립하지 않습니다 ✗"]},{"id":"G474","q":"____ la falta de personal, nos vemos obligados a contratar a nuevos trabajadores.","o":["De","Bajo","A","Ante"],"a":3,"k":"전치사 ante","t":"인력이 부족하다 보니 우리는 새 직원들을 고용할 수밖에 없다.","e":"ante는 '~ 앞에서, ~에 직면하여'라는 뜻으로, 어떤 상황에 대응할 때 씁니다. 'Ante la falta de personal'은 '인력 부족 앞에서(인력이 부족하자)'라는 의미입니다. 예: Ante el peligro, huyeron(위험에 처하자 그들은 도망쳤다).","x":["De: '~의/~로부터'로 이 문맥의 원인·상황을 나타내지 못합니다 ✗","Bajo: '~ 아래에서'로 조건·지배를 나타내 맞지 않습니다 ✗","A: 문두에서 상황을 이끄는 표현으로 쓰지 않습니다 ✗","Ante: '~에 직면하여' → 정답 ✓"]},{"id":"G475","q":"Llevé el reloj a la relojería para que lo ____.","o":["arreglaran","arreglarían","hayan arreglado","arreglarán"],"a":0,"k":"para que+접속법","t":"나는 시계를 고쳐 달라고 시계 수리점에 가져갔다.","e":"'para que(~하도록)'는 목적을 나타내며 뒤에는 항상 접속법을 씁니다. 주절이 과거(llevé)이므로 시제를 맞춰 접속법 과거 arreglaran을 씁니다.","x":["arreglaran: 접속법 과거 → 정답 ✓","arreglarían: 조건법은 para que 뒤에 쓰지 않습니다 ✗","hayan arreglado: 접속법 현재완료로, 과거 주절과 시제가 맞지 않습니다 ✗","arreglarán: 직설법 미래라 para que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G476","q":"Cuando eran jóvenes, mis padres ____ con ropa muy rara.","o":["se habían vestido","se han vestido","se vistieron","se vestían"],"a":3,"k":"불완료과거(습관)","t":"젊었을 때 우리 부모님은 아주 특이한 옷을 입곤 했다.","e":"'Cuando eran jóvenes(젊었을 때)'처럼 과거의 한 시기에 반복되던 습관을 말할 때는 불완료과거(pretérito imperfecto, '~하곤 했다')를 씁니다. vestirse(옷을 입다)의 3인칭 복수 불완료과거는 se vestían입니다.","x":["se habían vestido: 과거완료(이미 입었었다)로 습관을 나타내지 않습니다 ✗","se han vestido: 현재완료로 과거의 한 시기와 맞지 않습니다 ✗","se vistieron: 단순과거로 한 번 끝난 행동을 말해 습관에 맞지 않습니다 ✗","se vestían: 불완료과거(입곤 했다) → 정답 ✓"]},{"id":"G477","q":"De pequeña me ____ ir a la playa con mi familia cada domingo.","o":["estaba gustando","gustaba","gustó","ha gustado"],"a":1,"k":"gustar 불완료과거","t":"어릴 때 나는 매주 일요일 가족과 해변에 가는 걸 좋아했다.","e":"'De pequeña(어렸을 때)'와 'cada domingo(매주 일요일)'는 과거의 반복·습관을 나타내므로 불완료과거를 씁니다. gustar의 주어는 'ir a la playa(해변에 가는 것)'라서 3인칭 단수 gustaba가 맞습니다.","x":["estaba gustando: gustar는 진행형으로 거의 쓰지 않고 습관 의미와 맞지 않습니다 ✗","gustaba: 불완료과거(좋아했다, 습관) → 정답 ✓","gustó: 단순과거로 한 번의 경험을 말해 반복 의미와 맞지 않습니다 ✗","ha gustado: 현재완료로 어린 시절이라는 과거 시기와 맞지 않습니다 ✗"]},{"id":"G478","q":"No me sorprende que ____ el partido, han sido mejores que el otro equipo.","o":["estaban ganando","ganarían","hayan ganado","han ganado"],"a":2,"k":"감정 표현+접속법","t":"그들이 경기에서 이긴 게 놀랍지 않아, 상대 팀보다 잘했으니까.","e":"'(No) me sorprende que(~가 놀랍다/놀랍지 않다)' 같은 감정 표현 뒤에는 접속법을 씁니다. 이긴 일은 이미 끝났고 현재와 연결되어 있으므로 접속법 현재완료 hayan ganado를 씁니다.","x":["estaban ganando: 직설법 과거진행이라 감정 표현 뒤에 맞지 않습니다 ✗","ganarían: 조건법으로 감정 표현 뒤 접속법 자리에 쓰지 않습니다 ✗","hayan ganado: 접속법 현재완료 → 정답 ✓","han ganado: 직설법 현재완료라 감정 표현 뒤에 쓸 수 없습니다 ✗"]},{"id":"G479","q":"María está de viaje, ____ que no puede atenderle en este momento.","o":["pues","o sea","ya","debido a"],"a":1,"k":"설명 연결어 o sea","t":"마리아는 여행 중이에요, 그러니까 지금은 응대해 드릴 수가 없어요.","e":"'o sea que'는 '즉, 그러니까'라는 뜻으로 앞 내용을 바탕으로 결론이나 설명을 덧붙입니다. 여행 중이라는 사실에서 '지금 응대할 수 없다'는 결론을 이끌어 내므로 o sea가 자연스럽습니다. atenderle는 '당신을 응대하다'라는 존칭 표현입니다.","x":["pues: '왜냐하면'으로 뒤에 que를 붙여 쓰지 않습니다 ✗","o sea: 'o sea que(그러니까, 즉)' → 정답 ✓","ya: 'ya que'는 '~이니까'로 이유를 이끌어 순서가 맞지 않습니다 ✗","debido a: 'debido a que'는 '~때문에'로 이유를 나타내 의미가 반대입니다 ✗"]},{"id":"G480","q":"Niños, ____ a jugar al patio.","o":["saldrían","están saliendo","salid","salen"],"a":2,"k":"vosotros 명령형","t":"얘들아, 마당에 나가서 놀아라.","e":"'Niños(얘들아)'라고 여러 명에게 친근하게 명령하므로 vosotros 긍정 명령형을 씁니다. 만드는 법은 동사원형의 -r을 -d로 바꾸는 것(salir → salid)입니다. 중남미에서는 vosotros 대신 ustedes를 써서 'salgan'이라고 합니다.","x":["saldrían: 조건법(나갈 텐데)으로 명령이 아닙니다 ✗","están saliendo: 현재진행(나가고 있다)이라 명령이 아닙니다 ✗","salid: vosotros 긍정 명령형 → 정답 ✓","salen: 직설법 현재(그들이 나간다)로 명령이 되지 않습니다 ✗"]},{"id":"G481","q":"A lo mejor ____ a Córdoba este fin de semana.","o":["esté yendo","voy","fuera","vaya"],"a":1,"k":"a lo mejor+직설법","t":"어쩌면 이번 주말에 코르도바에 갈지도 몰라.","e":"'a lo mejor(어쩌면, 아마)'는 추측을 나타내지만 예외적으로 뒤에 직설법을 씁니다. 반면 quizás, tal vez는 직설법·접속법 모두 가능합니다. 그래서 직설법 현재 voy가 정답입니다.","x":["esté yendo: 접속법 진행형으로 a lo mejor 뒤에 쓰지 않습니다 ✗","voy: a lo mejor + 직설법 → 정답 ✓","fuera: 접속법 과거라 a lo mejor 뒤에 맞지 않습니다 ✗","vaya: 접속법 현재로 tal vez 뒤라면 가능하지만 a lo mejor 뒤에는 쓰지 않습니다 ✗"]},{"id":"G482","q":"¿____ de tus compañeras es Celia?","o":["Quién","Cuáles","Quiénes","Qué"],"a":0,"k":"의문사 quién","t":"네 동료들 중에 누가 셀리아야?","e":"사람을 묻는 의문사는 quién(누구)이며, 'quién de + 복수 명사'로 '~ 중 누구'라고 할 수 있습니다. 찾는 사람이 한 명(Celia)이고 동사도 es(단수)이므로 단수형 Quién이 맞습니다. 'Cuál de tus compañeras'도 자연스럽게 쓰입니다.","x":["Quién: 사람 한 명을 묻는 의문사 → 정답 ✓","Cuáles: 복수형이라 동사 es, 한 사람 Celia와 수가 맞지 않습니다 ✗","Quiénes: 복수형이라 단수 동사 es와 맞지 않습니다 ✗","Qué: 'qué de ~'라는 구조로 사람을 고르지 않습니다 ✗"]},{"id":"G483","q":"Confía ____ mí, yo no te voy a fallar.","o":["de","en","a","sobre"],"a":1,"k":"confiar en","t":"나를 믿어, 너를 실망시키지 않을게.","e":"confiar(믿다, 신뢰하다)는 전치사 en과 함께 써서 'confiar en alguien(~을 믿다)'이 됩니다. 전치사 뒤에서는 yo 대신 mí를 쓰며, 악센트에 주의하세요(mi는 '나의'). fallar는 '실망시키다, 저버리다'입니다.","x":["de: 'fiarse de'와 헷갈리기 쉽지만 confiar는 en을 씁니다 ✗","en: 'confiar en(~을 믿다)' → 정답 ✓","a: confiar와 함께 '믿다'의 뜻으로 쓰지 않습니다 ✗","sobre: '~ 위에/~에 관해'라 이 동사와 맞지 않습니다 ✗"]},{"id":"G484","q":"Si ____ frío, nos llevamos los abrigos y ya está.","o":["hará","hacía","haga","hace"],"a":3,"k":"현실 조건 si","t":"추우면 코트를 챙겨 가면 그만이야.","e":"실제로 일어날 수 있는 조건을 말할 때는 'si + 직설법 현재'를 씁니다. si 뒤에는 미래형이나 접속법 현재를 쓰지 않는다는 점이 중요합니다. 'y ya está'는 '그걸로 끝, 그만이다'라는 회화 표현입니다.","x":["hará: si 조건절에는 미래형을 쓰지 않습니다 ✗","hacía: 불완료과거로 현재·미래 조건에 맞지 않습니다 ✗","haga: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","hace: 'si + 직설법 현재' → 정답 ✓"]},{"id":"G485","q":"¿Qué se ve ____ la ventana de tu habitación?","o":["de","desde","a","para"],"a":1,"k":"전치사 desde","t":"네 방 창문에서는 뭐가 보여?","e":"desde는 '~에서(부터)'라는 출발점·관점을 나타냅니다. 창문이라는 위치를 기준으로 무언가를 바라보는 것이므로 desde la ventana(창문에서)가 자연스럽습니다. 예: Desde aquí se ve el mar(여기서 바다가 보인다).","x":["de: 출처·소유를 나타내지만 '바라보는 지점'으로는 desde가 자연스럽습니다 ✗","desde: 관점·출발점(~에서) → 정답 ✓","a: '~로'라는 방향을 나타내 의미가 맞지 않습니다 ✗","para: 목적(~을 위해)이라 맞지 않습니다 ✗"]},{"id":"G486","q":"Me arrepiento ____ muchas cosas.","o":["de","en","a","para"],"a":0,"k":"arrepentirse de","t":"나는 많은 것들을 후회한다.","e":"arrepentirse(후회하다)는 재귀동사로, 후회하는 대상 앞에 전치사 de를 씁니다. 'arrepentirse de algo'는 '~을 후회하다'라는 뜻입니다. 예: Me arrepiento de no haber estudiado(공부 안 한 게 후회된다).","x":["de: 'arrepentirse de(~을 후회하다)' → 정답 ✓","en: arrepentirse와 함께 쓰지 않는 전치사입니다 ✗","a: arrepentirse와 짝을 이루지 않습니다 ✗","para: 목적을 나타내 의미가 맞지 않습니다 ✗"]},{"id":"G487","q":"Es curioso que ____ el horario de este programa.","o":["han cambiado","hayan cambiado","habían cambiado","cambiaban"],"a":1,"k":"가치판단+접속법","t":"이 프로그램의 방송 시간을 바꿨다니 이상하네.","e":"'Es curioso que(~라니 신기하다/이상하다)'처럼 가치 판단이나 감정을 나타내는 표현 뒤에는 접속법을 씁니다. 바꾼 일은 이미 일어났고 현재와 관련 있으므로 접속법 현재완료 hayan cambiado가 맞습니다.","x":["han cambiado: 직설법 현재완료라 가치판단 표현 뒤에 쓰지 않습니다 ✗","hayan cambiado: 접속법 현재완료 → 정답 ✓","habían cambiado: 직설법 과거완료로 법과 시제가 맞지 않습니다 ✗","cambiaban: 직설법 불완료과거라 맞지 않습니다 ✗"]},{"id":"G488","q":"____ esté nevando, voy a sacar al perro.","o":["Aunque","Como si","Ya que","Y eso que"],"a":0,"k":"양보 aunque","t":"눈이 오고 있더라도 개를 산책시키러 나갈 거야.","e":"aunque는 '비록 ~이지만/~하더라도'라는 양보 접속사입니다. 뒤에 접속법(esté nevando)을 쓰면 '눈이 오더라도 상관없다'는 뉘앙스가 됩니다. 눈이 온다는 장애에도 불구하고 개를 데리고 나간다는 의미가 자연스럽습니다.","x":["Aunque: '~하더라도' 양보, 접속법과 결합 → 정답 ✓","Como si: '마치 ~처럼'으로 접속법 과거와 쓰며 의미도 맞지 않습니다 ✗","Ya que: '~이니까'라는 이유로 의미가 맞지 않고 직설법과 씁니다 ✗","Y eso que: '~인데도'라는 뜻이지만 문장 뒤쪽에 오고 직설법과 씁니다 ✗"]},{"id":"G489","q":"Ayer soñé que ____ en otro país.","o":["esté","estuviera","estuve","estaba"],"a":3,"k":"soñar que+직설법","t":"어제 나는 다른 나라에 있는 꿈을 꿨다.","e":"'soñar que(~라는 꿈을 꾸다)'는 꿈의 내용을 전달하므로 직설법을 씁니다. 꿈속 상황(다른 나라에 있음)은 배경 묘사이므로 불완료과거 estaba가 자연스럽습니다. 꿈 내용이 상상이라도 접속법을 쓰지 않는다는 점에 주의하세요.","x":["esté: 접속법 현재로 soñar que 뒤에 쓰지 않습니다 ✗","estuviera: 접속법 과거로 이 동사 뒤에는 맞지 않습니다 ✗","estuve: 단순과거로, 꿈속의 배경·상태 묘사에는 불완료과거가 자연스럽습니다 ✗","estaba: 직설법 불완료과거(있었다, 배경 묘사) → 정답 ✓"]},{"id":"G490","q":"____ he regalado una pulsera de plata a mi novia.","o":["Le","La","ø","Lo"],"a":0,"k":"간접목적격 대명사","t":"나는 여자친구에게 은 팔찌를 선물했다.","e":"regalar(선물하다)에서 '누구에게'는 간접목적격 대명사(~에게)로 씁니다. 'a mi novia(여자친구에게)'는 3인칭 단수이므로 le를 씁니다. 스페인어에서는 'a + 사람'이 있어도 간접목적격 대명사를 함께 쓰는 것이 일반적입니다.","x":["Le: 3인칭 단수 간접목적격(그녀에게) → 정답 ✓","La: 직접목적격(그녀를)이라 '선물받는 사람'에 쓰지 않습니다(laísmo 오류) ✗","ø: 문법적으로 완전히 틀리진 않지만 'a mi novia'가 있을 때 le를 쓰는 것이 표준입니다 ✗","Lo: 남성 직접목적격(그를/그것을)이라 맞지 않습니다 ✗"]},{"id":"G491","q":"Si hubiera sabido que ibais a venir, os ____ algo de comer.","o":["había preparado","estaría preparando","preparase","habría preparado"],"a":3,"k":"과거 비현실 가정","t":"너희가 올 줄 알았더라면 먹을 걸 좀 준비해 뒀을 텐데.","e":"'Si + 접속법 과거완료(hubiera sabido)'는 과거 사실과 반대되는 가정(~했더라면)입니다. 결과절에는 조건법 완료(habría + 과거분사, ~했을 텐데)를 씁니다. os는 '너희에게'라는 간접목적격 대명사입니다.","x":["había preparado: 직설법 과거완료로 가정문의 결과절에 맞지 않습니다 ✗","estaría preparando: 조건법 진행형(준비하고 있을 텐데)으로 과거 가정과 맞지 않습니다 ✗","preparase: 접속법 과거로 결과절에는 쓰지 않습니다 ✗","habría preparado: 조건법 완료 → 정답 ✓"]},{"id":"G492","q":"Ese edificio ____ por un conocido arquitecto.","o":["estaba diseñado","fue diseñado","estuvo diseñando","diseñó"],"a":1,"k":"수동태 ser+과거분사","t":"그 건물은 유명한 건축가에 의해 설계되었다.","e":"'por + 행위자(~에 의해)'가 있는 행위 수동태는 'ser + 과거분사'로 만듭니다. 설계는 과거에 완료된 행위이므로 단순과거 fue diseñado가 맞습니다. 'estar + 과거분사'는 결과 상태를 나타내므로 행위자 por와 잘 쓰지 않습니다.","x":["estaba diseñado: 상태(설계된 상태였다)를 나타내 행위자와 어울리지 않습니다 ✗","fue diseñado: 행위 수동태 → 정답 ✓","estuvo diseñando: '설계하고 있었다'라는 능동 진행형이라 ✗","diseñó: 능동태(설계했다)로, 건물이 주어이면 의미가 맞지 않습니다 ✗"]},{"id":"G493","q":"Elisa no es ni la mitad ____ guapa que su hermana.","o":["por","a","para","de"],"a":3,"k":"ni la mitad de","t":"엘리사는 그녀 언니의 절반만큼도 예쁘지 않다.","e":"'ni la mitad de + 형용사 + que'는 '~의 절반만큼도 ~하지 않다'라는 강조 비교 표현입니다. mitad(절반) 뒤에 형용사를 연결할 때 전치사 de를 씁니다. 예: No es ni la mitad de difícil(절반만큼도 어렵지 않다).","x":["por: 이 비교 표현에 쓰지 않습니다 ✗","a: mitad 뒤 형용사를 연결하지 못합니다 ✗","para: 목적을 나타내 의미가 맞지 않습니다 ✗","de: 'ni la mitad de guapa que' → 정답 ✓"]},{"id":"G494","q":"Te llamo más tarde si no te ____. Ahora mismo estoy ocupada.","o":["importe","importa","importara","importas"],"a":1,"k":"si no te importa","t":"괜찮으면 나중에 전화할게. 지금은 바빠서.","e":"'si no te importa'는 '괜찮다면, 네가 상관없다면'이라는 관용 표현입니다. si 조건절에는 직설법 현재를 쓰며, 주어는 '내가 나중에 전화하는 것'이므로 3인칭 단수 importa가 됩니다. te는 '너에게'입니다.","x":["importe: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","importa: 직설법 현재 3인칭 단수 → 정답 ✓","importara: 접속법 과거로 비현실 가정이 되어 상황에 맞지 않습니다 ✗","importas: 2인칭(네가 중요하다)이라 주어가 맞지 않습니다 ✗"]},{"id":"G495","q":"Eres igual ____ tu padre, siempre estás en tu mundo.","o":["que","como","por","de"],"a":0,"k":"igual que","t":"너는 네 아버지랑 똑같아, 늘 네 세계에 빠져 있지.","e":"'igual que + 명사'는 '~와 똑같은'이라는 뜻입니다. 'igual de + 형용사'는 '똑같이 ~한'이고, 여기처럼 명사(tu padre)와 직접 비교할 때는 que를 씁니다. 'estar en su mundo'는 '자기만의 세계에 빠져 있다'는 표현입니다.","x":["que: 'igual que(~와 똑같이)' → 정답 ✓","como: 'igual como'는 표준적인 표현이 아닙니다(일부 구어에만 나타남) ✗","por: igual과 결합해 비교를 만들지 못합니다 ✗","de: 'igual de'는 뒤에 형용사가 와야 합니다 ✗"]},{"id":"G496","q":"____ en ir a la playa el sábado, pero al final fuimos al centro comercial.","o":["Habríamos pensado","Hemos pensado","Pensaríamos","Habíamos pensado"],"a":3,"k":"과거완료","t":"우리는 토요일에 해변에 가려고 생각했었는데, 결국 쇼핑몰에 갔다.","e":"과거의 어떤 일(쇼핑몰에 감)보다 더 먼저 있었던 일(해변에 갈 계획)을 말할 때는 과거완료(había + 과거분사)를 씁니다. 'pensar en + 동사원형'은 '~할 생각을 하다'입니다. 'pero al final(하지만 결국)'과 함께 계획이 바뀌었음을 보여 줍니다.","x":["Habríamos pensado: 조건법 완료(생각했을 텐데)로 실제 있었던 계획에 맞지 않습니다 ✗","Hemos pensado: 현재완료로 과거 사건보다 앞선 시점을 나타내지 못합니다 ✗","Pensaríamos: 조건법이라 실제 일어난 일에 맞지 않습니다 ✗","Habíamos pensado: 직설법 과거완료 → 정답 ✓"]},{"id":"G497","q":"Imagino que los chicos ya ____ de la fiesta.","o":["estén volviendo","volviesen","vayan a volver","habrán vuelto"],"a":3,"k":"미래완료(추측)","t":"애들은 이미 파티에서 돌아왔을 것 같아.","e":"미래완료(habrá + 과거분사)는 미래뿐 아니라 '지금쯤 ~했을 것이다'라는 과거 일에 대한 추측도 나타냅니다. 'Imagino que(~라고 짐작한다)'는 직설법을 쓰므로 habrán vuelto가 자연스럽습니다.","x":["estén volviendo: 접속법이라 imagino que 뒤에 쓰지 않습니다 ✗","volviesen: 접속법 과거로 맞지 않습니다 ✗","vayan a volver: 접속법이고, ya(이미)와 미래 의미가 충돌합니다 ✗","habrán vuelto: 미래완료(돌아왔을 것이다, 추측) → 정답 ✓"]},{"id":"G498","q":"Esperaremos ____ estéis preparados.","o":["desde que","por que","hasta","hasta que"],"a":3,"k":"hasta que+접속법","t":"너희가 준비될 때까지 기다릴게.","e":"'hasta que(~할 때까지)'는 뒤에 절(주어+동사)이 올 때 쓰며, 아직 일어나지 않은 미래의 일이면 접속법을 씁니다. 'estéis preparados'는 접속법 현재입니다. hasta만 쓰면 뒤에 명사나 동사원형이 와야 합니다(hasta mañana).","x":["desde que: '~한 이후로'로 의미가 맞지 않습니다 ✗","por que: 'por + que'는 '~하는 이유'라는 뜻이라 맞지 않습니다 ✗","hasta: 뒤에 활용된 동사 절이 오려면 que가 필요합니다 ✗","hasta que: '~할 때까지' + 접속법 → 정답 ✓"]},{"id":"G499","q":"Estoy enferma, ____ no estoy yendo a clase.","o":["como","entonces","por eso","de ahí que"],"a":2,"k":"결과 표현 por eso","t":"나 아파서 그래서 학교에 안 가고 있어.","e":"앞 문장(아프다)이 원인, 뒤 문장(학교에 안 감)이 결과이므로 '그래서, 그 때문에'라는 por eso를 씁니다. 'de ahí que'도 결과를 나타내지만 뒤에 접속법을 써야 하므로 직설법 no estoy와 맞지 않습니다.","x":["como: 이유를 나타낼 때 문장 맨 앞에 와야 합니다 ✗","entonces: '그러면'이라는 뜻으로 쓰일 수 있으나 교재 정답은 결과를 명확히 하는 por eso입니다 ✗","por eso: '그 때문에' + 직설법 → 정답 ✓","de ahí que: 결과를 나타내지만 뒤에 접속법이 와야 합니다 ✗"]},{"id":"G500","q":"¿Cuándo ____ a este apartamento?","o":["te mudases","estuviste mudando","te estabas mudando","te mudaste"],"a":3,"k":"단순과거","t":"너 이 아파트로 언제 이사했어?","e":"'언제 ~했니?'처럼 과거의 특정 시점에 끝난 행동을 묻는 질문에는 단순과거를 씁니다. mudarse(이사하다)는 재귀동사이므로 te mudaste가 됩니다.","x":["te mudases: 접속법 과거로 의문문에 쓰지 않습니다 ✗","estuviste mudando: 재귀대명사도 없고 진행 의미도 맞지 않습니다 ✗","te estabas mudando: '이사하고 있던 중'이라는 진행 의미라 ✗","te mudaste: 단순과거(이사했다) → 정답 ✓"]},{"id":"G501","q":"____ sin azúcar.","o":["Nos hemos quedado","Estamos quedando","Hemos quedado","Quedamos"],"a":0,"k":"quedarse sin","t":"우리 설탕이 다 떨어졌어.","e":"'quedarse sin + 명사'는 '~이 떨어지다, ~이 없게 되다'라는 뜻입니다. 방금 다 써서 지금 없는 상태이므로 현재완료 nos hemos quedado가 자연스럽습니다. 예: Me he quedado sin batería(배터리가 다 됐어).","x":["Nos hemos quedado: 'quedarse sin(~이 떨어지다)' 현재완료 → 정답 ✓","Estamos quedando: 재귀대명사가 없고 진행형도 어색합니다 ✗","Hemos quedado: 재귀가 아닌 quedar는 '약속하다'라는 뜻이라 ✗","Quedamos: '우리 만나자/약속하자'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G502","q":"____ era festivo, casi todas las tiendas estaban cerradas.","o":["Que","Pues","Como","Ya que"],"a":2,"k":"이유 como","t":"공휴일이었기 때문에 거의 모든 가게가 문을 닫았다.","e":"como가 문장 맨 앞에서 '~이므로, ~이기 때문에'라는 이유를 나타냅니다. 이유절이 주절보다 앞에 올 때 자주 씁니다. 'Ya que'도 앞에 올 수 있지만, 듣는 이도 아는 전제를 말할 때 주로 쓰여 교재 정답은 como입니다.","x":["Que: 문두에서 이유를 나타내지 않습니다 ✗","Pues: 이유를 나타낼 때 문장 맨 앞에 오지 않습니다 ✗","Como: 문두의 이유 접속사(~이므로) → 정답 ✓","Ya que: 문법적으로는 가능하지만 일반 사실의 원인에는 como가 더 자연스럽습니다 ✗"]},{"id":"G503","q":"José Antonio ____ parece preocupado, ¿qué le pasará?","o":["le","se","ø","lo"],"a":2,"k":"parecer 용법","t":"호세 안토니오가 걱정스러워 보이는데, 무슨 일이 있는 걸까?","e":"'parecer + 형용사'는 '~해 보이다'라는 뜻으로 대명사가 필요 없습니다. 'le parece'라고 하면 '그에게 ~처럼 여겨진다'는 다른 의미가 되고, 'se parece'는 '닮다'입니다. 'qué le pasará'의 미래형은 현재에 대한 추측(무슨 일일까)입니다.","x":["le: 'le parece'는 '그에게는 ~로 생각된다'가 되어 의미가 맞지 않습니다 ✗","se: 'parecerse'는 '닮다'라서 맞지 않습니다 ✗","ø: 'parecer + 형용사(~해 보이다)' → 정답 ✓","lo: 직접목적격은 parecer와 이 의미로 쓰지 않습니다 ✗"]},{"id":"G504","q":"¿____ cuándo te encuentras mal?","o":["Desde","Hasta","Para","De"],"a":0,"k":"desde cuándo","t":"언제부터 몸이 안 좋아?","e":"'¿Desde cuándo ~?'는 '언제부터 ~?'라는 뜻으로, 어떤 상태가 시작된 시점을 묻습니다. 현재까지 계속되는 상태(몸이 안 좋음)이므로 현재형 te encuentras와 함께 씁니다. 'encontrarse mal'은 '몸이 안 좋다'입니다.","x":["Desde: '언제부터' → 정답 ✓","Hasta: '언제까지'라서 지금 아픈 상황과 맞지 않습니다 ✗","Para: '언제까지(기한)'라는 뜻이라 맞지 않습니다 ✗","De: 'de cuándo'는 '언제 적의/언제의 것'이라는 뜻이라 ✗"]},{"id":"G505","q":"No quiero hablar ____ todos, me da vergüenza.","o":["por delante de","delante","delante a","delante de"],"a":3,"k":"delante de","t":"모두 앞에서 말하고 싶지 않아, 창피해.","e":"'delante de + 명사/대명사'는 '~ 앞에서'라는 뜻입니다. delante는 부사라서 뒤에 대상을 붙일 때 전치사 de가 꼭 필요합니다. 'me da vergüenza'는 '창피하다, 부끄럽다'라는 표현입니다.","x":["por delante de: '~ 앞쪽을 지나'라는 이동 의미라 맞지 않습니다 ✗","delante: 뒤에 대상(todos)을 연결하려면 de가 필요합니다 ✗","delante a: 'delante a'는 표준어에서 틀린 형태입니다 ✗","delante de: '~ 앞에서' → 정답 ✓"]},{"id":"G506","q":"Si ____ más, habría aprobado el examen.","o":["hubiera estudiado","haya estudiado","estudiaría","estudiaba"],"a":0,"k":"과거 비현실 가정","t":"공부를 더 했더라면 시험에 합격했을 텐데.","e":"결과절이 조건법 완료(habría aprobado, 합격했을 텐데)이므로, 조건절에는 과거 사실의 반대를 나타내는 접속법 과거완료 hubiera estudiado가 필요합니다. 실제로는 공부를 많이 안 해서 떨어졌다는 의미입니다.","x":["hubiera estudiado: 접속법 과거완료 → 정답 ✓","haya estudiado: 접속법 현재완료는 si 조건절에 쓰지 않습니다 ✗","estudiaría: 조건법은 si 바로 뒤에 쓰지 않습니다 ✗","estudiaba: 직설법 불완료과거로 과거 비현실 가정이 되지 않습니다 ✗"]},{"id":"G507","q":"____ que esté arrepentido, no lo voy a perdonar.","o":["Incluso si","Por mucho","Aun cuando","Puesto que"],"a":1,"k":"양보 por mucho que","t":"그가 아무리 뉘우치고 있어도 나는 그를 용서하지 않을 거야.","e":"'Por mucho que + 접속법'은 '아무리 ~해도'라는 양보 표현입니다. 빈칸 뒤에 que가 있어 이와 결합하는 표현을 골라야 합니다. 예: Por mucho que llores, no cambiará nada(아무리 울어도 아무것도 바뀌지 않을 거야).","x":["Incluso si: '~할지라도'지만 뒤에 que가 오지 않고 'incluso si que'는 틀린 형태입니다 ✗","Por mucho: 'por mucho que(아무리 ~해도)' → 정답 ✓","Aun cuando: 그 자체로 접속사라 뒤에 que를 또 붙이지 않습니다 ✗","Puesto que: '~이므로'라는 이유 표현이라 의미가 반대입니다 ✗"]},{"id":"G508","q":"El verano pasado no fue ni la mitad ____ interesante que el anterior.","o":["de","que","tan","como"],"a":0,"k":"ni la mitad de","t":"지난여름은 그 전 여름의 절반만큼도 재미있지 않았다.","e":"'ni la mitad de + 형용사 + que'는 '~의 절반만큼도 ~하지 않다'라는 강조 비교입니다. mitad 뒤에 형용사를 이을 때는 de를 씁니다. 비교 대상(el anterior, 그 전 것) 앞에는 que가 이미 있습니다.","x":["de: 'ni la mitad de interesante' → 정답 ✓","que: que는 이미 비교 대상 앞에 있어 이 자리에 쓰지 않습니다 ✗","tan: 'tan ~ como' 동등 비교용이라 mitad와 결합하지 않습니다 ✗","como: 'tan ~ como'의 짝이라 이 구조에 맞지 않습니다 ✗"]},{"id":"G509","q":"Mi hijo ha llegado después de la medianoche, ____ le pedí que volviera antes.","o":["ya que","porque","debido a que","y eso que"],"a":3,"k":"y eso que(~인데도)","t":"내가 더 일찍 들어오라고 했는데도 우리 아들은 자정이 넘어서 들어왔다.","e":"'y eso que + 직설법'은 '~했는데도, ~인데도 불구하고'라는 양보를 문장 뒤쪽에 덧붙이는 회화 표현입니다. 일찍 오라고 부탁했음에도 늦게 왔다는 불만을 나타냅니다. 'volviera'는 pedir que 뒤의 접속법 과거입니다.","x":["ya que: '~이니까'라는 이유로 의미가 맞지 않습니다 ✗","porque: '왜냐하면'이라 이유가 되어 의미가 맞지 않습니다 ✗","debido a que: '~때문에'로 원인을 나타내 맞지 않습니다 ✗","y eso que: '~인데도(양보)' → 정답 ✓"]},{"id":"G510","q":"Ayer vimos a David con un compañero ____.","o":["el suyo","suyo","su","sus"],"a":1,"k":"소유사 강세형","t":"어제 우리는 다비드가 자기 동료 한 명과 있는 걸 봤다.","e":"소유사 강세형(mío, tuyo, suyo 등)은 명사 뒤에 와서 '~의 (여럿 중 하나)'라는 뜻을 나타냅니다. 'un compañero suyo'는 '그의 동료 중 한 명'입니다. 명사 앞에 쓰는 단축형 su는 부정관사 un과 함께 쓸 수 없습니다.","x":["el suyo: 명사 없이 대명사로 쓰는 형태라 명사 뒤에 붙지 않습니다 ✗","suyo: 명사 뒤에 오는 소유사 강세형 → 정답 ✓","su: 명사 앞에만 오는 형태입니다 ✗","sus: 복수 단축형이고 위치도 맞지 않습니다 ✗"]},{"id":"G511","q":"Se fueron cuando ____ Eloy.","o":["llegó","llegase","llegaría","llegue"],"a":0,"k":"cuando+직설법(과거)","t":"그들은 엘로이가 도착했을 때 떠났다.","e":"cuando 뒤에 미래 일이 오면 접속법을 쓰지만, 과거에 실제로 일어난 일이면 직설법을 씁니다. 엘로이가 도착한 것은 이미 일어난 과거 사건이므로 단순과거 llegó가 맞습니다.","x":["llegó: 과거 사실, 직설법 단순과거 → 정답 ✓","llegase: 접속법 과거는 과거 시점에서 본 미래일 때 쓰므로 여기선 맞지 않습니다 ✗","llegaría: 조건법은 cuando 뒤에 쓰지 않습니다 ✗","llegue: 접속법 현재는 미래 일에 쓰며 과거 주절(se fueron)과 맞지 않습니다 ✗"]},{"id":"G512","q":"Para que no se quejen, he comprado un juguete para ____.","o":["cada","cada uno","ninguno","alguno"],"a":1,"k":"부정대명사 cada uno","t":"불평하지 않도록 아이들 한 명 한 명에게 장난감을 하나씩 샀다.","e":"cada(각각의)는 형용사라서 반드시 뒤에 명사가 와야 합니다(cada niño). 명사 없이 '각자, 한 사람마다'라고 할 때는 대명사 cada uno를 씁니다. 전치사 para 뒤에 명사가 없으므로 cada uno가 정답입니다.","x":["cada: 뒤에 명사가 필요한 형용사라 단독으로 쓸 수 없습니다 ✗","cada uno: '각자에게' → 정답 ✓","ninguno: '아무도 ~않다'라서 의미가 반대입니다 ✗","alguno: '누군가 하나'라서 모두에게 사 주는 의미가 되지 않습니다 ✗"]},{"id":"G513","q":"¡____ bien que vivamos tan cerca de la escuela!","o":["Cómo","Qué","Cuánto","Cuál"],"a":1,"k":"감탄문 qué","t":"우리가 학교에서 이렇게 가까이 살다니 정말 좋다!","e":"'¡Qué + 형용사/부사 + que + 접속법!'은 '~하다니 정말 ~하다!'라는 감탄 표현입니다. 'Qué bien que'는 '~라니 정말 잘됐다'라는 뜻이고 감정 표현이므로 뒤에 접속법 vivamos가 옵니다.","x":["Cómo: '¡Cómo + 동사!'(얼마나 ~하는지!) 형태로 쓰며 bien 앞에 오지 않습니다 ✗","Qué: '¡Qué bien que ~!' → 정답 ✓","Cuánto: 양이나 정도를 강조할 때 동사나 명사와 씁니다 ✗","Cuál: 감탄문에 쓰지 않는 의문사입니다 ✗"]},{"id":"G514","q":"Ahora soy más abierta, pero antes ____ una persona muy reservada.","o":["era","estaba siendo","he sido","fui"],"a":0,"k":"불완료과거(묘사)","t":"지금은 더 개방적이지만, 예전에 나는 아주 내성적인 사람이었다.","e":"'antes(예전에)'처럼 과거의 일정 기간 동안 지속된 성격이나 상태를 묘사할 때는 불완료과거를 씁니다. 그래서 ser의 불완료과거 era가 자연스럽습니다. 'abierta(개방적인)'와 'reservada(내성적인)'가 대조됩니다.","x":["era: 불완료과거(~였다, 과거 상태 묘사) → 정답 ✓","estaba siendo: '~하게 굴고 있었다'라는 일시적 진행이라 성격 묘사에 맞지 않습니다 ✗","he sido: 현재완료로 '지금까지 ~였다'가 되어 antes와 어울리지 않습니다 ✗","fui: 단순과거로 기간이 명확히 끝난 경우에 쓰며 배경 묘사에 맞지 않습니다 ✗"]},{"id":"G515","q":"____ vas a la papelería, compra un par de bolígrafos azules, por favor.","o":["Ya que","Pues","Como que","Porque"],"a":0,"k":"이유 ya que","t":"어차피 문구점에 가는 거라면 파란 볼펜 두 자루만 사다 줘.","e":"'Ya que'는 '~이니까, 어차피 ~하는 김에'라는 뜻으로, 듣는 사람도 아는 사실을 이유로 들 때 씁니다. 문장 맨 앞에도 올 수 있습니다. 'un par de'는 '두어 개, 두 개'라는 뜻입니다.","x":["Ya que: '~하는 김에, ~이니까' → 정답 ✓","Pues: 이유를 나타낼 때 문장 맨 앞에 오지 않습니다 ✗","Como que: '마치 ~인 듯'이라는 구어 표현이라 의미가 맞지 않습니다 ✗","Porque: 문장 맨 앞에서 이유절로 쓰기 어렵고 보통 주절 뒤에 옵니다 ✗"]},{"id":"G516","q":"Te recomiendo que ____ este curso intensivo de español.","o":["hagas","hicieras","harías","haces"],"a":0,"k":"권유 동사+접속법","t":"이 스페인어 집중 과정을 들어 보라고 추천해.","e":"recomendar(추천하다)처럼 상대에게 무언가를 하라고 권하는 동사 뒤 que절에는 접속법을 씁니다. 주절이 현재형(recomiendo)이므로 접속법 현재 hagas가 맞습니다. hacer un curso는 '과정을 수강하다'입니다.","x":["hagas: 접속법 현재 → 정답 ✓","hicieras: 접속법 과거로 주절이 현재일 때는 보통 쓰지 않습니다 ✗","harías: 조건법이라 que 뒤 접속법 자리에 쓰지 않습니다 ✗","haces: 직설법이라 권유 동사 뒤에 맞지 않습니다 ✗"]},{"id":"G517","q":"Me ____ ser cantante, pero mis padres no me lo permitieron.","o":["había gustado","gustaba","habría gustado","ha gustado"],"a":2,"k":"조건법 완료(소망)","t":"나는 가수가 되고 싶었지만 부모님이 허락하지 않으셨다.","e":"'Me habría gustado + 동사원형'은 '~하고 싶었는데(이루지 못했다)'라는 실현되지 않은 과거의 소망을 나타냅니다. 뒤에 'pero mis padres no me lo permitieron'이 있어 이루어지지 않았음을 알 수 있습니다.","x":["había gustado: 과거완료로 아쉬움의 의미가 없습니다 ✗","gustaba: 불완료과거로 과거 취향일 뿐 이루지 못한 소망의 뉘앙스가 약합니다 ✗","habría gustado: 조건법 완료(~하고 싶었는데) → 정답 ✓","ha gustado: 현재완료라 이 문맥에 맞지 않습니다 ✗"]},{"id":"G518","q":"Necesito una niñera que ____ experiencia con bebés.","o":["tenga","tendría","tiene","tengan"],"a":0,"k":"관계절+접속법","t":"아기 돌본 경험이 있는 보모가 필요해요.","e":"아직 찾지 못한, 존재가 확실하지 않은 대상을 꾸미는 관계절에는 접속법을 씁니다. 'una niñera que tenga ~'는 '~을 가진 (그런) 보모'라는 뜻입니다. 주어 niñera가 단수이므로 tenga가 맞습니다.","x":["tenga: 접속법 현재 3인칭 단수 → 정답 ✓","tendría: 조건법이라 이 관계절에 맞지 않습니다 ✗","tiene: 직설법은 이미 아는 특정한 사람일 때 씁니다 ✗","tengan: 복수형이라 단수 niñera와 수가 맞지 않습니다 ✗"]},{"id":"G519","q":"Llegaremos a las 12 del mediodía, ____ salgamos con retraso.","o":["excepto si","siempre que","a no ser que","mientras que"],"a":2,"k":"a no ser que","t":"늦게 출발하지 않는 한, 우리는 정오 12시에 도착할 거야.","e":"'a no ser que + 접속법'은 '~하지 않는 한, ~이 아니라면'이라는 예외 조건을 나타냅니다. 늦게 출발하는 경우만 예외라는 의미입니다. 같은 뜻으로 'a menos que'도 씁니다.","x":["excepto si: '~라면 예외로'라는 뜻이지만 si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","siempre que: 조건 의미일 땐 '~하기만 하면'이라 뜻이 반대가 됩니다 ✗","a no ser que: '~하지 않는 한' + 접속법 → 정답 ✓","mientras que: '반면에'라는 대조 표현이라 맞지 않습니다 ✗"]},{"id":"G520","q":"Si ____ más paciente, no estarías tan estresado todo el rato.","o":["fueras","serías","fuiste","eras"],"a":0,"k":"현재 비현실 가정","t":"네가 좀 더 참을성이 있다면 이렇게 늘 스트레스받지 않을 텐데.","e":"결과절이 조건법(no estarías)이므로, 현재 사실과 반대되는 가정을 나타내는 'si + 접속법 과거'가 필요합니다. ser의 접속법 과거 2인칭 단수는 fueras입니다. 'todo el rato'는 '항상, 내내'입니다.","x":["fueras: 접속법 과거 → 정답 ✓","serías: 조건법은 si 바로 뒤에 쓰지 않습니다 ✗","fuiste: 단순과거로 비현실 가정이 되지 않습니다 ✗","eras: 직설법 불완료과거라 조건법 결과절과 맞지 않습니다 ✗"]},{"id":"G521","q":"¿Cuántos libros ____ hasta ahora?","o":["andas escribiendo","vuelves a escribir","sigues escribiendo","llevas escritos"],"a":3,"k":"llevar+과거분사","t":"지금까지 책을 몇 권 썼어?","e":"'llevar + 과거분사'는 '지금까지 ~해 놓았다'라는 누적된 결과를 나타냅니다. 과거분사는 목적어(libros)에 성·수를 맞춰 escritos가 됩니다. 'hasta ahora(지금까지)'와 잘 어울리는 표현입니다.","x":["andas escribiendo: '이것저것 쓰고 다니다'라는 뜻으로 개수를 묻기 어색합니다 ✗","vuelves a escribir: '다시 쓰다'라는 뜻이라 맞지 않습니다 ✗","sigues escribiendo: '계속 쓰고 있다'로, 지금까지의 개수를 묻는 의미가 아닙니다 ✗","llevas escritos: '지금까지 써 놓은' → 정답 ✓"]},{"id":"G522","q":"____ te llamo, me salta el contestador automático.","o":["Siempre","Nada más","Siempre que","Hasta que"],"a":2,"k":"siempre que(~할 때마다)","t":"너한테 전화할 때마다 자동응답기로 넘어가.","e":"'siempre que + 직설법'은 '~할 때마다'라는 반복을 나타냅니다. 반면 'siempre que + 접속법'은 '~하기만 하면(조건)'이라는 다른 뜻이 됩니다. 여기서는 매번 일어나는 습관적 상황이므로 직설법 te llamo와 함께 씁니다.","x":["Siempre: 부사라서 두 절을 연결하지 못합니다 ✗","Nada más: '~하자마자'는 'nada más + 동사원형'으로 써서 형태가 맞지 않습니다 ✗","Siempre que: '~할 때마다' → 정답 ✓","Hasta que: '~할 때까지'라서 의미가 맞지 않습니다 ✗"]},{"id":"G523","q":"Todos quieren participar en el concurso menos ____.","o":["tú","de ti","ti","te"],"a":0,"k":"menos+주격 대명사","t":"너만 빼고 모두 대회에 참가하고 싶어 해.","e":"menos(~을 제외하고), excepto, salvo, entre 같은 말 뒤에는 전치사격(mí, ti)이 아니라 주격 대명사(yo, tú)를 씁니다. 그래서 'menos tú'가 맞습니다. 예: Todos lo saben menos yo(나 빼고 다 알아).","x":["tú: menos 뒤에는 주격 대명사 → 정답 ✓","de ti: menos 뒤에 de를 쓰지 않습니다 ✗","ti: 전치사격 대명사인데 menos 뒤에는 쓰지 않습니다 ✗","te: 목적격 대명사로 동사에 붙여 쓰는 형태입니다 ✗"]},{"id":"G524","q":"Estábamos a punto de cenar cuando ____ el timbre.","o":["escuchábamos","habíamos escuchado","escuchamos","estábamos escuchando"],"a":2,"k":"단순과거 vs 불완료","t":"우리가 막 저녁을 먹으려는 참에 초인종 소리를 들었다.","e":"'estábamos a punto de cenar(막 저녁 먹으려던 참이었다)'는 배경(불완료과거)이고, 그 사이에 갑자기 일어난 사건(초인종 소리)은 단순과거로 씁니다. 배경 + cuando + 단순과거는 아주 흔한 구조입니다.","x":["escuchábamos: 불완료과거라 갑자기 끼어든 사건을 나타내지 못합니다 ✗","habíamos escuchado: 과거완료로 배경보다 앞선 일이 되어 맞지 않습니다 ✗","escuchamos: 단순과거(들었다) → 정답 ✓","estábamos escuchando: 진행형 배경 묘사라 사건을 나타내지 못합니다 ✗"]},{"id":"G525","q":"¿Sabes que los Pérez ____ a otra ciudad?","o":["han mudado","fueron mudados","se han mudado","han sido mudados"],"a":2,"k":"재귀동사 mudarse","t":"페레스 가족이 다른 도시로 이사했다는 거 알아?","e":"'이사하다'는 재귀동사 mudarse를 씁니다. 재귀대명사 se가 반드시 필요하므로 'se han mudado'가 됩니다. 'los Pérez'는 '페레스네 가족'이라는 뜻이며, 성(姓)은 복수에서도 형태가 변하지 않습니다.","x":["han mudado: 재귀대명사가 없어 '~을 옮겼다'는 타동사가 되어 맞지 않습니다 ✗","fueron mudados: 수동태(옮겨졌다)로 의미가 어색합니다 ✗","se han mudado: 재귀동사 현재완료(이사했다) → 정답 ✓","han sido mudados: 수동태라 스스로 이사한 의미가 되지 않습니다 ✗"]},{"id":"G526","q":"Espero que te ____ muy bien la entrevista de trabajo.","o":["saldrá","saliera","salga","sale"],"a":2,"k":"esperar que+접속법","t":"취업 면접이 잘되길 바랄게.","e":"'Espero que(~하길 바란다)'처럼 바람을 나타내는 동사 뒤에는 접속법을 씁니다. 'salir bien(잘되다)'의 접속법 현재 3인칭 단수 salga가 맞습니다. te는 '너에게(잘되다)'라는 간접목적격입니다.","x":["saldrá: 직설법 미래라 바람 표현 뒤에 쓰지 않습니다 ✗","saliera: 접속법 과거로 주절이 현재(espero)일 때 미래 바람에는 맞지 않습니다 ✗","salga: 접속법 현재 → 정답 ✓","sale: 직설법 현재라 맞지 않습니다 ✗"]},{"id":"G527","q":"Este no es mi libro, ____ está ahí.","o":["el mío","mi","lo mío","mío"],"a":0,"k":"소유대명사","t":"이건 내 책이 아니야, 내 것은 저기 있어.","e":"명사(libro)를 반복하지 않고 '내 것'이라고 할 때는 '정관사 + 소유사 강세형'인 소유대명사를 씁니다. libro가 남성 단수이므로 el mío가 됩니다. 예: Tu coche es rojo y el mío es azul(네 차는 빨간색이고 내 건 파란색이야).","x":["el mío: 소유대명사(내 것) → 정답 ✓","mi: 명사 앞에 오는 단축형이라 단독으로 못 씁니다 ✗","lo mío: '내 일, 내 몫'이라는 추상적 의미라 구체적인 책을 가리키지 않습니다 ✗","mío: 관사 없이는 주어가 될 수 없습니다 ✗"]},{"id":"G528","q":"Como ____ mintiendo, nadie te va a creer nunca más.","o":["sigue","seguís","siguieras","sigas"],"a":3,"k":"조건 como+접속법","t":"계속 거짓말하면 이제 아무도 너를 믿지 않을 거야.","e":"como가 문장 앞에서 접속법과 함께 쓰이면 '~하면(경고·위협의 조건)'이라는 뜻이 됩니다. 직설법과 쓰면 '~이니까'라는 이유가 됩니다. 2인칭 단수 tú에게 하는 말이므로 sigas가 맞습니다.","x":["sigue: 3인칭 직설법이라 조건 의미도, 인칭도 맞지 않습니다 ✗","seguís: vosotros 직설법이라 이유 의미가 되고 te(너)와도 맞지 않습니다 ✗","siguieras: 접속법 과거로 현재·미래 경고에 맞지 않습니다 ✗","sigas: 'como + 접속법(~하면)' → 정답 ✓"]},{"id":"G529","q":"Seguimos ____ a este restaurante porque nos encanta la comida que hacen.","o":["viniendo","venimos","a venir","venir"],"a":0,"k":"seguir+현재분사","t":"우리는 이 식당 음식을 정말 좋아해서 계속 이곳에 온다.","e":"'seguir + 현재분사(-ndo)'는 '계속 ~하다'라는 뜻입니다. 현재분사는 venir의 경우 viniendo입니다. 예: Sigue lloviendo(계속 비가 온다).","x":["viniendo: 'seguir + 현재분사' → 정답 ✓","venimos: 활용된 동사를 seguir 뒤에 또 쓸 수 없습니다 ✗","a venir: 'seguir a'는 이 의미로 쓰지 않습니다 ✗","venir: seguir 뒤에 동사원형은 쓰지 않습니다 ✗"]},{"id":"G530","q":"Dinos ____ te niegas a hacer lo que te pedimos.","o":["porqué","porque","por que","por qué"],"a":3,"k":"por qué/porque 구별","t":"우리가 부탁한 걸 왜 거부하는지 말해 줘.","e":"'왜'를 묻는 간접의문문에는 두 단어로 띄우고 악센트를 찍은 por qué를 씁니다. porque는 '왜냐하면', porqué는 '이유'라는 명사(el porqué), por que는 '전치사+관계사'입니다. negarse a는 '~하기를 거부하다'입니다.","x":["porqué: '이유'라는 명사로 관사와 함께 씁니다 ✗","porque: '왜냐하면'이라는 이유 접속사라 ✗","por que: 전치사 por + 관계사 que로 의문의 뜻이 없습니다 ✗","por qué: 간접의문문의 '왜' → 정답 ✓"]},{"id":"G531","q":"Siempre que me ____ mi tía, me trae unos dulces buenísimos.","o":["visitará","visitaría","visita","visite"],"a":2,"k":"siempre que+직설법","t":"우리 이모는 나를 방문할 때마다 아주 맛있는 과자를 가져온다.","e":"'siempre que + 직설법'은 '~할 때마다'라는 반복·습관을 나타냅니다. 주절도 현재형 습관(me trae)이므로 직설법 현재 visita를 씁니다. 접속법을 쓰면 '~하기만 하면'이라는 조건 의미가 됩니다.","x":["visitará: 미래형은 siempre que 뒤에 쓰지 않습니다 ✗","visitaría: 조건법이라 습관 표현과 맞지 않습니다 ✗","visita: 직설법 현재(~할 때마다) → 정답 ✓","visite: 접속법이면 조건 의미가 되어 습관 문맥과 맞지 않습니다 ✗"]},{"id":"G532","q":"Podemos ir ____ queráis.","o":["adónde","en donde","adonde","dónde"],"a":2,"k":"관계부사 adonde","t":"너희가 원하는 곳으로 가면 돼.","e":"ir(가다)처럼 이동을 나타내는 동사와 함께 '~하는 곳으로'라고 할 때는 관계부사 adonde(또는 a donde)를 씁니다. 의문문이 아니므로 악센트가 없습니다. queráis는 '원하는'의 접속법(정해지지 않은 장소)입니다.","x":["adónde: 악센트가 있는 의문사(어디로)라 관계사 자리에 맞지 않습니다 ✗","en donde: '~에서'라는 위치라 이동 동사 ir와 맞지 않습니다 ✗","adonde: 방향의 관계부사(~하는 곳으로) → 정답 ✓","dónde: 의문사이고 방향 a도 빠져 있습니다 ✗"]},{"id":"G533","q":"Para ____ el trabajo a tiempo necesitamos ser más rápidos.","o":["que terminaremos","que terminamos","terminemos","terminar"],"a":3,"k":"para+동사원형","t":"제시간에 일을 끝내려면 우리가 더 빨라야 한다.","e":"목적(~하기 위해)을 나타낼 때 주절과 목적절의 주어가 같으면 'para + 동사원형'을 씁니다. 여기서 끝내는 사람도, 빨라야 하는 사람도 '우리'이므로 para terminar가 맞습니다. 주어가 다르면 'para que + 접속법'을 씁니다.","x":["que terminaremos: para que 뒤에는 미래 직설법을 쓰지 않습니다 ✗","que terminamos: para que 뒤에는 직설법을 쓰지 않습니다 ✗","terminemos: para 바로 뒤에 활용된 동사를 쓸 수 없습니다 ✗","terminar: 주어가 같을 때 'para + 동사원형' → 정답 ✓"]},{"id":"G534","q":"No ____ luchar por lo que quieres.","o":["acabes de","dejes de","vuelvas a","acabes por"],"a":1,"k":"dejar de+동사원형","t":"네가 원하는 것을 위해 싸우는 걸 멈추지 마.","e":"'dejar de + 동사원형'은 '~하기를 그만두다'라는 뜻입니다. 부정 명령 'No dejes de ~'는 '꼭 ~해, ~하는 걸 멈추지 마'라는 격려가 됩니다. 예: No dejes de visitarnos(꼭 우리 집에 들러).","x":["acabes de: 'acabar de'는 '방금 ~했다'라서 의미가 맞지 않습니다 ✗","dejes de: '~하기를 그만두다' → 정답 ✓","vuelvas a: '다시 ~하지 마'가 되어 의미가 반대입니다 ✗","acabes por: '결국 ~하게 되다'라서 문맥에 맞지 않습니다 ✗"]},{"id":"G535","q":"Hoy no me apetece ____ ir al colegio, pero no puedo faltar.","o":["por","ø","de","a"],"a":1,"k":"apetecer+동사원형","t":"오늘은 학교에 가고 싶지 않지만, 빠질 수는 없어.","e":"apetecer(~하고 싶다, 당기다)는 gustar처럼 쓰는 동사로, 하고 싶은 일이 주어가 되어 동사원형이 바로 뒤에 옵니다. 따라서 전치사 없이 'me apetece ir'라고 합니다. apetecer는 주로 스페인에서 쓰고, 중남미에서는 'tener ganas de'를 더 흔히 씁니다.","x":["por: apetecer 뒤에 전치사를 쓰지 않습니다 ✗","ø: 'apetecer + 동사원형' → 정답 ✓","de: 'tener ganas de'와 혼동한 형태입니다 ✗","a: apetecer와 함께 쓰지 않습니다 ✗"]},{"id":"G536","q":"Gracias por su ayuda, si no me hubiera sujetado, me ____.","o":["había caído","cayera","haya caído","habría caído"],"a":3,"k":"과거 비현실 가정","t":"도와주셔서 감사합니다, 붙잡아 주지 않으셨다면 저는 넘어졌을 거예요.","e":"'si no me hubiera sujetado(붙잡아 주지 않았다면)'는 과거 사실의 반대를 가정합니다. 결과절에는 조건법 완료(habría + 과거분사, ~했을 텐데)를 쓰므로 me habría caído가 맞습니다.","x":["había caído: 직설법 과거완료로 가정의 결과가 되지 않습니다 ✗","cayera: 접속법 과거로 결과절에는 쓰지 않습니다 ✗","haya caído: 접속법 현재완료라 맞지 않습니다 ✗","habría caído: 조건법 완료 → 정답 ✓"]},{"id":"G537","q":"Hoy es ____ viernes, así que saldré un poco antes del trabajo.","o":["ø","un","los","el"],"a":0,"k":"요일 앞 관사 생략","t":"오늘은 금요일이라서 일을 조금 일찍 마치고 나갈 거야.","e":"'Hoy es + 요일(오늘은 ~요일이다)'처럼 요일을 말할 때는 관사를 쓰지 않습니다. 반면 '금요일에'처럼 특정 날을 가리킬 때는 'el viernes'라고 관사를 씁니다. 예: El viernes voy al cine(금요일에 영화 보러 가).","x":["ø: 'Hoy es viernes' 관사 생략 → 정답 ✓","un: '어느 금요일'이 되어 의미가 맞지 않습니다 ✗","los: 복수 관사로 '금요일마다'가 됩니다 ✗","el: '그 금요일에'라는 뜻이 되어 ser 뒤 요일 표현에 맞지 않습니다 ✗"]},{"id":"G538","q":"____ es millonaria, vive en una casa muy simple.","o":["Así que","Como","Ya que","Pese a que"],"a":3,"k":"양보 pese a que","t":"그녀는 백만장자인데도 아주 소박한 집에서 산다.","e":"'pese a que'는 '~임에도 불구하고'라는 양보 표현으로, 'a pesar de que'와 같은 뜻입니다. 백만장자라는 사실과 소박한 집이 서로 반대되는 내용이므로 양보가 알맞습니다. 사실을 말할 때는 직설법(es)을 씁니다.","x":["Así que: '그래서'라는 결과로, 문두에 와서 이유를 나타내지 않습니다 ✗","Como: '~이므로'라는 이유라 의미가 맞지 않습니다 ✗","Ya que: '~이니까'라는 이유라 의미가 반대입니다 ✗","Pese a que: '~임에도 불구하고' → 정답 ✓"]},{"id":"G539","q":"Me maravilla que Alba ____ coreano con tanta fluidez.","o":["hablaba","hable","habla","hablara"],"a":1,"k":"감정 동사+접속법","t":"알바가 한국어를 그렇게 유창하게 하다니 놀라워.","e":"'Me maravilla que(~가 놀랍다, 감탄스럽다)'는 감정을 나타내므로 뒤에 접속법을 씁니다. 주절이 현재(maravilla)이고 지금의 능력을 말하므로 접속법 현재 hable가 맞습니다.","x":["hablaba: 직설법 불완료과거라 감정 표현 뒤에 쓰지 않습니다 ✗","hable: 접속법 현재 → 정답 ✓","habla: 직설법 현재라 맞지 않습니다 ✗","hablara: 접속법 과거로 주절이 현재일 때 지금의 일에는 맞지 않습니다 ✗"]},{"id":"G540","q":"Mi computadora no funciona, ____ no puedo hacer el trabajo todavía.","o":["aunque","así que","a pesar de que","y eso que"],"a":1,"k":"결과 así que","t":"내 컴퓨터가 고장 나서 아직 과제를 할 수가 없어.","e":"앞 문장(컴퓨터 고장)이 원인, 뒤 문장(과제를 못 함)이 결과이므로 '그래서'라는 así que를 씁니다. computadora는 중남미에서 주로 쓰는 말이고, 스페인에서는 ordenador라고 합니다.","x":["aunque: '~이지만'이라는 양보라 맞지 않습니다 ✗","así que: '그래서' → 정답 ✓","a pesar de que: '~에도 불구하고'라 의미가 맞지 않습니다 ✗","y eso que: '~인데도'라는 양보라 맞지 않습니다 ✗"]},{"id":"G541","q":"¿Qué ropa ____ vas a poner el día de la boda de tu hermana?","o":["la","te","ø","te la"],"a":1,"k":"재귀동사 ponerse","t":"네 언니 결혼식 날 무슨 옷을 입을 거야?","e":"'ponerse + 옷'은 '(옷을) 입다'라는 재귀동사입니다. 주어가 tú이므로 재귀대명사 te를 씁니다. 목적어 qué ropa가 이미 문장 앞에 있으므로 la를 또 넣지 않습니다.","x":["la: 재귀대명사 te가 빠져 '입다'의 의미가 되지 않습니다 ✗","te: 'ponerse(입다)'의 재귀대명사 → 정답 ✓","ø: 대명사가 없으면 '(무언가를) 놓다'가 되어 맞지 않습니다 ✗","te la: qué ropa가 이미 목적어라 la를 중복해 쓰지 않습니다 ✗"]},{"id":"G542","q":"De todo ____ que hemos dicho, ¿qué os parece lo más importante?","o":["lo","ø","los","el"],"a":0,"k":"중성 lo que","t":"우리가 말한 것 전부 중에서 너희는 무엇이 가장 중요하다고 생각해?","e":"'lo que'는 '~하는 것'이라는 뜻으로, 구체적인 명사 없이 내용 전체를 가리킵니다. 'todo lo que'는 '~한 모든 것'입니다. 예: Haz todo lo que puedas(할 수 있는 건 다 해).","x":["lo: 'todo lo que(~한 모든 것)' → 정답 ✓","ø: 'todo que'는 틀린 형태입니다 ✗","los: 남성 복수 명사를 가리킬 때만 쓰는데 여기엔 그런 명사가 없습니다 ✗","el: 남성 단수 명사를 받을 때 쓰며 추상적 내용 전체를 가리키지 않습니다 ✗"]},{"id":"G543","q":"____ a estudiar ahora mismo.","o":["Voy a poner me","Voy a poner","Voy ponerme","Voy a ponerme"],"a":3,"k":"ir a+재귀동사","t":"나 지금 당장 공부를 시작할 거야.","e":"'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래입니다. 'ponerse a + 동사원형'은 '~하기 시작하다'이며, 재귀대명사는 동사원형 끝에 붙여 ponerme라고 씁니다(또는 'Me voy a poner'). 이 두 표현을 합친 Voy a ponerme가 정답입니다.","x":["Voy a poner me: 재귀대명사를 동사원형과 띄어 쓰지 않습니다 ✗","Voy a poner: 재귀대명사 me가 빠져 '시작하다' 의미가 되지 않습니다 ✗","Voy ponerme: 'ir a'의 전치사 a가 빠졌습니다 ✗","Voy a ponerme: 'ir a + ponerse a' → 정답 ✓"]},{"id":"G544","q":"No está de humor, ____ no le habléis todavía.","o":["por que","de modo que","ya que","para que"],"a":1,"k":"결과 de modo que","t":"그는 기분이 안 좋으니까 아직 그에게 말 걸지 마.","e":"'de modo que'는 '그러니까, 그러므로'라는 결과·결론 표현입니다. 앞의 사실(기분이 안 좋다)에서 결론(말 걸지 마)을 이끌어 냅니다. 뒤에 명령문이 올 수 있습니다. 'estar de humor'는 '기분이 좋다'입니다.","x":["por que: 전치사+관계사로 이 문맥에서 결과를 나타내지 못합니다 ✗","de modo que: '그러니까' → 정답 ✓","ya que: '~이니까'로 뒤에 이유가 와야 해서 순서가 맞지 않습니다 ✗","para que: '~하도록'이라는 목적이라 뒤에 명령문이 올 수 없습니다 ✗"]},{"id":"G545","q":"Todavía no ____ el informe que me pidieron.","o":["he terminado","terminaba","he estado terminando","estuve terminando"],"a":0,"k":"현재완료+todavía no","t":"그들이 부탁한 보고서를 나는 아직 끝내지 못했다.","e":"'todavía no(아직 ~않다)'는 지금까지 완료되지 않은 일을 나타내므로 현재완료(he + 과거분사)와 잘 어울립니다. 중남미에서는 'Todavía no terminé'처럼 단순과거를 쓰는 경우도 많습니다.","x":["he terminado: 현재완료(끝냈다) → 정답 ✓","terminaba: 불완료과거라 현재까지의 미완료를 나타내지 못합니다 ✗","he estado terminando: '끝내는 중이었다'로 어색합니다 ✗","estuve terminando: 과거 진행 기간이라 문맥에 맞지 않습니다 ✗"]},{"id":"G546","q":"Nos vemos mañana a las 9 en punto, ____ surja algún imprevisto.","o":["a no ser que","con tal de que","siempre que","siempre y cuando"],"a":0,"k":"a no ser que","t":"예상치 못한 일이 생기지 않는 한 내일 9시 정각에 보자.","e":"'a no ser que + 접속법'은 '~하지 않는 한'이라는 예외 조건입니다. 돌발 상황이 생기는 경우만 예외라는 뜻입니다. surgir는 '생기다, 발생하다', imprevisto는 '예상치 못한 일'입니다.","x":["a no ser que: '~하지 않는 한' → 정답 ✓","con tal de que: '~하기만 한다면'이라 돌발 상황이 조건이 되어 이상합니다 ✗","siempre que: 조건 의미로 '~한다면'이 되어 뜻이 반대입니다 ✗","siempre y cuando: '~하는 경우에 한해'라 의미가 반대입니다 ✗"]},{"id":"G547","q":"Te ____ de la cancelación del evento, pero yo tampoco lo sabía.","o":["habría avisado","había avisado","avisara","estaría avisando"],"a":0,"k":"조건법 완료","t":"행사 취소를 너에게 알려 줬을 텐데, 나도 몰랐어.","e":"과거에 하지 못한 일(알려 주기)에 대해 '~했을 텐데'라고 말할 때 조건법 완료를 씁니다. 숨은 조건 'si lo hubiera sabido(알았더라면)'가 뒤 문장(yo tampoco lo sabía)에 암시되어 있습니다.","x":["habría avisado: 조건법 완료(알려 줬을 텐데) → 정답 ✓","había avisado: 과거완료로 실제로 알려 줬다는 뜻이 되어 모순입니다 ✗","avisara: 접속법 과거로 주절에 단독으로 쓰지 않습니다 ✗","estaría avisando: 조건법 진행형이라 의미가 맞지 않습니다 ✗"]},{"id":"G548","q":"Temo que, cuando se vaya a vivir fuera, ____ de otra.","o":["se enamora","se enamorase","se enamore","se haya enamorado"],"a":2,"k":"두려움 표현+접속법","t":"그가 다른 곳에 살러 가면 다른 여자와 사랑에 빠질까 봐 두려워.","e":"temer(두려워하다)처럼 감정을 나타내는 동사 뒤 que절에는 접속법을 씁니다. 미래에 일어날까 걱정하는 일이므로 접속법 현재 se enamore가 맞습니다. 'enamorarse de'는 '~와 사랑에 빠지다'입니다.","x":["se enamora: 직설법이라 감정 동사 뒤에 쓰지 않습니다 ✗","se enamorase: 접속법 과거로 현재 주절(temo)과 시제가 맞지 않습니다 ✗","se enamore: 접속법 현재 → 정답 ✓","se haya enamorado: 접속법 현재완료로 이미 일어난 일이 되어 cuando 미래 문맥과 맞지 않습니다 ✗"]},{"id":"G549","q":"Hoy ____ martes, ¿verdad?","o":["es","son","estamos","está"],"a":0,"k":"요일 말하기 ser","t":"오늘 화요일 맞지?","e":"요일이나 날짜를 말할 때는 'Hoy es + 요일'처럼 ser를 씁니다. martes는 단수·복수 형태가 같지만 여기서는 하루이므로 단수 es입니다. 'Estamos a martes'처럼 estar를 쓸 때는 전치사 a가 필요합니다.","x":["es: 'Hoy es martes' → 정답 ✓","son: 복수형으로, 하루를 가리키는 문장에 맞지 않습니다 ✗","estamos: 'estamos a martes'처럼 a가 있어야 합니다 ✗","está: 요일을 말할 때 estar 3인칭 단수를 쓰지 않습니다 ✗"]},{"id":"G550","q":"Mamá te va a regañar si no haces los deberes, ____ empieza a hacerlos ya.","o":["aunque","puesto que","porque","conque"],"a":3,"k":"결과 conque","t":"숙제 안 하면 엄마가 혼낼 거야, 그러니까 당장 시작해.","e":"conque는 '그러니까, 그러므로'라는 결과 접속사로, 앞 내용에서 결론을 끌어낼 때 씁니다. 'con que(~하는 것으로)'와 다른 단어이니 붙여 쓰는 것에 주의하세요. 뒤에 명령문이 자주 옵니다.","x":["aunque: '~이지만'이라는 양보라 맞지 않습니다 ✗","puesto que: '~이므로'로 뒤에 이유가 와야 합니다 ✗","porque: '왜냐하면'이라 뒤에 명령문이 오지 않습니다 ✗","conque: '그러니까' → 정답 ✓"]},{"id":"G551","q":"Los precios de los combustibles están ____ las nubes.","o":["por","para","en","a"],"a":0,"k":"관용 표현 por las nubes","t":"연료 가격이 하늘 높은 줄 모르고 치솟아 있다.","e":"'estar por las nubes'는 '(가격이) 엄청 비싸다, 치솟다'라는 관용 표현입니다. 글자 그대로는 '구름 위에 있다'라는 뜻입니다. 예: La vivienda está por las nubes(집값이 엄청 올랐다).","x":["por: 'estar por las nubes(가격이 치솟다)' → 정답 ✓","para: 목적을 나타내 관용 표현이 되지 않습니다 ✗","en: 'estar en las nubes'는 '멍하니 딴생각하다'라는 다른 뜻입니다 ✗","a: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G552","q":"Les pregunté si ____ lo que había pasado.","o":["supieran","supieron","sabían","sabrían"],"a":2,"k":"간접의문 si+직설법","t":"나는 그들에게 무슨 일이 있었는지 아는지 물었다.","e":"간접의문문을 이끄는 si(~인지)는 조건의 si와 달리 뒤에 직설법을 씁니다. 주절이 과거(pregunté)이므로 시제를 맞춰 불완료과거 sabían을 씁니다. 원래 질문은 '¿Sabéis lo que ha pasado?'였습니다.","x":["supieran: 접속법 과거로 간접의문 si 뒤에 쓰지 않습니다 ✗","supieron: 단순과거로 '알게 되었다'는 뜻이 되어 맞지 않습니다 ✗","sabían: 직설법 불완료과거 → 정답 ✓","sabrían: 조건법으로 질문 내용과 맞지 않습니다 ✗"]},{"id":"G553","q":"Felipe ____ despedido de su trabajo la semana pasada.","o":["estuvo","estaba","fue","ha sido"],"a":2,"k":"수동태 ser+과거분사","t":"펠리페는 지난주에 회사에서 해고되었다.","e":"'해고되다'처럼 행위를 받는 수동태는 'ser + 과거분사'로 만듭니다. 'la semana pasada(지난주)'라는 끝난 과거 시점이 있으므로 단순과거 fue despedido가 맞습니다.","x":["estuvo: 'estar + 과거분사'는 상태를 나타내 해고 행위에 맞지 않습니다 ✗","estaba: 상태 묘사라 해고되는 사건을 나타내지 못합니다 ✗","fue: ser 단순과거 수동태 → 정답 ✓","ha sido: 현재완료로 'la semana pasada'와 어울리지 않습니다(스페인 기준) ✗"]},{"id":"G554","q":"Ni he visto esa película ____ pienso verla.","o":["ni","y no","tampoco","no"],"a":0,"k":"ni... ni","t":"나는 그 영화를 보지도 않았고 볼 생각도 없다.","e":"'ni A ni B'는 'A도 B도 아니다'라는 부정 연결 표현입니다. 앞에 ni가 이미 있으므로 짝을 맞춰 뒤에도 ni를 씁니다. 예: Ni come ni deja comer(자기도 안 먹고 남도 못 먹게 한다).","x":["ni: 'ni... ni...(~도 ~도 아니다)' → 정답 ✓","y no: 앞의 ni와 짝이 맞지 않습니다 ✗","tampoco: '~도 역시 아니다'라는 부사로 ni와 짝을 이루지 않습니다 ✗","no: 앞의 ni와 짝을 이루지 못합니다 ✗"]},{"id":"G555","q":"Javier y yo hemos quedado ____ vernos el sábado a las 2 de la tarde.","o":["por","con","en","a"],"a":2,"k":"quedar en","t":"하비에르와 나는 토요일 오후 2시에 만나기로 했다.","e":"'quedar en + 동사원형'은 '~하기로 약속하다/합의하다'라는 뜻입니다. 반면 'quedar con alguien'은 '~와 만날 약속을 하다'입니다. 여기서는 뒤에 동사원형 vernos가 오므로 en이 맞습니다.","x":["por: quedar와 이 의미로 쓰지 않습니다 ✗","con: 'quedar con + 사람'이라 뒤에 동사원형이 오지 않습니다 ✗","en: 'quedar en + 동사원형(~하기로 하다)' → 정답 ✓","a: 이 구조에 쓰지 않는 전치사입니다 ✗"]},{"id":"G556","q":"Si hubiera sabido que ibas a venir, ____ tu comida preferida.","o":["haya preparado","habría preparado","preparase","había preparado"],"a":1,"k":"과거 비현실 가정","t":"네가 올 줄 알았더라면 네가 제일 좋아하는 음식을 준비했을 텐데.","e":"'Si + 접속법 과거완료(hubiera sabido)'는 과거 사실과 반대되는 가정입니다. 이에 대한 결과는 조건법 완료 habría preparado(준비했을 텐데)로 말합니다. 실제로는 몰라서 준비하지 못했다는 뜻입니다.","x":["haya preparado: 접속법 현재완료라 결과절에 쓰지 않습니다 ✗","habría preparado: 조건법 완료 → 정답 ✓","preparase: 접속법 과거로 결과절에 쓰지 않습니다 ✗","había preparado: 직설법 과거완료로 가정의 결과가 되지 않습니다 ✗"]},{"id":"G557","q":"____ ese tema, lo trataremos en la próxima clase.","o":["Respecto","Con respecto a","De respecto a","Con respecto"],"a":1,"k":"con respecto a","t":"그 주제에 관해서는 다음 수업에서 다루겠습니다.","e":"'con respecto a + 명사'는 '~에 관해서는'이라는 고정 표현입니다. 'respecto a'만 써도 되지만, 보기 중에서 완전한 형태는 con respecto a입니다. 비슷한 표현으로 'en cuanto a', 'en lo que respecta a'가 있습니다.","x":["Respecto: 뒤에 a가 빠져 있어 불완전합니다 ✗","Con respecto a: '~에 관해서는' → 정답 ✓","De respecto a: 이런 형태는 없습니다 ✗","Con respecto: a가 빠져 명사와 연결되지 않습니다 ✗"]},{"id":"G558","q":"Alberto corre más que ____ otro atleta.","o":["ningún","ninguna","ninguno","alguna"],"a":0,"k":"más que ningún otro","t":"알베르토는 다른 어떤 선수보다 더 빨리 달린다.","e":"'más que ningún otro + 명사'는 '다른 어느 ~보다 더'라는 최상급 의미의 강조입니다. 남성 명사 앞에서 ninguno는 -o가 탈락해 ningún이 됩니다. atleta는 남녀 공통이지만 여기서는 otro(남성)와 함께 남성으로 쓰였습니다.","x":["ningún: 남성 단수 명사 앞 단축형 → 정답 ✓","ninguna: 여성형인데 'otro atleta'는 남성이라 ✗","ninguno: 명사 앞에서는 -o가 탈락해야 합니다 ✗","alguna: '어떤'이라는 긍정 의미에 여성형이라 맞지 않습니다 ✗"]},{"id":"G559","q":"¿____ vivís ahora?","o":["Adónde","Donde","Adonde","Dónde"],"a":3,"k":"의문사 dónde","t":"너희 지금 어디 살아?","e":"vivir(살다)는 이동이 아니라 위치를 나타내므로 '어디에서'를 뜻하는 dónde를 씁니다. 의문문이므로 악센트가 필요합니다. adónde(어디로)는 ir 같은 이동 동사와 씁니다.","x":["Adónde: '어디로'라서 이동 동사와 씁니다 ✗","Donde: 악센트가 없는 관계부사로 의문문에 쓰지 않습니다 ✗","Adonde: 관계부사에 방향 의미까지 있어 맞지 않습니다 ✗","Dónde: 위치를 묻는 의문사 → 정답 ✓"]},{"id":"G560","q":"Últimamente todos hablan ____ ese futbolista.","o":["en","de","por","hasta"],"a":1,"k":"hablar de","t":"요즘 모두가 그 축구 선수 얘기를 한다.","e":"'hablar de + 대상'은 '~에 대해 이야기하다'라는 뜻입니다. 'hablar sobre'도 같은 의미로 쓸 수 있습니다. 예: Hablamos de política(우리는 정치 얘기를 했다).","x":["en: 'hablar en + 언어'는 '~어로 말하다'라는 다른 의미입니다 ✗","de: 'hablar de(~에 대해 말하다)' → 정답 ✓","por: 'hablar por'는 '~을 대신해 말하다, ~로 통화하다'라서 맞지 않습니다 ✗","hasta: '~까지'라 의미가 맞지 않습니다 ✗"]},{"id":"G561","q":"Este aparato no sirve ____ nada.","o":["por","para","en","a"],"a":1,"k":"servir para","t":"이 기계는 아무 쓸모가 없다.","e":"'servir para + 명사/동사원형'은 '~에 쓸모가 있다, ~하는 데 쓰이다'라는 뜻입니다. 'no servir para nada'는 '아무 쓸모없다'라는 아주 흔한 표현입니다. 예: ¿Para qué sirve esto?(이건 어디에 쓰는 거야?)","x":["por: 이유를 나타내 servir와 이 의미로 쓰지 않습니다 ✗","para: 'servir para(~에 쓸모 있다)' → 정답 ✓","en: servir와 결합하지 않습니다 ✗","a: 이 의미로는 쓰지 않습니다 ✗"]},{"id":"G562","q":"Rosa y Cecilia son ____ altas.","o":["igual que","igual de","igual","iguales que"],"a":1,"k":"igual de+형용사","t":"로사와 세실리아는 키가 똑같이 크다.","e":"'igual de + 형용사'는 '똑같이 ~하다'라는 동등 비교 표현입니다. 'tan altas como ~'와 비슷한 뜻이지만 비교 대상이 주어에 함께 있을 때 씁니다. 예: Somos igual de inteligentes(우리는 똑같이 똑똑해).","x":["igual que: 뒤에 비교 대상(명사)이 와야 하는데 형용사가 왔습니다 ✗","igual de: '똑같이 ~한' → 정답 ✓","igual: de 없이 형용사 앞에 쓰지 않습니다 ✗","iguales que: 뒤에 비교 대상이 필요한 형태라 맞지 않습니다 ✗"]},{"id":"G563","q":"____ primero que hago al llegar a casa es quitarme los zapatos.","o":["ø","El","Lo","La"],"a":2,"k":"중성관사 lo","t":"집에 도착해서 내가 제일 먼저 하는 일은 신발을 벗는 것이다.","e":"'lo primero que ~'는 '~하는 첫 번째 일'이라는 추상적 표현입니다. 특정 명사를 가리키지 않는 내용이므로 중성관사 lo를 씁니다. 'al llegar'는 '도착하자, 도착할 때'라는 뜻입니다.","x":["ø: 관사가 없으면 주어로 쓸 수 없습니다 ✗","El: 남성 명사가 생략된 경우에만 쓰며 '하는 일'이라는 추상 의미가 되지 않습니다 ✗","Lo: 'lo primero que(제일 먼저 ~하는 것)' → 정답 ✓","La: 여성 명사를 받을 때 쓰는 관사라 맞지 않습니다 ✗"]},{"id":"G564","q":"____ no queríamos comer en ningún sitio, llevamos nuestra propia comida a la excursión.","o":["Como","Que","Por","Al"],"a":0,"k":"이유 como","t":"우리는 아무 데서도 먹고 싶지 않아서 소풍에 우리 음식을 가져갔다.","e":"문장 맨 앞의 como는 '~이므로, ~해서'라는 이유를 나타냅니다. 이유절이 먼저 오고 결과(음식을 가져감)가 뒤에 옵니다. 'en ningún sitio'는 '어디에서도 (~않다)'입니다.","x":["Como: 문두의 이유 접속사 → 정답 ✓","Que: 문두에서 이유를 나타내지 않습니다 ✗","Por: 전치사라 뒤에 활용된 동사 절이 바로 오지 않습니다 ✗","Al: 'al + 동사원형' 형태로 써야 해서 맞지 않습니다 ✗"]},{"id":"G565","q":"¿Ha llamado ____ mientras estaba fuera?","o":["algún","alguien","nadie","algunos"],"a":1,"k":"부정대명사 alguien","t":"내가 밖에 있는 동안 누가 전화했어?","e":"alguien은 '누군가'라는 뜻으로 사람을 가리키는 부정대명사입니다. 긍정 의문문에서 '누가 ~했어?'라고 물을 때 씁니다. nadie는 '아무도 (~않다)'라는 부정 의미라 이 문장과 맞지 않습니다.","x":["algún: 명사 앞에 쓰는 형용사라 단독으로 못 씁니다 ✗","alguien: '누군가' → 정답 ✓","nadie: '아무도'라 부정 의미가 됩니다 ✗","algunos: 복수인데 동사 ha llamado는 단수라 ✗"]},{"id":"G566","q":"Ayer nos dijiste que ____ a la hora acordada, pero no ha sido así.","o":["llegarás","llegases","llegarías","estarás llegando"],"a":2,"k":"간접화법 조건법","t":"어제 너는 약속한 시간에 도착할 거라고 했는데, 그렇지 않았잖아.","e":"과거에 한 말을 전할 때(nos dijiste que), 원래 말의 미래형(llegaré)은 과거에서 본 미래인 조건법(llegarías)으로 바뀝니다. 이를 '시제 일치'라고 합니다.","x":["llegarás: 미래형은 과거 시점의 전달문에서 조건법으로 바꿔야 합니다 ✗","llegases: 접속법 과거로 decir가 '전달'의 의미일 때는 쓰지 않습니다 ✗","llegarías: 과거에서 본 미래, 조건법 → 정답 ✓","estarás llegando: 미래 진행형이라 시제 일치에 맞지 않습니다 ✗"]},{"id":"G567","q":"Su auto ____ para el jueves, podrá pasar a recogerlo a partir de las 8.","o":["está siendo arreglado","será arreglado","estará arreglado","se está arreglando"],"a":2,"k":"estar+과거분사(결과)","t":"고객님 차는 목요일까지 수리되어 있을 테니, 8시부터 찾으러 오시면 됩니다.","e":"'estar + 과거분사'는 행위가 끝난 뒤의 결과 상태(~되어 있다)를 나타냅니다. 'para el jueves(목요일까지)'에는 이미 수리가 끝난 상태일 것이므로 미래형 estará arreglado가 맞습니다. auto는 중남미에서 주로 쓰고 스페인에서는 coche라고 합니다.","x":["está siendo arreglado: '지금 수리되는 중'이라 목요일 기한과 맞지 않습니다 ✗","será arreglado: 행위 수동태로 '목요일에 수리될 것'이 되어 기한 의미와 어울리지 않습니다 ✗","estará arreglado: 결과 상태(수리되어 있을 것) → 정답 ✓","se está arreglando: 현재 진행이라 기한 표현과 맞지 않습니다 ✗"]},{"id":"G568","q":"He tenido ____ problemas como tú para acceder al sistema.","o":["tantos","tanto","tanta","tantas"],"a":0,"k":"tanto 동등비교","t":"나도 시스템에 접속하는 데 너만큼 많은 문제가 있었다.","e":"'tanto/a/os/as + 명사 + como'는 '~만큼 많은 (명사)'라는 동등 비교입니다. tanto는 뒤 명사의 성·수에 맞춰야 합니다. problema는 -a로 끝나지만 남성 명사이므로 남성 복수 tantos가 맞습니다.","x":["tantos: 남성 복수(problemas) → 정답 ✓","tanto: 단수형이라 복수 명사와 맞지 않습니다 ✗","tanta: 여성 단수라 성·수가 모두 맞지 않습니다 ✗","tantas: problema를 여성으로 착각한 형태입니다 ✗"]},{"id":"G569","q":"Les pedí que me ____, pero no lo hicieron.","o":["esperarán","esperaban","esperarían","esperasen"],"a":3,"k":"pedir que+접속법","t":"나는 그들에게 나를 기다려 달라고 부탁했지만 그들은 그러지 않았다.","e":"pedir(부탁하다)처럼 남에게 무언가를 요청하는 동사 뒤 que절에는 접속법을 씁니다. 주절이 과거(pedí)이므로 접속법 과거 esperasen(= esperaran)을 씁니다.","x":["esperarán: 직설법 미래라 요청 동사 뒤에 쓰지 않습니다 ✗","esperaban: 직설법 불완료과거라 맞지 않습니다 ✗","esperarían: 조건법이라 접속법 자리에 쓰지 않습니다 ✗","esperasen: 접속법 과거 → 정답 ✓"]},{"id":"G570","q":"Victoria vino a verme ____ saber lo que me había pasado.","o":["nada más","desde que","en cuanto","tan pronto como"],"a":0,"k":"nada más+동사원형","t":"빅토리아는 나에게 무슨 일이 있었는지 알자마자 나를 보러 왔다.","e":"'nada más + 동사원형'은 '~하자마자'라는 뜻입니다. 뒤에 동사원형(saber)이 오므로 nada más가 맞습니다. en cuanto, tan pronto como도 '~하자마자'이지만 뒤에 활용된 동사(supo)가 와야 합니다.","x":["nada más: 'nada más + 동사원형(~하자마자)' → 정답 ✓","desde que: '~한 이후로'이고 뒤에 활용된 동사가 필요합니다 ✗","en cuanto: 뜻은 비슷하지만 뒤에 동사원형이 아닌 활용 동사가 와야 합니다 ✗","tan pronto como: 역시 뒤에 활용된 동사가 필요합니다 ✗"]},{"id":"G571","q":"Nosotros vivimos ____ cerca del centro que ellos.","o":["tanto","muy","tan","más"],"a":3,"k":"우월 비교 más que","t":"우리는 그들보다 시내 중심에 더 가까이 산다.","e":"뒤에 que(~보다)가 있으므로 우월 비교 'más + 형용사/부사 + que'를 씁니다. 'cerca de(~ 가까이)'라는 부사 앞에 más를 놓아 '더 가까이'라는 뜻이 됩니다. tan은 como와 짝을 이룹니다.","x":["tanto: 동등 비교로 como와 쓰며 부사 앞에선 tan으로 줄어듭니다 ✗","muy: '매우'라는 정도 부사로 비교 que와 함께 쓰지 않습니다 ✗","tan: 'tan ~ como' 동등 비교라 que와 맞지 않습니다 ✗","más: 'más cerca... que(~보다 더 가까이)' → 정답 ✓"]},{"id":"G572","q":"No olvides llamarme cuando ____ los resultados de tus pruebas médicas.","o":["sepas","has sabido","sabes","sabrás"],"a":0,"k":"cuando+접속법(미래)","t":"건강 검진 결과가 나오면 잊지 말고 나한테 전화해.","e":"cuando 뒤에 아직 일어나지 않은 미래의 일이 오면 접속법 현재를 씁니다. 결과를 알게 되는 것은 미래의 일이므로 saber의 접속법 sepas가 맞습니다. cuando 뒤에는 미래형을 쓰지 않는다는 점이 중요합니다.","x":["sepas: 접속법 현재(알게 되면) → 정답 ✓","has sabido: 직설법 현재완료로 미래 시점을 나타내지 못합니다 ✗","sabes: 직설법 현재는 습관적 cuando에 쓰며 미래 일에는 맞지 않습니다 ✗","sabrás: cuando 뒤에는 미래형을 쓰지 않습니다 ✗"]},{"id":"G573","q":"Si ____ más paciente, ahora no estarías subiéndote por las paredes.","o":["fueras","serías","eres","eras"],"a":0,"k":"현재 비현실 가정","t":"네가 좀 더 참을성이 있다면 지금 이렇게 길길이 날뛰지 않을 텐데.","e":"결과절이 조건법(no estarías)이므로 조건절에는 현재 사실의 반대를 나타내는 접속법 과거 fueras를 씁니다. 'subirse por las paredes'는 '벽을 타고 오를 만큼 화가 나다, 길길이 날뛰다'라는 관용 표현입니다.","x":["fueras: 접속법 과거 → 정답 ✓","serías: 조건법은 si 바로 뒤에 쓰지 않습니다 ✗","eres: 직설법 현재는 현실 조건이라 조건법 결과절과 맞지 않습니다 ✗","eras: 직설법 불완료과거라 비현실 가정이 되지 않습니다 ✗"]},{"id":"G574","q":"No debemos reírnos ____ nadie por su aspecto.","o":["para","a","de","con"],"a":2,"k":"reírse de","t":"우리는 외모 때문에 누군가를 비웃어서는 안 된다.","e":"'reírse de alguien'은 '~을 비웃다, 놀리다'라는 뜻입니다. 'reírse con alguien'은 '~와 함께 웃다'로 의미가 다릅니다. 'por su aspecto'는 '외모 때문에'라는 이유입니다.","x":["para: reírse와 결합하지 않습니다 ✗","a: reírse와 이 의미로 쓰지 않습니다 ✗","de: 'reírse de(~을 비웃다)' → 정답 ✓","con: '~와 함께 웃다'라는 긍정적 의미라 문맥에 맞지 않습니다 ✗"]},{"id":"G575","q":"¿Le diste a Margarita ____ que te pidió?","o":["lo","a lo","ø","le"],"a":0,"k":"관계사 lo que","t":"마르가리타에게 그녀가 부탁한 걸 줬어?","e":"'lo que'는 '~하는 것'이라는 뜻으로, dar(주다)의 직접목적어 역할을 합니다. 사물(것)이 목적어이므로 사람 앞에 붙는 a는 쓰지 않습니다. 'a Margarita'가 '누구에게'를, 'lo que te pidió'가 '무엇을'을 나타냅니다.","x":["lo: 'lo que(~한 것)' → 정답 ✓","a lo: 사물 목적어 앞에는 a를 쓰지 않습니다 ✗","ø: 'que te pidió'만으로는 명사 역할을 하지 못합니다 ✗","le: 간접목적격 대명사라 관계사 que 앞에 쓰지 않습니다 ✗"]},{"id":"G576","q":"Yo no ____ a esta persona en mi vida.","o":["veía","estuve viendo","estaba viendo","he visto"],"a":3,"k":"현재완료(경험)","t":"나는 이 사람을 평생 한 번도 본 적이 없어.","e":"'en mi vida(내 평생에)'는 지금까지의 인생 전체를 범위로 하는 경험을 말하므로 현재완료(he + 과거분사)를 씁니다. 'No ... en mi vida'는 '평생 한 번도 ~않다'라는 강한 부정입니다.","x":["veía: 불완료과거로 습관을 말해 경험 의미가 되지 않습니다 ✗","estuve viendo: '보고 있었다'라는 과거 진행이라 맞지 않습니다 ✗","estaba viendo: 과거 진행형 배경 묘사라 경험 의미가 아닙니다 ✗","he visto: 현재완료(본 적이 있다) → 정답 ✓"]},{"id":"G577","q":"No pude comprar leche porque cuando llegué al súper ya ____.","o":["había cerrado","cerró","ha cerrado","cerraba"],"a":0,"k":"과거완료","t":"내가 슈퍼에 도착했을 때 이미 문을 닫아서 우유를 사지 못했다.","e":"과거의 한 시점(llegué, 도착했다)보다 더 먼저 끝난 일(가게가 닫음)을 나타낼 때 과거완료(había + 과거분사)를 씁니다. ya(이미)와 함께 자주 쓰입니다. súper는 supermercado의 줄임말입니다.","x":["había cerrado: 과거완료(이미 닫았었다) → 정답 ✓","cerró: 단순과거로 도착과 같은 시점이나 그 뒤의 일처럼 들립니다 ✗","ha cerrado: 현재완료로 과거 시점을 기준으로 하지 못합니다 ✗","cerraba: 불완료과거로 '닫곤 했다/닫는 중이었다'가 되어 ya와 어울리지 않습니다 ✗"]},{"id":"G578","q":"¿Qué les pareció que sus hijos ____ una fiesta en casa sin su permiso?","o":["harían","habrían hecho","han hecho","hicieran"],"a":3,"k":"parecer que+접속법","t":"여러분의 자녀들이 허락도 없이 집에서 파티를 한 것에 대해 어떻게 생각하셨어요?","e":"'¿Qué te parece que ~?(~한 것을 어떻게 생각해?)'는 평가를 묻는 표현이라 que절에 접속법을 씁니다. 주절이 과거(pareció)이므로 접속법 과거 hicieran을 씁니다.","x":["harían: 조건법이라 평가 표현 뒤 접속법 자리에 쓰지 않습니다 ✗","habrían hecho: 조건법 완료라 맞지 않습니다 ✗","han hecho: 직설법 현재완료라 법과 시제 모두 맞지 않습니다 ✗","hicieran: 접속법 과거 → 정답 ✓"]},{"id":"G579","q":"Vivir en Madrid es más caro ____ que piensas.","o":["a lo","como","de lo","ø"],"a":2,"k":"más de lo que","t":"마드리드에 사는 건 네가 생각하는 것보다 더 비싸.","e":"비교 대상이 명사가 아니라 절(piensas)일 때, '~하는 것보다 더'는 'más + 형용사 + de lo que'로 씁니다. 형용사(caro)를 비교할 때는 중성 lo를 씁니다. 예: Es más fácil de lo que parece(보기보다 쉬워).","x":["a lo: 비교 구문에 a를 쓰지 않습니다 ✗","como: más와 짝을 이루지 않습니다 ✗","de lo: 'más ~ de lo que(~하는 것보다 더)' → 정답 ✓","ø: 'más caro que piensas'는 틀린 형태입니다 ✗"]},{"id":"G580","q":"¿____ pasaréis la Semana Santa?","o":["Adonde","Donde","Adónde","Dónde"],"a":3,"k":"의문사 dónde","t":"너희 부활절 주간은 어디서 보낼 거야?","e":"pasar(시간을 보내다)는 이동이 아니라 머무는 장소를 묻는 것이므로 dónde(어디에서)를 씁니다. 의문문이라 악센트가 필요합니다. Semana Santa는 부활절 직전 주간으로 스페인어권의 큰 휴가 기간입니다.","x":["Adonde: 악센트 없는 관계부사이고 방향 의미라 맞지 않습니다 ✗","Donde: 악센트가 없어 의문사가 될 수 없습니다 ✗","Adónde: '어디로'라서 이동 동사와 씁니다 ✗","Dónde: '어디에서' → 정답 ✓"]},{"id":"G581","q":"No es cierto que yo ____ ese correo electrónico. Otra persona lo ha hecho.","o":["escribiría","escriba","he escrito","haya escrito"],"a":3,"k":"부정 확실성+접속법","t":"내가 그 이메일을 썼다는 건 사실이 아니야. 다른 사람이 쓴 거야.","e":"'Es cierto que'는 직설법을 쓰지만, 'No es cierto que'처럼 부정하면 접속법을 씁니다. 이메일을 쓴 일은 이미 일어난 일(으로 주장되는 것)이므로 접속법 현재완료 haya escrito가 맞습니다.","x":["escribiría: 조건법이라 부정 확실성 표현 뒤에 쓰지 않습니다 ✗","escriba: 접속법 현재로 아직 일어나지 않은 일처럼 들립니다 ✗","he escrito: 직설법이라 'No es cierto que' 뒤에 쓰지 않습니다 ✗","haya escrito: 접속법 현재완료 → 정답 ✓"]},{"id":"G582","q":"____ vas a salir, cómprame el periódico.","o":["Así que","Para que","Porque","Ya que"],"a":3,"k":"이유 ya que","t":"어차피 나갈 거라면 나 신문 좀 사다 줘.","e":"'Ya que'는 '~하는 김에, ~이니까'라는 뜻으로, 상대가 하려는 일을 이유로 부탁할 때 아주 자연스럽습니다. 문장 맨 앞에 올 수 있습니다. 예: Ya que estás aquí, ayúdame(여기 온 김에 나 좀 도와줘).","x":["Así que: '그래서'라는 결과로 문두에서 이유를 나타내지 않습니다 ✗","Para que: '~하도록'이라는 목적이고 접속법이 필요합니다 ✗","Porque: 문두 이유절로는 어색하고 보통 주절 뒤에 옵니다 ✗","Ya que: '~하는 김에, ~이니까' → 정답 ✓"]},{"id":"G583","q":"No estoy de humor, ____ deja tus bromas para otro momento.","o":["pese a que","ya que","de modo que","a fin de que"],"a":2,"k":"결과 de modo que","t":"나 기분이 안 좋아, 그러니까 농담은 다른 때로 미뤄 줘.","e":"'de modo que'는 '그러니까, 그래서'라는 결과·결론을 나타냅니다. 앞 사실(기분이 안 좋다)에서 결론(농담은 나중에)을 끌어내며, 뒤에 명령문(deja)이 올 수 있습니다.","x":["pese a que: '~에도 불구하고'라는 양보라 맞지 않습니다 ✗","ya que: '~이니까'로 뒤에 이유가 와야 해서 순서가 맞지 않습니다 ✗","de modo que: '그러니까' → 정답 ✓","a fin de que: '~하도록'이라는 목적이고 접속법이 필요합니다 ✗"]},{"id":"G584","q":"A ellos siempre ____ digo la verdad.","o":["les","los","la","le"],"a":0,"k":"간접목적격 대명사","t":"나는 그들에게 항상 진실을 말한다.","e":"decir(말하다)에서 '누구에게'는 간접목적격 대명사로 나타냅니다. 'A ellos(그들에게)'는 3인칭 복수이므로 les를 씁니다. 'la verdad(진실)'가 직접목적어입니다.","x":["les: 3인칭 복수 간접목적격(그들에게) → 정답 ✓","los: 직접목적격(그들을)이라 '말해 주는 대상'에 쓰지 않습니다 ✗","la: 여성 단수 직접목적격(그녀를/그것을)이라 ✗","le: 단수형이라 복수 ellos와 맞지 않습니다 ✗"]},{"id":"G585","q":"¿____ has dicho a tus padres que has suspendido el examen de química?","o":["Le","Se","ø","Les"],"a":3,"k":"간접목적격 대명사","t":"부모님께 화학 시험 떨어졌다고 말씀드렸어?","e":"'a tus padres(네 부모님께)'는 3인칭 복수이므로 간접목적격 대명사 les를 씁니다. 스페인어에서는 'a + 사람'이 있어도 간접목적격 대명사를 함께 쓰는 것이 일반적입니다. suspender는 '(시험에) 떨어지다'입니다(스페인).","x":["Le: 단수형이라 복수 padres와 맞지 않습니다 ✗","Se: 직접목적격 lo와 함께 쓸 때(se lo)만 les가 se로 바뀝니다 ✗","ø: 'a tus padres'가 있을 때 간접목적격 대명사를 쓰는 것이 표준입니다 ✗","Les: 3인칭 복수 간접목적격 → 정답 ✓"]},{"id":"G586","q":"Llamé ____ vi el mensaje.","o":["en cuanto","nada más","después de","antes de"],"a":0,"k":"en cuanto(~하자마자)","t":"나는 메시지를 보자마자 전화했다.","e":"'en cuanto + 활용된 동사'는 '~하자마자'라는 뜻입니다. 뒤에 vi(봤다)라는 활용 동사가 있으므로 en cuanto가 맞습니다. nada más, después de, antes de는 뒤에 동사원형이 와야 합니다.","x":["en cuanto: '~하자마자' + 활용 동사 → 정답 ✓","nada más: 'nada más + 동사원형(nada más ver)'으로 써야 합니다 ✗","después de: 뒤에 동사원형이 와야 합니다(después de ver) ✗","antes de: '~하기 전에'이며 역시 동사원형이 필요합니다 ✗"]},{"id":"G587","q":"Vemos a nuestros antiguos compañeros de clase ____ raramente.","o":["casi","apenas","mucho","muy"],"a":3,"k":"부사 muy","t":"우리는 예전 반 친구들을 아주 드물게 만난다.","e":"muy(매우)는 형용사나 부사 앞에서 정도를 강조합니다. raramente(드물게)는 부사이므로 'muy raramente(아주 드물게)'가 자연스럽습니다. mucho는 형용사·부사 앞에 직접 쓰지 않습니다.","x":["casi: '거의'라서 'casi raramente'는 어색한 조합입니다 ✗","apenas: 그 자체로 '거의 ~않다'라 raramente와 겹칩니다 ✗","mucho: 부사 앞에서는 muy를 써야 합니다 ✗","muy: '아주 드물게' → 정답 ✓"]},{"id":"G588","q":"El niño se ha hecho una herida en ____ rodilla.","o":["ø","sus","su","la"],"a":3,"k":"신체 부위 정관사","t":"아이가 무릎을 다쳤다.","e":"스페인어에서 신체 부위는 소유사(su) 대신 정관사(el, la)를 씁니다. 재귀대명사 se가 이미 '자기 자신의'라는 의미를 주기 때문입니다. rodilla(무릎)는 여성 명사라 la를 씁니다. 예: Me duele la cabeza(머리가 아파).","x":["ø: 신체 부위 앞에 관사를 생략하지 않습니다 ✗","sus: 복수 소유사이고 신체 부위에는 보통 쓰지 않습니다 ✗","su: 신체 부위에는 소유사 대신 정관사를 씁니다 ✗","la: 정관사(신체 부위) → 정답 ✓"]},{"id":"G589","q":"No dejes ____ mañana lo que puedas hacer hoy.","o":["por","hacia","para","a"],"a":2,"k":"속담 dejar para","t":"오늘 할 수 있는 일을 내일로 미루지 마라.","e":"'dejar algo para + 시점'은 '~을 (시점)으로 미루다'라는 뜻입니다. 이 문장은 'No dejes para mañana lo que puedas hacer hoy'라는 유명한 속담입니다. para가 기한·예정 시점을 나타냅니다.","x":["por: 이유·경로를 나타내 시점을 미루는 의미가 되지 않습니다 ✗","hacia: '~쪽으로'라는 방향이라 맞지 않습니다 ✗","para: 'dejar para mañana(내일로 미루다)' → 정답 ✓","a: 이 속담에는 쓰지 않습니다 ✗"]},{"id":"G590","q":"¿____ no ha llegado Andrea?","o":["Ya","Casi","Apenas","Todavía"],"a":3,"k":"todavía no","t":"안드레아 아직 안 왔어?","e":"'todavía no'는 '아직 ~않다'라는 뜻으로, 기대했던 일이 아직 일어나지 않았음을 나타냅니다. 같은 뜻으로 'aún no'도 씁니다. 'ya'는 '이미'라서 '¿Ya ha llegado?(벌써 왔어?)'처럼 긍정문과 씁니다.","x":["Ya: '이미'라는 뜻으로, 'ya no'는 '더 이상 ~않다'가 됩니다 ✗","Casi: '거의'라서 의문문 'casi no ha llegado'는 어색합니다 ✗","Apenas: '거의 ~않다'라는 뜻이라 문맥에 맞지 않습니다 ✗","Todavía: 'todavía no(아직 ~않다)' → 정답 ✓"]},{"id":"G591","q":"Hasta el otro día, mi esposa y yo no ____ a la ópera.","o":["habíamos ido","hemos ido","estuvimos yendo","fuimos"],"a":0,"k":"과거완료","t":"며칠 전까지 아내와 나는 오페라에 가 본 적이 없었다.","e":"'Hasta el otro día(며칠 전까지)'는 과거의 기준 시점입니다. 그 시점까지의 경험(가 본 적 없음)을 말할 때는 과거완료(había + 과거분사)를 씁니다. 며칠 전에 처음 갔다는 뜻이 됩니다.","x":["habíamos ido: 과거완료(가 본 적이 없었다) → 정답 ✓","hemos ido: 현재완료는 지금까지의 경험이라 과거 기준 시점과 맞지 않습니다 ✗","estuvimos yendo: '가고 있었다'라는 진행 의미라 ✗","fuimos: 단순과거로 과거 시점까지의 경험을 나타내지 못합니다 ✗"]},{"id":"G592","q":"Mariana ____ más feliz desde que está soltera.","o":["parecen","parece","se parece","la parece"],"a":1,"k":"parecer 용법","t":"마리아나는 싱글이 된 이후로 더 행복해 보인다.","e":"'parecer + 형용사'는 '~해 보이다'라는 뜻이고 대명사 없이 씁니다. 주어 Mariana가 3인칭 단수이므로 parece가 맞습니다. 'desde que está soltera'는 '싱글이 된 이후로'입니다.","x":["parecen: 복수형이라 단수 주어와 맞지 않습니다 ✗","parece: '~해 보이다' 3인칭 단수 → 정답 ✓","se parece: 'parecerse'는 '닮다'라서 의미가 맞지 않습니다 ✗","la parece: 직접목적격 la를 쓰는 형태는 틀렸고 간접목적이면 le가 됩니다 ✗"]},{"id":"G593","q":"Disculpe, ¿____ cerrar la ventana? Es que tengo frío...","o":["puedes","podrás","podrías","podría"],"a":3,"k":"공손한 부탁 조건법","t":"실례합니다만, 창문을 닫아 주실 수 있을까요? 추워서요...","e":"'Disculpe(실례합니다)'는 usted(존칭)에게 하는 말이므로 동사도 usted 형태(3인칭 단수)를 씁니다. 조건법 podría는 '~해 주실 수 있을까요?'라는 공손한 부탁을 나타냅니다.","x":["puedes: tú 형태라 Disculpe(usted)와 맞지 않습니다 ✗","podrás: 미래형 tú 형태라 부탁 표현에 맞지 않습니다 ✗","podrías: 공손한 조건법이지만 tú 형태라 usted와 맞지 않습니다 ✗","podría: usted 조건법(~해 주실 수 있을까요) → 정답 ✓"]},{"id":"G594","q":"Hoy estamos ____ lunes, ¿no?","o":["para","en","a","de"],"a":2,"k":"estar a+요일","t":"오늘 월요일 맞지?","e":"estar로 요일·날짜를 말할 때는 'estamos a + 요일/날짜'처럼 전치사 a를 씁니다. 'Hoy es lunes'와 같은 의미입니다. 예: Estamos a 5 de mayo(오늘은 5월 5일이다).","x":["para: 기한을 나타내 이 표현에 쓰지 않습니다 ✗","en: 'estamos en + 달/계절'(estamos en mayo)에는 쓰지만 요일에는 쓰지 않습니다 ✗","a: 'estamos a lunes' → 정답 ✓","de: 이 구조에 맞지 않습니다 ✗"]},{"id":"G595","q":"Ojalá tuviera tanto tiempo libre ____ ella.","o":["a","de","que","como"],"a":3,"k":"tanto... como","t":"나도 그녀만큼 자유 시간이 많다면 좋을 텐데.","e":"'tanto/a + 명사 + como'는 '~만큼 많은 (명사)'라는 동등 비교입니다. 앞에 tanto가 있으므로 짝을 맞춰 como를 씁니다. 'Ojalá + 접속법 과거'는 이루기 어려운 현재의 소망(~라면 좋을 텐데)을 나타냅니다.","x":["a: 비교 구문에 쓰지 않습니다 ✗","de: 'más de + 숫자'처럼 쓰는 것으로 tanto와 짝을 이루지 않습니다 ✗","que: 우월·열등 비교(más/menos ~ que)에 쓰며 tanto와는 쓰지 않습니다 ✗","como: 'tanto ~ como(~만큼)' → 정답 ✓"]},{"id":"G596","q":"Señores, no ____ que mañana tenemos una reunión.","o":["olvidéis","olvidad","olviden","olvides"],"a":2,"k":"ustedes 부정 명령","t":"여러분, 내일 회의가 있다는 걸 잊지 마세요.","e":"'Señores(여러분)'는 ustedes(존칭 복수)에게 하는 말이므로 ustedes 명령형을 씁니다. 부정 명령은 접속법 현재로 만들어 'no olviden'이 됩니다. 중남미에서는 친한 사이에도 ustedes를 씁니다.","x":["olvidéis: vosotros 부정 명령이라 존칭 Señores와 맞지 않습니다 ✗","olvidad: vosotros 긍정 명령형이라 no와 함께 쓸 수 없습니다 ✗","olviden: ustedes 부정 명령 → 정답 ✓","olvides: tú 부정 명령이라 수가 맞지 않습니다 ✗"]},{"id":"G597","q":"¿A qué hora ____ has quedado con tus amigos?","o":["les","se","ø","te"],"a":2,"k":"quedar con","t":"친구들이랑 몇 시에 만나기로 했어?","e":"'quedar con alguien'은 '~와 만날 약속을 하다'라는 뜻으로 재귀대명사 없이 씁니다. 'quedarse'(재귀형)는 '머무르다, ~하게 되다'라는 다른 뜻이라 te를 넣으면 의미가 달라집니다. 이 용법은 주로 스페인에서 씁니다.","x":["les: 간접목적격 대명사로 quedar con 구조에 필요 없습니다 ✗","se: 3인칭 재귀대명사라 주어 tú와도 맞지 않습니다 ✗","ø: 'quedar con(~와 약속하다)' 대명사 없음 → 정답 ✓","te: 'quedarse'가 되어 '머물다'라는 의미로 바뀝니다 ✗"]},{"id":"G598","q":"Si quieres, ____ a comer con nosotros.","o":["quédese","quédate","quedaos","quédense"],"a":1,"k":"tú 긍정 명령","t":"원한다면 우리랑 같이 밥 먹고 가.","e":"'Si quieres(네가 원하면)'는 tú에게 하는 말이므로 tú 긍정 명령형을 씁니다. quedarse(머무르다)의 tú 명령형은 queda에 재귀대명사 te를 붙인 quédate입니다. 'quedarse a comer'는 '남아서 밥을 먹다'입니다.","x":["quédese: usted 명령형이라 quieres(tú)와 맞지 않습니다 ✗","quédate: tú 긍정 명령 → 정답 ✓","quedaos: vosotros 명령형이라 단수 tú와 맞지 않습니다 ✗","quédense: ustedes 명령형이라 맞지 않습니다 ✗"]},{"id":"G599","q":"Francisco corre más que ____ otro de su clase.","o":["ningunos","ningunas","ninguno","ningún"],"a":3,"k":"más que ningún otro","t":"프란시스코는 반에서 다른 어느 누구보다 빨리 달린다.","e":"'más que ningún otro'는 '다른 누구보다 더'라는 강조 표현입니다. 여기서 ninguno는 남성 단수 형용사로 'otro' 앞에 오므로 -o가 탈락한 ningún이 됩니다. 비슷하게 'mejor que nadie(누구보다 잘)'도 씁니다.","x":["ningunos: 복수형은 거의 쓰지 않으며 수도 맞지 않습니다 ✗","ningunas: 여성 복수형이라 맞지 않습니다 ✗","ninguno: 뒤에 단어(otro)가 올 때는 -o가 탈락해야 합니다 ✗","ningún: 남성 단수 단축형 → 정답 ✓"]},{"id":"G600","q":"Prefiero beber en vasos ____ cristal, intento usar menos plástico.","o":["por","con","a","de"],"a":3,"k":"재료 전치사 de","t":"나는 유리컵으로 마시는 걸 더 좋아해, 플라스틱을 덜 쓰려고 하거든.","e":"물건의 재료(~으로 만든)를 나타낼 때는 'de + 재료'를 씁니다. 'vasos de cristal'은 '유리로 된 컵'입니다. 예: una mesa de madera(나무 탁자), una camisa de algodón(면 셔츠).","x":["por: 재료를 나타내지 않습니다 ✗","con: '~이 들어 있는, ~을 가진'이라 재료 의미가 아닙니다 ✗","a: 재료를 나타내지 않으며 'a mano(손으로)' 같은 방식에 씁니다 ✗","de: 재료를 나타내는 de(유리로 된) → 정답 ✓"]},{"id":"G601","q":"Si ____ tú, hablaría con un experto para que te asesore.","o":["sería","era","sea","fuera"],"a":3,"k":"si + 접속법 과거","t":"내가 너라면, 너에게 조언해 줄 전문가와 이야기해 볼 텐데.","e":"현재 사실과 반대되는 가정(~라면 ~할 텐데)은 'si + 접속법 과거(imperfecto de subjuntivo) + 조건법(hablaría)' 구조를 씁니다. '내가 너라면'은 현실에서 불가능한 가정이므로 ser의 접속법 과거 fuera가 들어갑니다. 'Si yo fuera tú'는 조언할 때 아주 자주 쓰는 표현입니다.","x":["sería: 조건법이라 si 바로 뒤에는 쓰지 않습니다 ✗","era: 직설법 불완료과거로, 비현실 가정에는 쓰지 않습니다 ✗","sea: 접속법 현재로, si 뒤에는 쓰지 않습니다 ✗","fuera: ser의 접속법 과거, 비현실 가정 → 정답 ✓"]},{"id":"G602","q":"Marcelo está muy interesado en que ____ a la conferencia.","o":["vas a venir","vendrás","vienes","vengas"],"a":3,"k":"감정·관심 + 접속법","t":"마르셀로는 네가 회의에 오는 것에 매우 관심이 있다.","e":"'estar interesado en que ~'처럼 주어의 바람·관심을 나타내고 que 뒤 주어가 다를 때(마르셀로 ≠ 너) que절 동사는 접속법(바람·의심·감정을 나타내는 동사 형태)을 씁니다. 주절이 현재이므로 venir의 접속법 현재 vengas가 맞습니다.","x":["vas a venir: 직설법 근접미래라 바람을 나타내는 que절에 맞지 않습니다 ✗","vendrás: 직설법 미래라 ✗","vienes: 직설법 현재라 ✗","vengas: venir의 접속법 현재 2인칭 단수 → 정답 ✓"]},{"id":"G603","q":"¡Qué mala suerte! Justo cuando íbamos a salir de casa, ____ llover.","o":["se puso a","llegó a","dejó de","echó a"],"a":0,"k":"동사 우회구문","t":"운도 없지! 우리가 막 집을 나서려던 순간에 비가 내리기 시작했다.","e":"'ponerse a + 동사원형'은 '~하기 시작하다'라는 뜻으로, 갑자기 어떤 행동이 시작될 때 씁니다. 날씨(llover)에도 자연스럽게 쓰여 'se puso a llover(비가 내리기 시작했다)'가 됩니다.","x":["se puso a: ~하기 시작했다 → 정답 ✓","llegó a: ~하기에 이르렀다(결국 ~까지 했다)라는 뜻이라 문맥에 맞지 않습니다 ✗","dejó de: ~하기를 멈췄다, 그쳤다는 뜻이라 반대 의미입니다 ✗","echó a: 'echar a + 동사'는 주로 correr, andar, reír 같은 사람의 동작에 쓰고 llover와는 쓰지 않습니다 ✗"]},{"id":"G604","q":"Si no te gusta ese vestido, elige ____.","o":["un otro","unos otros","otro","uno otro"],"a":2,"k":"otro 용법","t":"그 원피스가 마음에 안 들면 다른 걸 골라.","e":"otro(다른 것)는 앞에 부정관사 un/uno를 붙이지 않습니다. 영어 'another'를 생각해서 'un otro'라고 하면 틀립니다. 원피스(vestido)는 남성 단수이므로 otro 하나만 씁니다.","x":["un otro: otro 앞에 부정관사를 붙이지 않습니다 ✗","unos otros: 부정관사 복수도 붙이지 않고, 수도 맞지 않습니다 ✗","otro: '다른 것(하나)' → 정답 ✓","uno otro: 이런 형태는 쓰지 않습니다 ✗"]},{"id":"G605","q":"¡Esta niña ha nacido ____ artista!","o":["con","a","para","por"],"a":2,"k":"전치사 para","t":"이 아이는 예술가가 되려고 태어났어!","e":"'nacer para + 명사/동사'는 '~이 되기 위해(~할 운명으로) 태어나다'라는 뜻입니다. para는 목적·용도를 나타내기 때문에 타고난 재능을 강조할 때 씁니다. 예: Nació para cantar.(그는 노래하려고 태어났다.)","x":["con: ~와 함께라는 뜻으로 '예술가와 함께 태어났다'가 되어 어색합니다 ✗","a: 이 표현에서는 쓰지 않습니다 ✗","para: 목적·운명을 나타냄 → 정답 ✓","por: 원인·이유를 나타내서 의미가 맞지 않습니다 ✗"]},{"id":"G606","q":"Este libro lo ____ al español mi profesora de francés.","o":["tradujo","traduzca","tradució","traduje"],"a":0,"k":"traducir 과거형","t":"이 책은 내 프랑스어 선생님이 스페인어로 번역했다.","e":"traducir(번역하다)는 -ducir로 끝나는 불규칙 동사로, 단순과거에서 -duj- 형태가 됩니다(traduje, tradujiste, tradujo…). 주어가 mi profesora(3인칭 단수)이므로 tradujo가 맞습니다. 목적어 'Este libro'가 앞에 나와서 lo로 다시 받아 준 구조입니다.","x":["tradujo: 3인칭 단수 단순과거 → 정답 ✓","traduzca: 접속법 현재라 평서문에 맞지 않습니다 ✗","tradució: 존재하지 않는 잘못된 형태입니다 ✗","traduje: 1인칭 단수(나는 번역했다)라 주어와 맞지 않습니다 ✗"]},{"id":"G607","q":"¿Qué tal ____ te da aprender nuevos idiomas?","o":["se","le","ø","lo"],"a":0,"k":"darse bien/mal","t":"새로운 언어를 배우는 건 너 어때(잘하니)?","e":"'다른 사람에게 어떤 일이 잘 맞다/잘하다'는 'darse bien/mal a alguien' 구문으로 표현합니다. 이때 se가 반드시 필요하고, 사람은 간접목적격 대명사(te)로 나타냅니다. '¿Qué tal se te da…?'는 '너 ~하는 거 어때(잘해)?'라는 아주 흔한 질문입니다.","x":["se: darse 구문의 se → 정답 ✓","le: te와 함께 쓸 수 없고 이미 간접목적어 te가 있습니다 ✗","ø: se가 빠지면 '무엇이 너에게 주니?'라는 엉뚱한 뜻이 됩니다 ✗","lo: 직접목적격이라 이 구문에 맞지 않습니다 ✗"]},{"id":"G608","q":"Nos vamos ____ se haga demasiado tarde.","o":["después de que","antes","antes de que","mientras"],"a":2,"k":"antes de que + 접속법","t":"너무 늦어지기 전에 우리 가자.","e":"'antes de que(~하기 전에)'는 뒤에 항상 접속법이 오고, 이 문장의 haga가 접속법 현재입니다. 뒤에 활용된 동사가 오려면 반드시 que가 있어야 하므로 antes만으로는 안 됩니다.","x":["después de que: ~한 후에라는 뜻이라 '너무 늦어진 후에 가자'가 되어 어색합니다 ✗","antes: 뒤에 활용 동사가 오려면 'antes de que'가 필요합니다 ✗","antes de que: ~하기 전에 + 접속법 → 정답 ✓","mientras: ~하는 동안이라 의미가 맞지 않습니다 ✗"]},{"id":"G609","q":"Vamos, ya es hora ____ volver a casa.","o":["de","desde","por","a"],"a":0,"k":"ser hora de","t":"자, 이제 집에 돌아갈 시간이야.","e":"'(ya) es hora de + 동사원형'은 '~할 시간이다'라는 고정 표현으로, 전치사 de를 씁니다. 예: Es hora de dormir.(잘 시간이야.)","x":["de: 'es hora de + 동사원형' → 정답 ✓","desde: ~부터라는 뜻이라 맞지 않습니다 ✗","por: 이 표현에는 쓰지 않습니다 ✗","a: 이 표현에는 쓰지 않습니다 ✗"]},{"id":"G610","q":"Incluso ____ lo haría mejor que él.","o":["yo","a mí","me","mí"],"a":0,"k":"주격 인칭대명사","t":"나조차도 그 사람보다는 잘할 거야.","e":"빈칸은 동사 haría(~할 것이다)의 주어 자리이므로 주격 대명사 yo가 들어갑니다. incluso(~조차도)는 부사라서 전치사처럼 뒤에 mí를 요구하지 않습니다. 비교 대상 'que él'도 주격입니다.","x":["yo: 동사의 주어(나) → 정답 ✓","a mí: 간접목적어 형태(나에게)라 주어가 될 수 없습니다 ✗","me: 목적격 대명사라 주어가 될 수 없습니다 ✗","mí: 전치사 뒤에서만 쓰는 형태입니다 ✗"]},{"id":"G611","q":"No conozco a casi nadie que ____ hablar cuatro lenguas con fluidez.","o":["puedan","esté pudiendo","pueda","puede"],"a":2,"k":"관계절 + 접속법","t":"네 개 언어를 유창하게 할 수 있는 사람은 거의 아무도 모른다.","e":"관계절이 수식하는 대상이 존재하지 않거나 거의 없을 때(nadie, casi nadie) 관계절 동사는 접속법을 씁니다. 선행사 nadie는 3인칭 단수이므로 poder의 접속법 현재 pueda가 맞습니다.","x":["puedan: 접속법이지만 복수형이라 nadie와 수가 맞지 않습니다 ✗","esté pudiendo: poder는 진행형으로 쓰지 않습니다 ✗","pueda: 3인칭 단수 접속법 현재 → 정답 ✓","puede: 직설법이라 존재를 부정하는 선행사와 맞지 않습니다 ✗"]},{"id":"G612","q":"El avión aterrizó a la hora prevista ____ había salido con retraso.","o":["y eso que","debido a que","ya que","puesto que"],"a":0,"k":"양보 접속사","t":"비행기는 지연 출발했는데도 예정된 시간에 착륙했다.","e":"'y eso que'는 구어에서 '~인데도, ~했는데 말이야'라는 양보(뜻밖의 사실)를 나타냅니다. 늦게 출발했는데도 제시간에 도착했다는 대조 관계이므로 정답입니다. 뒤에 직설법이 옵니다.","x":["y eso que: ~했는데도(양보) → 정답 ✓","debido a que: ~때문에(원인)라서 논리가 맞지 않습니다 ✗","ya que: ~이므로(이유)라서 맞지 않습니다 ✗","puesto que: ~이므로(이유)라서 맞지 않습니다 ✗"]},{"id":"G613","q":"Miguel ____ su programa favorito ahora mismo. Será mejor que no le molestemos.","o":["está viendo","ha visto","ha estado viendo","ve"],"a":0,"k":"현재진행형","t":"미겔은 지금 좋아하는 프로그램을 보고 있어. 방해하지 않는 게 좋겠어.","e":"'ahora mismo(지금 바로)'는 말하는 순간 진행 중인 행동을 나타내므로 'estar + 현재분사' 진행형을 씁니다. 그래서 está viendo(보고 있다)가 정답입니다.","x":["está viendo: 지금 보고 있다(진행형) → 정답 ✓","ha visto: 이미 봤다(완료)라서 방해하지 말자는 말과 맞지 않습니다 ✗","ha estado viendo: 계속 보고 있었다(과거부터 지금까지)로 ahora mismo와 덜 자연스럽습니다 ✗","ve: 단순현재는 습관을 나타내는 느낌이라 지금 진행 중임을 강조하지 못합니다 ✗"]},{"id":"G614","q":"Te llamo para que me ____ una duda.","o":["resuelvas","resuelves","resolverás","vas a resolver"],"a":0,"k":"para que + 접속법","t":"내 의문 하나를 해결해 달라고 너에게 전화하는 거야.","e":"'para que(~하도록, ~하기 위해)'는 목적을 나타내며 뒤에 항상 접속법이 옵니다. 주절이 현재(llamo)이므로 resolver의 접속법 현재 resuelvas가 맞습니다.","x":["resuelvas: 접속법 현재 2인칭 단수 → 정답 ✓","resuelves: 직설법 현재라 para que 뒤에 쓸 수 없습니다 ✗","resolverás: 직설법 미래라 ✗","vas a resolver: 직설법 근접미래라 ✗"]},{"id":"G615","q":"Estoy totalmente de acuerdo ____.","o":["con tú","con ti","con tu","contigo"],"a":3,"k":"conmigo/contigo","t":"나는 너에게 전적으로 동의해.","e":"전치사 con 뒤에 '너'가 올 때는 'con ti'가 아니라 특별한 형태 contigo를 씁니다(나와: conmigo). 'estar de acuerdo con alguien'은 '~에게 동의하다'라는 표현입니다.","x":["con tú: 전치사 뒤에 주격 tú는 쓰지 않습니다 ✗","con ti: con과 ti는 합쳐서 contigo로 씁니다 ✗","con tu: tu는 소유사(너의)라서 명사 없이 쓸 수 없습니다 ✗","contigo: con + 너 → 정답 ✓"]},{"id":"G616","q":"Busco un abogado que ____ experiencia en este tipo de casos. ¿Conoce alguno?","o":["tendría","está teniendo","tenga","tiene"],"a":2,"k":"관계절 + 접속법","t":"이런 종류의 사건에 경험이 있는 변호사를 찾고 있어요. 아는 분 있으세요?","e":"찾고 있지만 아직 존재하는지 모르는 대상(불특정)을 설명하는 관계절에서는 접속법을 씁니다. '¿Conoce alguno?'로 보아 특정 변호사가 아니므로 tener의 접속법 현재 tenga가 맞습니다.","x":["tendría: 조건법이라 맞지 않습니다 ✗","está teniendo: tener(가지다)는 이런 의미로 진행형을 쓰지 않습니다 ✗","tenga: 불특정 대상 + 접속법 현재 → 정답 ✓","tiene: 직설법은 이미 아는 특정 변호사일 때 씁니다 ✗"]},{"id":"G617","q":"No veo mi bolígrafo negro. ¿____ ha llevado alguien?","o":["Se","Se lo","Le lo","Lo"],"a":1,"k":"se lo (대명사 결합)","t":"내 검은 볼펜이 안 보여. 누가 가져갔어?","e":"'llevarse algo'는 '~을 가져가 버리다'라는 뜻으로 재귀 se가 붙습니다. 여기에 직접목적어 '볼펜'(el bolígrafo)을 lo로 받아 'se lo ha llevado'가 됩니다. 대명사가 둘일 때 se가 먼저 옵니다.","x":["Se: 직접목적어(볼펜)를 받는 lo가 빠졌습니다 ✗","Se lo: 재귀 se + 직접목적 lo → 정답 ✓","Le lo: le와 lo는 함께 쓰지 않고 se lo로 바뀝니다 ✗","Lo: 그것을 가져갔다는 뜻은 되지만 '가져가 버리다'의 llevarse에 필요한 se가 빠져 덜 자연스럽습니다 ✗"]},{"id":"G618","q":"¡____ paisaje tan bonito!","o":["Cómo","Qué","Cuál","Cuánto"],"a":1,"k":"감탄문 qué","t":"정말 아름다운 경치구나!","e":"'¡Qué + 명사 + tan/más + 형용사!'는 '정말 ~한 …구나!'라는 감탄문 구조입니다. 명사(paisaje) 앞에서 감탄을 나타낼 때는 qué를 씁니다.","x":["Cómo: 동사와 함께 쓰는 감탄(¡Cómo llueve! 비 정말 많이 온다!)이라 ✗","Qué: 명사 앞 감탄사 → 정답 ✓","Cuál: 감탄문에 쓰지 않습니다 ✗","Cuánto: 양(얼마나 많은)을 감탄할 때 쓰고 tan과 함께 쓰지 않습니다 ✗"]},{"id":"G619","q":"Nadie reparó ____ el extraño que había en la puerta excepto Carla.","o":["con","por","en","sobre"],"a":2,"k":"reparar en","t":"카를라 말고는 아무도 문 앞에 있던 낯선 사람을 눈치채지 못했다.","e":"reparar가 '~을 알아차리다, 주목하다'라는 뜻일 때는 전치사 en과 함께 씁니다(reparar en algo). 같은 뜻의 'fijarse en'과 함께 외워 두면 좋습니다.","x":["con: reparar와 쓰지 않습니다 ✗","por: reparar와 쓰지 않습니다 ✗","en: reparar en = ~을 알아차리다 → 정답 ✓","sobre: reparar와 쓰지 않습니다 ✗"]},{"id":"G620","q":"Mientras ____ por el parque, se nos acercó un perrito.","o":["paseábamos","paseamos","habíamos paseado","hemos paseado"],"a":0,"k":"불완료과거 배경","t":"우리가 공원을 산책하고 있을 때 강아지 한 마리가 우리에게 다가왔다.","e":"과거에 진행 중이던 배경 행동(산책하던 중)은 불완료과거(pretérito imperfecto)로, 그 사이에 일어난 사건(다가왔다)은 단순과거(se acercó)로 씁니다. mientras(~하는 동안)와 잘 어울리는 형태는 paseábamos입니다.","x":["paseábamos: 진행 중인 과거 배경 → 정답 ✓","paseamos: 단순과거(또는 현재)라 배경 묘사에 맞지 않습니다 ✗","habíamos paseado: 과거완료(이미 산책했었다)라 동시 진행이 아닙니다 ✗","hemos paseado: 현재완료라 과거 이야기와 맞지 않습니다 ✗"]},{"id":"G621","q":"Inés da ____ clases en un instituto de secundaria.","o":["la","ø","unas","las"],"a":1,"k":"관사 생략","t":"이네스는 중학교에서 수업을 한다(가르친다).","e":"'dar clases'는 '수업을 하다, 가르치다'라는 고정 표현으로 보통 관사 없이 씁니다. 특정 수업을 가리키는 게 아니라 직업 활동을 말하므로 관사를 넣지 않습니다.","x":["la: 단수 관사라 복수 clases와 맞지 않습니다 ✗","ø: 'dar clases' 관사 없이 → 정답 ✓","unas: '몇몇 수업'이라는 뜻이 되어 직업을 말하는 문맥에 어색합니다 ✗","las: 특정 수업을 가리키는 게 아니라서 어색합니다 ✗"]},{"id":"G622","q":"____ niña querría ese juguete.","o":["Cualquiera","Uno cualquiera","Cualquier","Una cualquiera"],"a":2,"k":"cualquier","t":"어떤 여자아이라도 그 장난감을 갖고 싶어 할 거야.","e":"cualquiera(어떤 ~라도)는 명사 앞에서는 끝의 -a가 빠져 cualquier가 됩니다(남성·여성 모두). 그래서 'cualquier niña'가 맞습니다. 명사 뒤에서는 'una niña cualquiera(아무 여자아이)'처럼 cualquiera를 씁니다.","x":["Cualquiera: 명사 앞에서는 cualquier로 줄어듭니다 ✗","Uno cualquiera: 명사 앞에 올 수 없고 성도 맞지 않습니다 ✗","Cualquier: 명사 앞 형태 → 정답 ✓","Una cualquiera: 명사 앞에 쓰는 형태가 아닙니다 ✗"]},{"id":"G623","q":"____ tú, ¿cómo debería vestirme para este evento?","o":["Por","Según","Para","De"],"a":1,"k":"según (~에 따르면)","t":"네 생각엔, 이 행사에 내가 어떻게 입고 가야 할까?","e":"'según tú(네 생각에는, 네 말에 따르면)'는 상대방의 의견을 물을 때 씁니다. según 뒤에는 인칭대명사가 주격(yo, tú) 형태로 온다는 점이 특이합니다.","x":["Por: por tú라는 표현은 없습니다 ✗","Según: ~에 따르면, ~의 생각에는 → 정답 ✓","Para: 'para ti(너에게는)'라면 가능하지만 tú와는 쓸 수 없습니다 ✗","De: 의미가 통하지 않습니다 ✗"]},{"id":"G624","q":"¿Qué sueles hacer cuando te ____ triste?","o":["sientes","sienta","sientas","siente"],"a":0,"k":"cuando + 직설법","t":"너는 슬플 때 보통 뭘 하니?","e":"cuando가 습관적·반복적인 상황(~할 때마다)을 나타낼 때는 직설법을 씁니다(미래 상황일 때만 접속법). 'sentirse triste(슬프게 느끼다)'의 2인칭 단수 현재 te sientes가 맞습니다.","x":["sientes: 직설법 현재 2인칭 단수 → 정답 ✓","sienta: 접속법 1·3인칭이라 te와도 맞지 않습니다 ✗","sientas: 접속법인데 습관을 말하는 문장이라 직설법이 필요합니다 ✗","siente: 3인칭 단수라 te와 맞지 않습니다 ✗"]},{"id":"G625","q":"Madrid ____ algunos de los mejores museos del mundo.","o":["hay","es","tiene","está"],"a":2,"k":"tener vs hay","t":"마드리드에는 세계 최고의 박물관 몇 곳이 있다.","e":"주어(Madrid)가 있을 때 '~을 가지고 있다'는 tener를 씁니다. hay는 주어 없이 'En Madrid hay…'처럼 써야 합니다. estar는 특정한 것의 위치를 나타낼 때 씁니다.","x":["hay: 주어 Madrid와 함께 쓸 수 없습니다('En Madrid hay…'라면 가능) ✗","es: '~이다'라서 의미가 맞지 않습니다 ✗","tiene: 마드리드가 ~을 가지고 있다 → 정답 ✓","está: 위치를 나타내는 동사라 맞지 않습니다 ✗"]},{"id":"G626","q":"¿Cuándo ____ tus estudios?","o":["estuviste terminando","has estado terminando","estabas terminando","terminaste"],"a":3,"k":"단순과거","t":"너는 언제 학업을 마쳤니?","e":"cuándo(언제)로 과거의 특정 시점에 완결된 행동을 물을 때는 단순과거(pretérito indefinido)를 씁니다. 학업을 마친 것은 한 번에 끝난 사건이므로 terminaste가 맞습니다.","x":["estuviste terminando: 진행형이라 완결된 시점을 묻는 질문에 어색합니다 ✗","has estado terminando: 현재완료 진행형이라 맞지 않습니다 ✗","estabas terminando: 과거 진행 배경이라 맞지 않습니다 ✗","terminaste: 완결된 과거 사건 → 정답 ✓"]},{"id":"G627","q":"____ toda la noche y ahora me duele la cabeza.","o":["Estaba estudiando","Estudié","He estado estudiando","Estudiaba"],"a":2,"k":"현재완료 진행형","t":"밤새 공부했더니 지금 머리가 아파.","e":"최근까지 계속된 행동이 현재에 영향을 줄 때(그래서 지금 머리가 아프다)는 현재완료 진행형 'he estado + 현재분사'를 씁니다. 'ahora me duele'와 연결되어 현재와 관련 있다는 점이 핵심입니다.","x":["Estaba estudiando: 과거 진행 배경이라 다른 사건이 필요하고 현재와 연결이 약합니다 ✗","Estudié: 단순과거도 가능해 보이지만 지금까지의 계속성과 현재 결과를 나타내지 못합니다 ✗","He estado estudiando: 최근까지 계속한 행동 + 현재 결과 → 정답 ✓","Estudiaba: 과거 습관·묘사라 맞지 않습니다 ✗"]},{"id":"G628","q":"No ____ que Ana María se había ido a vivir a Madrid.","o":["hemos sabido","sabíamos","supimos","habíamos sabido"],"a":1,"k":"saber 불완료과거","t":"우리는 아나 마리아가 마드리드로 이사 간 줄 몰랐다.","e":"과거의 '알고 있던/모르던 상태'는 불완료과거 sabíamos로 씁니다. saber를 단순과거(supimos)로 쓰면 '알게 되었다'라는 순간적인 의미가 됩니다. que절의 과거완료(se había ido)는 그보다 앞선 일입니다.","x":["hemos sabido: 현재완료라 과거 이야기와 맞지 않습니다 ✗","sabíamos: 과거에 모르던 상태 → 정답 ✓","supimos: '알게 되었다'라는 뜻이라 부정문에서 어색합니다 ✗","habíamos sabido: 과거완료라 시제 관계가 맞지 않습니다 ✗"]},{"id":"G629","q":"Fue despedido ____ haber mentido en su currículum.","o":["de","por","para","con"],"a":1,"k":"전치사 por (원인)","t":"그는 이력서에 거짓말을 해서 해고되었다.","e":"해고된 원인·이유를 나타낼 때는 'por + 동사원형'을 씁니다. 'por haber mentido'는 '거짓말을 했기 때문에'라는 뜻입니다.","x":["de: 원인을 나타내는 이 구조에는 쓰지 않습니다 ✗","por: 원인·이유 → 정답 ✓","para: 목적이라 '거짓말하기 위해 해고됐다'가 됩니다 ✗","con: ~와 함께라서 맞지 않습니다 ✗"]},{"id":"G630","q":"¿Cuánto tiempo ____ en esta ciudad?","o":["sigues viviendo","andas viviendo","vas viviendo","llevas viviendo"],"a":3,"k":"llevar + 현재분사","t":"너는 이 도시에 산 지 얼마나 됐어?","e":"'llevar + 기간 + 현재분사'는 '~한 지 (기간)이 되다'라는 뜻으로, 기간을 묻는 '¿Cuánto tiempo llevas viviendo…?'는 아주 흔한 질문입니다.","x":["sigues viviendo: '계속 살고 있니'라는 뜻으로 기간 질문과 맞지 않습니다 ✗","andas viviendo: '이리저리 ~하고 다니다'라는 뜻이라 ✗","vas viviendo: '점차 ~해 가다'라는 뜻이라 ✗","llevas viviendo: ~한 지 얼마나 됐는지 → 정답 ✓"]},{"id":"G631","q":"No conozco ____ nadie con ese apellido.","o":["por","de","ø","a"],"a":3,"k":"사람 목적어 a","t":"나는 그 성을 가진 사람은 아무도 모른다.","e":"사람이 직접목적어일 때는 앞에 전치사 a를 붙입니다(인칭 a). nadie(아무도), alguien(누군가)도 사람을 가리키므로 'conocer a nadie'처럼 a가 필요합니다.","x":["por: 이 구조에 쓰지 않습니다 ✗","de: 이 구조에 쓰지 않습니다 ✗","ø: 사람 목적어 앞의 a가 빠지면 틀립니다 ✗","a: 사람 직접목적어 앞 인칭 a → 정답 ✓"]},{"id":"G632","q":"No es justo que no te ____ la beca.","o":["han concedido","concederían","concedieron","hayan concedido"],"a":3,"k":"접속법 현재완료","t":"너에게 장학금이 주어지지 않았다니 불공평해.","e":"'Es justo/injusto que ~'처럼 가치 판단을 나타내는 표현 뒤에는 접속법을 씁니다. 이미 일어난 일(장학금을 받지 못한 것)에 대한 판단이므로 접속법 현재완료 hayan concedido가 맞습니다.","x":["han concedido: 직설법이라 가치 판단 뒤에 쓰지 않습니다 ✗","concederían: 조건법이라 ✗","concedieron: 직설법 단순과거라 ✗","hayan concedido: 접속법 현재완료 → 정답 ✓"]},{"id":"G633","q":"¿____ tus compañeros de clase hablan francés?","o":["Cuántos de","Cuánto de","Cuántos","Cuántas de"],"a":0,"k":"cuántos de","t":"너희 반 친구들 중 몇 명이 프랑스어를 하니?","e":"'~ 중에서 몇 명'은 'cuántos/cuántas de + 정관사/소유사 + 명사'로 씁니다. compañeros는 남성 복수이므로 cuántos de가 맞습니다.","x":["Cuántos de: 남성 복수 + 중에서 → 정답 ✓","Cuánto de: 단수형이라 사람 수를 셀 때 맞지 않습니다 ✗","Cuántos: de 없이 바로 소유사 tus가 오면 틀립니다 ✗","Cuántas de: 여성형이라 compañeros와 성이 맞지 않습니다 ✗"]},{"id":"G634","q":"No creo ____ los fantasmas.","o":["en","de","sobre","ø"],"a":0,"k":"creer en","t":"나는 유령의 존재를 믿지 않아.","e":"'~의 존재를 믿다, ~을 신뢰하다'는 'creer en'으로 씁니다. 예: Creo en Dios.(나는 신을 믿는다.) 'creer que + 문장'과 구별하세요.","x":["en: creer en = ~의 존재를 믿다 → 정답 ✓","de: creer와 이 뜻으로 쓰지 않습니다 ✗","sobre: creer와 쓰지 않습니다 ✗","ø: 'creer a los fantasmas'처럼 전치사 없이는 '유령의 말을 믿다'와 같은 다른 뜻이 됩니다 ✗"]},{"id":"G635","q":"Está demostrado que hablar más de un idioma ____ abrir muchas puertas en el mundo laboral.","o":["pueden","puedan","pueda","puede"],"a":3,"k":"사실 확인 + 직설법","t":"하나 이상의 언어를 하는 것이 직업 세계에서 많은 문을 열어 줄 수 있다는 것은 입증되었다.","e":"'Está demostrado que(~는 입증되었다)'처럼 확실한 사실을 말하는 표현 뒤에는 직설법을 씁니다. 주어 'hablar más de un idioma'(동사원형 주어)는 3인칭 단수이므로 puede가 맞습니다.","x":["pueden: 복수형이라 주어와 수가 맞지 않습니다 ✗","puedan: 접속법 복수라 ✗","pueda: 접속법이라 확실한 사실 표현과 맞지 않습니다 ✗","puede: 직설법 3인칭 단수 → 정답 ✓"]},{"id":"G636","q":"____ hace un frío que pela, los niños están jugando en el jardín.","o":["Como","Debido a que","A pesar de que","Ya que"],"a":2,"k":"a pesar de que","t":"엄청 추운데도 아이들이 마당에서 놀고 있다.","e":"'a pesar de que(~임에도 불구하고)'는 양보를 나타냅니다. 매우 추운데(hace un frío que pela: 살이 벗겨질 만큼 춥다는 관용 표현) 밖에서 논다는 대조 관계이므로 정답입니다.","x":["Como: 문장 앞에서 '~이므로'(이유)라서 논리가 맞지 않습니다 ✗","Debido a que: ~때문에(원인)라서 ✗","A pesar de que: ~에도 불구하고(양보) → 정답 ✓","Ya que: ~이므로(이유)라서 ✗"]},{"id":"G637","q":"Quien ____ algo así de Manuel, seguro que no lo conoce.","o":["haya dicho","habría dicho","habría estado diciendo","habrá dicho"],"a":0,"k":"quien + 접속법","t":"마누엘에 대해 그런 말을 한 사람이라면, 분명 그를 모르는 거야.","e":"'Quien(~하는 사람)'이 특정하지 않은 누군가를 가리킬 때는 관계절에 접속법을 씁니다. 이미 일어났을 수 있는 말이므로 접속법 현재완료 haya dicho가 맞습니다.","x":["haya dicho: 불특정 인물 + 접속법 현재완료 → 정답 ✓","habría dicho: 조건완료라 맞지 않습니다 ✗","habría estado diciendo: 조건완료 진행형이라 ✗","habrá dicho: 직설법 미래완료(추측)라 불특정 선행사와 맞지 않습니다 ✗"]},{"id":"G638","q":"El formulario no ____ en su totalidad.","o":["se completaron","fue completada","fue completado","fueron completados"],"a":2,"k":"수동태 일치","t":"그 서류는 완전히 작성되지 않았다.","e":"'ser + 과거분사' 수동태에서 과거분사는 주어의 성·수에 맞춥니다. 주어 el formulario는 남성 단수이므로 'fue completado'가 맞습니다.","x":["se completaron: 복수형이라 단수 주어와 맞지 않습니다 ✗","fue completada: 여성형이라 남성 formulario와 맞지 않습니다 ✗","fue completado: 남성 단수 수동태 → 정답 ✓","fueron completados: 복수형이라 ✗"]},{"id":"G639","q":"Alfonso no está aquí, hace un par de minutos que ____.","o":["se estaba yendo","se había ido","se ha ido","se iba"],"a":2,"k":"현재완료","t":"알폰소는 여기 없어, 몇 분 전에 가 버렸어.","e":"방금 일어나 현재와 연결된 일(그래서 지금 여기 없다)은 현재완료로 표현합니다. irse(떠나 버리다)의 현재완료 se ha ido가 맞습니다. 'hace + 시간 + que'와 함께 쓰여 '~전에 가 버렸다'가 됩니다.","x":["se estaba yendo: 과거진행이라 지금 없다는 사실과 맞지 않습니다 ✗","se había ido: 과거완료로, 다른 과거 시점이 필요합니다 ✗","se ha ido: 현재완료 → 정답 ✓","se iba: 불완료과거라 완결된 사건이 아닙니다 ✗"]},{"id":"G640","q":"Las clases ____ el próximo 10 de septiembre.","o":["empiezan","están empezando","empezaran","empiecen"],"a":0,"k":"현재형의 미래","t":"수업은 다가오는 9월 10일에 시작한다.","e":"예정·일정이 확정된 미래는 직설법 현재로 표현할 수 있습니다. 'Las clases empiezan el lunes(수업은 월요일에 시작한다)'처럼 시간표에 자주 씁니다.","x":["empiezan: 확정된 일정 = 현재형 → 정답 ✓","están empezando: 지금 시작하는 중이라는 뜻이라 ✗","empezaran: 접속법 과거라 평서문에 쓰지 않습니다 ✗","empiecen: 접속법 현재라 ✗"]},{"id":"G641","q":"Creo que esa chica ____ está aprovechando de ti.","o":["le","lo","se","ø"],"a":2,"k":"aprovecharse de","t":"내 생각에 그 여자애가 너를 이용하고 있는 것 같아.","e":"'aprovecharse de alguien'은 '~을 (나쁜 의미로) 이용하다'라는 뜻의 재귀 동사입니다. 주어가 esa chica(3인칭)이므로 재귀대명사 se가 필요합니다.","x":["le: 간접목적격이라 재귀 동사에 맞지 않습니다 ✗","lo: 직접목적격이라 ✗","se: aprovecharse의 재귀대명사 → 정답 ✓","ø: se 없이 'aprovechar de'라고 하지 않습니다 ✗"]},{"id":"G642","q":"Según las encuestas, dos ____ cada diez personas van a votar a ese partido.","o":["a","de","en","para"],"a":1,"k":"비율 표현 de cada","t":"여론조사에 따르면 열 명 중 두 명이 그 정당에 투표할 것이다.","e":"비율을 나타낼 때 '(숫자) de cada (숫자)'로 '~명 중 ~명'이라고 표현합니다. 예: uno de cada tres(세 명 중 한 명).","x":["a: 이 표현에 쓰지 않습니다 ✗","de: 'dos de cada diez' → 정답 ✓","en: 이 표현에 쓰지 않습니다 ✗","para: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G643","q":"Es raro que Inés no nos ____ todavía.","o":["haya respondido","había respondido","ha respondido","respondiese"],"a":0,"k":"접속법 현재완료","t":"이네스가 아직 우리에게 답장을 안 했다니 이상하다.","e":"'Es raro que(~라니 이상하다)'는 감정·판단 표현이라 접속법이 옵니다. todavía(아직)와 함께 현재까지 완료되지 않은 일이므로 접속법 현재완료 haya respondido가 맞습니다.","x":["haya respondido: 접속법 현재완료 → 정답 ✓","había respondido: 직설법 과거완료라 ✗","ha respondido: 직설법 현재완료라 ✗","respondiese: 접속법 과거로, 주절이 현재(Es)라 시제가 맞지 않습니다 ✗"]},{"id":"G644","q":"Para ya, estás abusando ____ mi paciencia.","o":["para","a","con","de"],"a":3,"k":"abusar de","t":"그만해, 너 내 인내심을 너무 시험하고(남용하고) 있어.","e":"abusar(남용하다, 지나치게 이용하다)는 전치사 de와 함께 씁니다. 예: abusar de la confianza(신뢰를 악용하다).","x":["para: abusar와 쓰지 않습니다 ✗","a: abusar와 쓰지 않습니다 ✗","con: abusar와 이 뜻으로는 쓰지 않습니다 ✗","de: abusar de = ~을 남용하다 → 정답 ✓"]},{"id":"G645","q":"Estoy harto de que me ____ como si fuera tonto.","o":["trataba","trate","tratase","trata"],"a":1,"k":"감정 + 접속법","t":"그 사람이 나를 바보처럼 대하는 것에 질렸어.","e":"'estar harto de que(~에 질리다)'는 감정 표현이므로 que절에 접속법을 씁니다. 주절이 현재(Estoy)이므로 접속법 현재 trate(그/그녀가 대하다)가 맞습니다. 'como si' 뒤에는 접속법 과거(fuera)가 옵니다.","x":["trataba: 직설법 불완료과거라 ✗","trate: 접속법 현재 → 정답 ✓","tratase: 접속법 과거로, 주절 현재와 시제가 맞지 않습니다 ✗","trata: 직설법 현재라 ✗"]},{"id":"G646","q":"Es en primavera ____ tengo más problemas con la alergia.","o":["cuando","donde","cuanto","como"],"a":0,"k":"강조 구문 cuando","t":"내가 알레르기로 가장 고생하는 때는 바로 봄이다.","e":"'Es + 강조할 말 + 관계사' 구문(분열문)에서 관계사는 강조하는 말의 종류에 맞춥니다. 강조 대상이 시간(en primavera)이므로 cuando를 씁니다. 장소면 donde, 방법이면 como를 씁니다.","x":["cuando: 시간 강조 → 정답 ✓","donde: 장소를 강조할 때 씁니다 ✗","cuanto: 양(~만큼)을 나타내서 ✗","como: 방법을 강조할 때 씁니다 ✗"]},{"id":"G647","q":"Aunque ____ una piscina en su casa, nunca se mete.","o":["hay","habría","hubo","ha habido"],"a":0,"k":"aunque + 직설법","t":"그의 집에 수영장이 있는데도 그는 한 번도 들어가지 않는다.","e":"aunque 뒤에 실제 사실(수영장이 있다는 것)이 오면 직설법을 씁니다. 존재를 나타내는 haber의 현재형 hay가 맞습니다. 사실 여부가 불확실하거나 중요하지 않을 때는 접속법(haya)을 씁니다.","x":["hay: 현재 사실 + 직설법 → 정답 ✓","habría: 조건법이라 ✗","hubo: 단순과거라 현재 습관(nunca se mete)과 맞지 않습니다 ✗","ha habido: 현재완료라 맞지 않습니다 ✗"]},{"id":"G648","q":"Aquel invierno ____ realmente duro.","o":["ha sido","ha estado siendo","fue","estuvo siendo"],"a":2,"k":"단순과거","t":"그해 겨울은 정말 혹독했다.","e":"'aquel invierno(그해 겨울)'처럼 이미 끝난 과거 기간을 전체적으로 평가할 때는 단순과거를 씁니다. 그래서 fue(ser의 단순과거)가 맞습니다.","x":["ha sido: 현재완료는 aquel(그때의)과 어울리지 않습니다 ✗","ha estado siendo: ser를 진행형으로 이렇게 쓰지 않습니다 ✗","fue: 완결된 과거 기간 평가 → 정답 ✓","estuvo siendo: 부자연스러운 진행형입니다 ✗"]},{"id":"G649","q":"Llevo desde enero sin ____ a Marta.","o":["he visto","veo","estar viendo","ver"],"a":3,"k":"sin + 동사원형","t":"나는 1월부터 마르타를 못 보고 있다.","e":"'llevar + 기간 + sin + 동사원형'은 '~동안 ~하지 않고 있다'는 뜻입니다. 전치사 sin 뒤에는 동사원형이 옵니다.","x":["he visto: 전치사 뒤에 활용 동사는 올 수 없습니다 ✗","veo: 전치사 뒤에 활용 동사는 올 수 없습니다 ✗","estar viendo: 이 구조에서는 쓰지 않습니다 ✗","ver: sin + 동사원형 → 정답 ✓"]},{"id":"G650","q":"¡No te olvides ____ nosotros!","o":["sobre","a","de","con"],"a":2,"k":"olvidarse de","t":"우리를 잊지 마!","e":"olvidar는 재귀 형태(olvidarse)로 쓰면 전치사 de가 필요합니다: olvidarse de algo/alguien. 재귀 없이 쓰면 'No nos olvides'처럼 전치사가 없습니다.","x":["sobre: 쓰지 않습니다 ✗","a: 쓰지 않습니다 ✗","de: olvidarse de → 정답 ✓","con: 쓰지 않습니다 ✗"]},{"id":"G651","q":"Compré un dulce para cada uno. ____ esta manera, nadie se quejó.","o":["Por","De","Con","En"],"a":1,"k":"de esta manera","t":"나는 각자에게 사탕을 하나씩 샀다. 이렇게 해서 아무도 불평하지 않았다.","e":"'de esta manera / de este modo'는 '이런 방식으로, 그렇게 해서'라는 뜻의 고정 표현으로, 전치사 de를 씁니다.","x":["Por: 'por esta manera'라고 하지 않습니다 ✗","De: de esta manera = 이렇게 해서 → 정답 ✓","Con: 이 표현에 쓰지 않습니다 ✗","En: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G652","q":"A continuación, gire ____ la derecha.","o":["a","en","para","por"],"a":0,"k":"girar a","t":"그다음 오른쪽으로 도세요.","e":"방향을 바꿀 때는 'girar a la derecha/izquierda(오른쪽/왼쪽으로 돌다)'처럼 전치사 a를 씁니다. 길 안내에서 매우 자주 나옵니다. gire는 usted에게 하는 명령형입니다.","x":["a: 방향 전환 → 정답 ✓","en: 이 표현에 쓰지 않습니다 ✗","para: 'para la derecha'는 '오른쪽 방향으로'라는 구어 표현이 일부 있지만 표준 표현은 a입니다 ✗","por: '오른쪽을 통해'라는 뜻이라 ✗"]},{"id":"G653","q":"¿Me ayudas ____ rellenar este impreso?","o":["de","en","ø","a"],"a":3,"k":"ayudar a","t":"이 서식 작성하는 거 좀 도와줄래?","e":"'ayudar a alguien a + 동사원형'은 '~가 ~하는 것을 돕다'라는 뜻으로 동사원형 앞에 전치사 a가 필요합니다. rellenar un impreso는 스페인에서 '서식을 작성하다'라는 뜻입니다.","x":["de: ayudar와 쓰지 않습니다 ✗","en: 명사와는 'ayudar en algo'가 가능하지만 동사원형 앞에서는 a를 씁니다 ✗","ø: 전치사가 빠지면 틀립니다 ✗","a: ayudar a + 동사원형 → 정답 ✓"]},{"id":"G654","q":"¡Qué caro ____ el aceite de girasol últimamente!","o":["está","es","esté","sea"],"a":0,"k":"estar + 가격","t":"요즘 해바라기유 정말 비싸네!","e":"가격이 일시적으로 변한 상태(요즘 비싸졌다)는 estar로 표현합니다. últimamente(최근에)가 변화된 상태임을 보여 줍니다. ser caro는 원래 비싼 물건의 성질을 말할 때 씁니다.","x":["está: 일시적 상태(요즘 비싸다) → 정답 ✓","es: 본래 성질을 말해서 últimamente와 덜 어울립니다 ✗","esté: 접속법이라 감탄문에 쓰지 않습니다 ✗","sea: 접속법이라 ✗"]},{"id":"G655","q":"¿Conocéis a ____ de esos chicos que están allí?","o":["alguien","algún","alguno","ninguno"],"a":2,"k":"alguno de","t":"너희 저기 있는 남자애들 중 누구 아는 사람 있어?","e":"'~ 중의 누군가'는 'alguno de + 복수 명사'로 씁니다. alguien은 뒤에 de를 붙여 집단 중 하나를 고르는 데 쓰지 않고, algún은 명사 앞에서만 씁니다.","x":["alguien: 'alguien de esos chicos'는 쓰지 않습니다 ✗","algún: 명사 바로 앞에서만 쓰는 줄임형입니다 ✗","alguno: alguno de = ~ 중 누군가 → 정답 ✓","ninguno: 부정어라 긍정 의문문에 맞지 않습니다 ✗"]},{"id":"G656","q":"Ese actor no se llevó el Óscar; ____, todos piensan que se lo merecía.","o":["no obstante","por tanto","de lo contrario","por eso"],"a":0,"k":"no obstante","t":"그 배우는 오스카를 받지 못했다. 그럼에도 불구하고 모두 그가 받을 자격이 있었다고 생각한다.","e":"'no obstante'는 '그럼에도 불구하고, 하지만'이라는 뜻으로 sin embargo와 같습니다. 상을 못 받았지만 모두 자격이 있었다고 생각한다는 대조 관계이므로 정답입니다.","x":["no obstante: 그럼에도 불구하고(대조) → 정답 ✓","por tanto: 따라서(결과)라 논리가 맞지 않습니다 ✗","de lo contrario: 그렇지 않으면이라 ✗","por eso: 그래서(결과)라 ✗"]},{"id":"G657","q":"¿Cuántas personas crees que ____ en la próxima reunión?","o":["habrán","habrá","hay","van a haber"],"a":1,"k":"haber 단수","t":"다음 회의에 몇 명이 있을 것 같아?","e":"존재를 나타내는 haber(있다)는 뒤 명사가 복수여도 항상 3인칭 단수로 씁니다(hay, había, habrá). 그래서 'habrán'이 아니라 habrá가 맞습니다. 미래 회의에 대한 추측이므로 미래형이 자연스럽습니다.","x":["habrán: 존재의 haber는 복수형을 쓰지 않습니다 ✗","habrá: 미래 3인칭 단수 → 정답 ✓","hay: 현재형이라 próxima reunión(다음 회의)과 맞지 않습니다 ✗","van a haber: haber는 단수로 'va a haber'가 되어야 합니다 ✗"]},{"id":"G658","q":"Si no surge ningún imprevisto, mañana a esta hora ya ____ a Barcelona.","o":["habremos llegado","hemos llegado","llegásemos","llegaremos"],"a":0,"k":"미래완료","t":"예상치 못한 일이 없다면, 내일 이 시간쯤에는 우리는 이미 바르셀로나에 도착해 있을 거야.","e":"미래의 어느 시점(내일 이 시간)까지 이미 끝나 있을 일은 미래완료 'habré/habremos + 과거분사'로 씁니다. ya(이미)가 완료 의미를 보여 줍니다.","x":["habremos llegado: 미래완료 → 정답 ✓","hemos llegado: 현재완료라 내일과 맞지 않습니다 ✗","llegásemos: 접속법 과거라 ✗","llegaremos: 단순미래는 '도착할 것이다'라서 ya와 함께 '이미 도착해 있다'는 의미를 못 냅니다 ✗"]},{"id":"G659","q":"Intenté evitar el accidente, pero fue ____ vano.","o":["en","a","de","por"],"a":0,"k":"en vano","t":"사고를 피하려고 했지만 헛수고였다.","e":"'en vano'는 '헛되이, 소용없이'라는 뜻의 고정 표현입니다. 'fue en vano(헛수고였다)'로 자주 씁니다.","x":["en: en vano = 헛되이 → 정답 ✓","a: 이 표현에 쓰지 않습니다 ✗","de: 이 표현에 쓰지 않습니다 ✗","por: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G660","q":"Este verano ____ mucho el color rosa.","o":["se lleva","lleva","está llevando","es llevado"],"a":0,"k":"llevarse (유행)","t":"올여름에는 분홍색이 많이 유행한다.","e":"'se lleva'는 '(옷·색깔 등이) 유행이다, 많이 입는다'라는 뜻의 무인칭 se 표현입니다. 예: Se llevan los pantalones anchos.(통 넓은 바지가 유행이다.)","x":["se lleva: 유행하다 → 정답 ✓","lleva: 주어가 '가지고 가다/입다'가 되어 의미가 맞지 않습니다 ✗","está llevando: 진행형이라 유행의 뜻이 되지 않습니다 ✗","es llevado: 수동태로 '운반되다'라는 뜻이 되어 ✗"]},{"id":"G661","q":"Ana y Almudena ____ cada día. No pueden estar ni un día sin hablar.","o":["se llaman","se llamen","llaman","se llama"],"a":0,"k":"상호 재귀 se","t":"아나와 알무데나는 매일 서로 전화한다. 하루도 이야기하지 않고는 못 견딘다.","e":"두 사람이 '서로' ~할 때는 재귀대명사 se를 써서 상호 동작을 나타냅니다. 주어가 복수(Ana y Almudena)이고 매일의 습관이므로 직설법 현재 se llaman이 맞습니다.","x":["se llaman: 서로 전화하다(현재) → 정답 ✓","se llamen: 접속법이라 평서문에 쓰지 않습니다 ✗","llaman: se가 없으면 '(누군가에게) 전화한다'로 '서로'의 의미가 없습니다 ✗","se llama: 단수라 두 사람 주어와 맞지 않습니다 ✗"]},{"id":"G662","q":"Trabaja ____ que no tiene tiempo para sus aficiones.","o":["tan","tanto","tantos","tanta"],"a":1,"k":"tanto que","t":"그는 일을 너무 많이 해서 취미 생활할 시간이 없다.","e":"'동사 + tanto que ~'는 '너무 많이 ~해서 ~하다'라는 결과 표현입니다. 동사(trabaja)를 수식할 때는 부사 tanto를 쓰고, 형용사·부사 앞에서는 tan을 씁니다.","x":["tan: 형용사·부사 앞에 씁니다(tan cansado que) ✗","tanto: 동사 수식 → 정답 ✓","tantos: 남성 복수 명사 앞에 씁니다 ✗","tanta: 여성 단수 명사 앞에 씁니다 ✗"]},{"id":"G663","q":"Una vez ____ por ambas partes, el contrato será válido.","o":["firmando","firmar","estar firmado","firmado"],"a":3,"k":"과거분사 구문","t":"양측이 서명하고 나면 계약은 유효해질 것이다.","e":"'una vez + 과거분사'는 '일단 ~되고 나면'이라는 뜻입니다. 과거분사 firmado는 계약(el contrato)에 맞춰 남성 단수입니다. 'por ambas partes'는 '양측에 의해'라는 뜻입니다.","x":["firmando: 현재분사(서명하면서)라 이 구조에 맞지 않습니다 ✗","firmar: 동사원형이라 ✗","estar firmado: 'una vez estar…'라고 하지 않습니다 ✗","firmado: una vez + 과거분사 → 정답 ✓"]},{"id":"G664","q":"Eugenia no gana tanto dinero ____ tú.","o":["cuanto","como","que","de"],"a":1,"k":"tanto como 비교","t":"에우헤니아는 너만큼 돈을 많이 벌지 않는다.","e":"동등 비교(~만큼)는 'tanto/tanta/tantos/tantas + 명사 + como'로 씁니다. 'más ~ que'와 혼동해 que를 쓰기 쉬우니 주의하세요.","x":["cuanto: 'tanto… cuanto'는 쓰지 않습니다 ✗","como: tanto… como → 정답 ✓","que: 우등·열등 비교(más/menos… que)에 씁니다 ✗","de: 숫자 앞 비교(más de 100)에 씁니다 ✗"]},{"id":"G665","q":"____ iban llegando los espectadores, me iba poniendo más nerviosa.","o":["Nada más","Al","Hasta que","A medida que"],"a":3,"k":"a medida que","t":"관객들이 하나둘 도착할수록 나는 점점 더 긴장되었다.","e":"'a medida que'는 '~함에 따라, ~할수록'이라는 뜻으로 두 변화가 함께 진행될 때 씁니다. 'ir + 현재분사(iban llegando, me iba poniendo)'가 점진적인 변화를 보여 줍니다.","x":["Nada más: '~하자마자'라는 뜻으로 뒤에 동사원형이 옵니다 ✗","Al: 'al + 동사원형' 형태라 활용 동사와 쓸 수 없습니다 ✗","Hasta que: ~할 때까지라 의미가 맞지 않습니다 ✗","A medida que: ~할수록 → 정답 ✓"]},{"id":"G666","q":"Este invierno ____ el color gris.","o":["se lleva","es llevado","se lleve","lleva"],"a":0,"k":"llevarse (유행)","t":"이번 겨울에는 회색이 유행한다.","e":"옷이나 색이 '유행하다'는 'llevarse'를 무인칭 se 형태로 씁니다: se lleva + 단수 / se llevan + 복수. 사실을 말하는 평서문이므로 직설법 se lleva가 맞습니다.","x":["se lleva: 유행이다 → 정답 ✓","es llevado: 수동태로 '운반된다'는 뜻이 됩니다 ✗","se lleve: 접속법이라 평서문에 쓰지 않습니다 ✗","lleva: se가 없으면 유행의 의미가 되지 않습니다 ✗"]},{"id":"G667","q":"Nos habló como si ____ extraños.","o":["seríamos","fuéramos","somos","seamos"],"a":1,"k":"como si + 접속법","t":"그는 우리가 낯선 사람인 것처럼 말했다.","e":"'como si(마치 ~인 것처럼)' 뒤에는 항상 접속법 과거(또는 과거완료)가 옵니다. 그래서 ser의 접속법 과거 fuéramos가 맞습니다.","x":["seríamos: 조건법이라 ✗","fuéramos: como si + 접속법 과거 → 정답 ✓","somos: 직설법이라 ✗","seamos: 접속법 현재는 como si 뒤에 쓰지 않습니다 ✗"]},{"id":"G668","q":"No creo que ____ los resultados de las elecciones hasta la medianoche.","o":["sabemos","sepamos","sabremos","hemos sabido"],"a":1,"k":"no creer + 접속법","t":"나는 우리가 자정 전에는 선거 결과를 알 수 있을 거라고 생각하지 않아.","e":"'no creo que'처럼 믿음을 부정하면 que절에 접속법을 씁니다. 그래서 saber의 접속법 현재 sepamos가 맞습니다. 접속법 현재는 미래 의미도 나타냅니다.","x":["sabemos: 직설법이라 'no creo que' 뒤에 쓰지 않습니다 ✗","sepamos: 접속법 현재 → 정답 ✓","sabremos: 직설법 미래라 ✗","hemos sabido: 직설법 현재완료라 ✗"]},{"id":"G669","q":"Dijiste que nos llamarías cuando ____, pero no lo hiciste.","o":["llegues","llegarías","llegas","llegases"],"a":3,"k":"과거 속 미래 cuando","t":"너는 도착하면 우리에게 전화하겠다고 했지만, 하지 않았다.","e":"cuando가 미래 시점을 나타내면 접속법을 쓰는데, 주절이 과거(Dijiste… llamarías)이므로 접속법 과거 llegases(=llegaras)를 씁니다. 시제 일치에 따라 현재(llegues)가 과거(llegases)로 바뀐 것입니다.","x":["llegues: 접속법 현재라 과거 주절과 시제가 맞지 않습니다 ✗","llegarías: cuando 뒤에는 조건법을 쓰지 않습니다 ✗","llegas: 직설법 현재라 ✗","llegases: 접속법 과거 → 정답 ✓"]},{"id":"G670","q":"No me fío ____ ese hombre, no me da buena espina.","o":["en","a","de","con"],"a":2,"k":"fiarse de","t":"나는 그 남자를 믿지 않아, 왠지 느낌이 안 좋아.","e":"'fiarse de alguien'은 '~을 믿다, 신뢰하다'라는 재귀 동사로 전치사 de를 씁니다. 'no me da buena espina'는 '느낌이 좋지 않다(수상하다)'라는 관용 표현입니다.","x":["en: 'confiar en'이라면 가능하지만 fiarse와는 쓰지 않습니다 ✗","a: fiarse와 쓰지 않습니다 ✗","de: fiarse de → 정답 ✓","con: fiarse와 쓰지 않습니다 ✗"]},{"id":"G671","q":"Nos mira como si ____ algo en nuestra contra.","o":["tenía","tendría","tuviera","tenga"],"a":2,"k":"como si + 접속법","t":"그는 마치 우리에게 뭔가 앙심이라도 품은 것처럼 우리를 쳐다본다.","e":"'como si'는 주절이 현재(mira)여도 항상 접속법 과거가 옵니다. 그래서 tener의 접속법 과거 tuviera가 맞습니다. 'tener algo en contra de alguien'은 '~에게 불만·반감이 있다'는 뜻입니다.","x":["tenía: 직설법이라 ✗","tendría: 조건법이라 ✗","tuviera: 접속법 과거 → 정답 ✓","tenga: 접속법 현재는 como si 뒤에 쓰지 않습니다 ✗"]},{"id":"G672","q":"Aquel día hacía ____ calor insoportable.","o":["el","un","uno","ø"],"a":1,"k":"부정관사 un","t":"그날은 견딜 수 없을 정도로 더웠다.","e":"'hacer calor(덥다)'는 보통 관사 없이 쓰지만, calor 뒤에 형용사(insoportable)가 붙어 정도를 묘사하면 부정관사 un을 넣습니다: 'hacía un calor insoportable'. calor는 남성 명사입니다.","x":["el: 특정한 그 더위가 아니라서 어색합니다 ✗","un: 형용사로 묘사되는 더위 앞 부정관사 → 정답 ✓","uno: 명사 앞에서는 un으로 줄어듭니다 ✗","ø: 형용사가 붙으면 관사가 필요합니다 ✗"]},{"id":"G673","q":"Si no nos ____ dicho que no había clase, ahora estaríamos esperando a la profesora.","o":["hayas","hubieras","habrías","has"],"a":1,"k":"si + 접속법 과거완료","t":"네가 수업이 없다고 말해 주지 않았다면, 지금 우리는 선생님을 기다리고 있을 거야.","e":"과거 사실과 반대되는 가정(~하지 않았다면)은 'si + 접속법 과거완료(hubieras + 과거분사)'를 씁니다. 결과가 현재에 미치므로 주절은 조건법 estaríamos입니다(혼합 가정문).","x":["hayas: 접속법 현재완료는 si 뒤에 쓰지 않습니다 ✗","hubieras: 접속법 과거완료 → 정답 ✓","habrías: 조건완료라 si 뒤에 쓰지 않습니다 ✗","has: 직설법 현재완료라 가정 의미가 안 됩니다 ✗"]},{"id":"G674","q":"Disculpe, señora, ¿es ____ esta maleta?","o":["suya","la tuya","tuya","su"],"a":0,"k":"usted 소유사","t":"실례합니다, 부인. 이 여행 가방이 당신 것인가요?","e":"'señora'에게 존댓말(usted)로 말하고 있으므로 소유대명사는 suyo/suya(당신의 것)를 씁니다. maleta가 여성 단수라 suya가 됩니다. ser 뒤에서는 관사 없이 'es suya'라고 합니다.","x":["suya: usted의 소유(여성 단수) → 정답 ✓","la tuya: tú에게 쓰는 형태라 존댓말과 맞지 않습니다 ✗","tuya: tú에게 쓰는 형태라 ✗","su: 명사 앞에만 쓰는 소유형용사입니다 ✗"]},{"id":"G675","q":"Los trabajadores más eficientes son los que ____ aprovechan bien el tiempo mientras trabajan.","o":["le","se lo","se","ø"],"a":3,"k":"aprovechar (비재귀)","t":"가장 효율적인 직원은 일하는 동안 시간을 잘 활용하는 사람들이다.","e":"'aprovechar algo'는 '~을 활용하다'라는 뜻의 일반 타동사로, 목적어 el tiempo가 이미 있으므로 대명사가 필요 없습니다. 'aprovecharse de'는 '~을 (나쁘게) 이용하다'라는 다른 뜻입니다.","x":["le: 간접목적어가 필요 없습니다 ✗","se lo: 대명사가 중복되어 틀립니다 ✗","se: aprovecharse는 de와 함께 쓰며 '악용하다'라는 뜻이라 ✗","ø: aprovechar el tiempo → 정답 ✓"]},{"id":"G676","q":"Le cuesta mucho concentrarse. ____, hace bastante bien las tareas de la escuela.","o":["Pero","Por lo tanto","Sin embargo","De lo contrario"],"a":2,"k":"sin embargo","t":"그는 집중하는 걸 매우 힘들어한다. 그럼에도 불구하고 학교 숙제는 꽤 잘한다.","e":"'Sin embargo'는 문장 맨 앞에서 쉼표와 함께 '그럼에도 불구하고'라는 대조를 나타냅니다. 'Pero'도 대조이지만 마침표 뒤 쉼표와 함께 쓰는 연결어로는 sin embargo가 자연스럽습니다.","x":["Pero: 대조이지만 'Pero,'처럼 쉼표를 붙여 쓰는 형태는 부자연스럽습니다 ✗","Por lo tanto: 따라서(결과)라 논리가 맞지 않습니다 ✗","Sin embargo: 그럼에도 불구하고 → 정답 ✓","De lo contrario: 그렇지 않으면이라 ✗"]},{"id":"G677","q":"Este año está ____ moda el color verde.","o":["por","a","de","con"],"a":2,"k":"estar de moda","t":"올해는 초록색이 유행이다.","e":"'estar de moda'는 '유행하고 있다'라는 고정 표현으로 전치사 de를 씁니다. 반대말은 'pasado de moda(유행이 지난)'입니다.","x":["por: 이 표현에 쓰지 않습니다 ✗","a: 'a la moda(유행에 맞게)'처럼 관사가 필요하고 estar와는 de를 씁니다 ✗","de: estar de moda → 정답 ✓","con: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G678","q":"Hoy el mar está ____ calma.","o":["con","de","en","a"],"a":2,"k":"estar en calma","t":"오늘 바다는 잔잔하다.","e":"'estar en calma'는 '고요하다, 잔잔하다'라는 고정 표현입니다. 바다·날씨·분위기 등이 평온할 때 씁니다.","x":["con: 이 표현에 쓰지 않습니다 ✗","de: 이 표현에 쓰지 않습니다 ✗","en: estar en calma → 정답 ✓","a: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G679","q":"Yo en tu lugar ____ la verdad.","o":["diría","dirías","diga","dijera"],"a":0,"k":"조언 조건법","t":"내가 너라면 진실을 말할 거야.","e":"'Yo en tu lugar(내가 네 입장이라면)'는 조언할 때 쓰는 표현으로 뒤에 조건법이 옵니다. 주어가 yo이므로 decir의 조건법 1인칭 diría가 맞습니다.","x":["diría: 조건법 1인칭 단수 → 정답 ✓","dirías: 2인칭이라 주어 yo와 맞지 않습니다 ✗","diga: 접속법 현재라 ✗","dijera: 접속법 과거로 si절에 쓰는 형태입니다 ✗"]},{"id":"G680","q":"¿Cada cuánto tiempo ____ esta piscina?","o":["son limpiadas","se limpian","limpiarse","se limpia"],"a":3,"k":"수동의 se","t":"이 수영장은 얼마나 자주 청소하나요?","e":"행위자보다 대상이 중요할 때 'se + 3인칭 동사'(수동의 se)를 씁니다. 동사는 대상(esta piscina, 단수)에 맞추므로 se limpia가 맞습니다.","x":["son limpiadas: 복수형이라 단수 piscina와 맞지 않습니다 ✗","se limpian: 복수형이라 ✗","limpiarse: 동사원형이라 활용 동사가 필요합니다 ✗","se limpia: 수동의 se + 단수 → 정답 ✓"]},{"id":"G681","q":"¿No recuerdas ____ lo que pasó aquel día?","o":["ø","por","de","a"],"a":0,"k":"recordar 타동사","t":"그날 무슨 일이 있었는지 기억 안 나?","e":"recordar(기억하다)는 타동사로 전치사 없이 바로 목적어를 받습니다. 'acordarse de'와 혼동하지 마세요: ¿No te acuerdas de lo que pasó?","x":["ø: recordar + 목적어 → 정답 ✓","por: 쓰지 않습니다 ✗","de: 'acordarse de'에는 쓰지만 recordar에는 쓰지 않습니다 ✗","a: 사람 목적어가 아니라 쓰지 않습니다 ✗"]},{"id":"G682","q":"____ te lo he dicho, no sé dónde están tus llaves.","o":["Casi","Todavía","Ya","Aún"],"a":2,"k":"ya (이미)","t":"이미 말했잖아, 네 열쇠가 어디 있는지 난 몰라.","e":"'Ya te lo he dicho'는 '이미(벌써) 말했잖아'라는 뜻으로 짜증이나 반복을 나타낼 때 자주 씁니다. ya는 완료된 일을 강조합니다.","x":["Casi: 거의라는 뜻으로 '거의 말했다'가 되어 어색합니다 ✗","Todavía: 아직이라는 뜻으로 긍정 완료문과 맞지 않습니다 ✗","Ya: 이미 → 정답 ✓","Aún: 아직이라는 뜻이라 ✗"]},{"id":"G683","q":"Eva siempre ____ a su hermana.","o":["defiende","se defiende","se defienda","defienda"],"a":0,"k":"defender 타동사","t":"에바는 항상 자기 여동생(언니)을 감싼다.","e":"'defender a alguien'은 '~을 방어하다, 편들다'라는 타동사입니다. 목적어(a su hermana)가 있으므로 재귀 se는 필요 없고, 습관이므로 직설법 defiende가 맞습니다.","x":["defiende: 직설법 현재 → 정답 ✓","se defiende: '자기 자신을 방어한다'라는 뜻이 되어 ✗","se defienda: 접속법이고 재귀라 ✗","defienda: 접속법이라 평서문에 쓰지 않습니다 ✗"]},{"id":"G684","q":"Mientras yo ____, mi mujer trabajaba en el jardín.","o":["cocinaba","cocino","cociné","estuve cocinando"],"a":0,"k":"불완료과거 동시","t":"내가 요리하는 동안 아내는 정원에서 일하고 있었다.","e":"mientras로 연결된 두 과거 행동이 동시에 진행 중이었을 때는 둘 다 불완료과거로 씁니다. trabajaba와 맞춰 cocinaba가 정답입니다.","x":["cocinaba: 과거의 동시 진행 → 정답 ✓","cocino: 현재형이라 과거 trabajaba와 맞지 않습니다 ✗","cociné: 완결된 단순과거라 동시 진행 묘사에 맞지 않습니다 ✗","estuve cocinando: 완결된 기간을 나타내서 배경 묘사에 어색합니다 ✗"]},{"id":"G685","q":"De joven me gustaba ____ dulce, pero ahora prefiero otros sabores.","o":["los","lo","la","las"],"a":1,"k":"중성 lo + 형용사","t":"어렸을 때는 단 걸 좋아했지만, 지금은 다른 맛을 더 좋아한다.","e":"'lo + 형용사'는 '~한 것'이라는 추상적 의미를 만듭니다. 'lo dulce'는 '단 것(단맛)'이라는 뜻입니다. 예: lo bueno(좋은 점), lo importante(중요한 것).","x":["los: 남성 복수 관사라 단수 형용사 dulce와 맞지 않습니다 ✗","lo: 중성 관사 + 형용사 → 정답 ✓","la: 여성 관사라 명사 없이 쓸 수 없습니다 ✗","las: 여성 복수라 ✗"]},{"id":"G686","q":"Gregorio parece ____ muy seguro de lo que dice.","o":["que esté","estar","estado","estando"],"a":1,"k":"parecer + 동사원형","t":"그레고리오는 자기 말에 매우 확신이 있는 것 같다.","e":"주어가 있을 때 'parecer + 동사원형'은 '~인 것 같다'라는 뜻입니다. 'Parece que está seguro'처럼 que를 쓰면 직설법이 오고 주어 위치가 달라집니다.","x":["que esté: 'parece que' 뒤 긍정문은 직설법이고 이 어순에서는 어색합니다 ✗","estar: parecer + 동사원형 → 정답 ✓","estado: 과거분사라 ✗","estando: 현재분사라 ✗"]},{"id":"G687","q":"Me da mucha rabia que ____ el partido.","o":["hemos perdido","perdimos","perdíamos","hayamos perdido"],"a":3,"k":"감정 + 접속법","t":"우리가 경기에 졌다는 게 너무 화가 나.","e":"'Me da rabia que(~해서 화가 나다)'는 감정 표현이므로 접속법이 옵니다. 이미 일어난 일(경기에 진 것)이므로 접속법 현재완료 hayamos perdido가 맞습니다.","x":["hemos perdido: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","perdimos: 직설법이라 ✗","perdíamos: 직설법이라 ✗","hayamos perdido: 접속법 현재완료 → 정답 ✓"]},{"id":"G688","q":"Me llamó nada más ____ que le habían dado el puesto de trabajo.","o":["sabido","sabiendo","saber","al saber"],"a":2,"k":"nada más + 동사원형","t":"그는 자신이 그 일자리를 얻었다는 걸 알자마자 나에게 전화했다.","e":"'nada más + 동사원형'은 '~하자마자'라는 뜻입니다. 같은 뜻의 'al + 동사원형'이 있지만 nada más와 al을 함께 쓰지는 않습니다.","x":["sabido: 과거분사라 ✗","sabiendo: 현재분사라 ✗","saber: nada más + 동사원형 → 정답 ✓","al saber: 'nada más al saber'처럼 겹쳐 쓰지 않습니다 ✗"]},{"id":"G689","q":"Jorge siempre ha tenido facilidad ____ hacer nuevos amigos.","o":["a","por","para","sobre"],"a":2,"k":"facilidad para","t":"호르헤는 항상 새로운 친구를 쉽게 사귀는 재능이 있었다.","e":"'tener facilidad para + 동사원형/명사'는 '~하는 데 재능이 있다, ~을 쉽게 하다'라는 표현입니다. 능력·적성을 나타낼 때 para를 씁니다.","x":["a: 이 표현에 쓰지 않습니다 ✗","por: 이 표현에 쓰지 않습니다 ✗","para: facilidad para → 정답 ✓","sobre: 이 표현에 쓰지 않습니다 ✗"]},{"id":"G690","q":"Hice el pastel exactamente ____ tú me dijiste y salió muy bien.","o":["qué","como","cómo","como que"],"a":1,"k":"como (방식)","t":"나는 네가 말해 준 대로 정확하게 케이크를 만들었고 아주 잘 나왔다.","e":"'como'는 관계부사로 '~하는 대로, ~처럼'이라는 방식을 나타냅니다. 악센트가 있는 cómo는 의문사(어떻게)일 때 씁니다.","x":["qué: 의문사 '무엇'이라 ✗","como: ~한 대로(방식) → 정답 ✓","cómo: 의문·감탄의 '어떻게'라 이 문장에 맞지 않습니다 ✗","como que: '~인 것 같다'라는 구어 표현이라 ✗"]},{"id":"G691","q":"____ nos mientas otra vez, nos vamos a enfadar mucho.","o":["Como","Siempre y cuando","Por si","Si"],"a":0,"k":"como + 접속법 (조건)","t":"네가 또 우리에게 거짓말하면 우리 정말 화낼 거야.","e":"'como + 접속법'은 문장 앞에서 '~하기만 해 봐, ~하면'이라는 경고·위협성 조건을 나타냅니다. 빈칸 뒤가 접속법 mientas이므로 como가 맞습니다. si는 접속법 현재와 함께 쓰지 않습니다.","x":["Como: como + 접속법 = 경고성 조건 → 정답 ✓","Siempre y cuando: '~하는 한(조건으로)'이라 경고 문맥에 어색합니다 ✗","Por si: 만일을 대비해서라는 뜻이라 ✗","Si: si 뒤에는 접속법 현재(mientas)를 쓰지 않습니다 ✗"]},{"id":"G692","q":"Llama después de las 9, que antes de esa hora ____ las tareas del día.","o":["estaremos organizando","organizaríamos","estaríamos organizando","estamos organizando"],"a":0,"k":"미래진행형","t":"9시 이후에 전화해, 그 전에는 우리가 하루 일과를 정리하고 있을 거야.","e":"미래의 특정 시간에 진행 중일 행동은 미래진행형 'estar의 미래 + 현재분사'로 씁니다. 그래서 estaremos organizando가 맞습니다.","x":["estaremos organizando: 미래 시점에 진행 중 → 정답 ✓","organizaríamos: 조건법이라 ✗","estaríamos organizando: 조건법 진행형이라 ✗","estamos organizando: 지금 진행 중이라는 뜻이라 ✗"]},{"id":"G693","q":"Contacto con ustedes ____ hacerles una consulta.","o":["a efectos de","a fin","para que","con el fin"],"a":0,"k":"목적 표현","t":"문의를 드리고자 여러분께 연락드립니다.","e":"'a efectos de + 동사원형'은 '~할 목적으로'라는 격식체 목적 표현입니다. 'a fin de', 'con el fin de'도 같은 뜻이지만 de가 꼭 있어야 합니다.","x":["a efectos de: ~할 목적으로 → 정답 ✓","a fin: 'a fin de'가 되어야 합니다 ✗","para que: 뒤에 접속법 활용 동사가 와야 하고 동사원형은 올 수 없습니다 ✗","con el fin: 'con el fin de'가 되어야 합니다 ✗"]},{"id":"G694","q":"Su padre es inglés y su madre española, ____ sea bilingüe.","o":["así que","por eso","por tanto","de ahí que"],"a":3,"k":"de ahí que + 접속법","t":"그의 아버지는 영국인이고 어머니는 스페인인이다. 그래서 그는 이중 언어 사용자다.","e":"'de ahí que'는 '그래서, 그 때문에'라는 결과 표현인데, 특이하게도 뒤에 접속법이 옵니다. 빈칸 뒤 sea가 접속법이므로 de ahí que가 정답입니다.","x":["así que: 결과지만 뒤에 직설법(es)이 옵니다 ✗","por eso: 결과지만 직설법이 옵니다 ✗","por tanto: 결과지만 직설법이 옵니다 ✗","de ahí que: 결과 + 접속법 → 정답 ✓"]},{"id":"G695","q":"Los Fernández no repararon ____ gastos para la boda de su hija.","o":["con","a","en","de"],"a":2,"k":"no reparar en gastos","t":"페르난데스 가족은 딸의 결혼식을 위해 비용을 아끼지 않았다.","e":"'no reparar en gastos'는 '비용을 아끼지 않다, 돈을 아낌없이 쓰다'라는 관용 표현입니다. reparar en(~을 신경 쓰다)에서 나온 표현입니다.","x":["con: 쓰지 않습니다 ✗","a: 쓰지 않습니다 ✗","en: no reparar en gastos → 정답 ✓","de: 쓰지 않습니다 ✗"]},{"id":"G696","q":"____ le digo a mi hijo que estudie, no me hace caso.","o":["Por más que","A pesar de","A causa de que","Pese a"],"a":0,"k":"por más que","t":"아들에게 아무리 공부하라고 말해도 내 말을 듣지 않는다.","e":"'por más que + 동사'는 '아무리 ~해도'라는 양보 표현입니다. 빈칸 뒤에 활용 동사(digo)가 오므로 que가 있는 접속사가 필요합니다.","x":["Por más que: 아무리 ~해도 → 정답 ✓","A pesar de: 뒤에 활용 동사가 오려면 que가 필요합니다 ✗","A causa de que: ~때문에(원인)라 논리가 맞지 않습니다 ✗","Pese a: 뒤에 활용 동사가 오려면 que가 필요합니다 ✗"]},{"id":"G697","q":"Jimena, ____ marido es un conocido cirujano, es médica de cabecera.","o":["cuya","que su","que el","cuyo"],"a":3,"k":"관계형용사 cuyo","t":"남편이 유명한 외과의사인 히메나는 가정의학과 의사다.","e":"cuyo(~의, 그의)는 소유 관계를 나타내는 관계사로, 뒤에 오는 명사(소유된 것)의 성·수에 맞춥니다. marido는 남성 단수이므로 cuyo가 맞습니다. 'que su'는 틀린 구조입니다.","x":["cuya: 여성형이라 marido와 맞지 않습니다(소유자 Jimena가 아니라 소유물에 일치) ✗","que su: 소유 관계를 이렇게 표현하지 않습니다 ✗","que el: 의미가 통하지 않습니다 ✗","cuyo: 남성 단수 marido에 일치 → 정답 ✓"]},{"id":"G698","q":"¿____ habéis dicho a Carmen que tenemos una reunión mañana?","o":["Les","La","Lo","Le"],"a":3,"k":"간접목적격 le","t":"너희 카르멘에게 내일 우리 회의 있다고 말했니?","e":"decir algo a alguien(누구에게 말하다)에서 '누구에게'는 간접목적어이므로 le(그/그녀에게)를 씁니다. 'a Carmen'과 le를 함께 쓰는 것이 자연스럽습니다.","x":["Les: 복수형이라 카르멘 한 명과 맞지 않습니다 ✗","La: 직접목적격(그녀를)이라 ✗","Lo: 직접목적격이라 ✗","Le: 간접목적격 단수 → 정답 ✓"]},{"id":"G699","q":"Ojalá ____ qué me depara el futuro.","o":["sabré","sabía","sabría","supiera"],"a":3,"k":"ojalá + 접속법 과거","t":"미래가 나에게 무엇을 가져다줄지 알 수 있다면 좋을 텐데.","e":"ojalá 뒤에는 접속법이 옵니다. 실현 가능성이 낮거나 불가능한 바람(미래를 아는 것)은 접속법 과거 supiera로 표현합니다.","x":["sabré: 직설법 미래라 ✗","sabía: 직설법이라 ✗","sabría: 조건법이라 ✗","supiera: 접속법 과거 → 정답 ✓"]},{"id":"G700","q":"No conozco a ____ que tenga tanta paciencia como tú.","o":["alguien","alguno","algún","nadie"],"a":3,"k":"no… nadie 이중부정","t":"너만큼 인내심이 많은 사람은 아무도 모른다.","e":"스페인어는 no와 다른 부정어(nadie)를 함께 쓰는 이중 부정이 정상입니다. 존재를 부정하는 선행사(nadie)이므로 관계절에 접속법 tenga가 쓰였습니다.","x":["alguien: no 뒤에서는 nadie를 써야 합니다 ✗","alguno: 긍정어라 부정문에 어색하고 명사도 없습니다 ✗","algún: 명사 앞에서만 씁니다 ✗","nadie: 이중부정 → 정답 ✓"]},{"id":"G701","q":"____ salí empezó a diluviar.","o":["Apenas","Al","Mientras","Nada más"],"a":0,"k":"apenas (~하자마자)","t":"내가 나가자마자 비가 억수같이 쏟아지기 시작했다.","e":"'apenas + 활용 동사'는 '~하자마자'라는 뜻입니다. 빈칸 뒤에 활용된 동사 salí가 오므로 apenas가 맞습니다. 'al'과 'nada más'는 표준 스페인어에서 동사원형(al salir, nada más salir)과 함께 씁니다.","x":["Apenas: ~하자마자 + 활용 동사 → 정답 ✓","Al: 'al salir'처럼 동사원형과 써야 합니다 ✗","Mientras: ~하는 동안이라 순간적인 순서를 나타내지 못합니다 ✗","Nada más: 표준어에서는 'nada más salir'처럼 동사원형과 씁니다 ✗"]},{"id":"G702","q":"Mañana tengo cita con el médico, por eso ____ que llegue tarde al trabajo.","o":["se puede","podrá","puede","puedo"],"a":2,"k":"puede que + 접속법","t":"내일 병원 예약이 있어서, 아마 회사에 늦게 도착할 수도 있어.","e":"'puede que + 접속법'은 '아마 ~일지도 모른다'라는 가능성 표현입니다. 이때 puede는 무인칭 3인칭 단수로 고정되어 쓰입니다. 뒤의 llegue가 접속법입니다.","x":["se puede: '~하는 것이 허용된다'라는 뜻이라 ✗","podrá: 'podrá que'라는 표현은 없습니다 ✗","puede: puede que = 아마 ~일 것이다 → 정답 ✓","puedo: 'puedo que'라는 표현은 없습니다 ✗"]},{"id":"G703","q":"____ a esta tienda porque me gustan sus productos.","o":["Sigo viniendo","Tengo que venir","Llevo viniendo","Dejo de venir"],"a":0,"k":"seguir + 현재분사","t":"나는 이 가게 제품이 마음에 들어서 계속 이 가게에 오고 있다.","e":"'seguir + 현재분사'는 '계속 ~하다'라는 뜻입니다. 제품이 좋아서 계속 온다는 이유 관계에 가장 자연스럽습니다.","x":["Sigo viniendo: 계속 오고 있다 → 정답 ✓","Tengo que venir: 와야만 한다(의무)라서 '좋아서'라는 이유와 어울리지 않습니다 ✗","Llevo viniendo: 기간 표현(desde hace años 등)이 필요합니다 ✗","Dejo de venir: 오지 않게 된다는 뜻이라 반대 의미입니다 ✗"]},{"id":"G704","q":"____ más tiempo con mis hijos si no trabajase tanto.","o":["Pasaría","Pasaré","Pasase","Estaré pasando"],"a":0,"k":"가정문 조건법","t":"이렇게 많이 일하지 않는다면 아이들과 더 많은 시간을 보낼 텐데.","e":"'si + 접속법 과거(trabajase)'로 현재 사실과 반대되는 가정을 할 때 주절에는 조건법을 씁니다. 그래서 pasar의 조건법 pasaría가 맞습니다.","x":["Pasaría: 조건법 → 정답 ✓","Pasaré: 직설법 미래라 비현실 가정과 맞지 않습니다 ✗","Pasase: 접속법 과거라 주절에 쓰지 않습니다 ✗","Estaré pasando: 미래진행형이라 ✗"]},{"id":"G705","q":"Tuve que tomarme una pastilla ____ se me quitara el dolor de cabeza.","o":["para que","por que","a que","para"],"a":0,"k":"para que + 접속법","t":"두통이 사라지도록 약을 한 알 먹어야 했다.","e":"주절과 que절의 주어가 다를 때(나 ≠ 두통) 목적은 'para que + 접속법'으로 씁니다. 주절이 과거(Tuve)라서 접속법 과거 quitara가 쓰였습니다.","x":["para que: 목적 + 접속법 → 정답 ✓","por que: 이 뜻으로 쓰지 않습니다 ✗","a que: 이 뜻으로 쓰지 않습니다 ✗","para: 뒤에 활용 동사가 오려면 que가 필요합니다 ✗"]},{"id":"G706","q":"Somos ____ Bélgica. ¿Y ustedes?","o":["del","de","de la","desde"],"a":1,"k":"국가명 + de","t":"우리는 벨기에 출신이에요. 여러분은요?","e":"출신을 말할 때 'ser de + 나라 이름'을 씁니다. 대부분의 나라 이름에는 관사를 붙이지 않으므로 'de Bélgica'가 맞습니다.","x":["del: de + el로 남성 관사가 들어갑니다 ✗","de: ser de + 나라 → 정답 ✓","de la: Bélgica에는 관사를 붙이지 않습니다 ✗","desde: ~에서부터(출발점)라서 출신을 말할 때 쓰지 않습니다 ✗"]},{"id":"G707","q":"____ he dicho ya, no sé dónde están las llaves.","o":["Os los","Se los","Os lo","Se la"],"a":2,"k":"os lo (대명사 결합)","t":"너희에게 이미 말했잖아, 열쇠가 어디 있는지 몰라.","e":"간접목적어(너희에게 os)와 직접목적어(그것을, 내가 한 말 전체 lo)가 함께 오면 'os lo' 순서로 씁니다. 말한 내용 전체는 중성 lo로 받습니다. os는 스페인에서 쓰고 중남미에서는 'se lo (he dicho a ustedes)'를 씁니다.","x":["Os los: 복수 los는 llaves를 받는 것처럼 보이지만 말한 내용은 중성 lo입니다 ✗","Se los: 대상도 복수 los도 맞지 않습니다 ✗","Os lo: 너희에게 + 그것(말한 내용) → 정답 ✓","Se la: 여성 단수 la가 가리킬 대상이 없습니다 ✗"]},{"id":"G708","q":"Tranquilos, no ha pasado ____ serio.","o":["algo","nada","algún","alguno"],"a":1,"k":"no… nada","t":"걱정 마, 심각한 일은 아무것도 일어나지 않았어.","e":"부정문 no 뒤에서 '아무것도'는 nada를 씁니다(이중 부정). 'nada + 형용사(serio)'는 '심각한 것은 아무것도'라는 뜻입니다.","x":["algo: 긍정어라 no와 함께 쓰지 않습니다 ✗","nada: 이중부정 → 정답 ✓","algún: 명사 앞에서만 쓰고 긍정어입니다 ✗","alguno: 긍정어이고 사람·사물 중 하나를 가리킵니다 ✗"]},{"id":"G709","q":"Me mareé ____ levantarme demasiado rápido del sofá.","o":["mientras","al","en cuanto","cuando"],"a":1,"k":"al + 동사원형","t":"소파에서 너무 빨리 일어나서 어지러웠다.","e":"'al + 동사원형'은 '~할 때, ~하자'라는 뜻으로 동시성이나 원인을 나타냅니다. 빈칸 뒤가 동사원형 levantarme이므로 al이 맞습니다.","x":["mientras: 뒤에 활용 동사가 옵니다 ✗","al: al + 동사원형 → 정답 ✓","en cuanto: 뒤에 활용 동사가 옵니다 ✗","cuando: 뒤에 활용 동사가 옵니다 ✗"]},{"id":"G710","q":"¿Cuándo ____ a Barcelona por última vez?","o":["estuviste yendo","estabas yendo","ibas","fuiste"],"a":3,"k":"단순과거","t":"마지막으로 바르셀로나에 간 게 언제야?","e":"'por última vez(마지막으로)'는 과거의 특정한 한 번을 가리키므로 단순과거를 씁니다. ir의 단순과거 2인칭 fuiste가 맞습니다.","x":["estuviste yendo: 진행형이라 한 번의 방문을 묻는 질문에 맞지 않습니다 ✗","estabas yendo: 과거 진행 배경이라 ✗","ibas: 불완료과거라 습관·배경을 나타냅니다 ✗","fuiste: 완결된 과거 사건 → 정답 ✓"]},{"id":"G711","q":"El bebé ____ llorar al ver que su madre se alejaba.","o":["empezó","se puso","se echó a","estuvo a"],"a":2,"k":"echarse a","t":"엄마가 멀어지는 걸 보자 아기가 울음을 터뜨렸다.","e":"'echarse a + 동사원형'은 '갑자기 ~하기 시작하다'라는 뜻으로 llorar(울다), reír(웃다), correr(달리다)와 자주 씁니다. 빈칸 뒤에 전치사가 없으므로 a가 포함된 선택지가 필요합니다.","x":["empezó: 'empezó a llorar'처럼 a가 필요합니다 ✗","se puso: 'se puso a llorar'처럼 a가 필요합니다 ✗","se echó a: 갑자기 ~하기 시작했다 → 정답 ✓","estuvo a: '~할 뻔했다'는 'estuvo a punto de'라서 ✗"]},{"id":"G712","q":"¡____ alegría que hayáis venido!","o":["Cuál","Qué","Que","La cual"],"a":1,"k":"감탄문 qué","t":"너희가 와 줘서 정말 기뻐!","e":"'¡Qué + 명사 + que + 접속법!'은 '~해서 정말 ~하다!'라는 감탄문입니다. 감탄사 qué에는 반드시 악센트가 붙습니다.","x":["Cuál: 감탄문에 쓰지 않습니다 ✗","Qué: 감탄사(악센트 있음) → 정답 ✓","Que: 악센트 없는 que는 접속사라 감탄할 수 없습니다 ✗","La cual: 관계대명사라 ✗"]},{"id":"G713","q":"Intento ____ temprano cada noche, pero no lo consigo.","o":["acostar me","acostar","acostarme","que me acueste"],"a":2,"k":"재귀 동사원형","t":"매일 밤 일찍 자려고 하는데 잘 안 된다.","e":"재귀 동사 acostarse(잠자리에 들다)를 동사원형으로 쓸 때는 재귀대명사를 붙여 한 단어로 씁니다: acostarme. 주어(yo)가 같으므로 que절은 필요 없습니다.","x":["acostar me: 띄어 쓰지 않고 붙여 씁니다 ✗","acostar: 재귀대명사가 빠지면 '누군가를 재우다'라는 뜻이 됩니다 ✗","acostarme: 동사원형 + 재귀대명사 → 정답 ✓","que me acueste: 주어가 같을 때는 que절 대신 동사원형을 씁니다 ✗"]},{"id":"G714","q":"¿____ cuándo compras en este supermercado?","o":["Hace","De","Desde","Desde hace"],"a":2,"k":"desde cuándo","t":"너는 언제부터 이 슈퍼마켓에서 장을 보니?","e":"'¿Desde cuándo…?'는 '언제부터 ~하니?'라는 질문입니다. 시작 시점을 묻기 때문에 desde를 씁니다. 'desde hace'는 기간(desde hace dos años) 앞에 씁니다.","x":["Hace: 'Hace cuánto'처럼 기간을 물을 때 씁니다 ✗","De: 'de cuándo'는 '언제 것인지'라는 뜻이라 ✗","Desde: 언제부터 → 정답 ✓","Desde hace: 뒤에 기간이 와야 합니다 ✗"]},{"id":"G715","q":"Que ____ mucho dinero no significa que seas feliz.","o":["estés teniendo","tienes","tengas","estás teniendo"],"a":2,"k":"que절 주어 + 접속법","t":"돈을 많이 가지고 있다고 해서 행복하다는 뜻은 아니다.","e":"문장 맨 앞에 오는 'Que + 동사'(~라는 것)가 주어가 될 때는 보통 접속법을 씁니다. 또한 'no significa que' 뒤에도 접속법(seas)이 옵니다. 그래서 tener의 접속법 tengas가 맞습니다.","x":["estés teniendo: tener는 소유의 의미로 진행형을 쓰지 않습니다 ✗","tienes: 직설법이라 문두 que절 주어에 맞지 않습니다 ✗","tengas: 접속법 현재 → 정답 ✓","estás teniendo: 직설법 진행형이라 ✗"]},{"id":"G716","q":"María está interesada en comprar tu moto. ¿Por qué no ____ vendes?","o":["le la","se lo","se la","se"],"a":2,"k":"se la (대명사 결합)","t":"마리아가 네 오토바이를 사고 싶어 해. 그녀에게 그걸 파는 게 어때?","e":"간접목적어 le(마리아에게)와 직접목적어 la(오토바이, la moto는 여성)가 함께 오면 le가 se로 바뀌어 'se la'가 됩니다.","x":["le la: le와 la는 함께 쓸 수 없고 se la로 바뀝니다 ✗","se lo: lo는 남성이라 la moto와 맞지 않습니다 ✗","se la: 그녀에게 + 그것(여성) → 정답 ✓","se: 직접목적어(오토바이)를 받는 대명사가 빠졌습니다 ✗"]},{"id":"G717","q":"Me dio un dolor en el hombro mientras ____ al baloncesto.","o":["estuve jugando","jugué","jugaba","jugaría"],"a":2,"k":"불완료과거 배경","t":"농구를 하던 중에 어깨에 통증이 왔다.","e":"mientras로 과거에 진행 중이던 배경 행동을 나타낼 때는 불완료과거(jugaba)를 쓰고, 그 사이 일어난 사건은 단순과거(me dio)로 씁니다. 'jugar al + 운동'으로 '~을 하다'를 표현합니다.","x":["estuve jugando: 완결된 기간을 나타내서 배경 묘사에 맞지 않습니다 ✗","jugué: 단순과거라 진행 중인 배경이 아닙니다 ✗","jugaba: 과거 진행 배경 → 정답 ✓","jugaría: 조건법이라 ✗"]},{"id":"G718","q":"Hijo mío, ya te he dicho que no ____ poner la música tan alta tan tarde.","o":["la puede","se puede","te puedes","puede"],"a":1,"k":"무인칭 se","t":"얘야, 이렇게 늦은 시간에 음악을 그렇게 크게 틀면 안 된다고 이미 말했잖아.","e":"'se puede / no se puede + 동사원형'은 '(일반적으로) ~해도 된다/안 된다'라는 무인칭 표현입니다. 규칙이나 금지를 말할 때 자주 씁니다.","x":["la puede: 목적어 la가 앞에 오면 'la música'와 중복되고 의미가 어색합니다 ✗","se puede: 무인칭 금지 표현 → 정답 ✓","te puedes: poder는 재귀형으로 쓰지 않습니다 ✗","puede: 주어가 '그/그녀'가 되어 아들에게 하는 말과 맞지 않습니다 ✗"]},{"id":"G719","q":"¿Cuánto tiempo ____ en este piso?","o":["llevas viviendo","andas viviendo","vas viviendo","estás viviendo"],"a":0,"k":"llevar + 현재분사","t":"너 이 아파트에 산 지 얼마나 됐어?","e":"'¿Cuánto tiempo llevas + 현재분사?'는 '~한 지 얼마나 됐어?'라는 기간 질문의 대표 형태입니다. 같은 뜻으로 '¿Cuánto tiempo hace que vives…?'도 씁니다. piso는 스페인에서 '아파트'라는 뜻입니다.","x":["llevas viviendo: ~한 지 얼마나 → 정답 ✓","andas viviendo: '이리저리 ~하며 다니다'라는 뜻이라 ✗","vas viviendo: '점차 ~해 가다'라는 뜻이라 ✗","estás viviendo: 진행형은 기간 질문(cuánto tiempo)과 어울리지 않습니다 ✗"]},{"id":"G720","q":"Adriana y su hermano ____ parecen mucho.","o":["los","se","les","ø"],"a":1,"k":"parecerse (닮다)","t":"아드리아나와 그녀의 남동생(오빠)은 많이 닮았다.","e":"'parecerse'는 '닮다'라는 재귀 동사로, 서로 닮았다는 상호 의미도 나타냅니다. 주어가 복수이므로 'se parecen'이 됩니다. parecer만 쓰면 '~처럼 보이다'라는 다른 뜻입니다.","x":["los: 직접목적격이라 ✗","se: parecerse의 재귀대명사 → 정답 ✓","les: 간접목적격이라 '그들에게 많이 ~처럼 보인다'가 되어 어색합니다 ✗","ø: se가 없으면 '닮다'라는 뜻이 되지 않습니다 ✗"]},{"id":"G721","q":"Almudena es una buena amiga ____.","o":["mi","de mí","mía","de mía"],"a":2,"k":"소유대명사 mía","t":"알무데나는 내 좋은 친구다.","e":"'명사 + 소유사'로 쓸 때는 강세형 소유사(mío, mía, míos, mías)를 씁니다. amiga가 여성 단수이므로 mía가 맞습니다. 'una buena amiga mía'는 '내 좋은 친구 중 한 명'이라는 느낌입니다.","x":["mi: 명사 앞에만 쓰는 형태라 ✗","de mí: 소유를 이렇게 표현하지 않습니다 ✗","mía: 명사 뒤 강세형 소유사(여성 단수) → 정답 ✓","de mía: 틀린 형태입니다 ✗"]},{"id":"G722","q":"No estamos seguros ____ que eso sea cierto.","o":["ø","de","por","a"],"a":1,"k":"estar seguro de","t":"우리는 그게 사실이라고 확신하지 못한다.","e":"'estar seguro de algo/que…'는 '~을 확신하다'라는 표현으로 que 앞에도 전치사 de가 필요합니다. de를 빼는 실수(queísmo)에 주의하세요. 확신을 부정했으므로 que절에 접속법(sea)이 왔습니다.","x":["ø: de가 빠지면 틀립니다 ✗","de: estar seguro de que → 정답 ✓","por: 쓰지 않습니다 ✗","a: 쓰지 않습니다 ✗"]},{"id":"G723","q":"Si ____ más energía, haría muchas más cosas.","o":["tuviera","tenga","tenía","tendría"],"a":0,"k":"si + 접속법 과거","t":"내게 에너지가 더 있다면 훨씬 더 많은 일을 할 텐데.","e":"현재 사실과 반대되는 가정은 'si + 접속법 과거 + 조건법(haría)'입니다. 그래서 tener의 접속법 과거 tuviera가 맞습니다.","x":["tuviera: 접속법 과거 → 정답 ✓","tenga: 접속법 현재는 si 뒤에 쓰지 않습니다 ✗","tenía: 직설법 불완료과거라 비현실 가정에 맞지 않습니다 ✗","tendría: 조건법은 si 뒤에 쓰지 않습니다 ✗"]},{"id":"G724","q":"Es normal desconfiar ____ los desconocidos.","o":["por","a","en","de"],"a":3,"k":"desconfiar de","t":"낯선 사람을 경계하는 것은 당연하다.","e":"desconfiar(믿지 않다, 경계하다)는 전치사 de와 함께 씁니다: desconfiar de alguien. 반대말 confiar는 en과 씁니다(confiar en alguien).","x":["por: 쓰지 않습니다 ✗","a: 쓰지 않습니다 ✗","en: confiar en에서 쓰지만 desconfiar에는 쓰지 않습니다 ✗","de: desconfiar de → 정답 ✓"]},{"id":"G725","q":"Niños, no ____ con la boca llena, por favor.","o":["habléis","habláis","hablad","hablas"],"a":0,"k":"부정 명령형","t":"얘들아, 입에 음식 넣은 채로 말하지 마라.","e":"부정 명령은 'no + 접속법 현재'로 만듭니다. 대상이 vosotros(niños)이므로 hablar의 접속법 2인칭 복수 habléis가 맞습니다. 중남미에서는 'no hablen'(ustedes)을 씁니다.","x":["habléis: 부정 명령(vosotros) → 정답 ✓","habláis: 직설법 현재라 명령이 되지 않습니다 ✗","hablad: 긍정 명령형이라 no와 함께 쓰지 않습니다 ✗","hablas: 직설법 2인칭 단수라 ✗"]},{"id":"G726","q":"____ sabe de matemáticas es Gabriel. Pídele a él que te eche una mano.","o":["Quién","Quien","Que","Cual"],"a":1,"k":"관계사 quien","t":"수학을 잘 아는 사람은 가브리엘이야. 그에게 도와달라고 해.","e":"'Quien(~하는 사람)'은 선행사 없이 '~하는 그 사람'이라는 뜻의 관계대명사입니다. 의문문이 아니므로 악센트 없는 quien을 씁니다. 'El que'로 바꿔 쓸 수도 있습니다.","x":["Quién: 악센트 있는 형태는 의문사라 ✗","Quien: 관계대명사(~하는 사람) → 정답 ✓","Que: 선행사 없이 단독으로 사람을 가리키지 못합니다 ✗","Cual: 단독으로 쓰지 않습니다 ✗"]},{"id":"G727","q":"A eso de las nueve de la noche ya ____ del resultado de las elecciones.","o":["nos enterásemos","nos estaremos enterados","enteraremos","nos habremos enterado"],"a":3,"k":"미래완료","t":"밤 9시쯤이면 우리는 이미 선거 결과를 알게 되었을 것이다.","e":"미래의 어느 시점(밤 9시쯤)에 이미 완료되어 있을 일은 미래완료로 씁니다. enterarse de(~을 알게 되다)는 재귀 동사이므로 'nos habremos enterado'가 맞습니다.","x":["nos enterásemos: 접속법 과거라 평서문에 쓰지 않습니다 ✗","nos estaremos enterados: enterarse를 이렇게 쓰지 않습니다 ✗","enteraremos: 재귀대명사 nos가 빠졌습니다 ✗","nos habremos enterado: 미래완료 → 정답 ✓"]},{"id":"G728","q":"Les llamo ____ me informen sobre un curso en el que estoy interesado.","o":["a fin de","para","con el fin","para que"],"a":3,"k":"para que + 접속법","t":"제가 관심 있는 강좌에 대해 안내를 받고 싶어서 여러분께 전화드립니다.","e":"주어가 다를 때(나 ≠ 여러분) 목적은 'para que + 접속법'입니다. 빈칸 뒤가 접속법 informen이므로 para que가 맞습니다. 'a fin de que'도 가능하지만 선택지에는 que가 없습니다.","x":["a fin de: 뒤에 동사원형이 와야 합니다 ✗","para: 뒤에 동사원형이 와야 합니다 ✗","con el fin: 'con el fin de que'가 되어야 합니다 ✗","para que: 목적 + 접속법 → 정답 ✓"]},{"id":"G729","q":"Cuando ____ de noche duermo fatal.","o":["trabajaría","trabajo","esté trabajando","trabaje"],"a":1,"k":"cuando + 직설법","t":"나는 밤에 일할 때면 잠을 아주 못 잔다.","e":"cuando가 반복되는 습관(~할 때마다)을 나타낼 때는 직설법 현재를 씁니다. 미래 상황일 때만 접속법을 씁니다. 주절 duermo가 습관을 보여 줍니다.","x":["trabajaría: 조건법이라 ✗","trabajo: 습관 + 직설법 → 정답 ✓","esté trabajando: 접속법이라 습관 문장에 맞지 않습니다 ✗","trabaje: 접속법은 미래 상황에 씁니다 ✗"]},{"id":"G730","q":"No vimos a Lucía, nos marchamos antes de que ____.","o":["llegaría","llegó","llegara","llegue"],"a":2,"k":"antes de que + 접속법","t":"우리는 루시아를 보지 못했다. 그녀가 도착하기 전에 떠났기 때문이다.","e":"'antes de que'는 항상 접속법과 함께 씁니다. 주절이 과거(nos marchamos)이므로 접속법 과거 llegara가 맞습니다.","x":["llegaría: 조건법이라 ✗","llegó: 직설법이라 antes de que 뒤에 쓰지 않습니다 ✗","llegara: 접속법 과거 → 정답 ✓","llegue: 접속법 현재라 과거 주절과 시제가 맞지 않습니다 ✗"]},{"id":"G731","q":"Ángela está triste, ¿qué le ____?","o":["pasaría","habría pasado","estaría pasando","habrá pasado"],"a":3,"k":"미래완료 추측","t":"앙헬라가 슬퍼하네, 무슨 일이 있었던 걸까?","e":"미래완료는 '아마 ~했을 것이다'라는 가까운 과거에 대한 추측을 나타낼 수 있습니다. 현재완료로 말할 일(¿qué le ha pasado?)을 추측할 때 habrá pasado를 씁니다.","x":["pasaría: 조건법은 과거 시점(불완료과거)에 대한 추측에 씁니다 ✗","habría pasado: 조건완료는 과거완료에 대한 추측이라 ✗","estaría pasando: 과거 진행 추측이라 ✗","habrá pasado: 가까운 과거 추측 → 정답 ✓"]},{"id":"G732","q":"¿Qué harías si te ____ mucho dinero en la lotería?","o":["toque","tocara","tocaría","tocaba"],"a":1,"k":"si + 접속법 과거","t":"복권에서 큰돈이 당첨된다면 너는 뭘 할 거야?","e":"주절이 조건법(harías)이면 si절에는 접속법 과거를 씁니다. 'tocar la lotería a alguien'은 '~에게 복권이 당첨되다'라는 표현이라 tocara가 맞습니다.","x":["toque: 접속법 현재는 si 뒤에 쓰지 않습니다 ✗","tocara: 접속법 과거 → 정답 ✓","tocaría: 조건법은 si 뒤에 쓰지 않습니다 ✗","tocaba: 직설법이라 ✗"]},{"id":"G733","q":"El concierto ____ en el auditorio municipal.","o":["será","tendrá","habrá","estará"],"a":0,"k":"ser (행사 장소)","t":"콘서트는 시립 강당에서 열릴 것이다.","e":"사물의 위치는 estar를 쓰지만, 행사·사건이 '열리다, 개최되다'라는 의미의 장소는 ser를 씁니다. 예: La fiesta es en mi casa.(파티는 우리 집에서 열린다.)","x":["será: 행사 개최 장소 = ser → 정답 ✓","tendrá: 주어가 장소를 가진다는 뜻이 되어 ✗","habrá: 'Habrá un concierto en…'처럼 써야 하고 정관사 el과 쓰지 않습니다 ✗","estará: 물건의 위치에 쓰는 동사라 행사에는 맞지 않습니다 ✗"]},{"id":"G734","q":"¿Cuál ha sido ____ mejor día de tu vida?","o":["el","ø","lo","la"],"a":0,"k":"최상급 관사","t":"네 인생에서 최고의 날은 언제였어?","e":"최상급은 '정관사 + mejor/peor + 명사' 형태입니다. día는 -a로 끝나지만 남성 명사이므로 el을 씁니다.","x":["el: 남성 정관사 + 최상급 → 정답 ✓","ø: 최상급에는 관사가 필요합니다 ✗","lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗","la: día는 남성 명사입니다 ✗"]},{"id":"G735","q":"No me agrada que me ____ por la espalda.","o":["critiquen","están criticando","critican","criticarían"],"a":0,"k":"감정 + 접속법","t":"사람들이 내 뒤에서 나를 험담하는 게 싫다.","e":"'No me agrada que(~하는 것이 마음에 들지 않다)'는 감정 표현이라 que절에 접속법을 씁니다. 불특정 사람들이 주어이므로 3인칭 복수 critiquen이 맞습니다. 'criticar por la espalda'는 '뒤에서 험담하다'라는 뜻입니다.","x":["critiquen: 접속법 현재 → 정답 ✓","están criticando: 직설법이라 ✗","critican: 직설법이라 ✗","criticarían: 조건법이라 ✗"]},{"id":"G736","q":"Si te pones delante ____, no podré ver nada.","o":["mío","de mi","de mí","mía"],"a":2,"k":"delante de mí","t":"네가 내 앞에 서면 나는 아무것도 볼 수 없을 거야.","e":"'delante de(~의 앞에)' 뒤에 대명사가 올 때는 전치사격 mí(악센트 있음)를 씁니다. 구어에서 'delante mío'라고도 하지만 표준 형태는 'delante de mí'입니다.","x":["mío: 표준어에서는 'delante de mí'를 씁니다 ✗","de mi: 악센트 없는 mi는 소유사(나의)라 ✗","de mí: 전치사 + mí → 정답 ✓","mía: 여성 소유사라 ✗"]},{"id":"G737","q":"La empresa ____ la que trabajo es francesa.","o":["a","para","hacia","de"],"a":1,"k":"trabajar para","t":"내가 다니는(일하는) 회사는 프랑스 회사다.","e":"'trabajar para una empresa'는 '~회사를 위해 일하다(~회사에 다니다)'라는 표현입니다. 관계절에서는 전치사가 관계사 앞으로 와서 'para la que trabajo'가 됩니다.","x":["a: trabajar a라는 표현은 없습니다 ✗","para: trabajar para + 회사 → 정답 ✓","hacia: ~쪽으로(방향)라 ✗","de: 'trabajar de'는 직책(~로 일하다)을 말할 때 씁니다 ✗"]},{"id":"G738","q":"Mañana no tenemos clase, ____ podemos levantarnos más tarde.","o":["ya que","aunque","así que","porque"],"a":2,"k":"así que (결과)","t":"내일 수업이 없으니까 우리 늦게 일어나도 돼.","e":"'así que'는 '그러니까, 그래서'라는 결과 접속사입니다. 앞 문장(수업이 없다)이 원인, 뒤(늦게 일어나도 된다)가 결과이므로 정답입니다.","x":["ya que: ~이므로(이유)라서 원인과 결과가 뒤바뀝니다 ✗","aunque: ~이지만(양보)이라 ✗","así que: 그러니까(결과) → 정답 ✓","porque: ~때문에(이유)라 순서가 맞지 않습니다 ✗"]},{"id":"G739","q":"No hace falta que ____ más comida, ya tenemos suficiente.","o":["comprarías","comprarás","compres","compras"],"a":2,"k":"no hace falta que","t":"음식을 더 살 필요 없어, 이미 충분히 있어.","e":"'(No) hace falta que(~할 필요가 (없)다)'는 필요성을 나타내는 표현이라 que절에 접속법을 씁니다. 그래서 comprar의 접속법 현재 compres가 맞습니다.","x":["comprarías: 조건법이라 ✗","comprarás: 직설법 미래라 ✗","compres: 접속법 현재 → 정답 ✓","compras: 직설법이라 ✗"]},{"id":"G740","q":"No me molesta ____ a pie al trabajo, pues caminar es bueno para la salud.","o":["ir","que estoy yendo","que voy","yendo"],"a":0,"k":"동사원형 주어","t":"걸어서 출근하는 건 싫지 않아. 걷는 건 건강에 좋으니까.","e":"'No me molesta(~이 귀찮지 않다)'처럼 gustar류 동사에서 주어인 행동을 말하는 사람과 하는 사람이 같으면 동사원형을 씁니다. 다를 때는 'que + 접속법'을 씁니다.","x":["ir: 동사원형 주어 → 정답 ✓","que estoy yendo: 직설법이고 주어가 같으면 que절을 쓰지 않습니다 ✗","que voy: 직설법이라 이 구문에 맞지 않습니다 ✗","yendo: 현재분사는 주어가 될 수 없습니다 ✗"]},{"id":"G741","q":"Dijo que ____ acompañado, pero al final llegó solo.","o":["vendrá","va a venir","habría venido","vendría"],"a":3,"k":"과거 속 미래 조건법","t":"그는 누군가와 함께 오겠다고 했지만, 결국 혼자 왔다.","e":"과거 시점(Dijo)에서 본 미래는 조건법으로 표현합니다. 그래서 venir의 조건법 vendría가 맞습니다. 직접화법 'Vendré acompañado'를 간접화법으로 바꾼 것입니다.","x":["vendrá: 직설법 미래는 현재 시점의 미래라 과거 보고와 맞지 않습니다 ✗","va a venir: 현재 기준 근접미래라 ✗","habría venido: 조건완료(왔을 것이다)라 ✗","vendría: 과거 속 미래 → 정답 ✓"]},{"id":"G742","q":"¿Os ____ esperar un poco?","o":["importaría","importaríais","importarías","importarían"],"a":0,"k":"importar 구문","t":"너희 조금 기다려 줄 수 있겠니?","e":"importar(~이 신경 쓰이다)는 gustar처럼 '사람'이 간접목적어(os)이고, 주어는 동사원형 esperar입니다. 동사원형 주어는 3인칭 단수이므로 importaría가 맞습니다. 조건법은 공손한 부탁을 나타냅니다.","x":["importaría: 3인칭 단수 조건법 → 정답 ✓","importaríais: 2인칭 복수라 주어(esperar)와 맞지 않습니다 ✗","importarías: 2인칭 단수라 ✗","importarían: 3인칭 복수라 ✗"]},{"id":"G743","q":"Si Teresa ____, se lo habría pasado muy bien.","o":["haya venido","hubo venido","había venido","hubiera venido"],"a":3,"k":"si + 접속법 과거완료","t":"테레사가 왔더라면 아주 즐거운 시간을 보냈을 텐데.","e":"과거 사실과 반대되는 가정은 'si + 접속법 과거완료(hubiera + 과거분사) + 조건완료(habría + 과거분사)'입니다. 'pasárselo bien'은 '즐겁게 지내다'라는 표현입니다.","x":["haya venido: 접속법 현재완료는 si 뒤에 쓰지 않습니다 ✗","hubo venido: 직전과거로 거의 쓰지 않으며 가정에 맞지 않습니다 ✗","había venido: 직설법 과거완료라 비현실 가정이 되지 않습니다 ✗","hubiera venido: 접속법 과거완료 → 정답 ✓"]},{"id":"G744","q":"Me gustaría que ____ el plato que tanto me gusta.","o":["cocinas","cocinaras","cocinarías","cocinarás"],"a":1,"k":"조건법 + 접속법 과거","t":"내가 정말 좋아하는 그 요리를 네가 해 주면 좋겠어.","e":"'Me gustaría que(~하면 좋겠다)'처럼 주절이 조건법이면 que절에는 접속법 과거를 씁니다. 그래서 cocinar의 접속법 과거 cocinaras가 맞습니다.","x":["cocinas: 직설법이라 ✗","cocinaras: 접속법 과거 → 정답 ✓","cocinarías: 조건법이라 ✗","cocinarás: 직설법 미래라 ✗"]},{"id":"G745","q":"No me ____ miedo las arañas.","o":["da","dé","den","dan"],"a":3,"k":"dar miedo 일치","t":"나는 거미가 무섭지 않다.","e":"'dar miedo(겁나게 하다)'는 gustar처럼 무서운 대상이 주어입니다. 주어 las arañas가 복수이므로 동사도 3인칭 복수 dan이 됩니다.","x":["da: 단수라 복수 주어 arañas와 맞지 않습니다 ✗","dé: 접속법 단수라 ✗","den: 접속법이라 평서문에 쓰지 않습니다 ✗","dan: 3인칭 복수 직설법 → 정답 ✓"]},{"id":"G746","q":"Si ____ tendremos que quedarnos en casa.","o":["nevará","nieve","nevaría","nieva"],"a":3,"k":"si + 직설법 현재","t":"눈이 오면 우리는 집에 있어야 할 거야.","e":"실현 가능한 조건(~하면 ~할 것이다)은 'si + 직설법 현재 + 미래'입니다. si 뒤에는 미래형이나 접속법 현재를 쓰지 않으므로 nevar의 현재형 nieva가 맞습니다.","x":["nevará: si 뒤에는 미래형을 쓰지 않습니다 ✗","nieve: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","nevaría: 조건법은 si 뒤에 쓰지 않습니다 ✗","nieva: 직설법 현재 → 정답 ✓"]},{"id":"G747","q":"Mis padres no conocen a ____ de mis amigos.","o":["algún","alguno","ninguno","ningún"],"a":2,"k":"ninguno de","t":"우리 부모님은 내 친구들 중 아무도 모르신다.","e":"부정문(no)에서 '~ 중 아무도'는 'ninguno/ninguna de + 복수 명사'로 씁니다. 명사 앞이 아니라 de 앞이므로 줄임형 ningún을 쓰지 않습니다.","x":["algún: 명사 앞 줄임형이고 긍정어라 ✗","alguno: 긍정어라 부정문에 맞지 않습니다 ✗","ninguno: ninguno de + 복수 명사 → 정답 ✓","ningún: 명사 바로 앞에서만 씁니다 ✗"]},{"id":"G748","q":"____ estáis aquí, ¿nos echáis una mano con la mudanza?","o":["Debido a que","Conque","A pesar de que","Ya que"],"a":3,"k":"ya que (이유)","t":"너희가 여기 온 김에, 이사하는 거 좀 도와줄래?","e":"'ya que'는 '~이니까, ~인 김에'라는 이유 접속사로, 문장 앞에 와서 이미 알려진 사실을 근거로 제안·부탁할 때 자주 씁니다.","x":["Debido a que: 원인을 나타내지만 격식체라 부탁하는 문장에 어색합니다 ✗","Conque: '그러니까'라는 결과 접속사로 문장 맨 앞에 쓰지 않습니다 ✗","A pesar de que: ~에도 불구하고(양보)라 ✗","Ya que: ~인 김에(이유) → 정답 ✓"]},{"id":"G749","q":"A María no ____ han dado aún el dinero que le deben.","o":["le","la","ø","lo"],"a":0,"k":"간접목적격 le","t":"마리아에게 빌린 돈을 아직 그녀에게 돌려주지 않았다.","e":"dar algo a alguien(누구에게 주다)에서 '누구에게'는 간접목적어이므로 le를 씁니다. 문장 앞의 'A María'를 le로 다시 받아 주는 것이 스페인어에서는 필수입니다. 주어는 불특정 '그들'(han dado)입니다.","x":["le: 간접목적격 → 정답 ✓","la: 직접목적격(그녀를)이라 ✗","ø: 'A María'가 앞에 나오면 le로 반드시 다시 받아야 합니다 ✗","lo: 직접목적격이라 ✗"]},{"id":"G750","q":"¿Cuántos países forman ____ Unión Europea?","o":["la","al","el","ø"],"a":0,"k":"정관사 la","t":"유럽연합은 몇 개 나라로 구성되어 있니?","e":"Unión Europea(유럽연합) 같은 기구·단체 이름에는 정관사를 붙입니다. unión은 여성 명사이므로 la를 씁니다. 'formar'는 여기서 '~을 구성하다'라는 뜻입니다.","x":["la: 여성 정관사 → 정답 ✓","al: a + el이라 전치사가 필요 없고 성도 맞지 않습니다 ✗","el: 남성 관사라 unión과 맞지 않습니다 ✗","ø: 기구 이름에는 정관사가 필요합니다 ✗"]}];